
function obtenerCodigosEdificiosPorPrefijo(prefijo) {
  const pref = String(prefijo || "").trim().toUpperCase().slice(0, 2);
  if (!pref) return ["0361", "0362", "0380", "0381", "0382"];
  const codigos = new Set();
  if (typeof listaCopropiedadesSuperadmin !== "undefined" && Array.isArray(listaCopropiedadesSuperadmin)) {
    listaCopropiedadesSuperadmin.forEach(c => {
      if (c && c.codigo && String(c.codigo).toUpperCase().startsWith(pref)) codigos.add(String(c.codigo));
    });
  }
  if (typeof CATALOGO_OFICIAL_DBPLUS !== "undefined") {
    Object.keys(CATALOGO_OFICIAL_DBPLUS).forEach(k => {
      if (k.toUpperCase().startsWith(pref)) codigos.add(k);
    });
  }
  return codigos.size > 0 ? Array.from(codigos) : ["0361", "0362", "0380", "0381", "0382"];
}

// ==============================================================================
// VALIDACIÓN ESTRICTA DE INMUEBLES (CUARTO ÚTIL Y PARQUEADERO 100% REALES DB)
// ==============================================================================
function esDatoRealInmueble(val, prefijoInvalido) {
  if (!val) return false;
  const str = String(val).trim();
  if (!str || str === "--" || str.toLowerCase() === "null" || str.toLowerCase() === "none" || str.toLowerCase() === "no tiene") return false;
  if (prefijoInvalido && str.toUpperCase().startsWith(prefijoInvalido.toUpperCase())) return false;
  const lower = str.toLowerCase();
  if (lower === "torre 1" || lower === "torre 00" || lower === "ap" || lower === "00" || lower === "apto") return false;
  return true;
}

function normalizarDatoInmueble(val, prefijoInvalido) {
  if (!esDatoRealInmueble(val, prefijoInvalido)) return "";
  return String(val).trim();
}



// ==============================================================================

// GESTION DINAMICA DE DATOS DEL COPROPIETARIO / RESIDENTE SEGUN INGRESO

// ==============================================================================

function actualizarPerfilResidente(codigoEdificio, aptoInput) {

  const codLimpio = String(codigoEdificio || AppState.codigoEdificio || "4901").replace(/^cj_/, "").trim();

  const aptoLimpio = String(aptoInput || AppState.aptoNumero || "0107").trim();

  const copropiedad = (typeof obtenerDatosCopropiedad === "function") ? obtenerDatosCopropiedad(codLimpio) : null;

  const numAptoBuscado = parseInt(aptoLimpio.replace(/\D/g, ""), 10);



  let unidadEncontrada = null;

  if (copropiedad && copropiedad.unidades && copropiedad.unidades.length > 0) {

    unidadEncontrada = copropiedad.unidades.find(u => {

      const uCod = String(u.unidad || u.apto || "").trim();

      if (uCod.toLowerCase() === aptoLimpio.toLowerCase()) return true;

      const uNum = parseInt(uCod.replace(/\D/g, ""), 10);

      if (!isNaN(uNum) && !isNaN(numAptoBuscado) && uNum === numAptoBuscado) return true;

      return false;

    });

  }



  if (unidadEncontrada) {

    AppState.aptoNumero = unidadEncontrada.unidad || unidadEncontrada.apto || aptoLimpio;

    AppState.propietario = unidadEncontrada.propietario || unidadEncontrada.nombre || "";

    AppState.documento = unidadEncontrada.cc || unidadEncontrada.cedula || unidadEncontrada.nit || "";

    AppState.email = unidadEncontrada.email || unidadEncontrada.correo || "";

    AppState.coeficiente = unidadEncontrada.coefNum || parseFloat(unidadEncontrada.coeficiente) || 0;

    AppState.coeficienteFmt = unidadEncontrada.coeficiente || (AppState.coeficiente > 0 ? `${AppState.coeficiente}%` : "0.000%");

    const pendPuro = (unidadEncontrada.pend !== undefined) ? parseFloat(unidadEncontrada.pend) : (parseFloat(unidadEncontrada.saldoAnterior) || 0);
    const intp = parseFloat(unidadEncontrada.intp) || 0;
    const ndncp = parseFloat(unidadEncontrada.ndncp) || 0;
    const extrap = parseFloat(unidadEncontrada.extrap) || 0;
    const otrosp = parseFloat(unidadEncontrada.otrosp) || 0;
    const multap = parseFloat(unidadEncontrada.multap) || 0;
    const serpup = parseFloat(unidadEncontrada.serpup) || 0;
    const servip = parseFloat(unidadEncontrada.servip) || 0;

    // Saldo pendiente total acumulado: capital pendiente + mora anterior + notas + cuotas extra + multas + serv. públicos + serv. especiales
    const saldoPendienteTotal = (unidadEncontrada.saldoPendienteNum !== undefined && !isNaN(unidadEncontrada.saldoPendienteNum))
      ? parseFloat(unidadEncontrada.saldoPendienteNum)
      : (pendPuro + intp + ndncp + extrap + otrosp + multap + serpup + servip);

    AppState.admon = (unidadEncontrada.admon !== undefined) ? parseFloat(unidadEncontrada.admon) : (parseFloat(unidadEncontrada.actual) || parseFloat(unidadEncontrada.cuota) || 0);

    AppState.pend = saldoPendienteTotal;
    AppState.pendPuro = pendPuro;
    AppState.intp = intp;
    AppState.ndncp = ndncp;
    AppState.extrap = extrap;
    AppState.otrosp = otrosp;
    AppState.multap = multap;
    AppState.serpup = serpup;
    AppState.servip = servip;
    AppState.saldoPendienteTotal = saldoPendienteTotal;

    AppState.inta = (unidadEncontrada.inta !== undefined) ? parseFloat(unidadEncontrada.inta) : (parseFloat(unidadEncontrada.interes) || 0);

    AppState.saldoTotal = unidadEncontrada.totalNum !== undefined ? parseFloat(unidadEncontrada.totalNum) : (AppState.admon + saldoPendienteTotal + AppState.inta);

    AppState.valpag = (unidadEncontrada.valpag !== undefined) ? parseFloat(unidadEncontrada.valpag) : 0;

    AppState.estado = unidadEncontrada.estado || (saldoPendienteTotal > 0 ? "En Mora" : "Al Dia");

    AppState.fac = unidadEncontrada.fac || unidadEncontrada.nfac || "";

    AppState.rec = unidadEncontrada.rec || "";

    const cuFound = unidadEncontrada.cuartoUtil || unidadEncontrada.cuarto_util || "";
    AppState.cuartoUtil = normalizarDatoInmueble(cuFound, "CU-");

    const pkFound = unidadEncontrada.parqueadero || unidadEncontrada.parq || "";
    AppState.parqueadero = normalizarDatoInmueble(pkFound, "PK-");

  } else {

    AppState.aptoNumero = aptoLimpio;

    AppState.propietario = "";

    AppState.documento = "";

    AppState.email = "";

    AppState.coeficiente = 0;

    AppState.coeficienteFmt = "0.000%";

    AppState.admon = 0;

    AppState.pend = 0;

    AppState.inta = 0;

    AppState.intp = 0;

    AppState.saldoTotal = 0;

    AppState.valpag = 0;

    AppState.estado = "Al Dia";

    AppState.fac = "";

    AppState.rec = "";

    AppState.cuartoUtil = "";

    AppState.parqueadero = "";

  }



  if (typeof driveEdificioSeleccionado !== "undefined") {

    driveEdificioSeleccionado = codLimpio;

  }



  // 1. Sincronizar UI de tab-inicio

  actualizarDashboardResidente(copropiedad);



  // 2. Sincronizar Avatar superior

  actualizarTopAvatarResidente();

}



