function actualizarTopAvatarResidente() {

  const topAvatarCircle = document.getElementById("top-avatar-circle");

  const topAvatarNombre = document.getElementById("top-avatar-nombre");

  const topAvatarRol = document.getElementById("top-avatar-rol");

  if (!topAvatarCircle || !topAvatarNombre || !topAvatarRol) return;



  const nomProp = AppState.propietario || (AppState.aptoNumero ? `Apto ${AppState.aptoNumero}` : "Usuario");

  const aptoNum = AppState.aptoNumero || "";

  const partes = nomProp.trim().split(/\s+/).filter(p => !["de", "del", "la", "las", "los", "y"].includes(p.toLowerCase()));

  const iniciales = partes.length >= 2 ? (partes[0][0] + partes[1][0]).toUpperCase() : nomProp.slice(0, 2).toUpperCase();



  topAvatarCircle.innerText = iniciales;

  topAvatarCircle.className = "w-8 h-8 rounded-full bg-blue-600 text-white font-black text-xs flex items-center justify-center shadow-md shrink-0";

  topAvatarNombre.innerText = nomProp;

  topAvatarRol.innerText = `Copropietario (Apto ${aptoNum})`;

}



