function actualizarEstadoAceptacionHabeas(checked) {

  const tsBox = document.getElementById("habeas-data-timestamp-box");

  const tsTxt = document.getElementById("habeas-data-timestamp-texto");

  if (!tsBox || !tsTxt) return;



  if (checked) {

    const ahora = new Date();

    const fechaFmt = ahora.toLocaleDateString("es-CO", { year: 'numeric', month: 'short', day: 'numeric' });

    const horaFmt = ahora.toLocaleTimeString("es-CO", { hour: '2-digit', minute: '2-digit', second: '2-digit' });

    tsTxt.innerText = `Aceptado: ${fechaFmt} ${horaFmt}`;

    tsBox.classList.remove("hidden");

    safeCreateIcons();

  } else {

    tsBox.classList.add("hidden");

  }

}



