// Sincronización oficial del Administrador con el Archivo de Edificios (EDIFICIO.xlsx)

function sincronizarAdministradorEdificio(cod) {

  // NO sobreescribir el avatar del usuario si el rol activo es Copropietario o Porteria

  if (typeof AppState !== "undefined" && AppState.rol !== "admin" && AppState.rol !== "superadmin") {

    return;

  }

  if (!cod) cod = (typeof AppState !== "undefined" && AppState.codigoEdificio) ? AppState.codigoEdificio : "4901";

  const codLimpio = String(cod).replace(/^cj_/, "").trim();

  try {

    if (typeof sincronizarClavePorteriaAdmin === "function") {

      sincronizarClavePorteriaAdmin(codLimpio);

    }

  } catch (e) {}



  let adminNom = (typeof AppState !== "undefined" && AppState.adminNombre) ? AppState.adminNombre : null;

  // 1. PRIMERO: listaCopropiedadesSuperadmin (edición activa del usuario en SuperAdmin / localStorage)
  if (!adminNom && typeof listaCopropiedadesSuperadmin !== 'undefined' && Array.isArray(listaCopropiedadesSuperadmin)) {
    const cop = listaCopropiedadesSuperadmin.find(c => c && (c.codigo === codLimpio || c.id === cod || c.id === `cj_${codLimpio}`));
    if (cop && cop.administrador) adminNom = cop.administrador;
  }

  // 2. SEGUNDO: EDIFICIOS_CATALOGO_DRIVE
  if (!adminNom && typeof EDIFICIOS_CATALOGO_DRIVE !== 'undefined' && EDIFICIOS_CATALOGO_DRIVE[codLimpio] && EDIFICIOS_CATALOGO_DRIVE[codLimpio].administrador) {
    adminNom = EDIFICIOS_CATALOGO_DRIVE[codLimpio].administrador;
  }

  // 3. TERCERO: COPROPIEDADES
  if (!adminNom && typeof COPROPIEDADES !== 'undefined' && COPROPIEDADES[codLimpio] && COPROPIEDADES[codLimpio].administrador) {
    adminNom = COPROPIEDADES[codLimpio].administrador;
  }

  // 3. Catálogo Oficial extraído de EDIFICIO.xlsx

  if (!adminNom && typeof CATALOGO_ADMINISTRADORES_OFICIAL_EDIFICIO !== 'undefined' && CATALOGO_ADMINISTRADORES_OFICIAL_EDIFICIO[codLimpio]) {

    adminNom = CATALOGO_ADMINISTRADORES_OFICIAL_EDIFICIO[codLimpio].administrador;

  }

  if (!adminNom) {

    adminNom = "Administrador Copropiedad";

  }



  // Limpiar nombre si trae teléfono o extensión (ej: "Sofía Jiménez Rangel")

  const nombreLimpio = adminNom.replace(/\s*\(?\d{3,}\)?[\d\s\-Ext\.]*$/i, "").trim() || adminNom;



  // Extraer iniciales

  const partes = nombreLimpio.trim().split(/\s+/).filter(p => !["de", "del", "la", "las", "los", "y"].includes(p.toLowerCase()));

  const iniciales = partes.length >= 2 ? (partes[0][0] + partes[1][0]).toUpperCase() : nombreLimpio.slice(0, 2).toUpperCase();



  const topAvatarCircle = document.getElementById("top-avatar-circle");

  const topAvatarNombre = document.getElementById("top-avatar-nombre");

  const topAvatarRol = document.getElementById("top-avatar-rol");



  if (topAvatarNombre) topAvatarNombre.innerText = nombreLimpio;

  if (topAvatarCircle) {

    topAvatarCircle.innerText = iniciales;

    topAvatarCircle.className = "w-8 h-8 rounded-full bg-emerald-600 text-white font-black text-xs flex items-center justify-center shadow-md";

  }

  if (topAvatarRol) topAvatarRol.innerText = "Administrador(a)";

  const topNombre = document.getElementById("top-header-edificio-nombre");
  if (topNombre) {
    const cop = (typeof obtenerDatosCopropiedad === "function") ? obtenerDatosCopropiedad(codLimpio) : null;
    if (cop && cop.nombre) {
      topNombre.innerText = `${cop.codigo} ${cop.nombre.toUpperCase()}`;
    }
  }



  // Sincronizar select superior si existe

  const selConjunto = document.getElementById("sel-conjunto");

  if (selConjunto) {

    const opt = Array.from(selConjunto.options).find(o => o.value === `cj_${codLimpio}` || o.value === codLimpio);

    if (opt && selConjunto.value !== opt.value) {

      selConjunto.value = opt.value;

    }

  }

}



// Manejador ultra-seguro de Lucide Icons (Previene cualquier pantallazo blanco por fallo de CDN o scripts)

function safeCreateIcons() {
  try {
    if (typeof window !== "undefined" && window.lucide && typeof window.lucide.createIcons === "function" && window.lucide.createIcons !== safeCreateIcons) {
      window.lucide.createIcons();
    }
  } catch(e) {
    console.warn("Lucide createIcons:", e);
  }
}





