// ==============================================================================

// PERSISTENCIA Y SINCRONIZACIÓN DE COPROPIEDADES (LOCALSTORAGE + SQLITE BACKEND)

// ==============================================================================



function cargarCopropiedadesGuardadasPersistentes() {

  try {

    if (typeof localStorage === "undefined") return;



    // Purga definitiva de edificios de prueba o simulados

    const FAKE_CODES = new Set(["1428", "1A2B", "2609", "0002", "9876"]);

    const FAKE_NAMES = ["Torres del Parque", "Los Sauces", "Balcones de Baviera", "Torres de San Carlos"];

    const isFake = (c) => {
      if (!c) return true;
      const cod = String(c.codigo || c.id || "").replace(/^cj_/, "").trim();
      if (FAKE_CODES.has(cod)) return true;
      if (c.nombre && FAKE_NAMES.some(fn => c.nombre.toLowerCase().includes(fn.toLowerCase()))) return true;
      // Purga automatica de edificios ficticios generados por fallbacks previos
      if (c.nombre && /^EDIFICIO COPROPIEDAD #/i.test(c.nombre)) return true;
      if (c.nombre && /^EDIFICIO #\d+$/i.test(c.nombre)) return true;
      if (c.nombre && /^EDIFICIO \d+$/i.test(c.nombre)) return true;
      if (c.nombre && /^Copropiedad #\d+$/i.test(c.nombre) && (!c.unidades || c.unidades.length === 0)) return true;
      return false;
    };



    // Asegurar que la lista en memoria esté 100% limpia de edificios demo

    listaCopropiedadesSuperadmin = listaCopropiedadesSuperadmin.filter(c => !isFake(c));



    const activeCod = localStorage.getItem("lefacturamos_active_building") || "";

    if (FAKE_CODES.has(activeCod) || activeCod === "0955" || isFake({ codigo: activeCod, nombre: activeCod })) {

      localStorage.setItem("lefacturamos_active_building", "4901");

    }



    const raw = localStorage.getItem("lefacturamos_copropiedades_custom");

    if (!raw) return;

    const parsed = JSON.parse(raw);

    if (!Array.isArray(parsed) || parsed.length === 0) return;

    const cleaned = parsed.filter(c => !isFake(c));

    localStorage.setItem("lefacturamos_copropiedades_custom", JSON.stringify(cleaned));



    parsed.forEach(cGuardada => {

      if (!cGuardada || !cGuardada.codigo) return;

      const cod = String(cGuardada.codigo).trim();



      // Sanitizar nombres provisionales / de ensayo para que siempre use los datos reales de DBPLUS

      if (cGuardada.nombre && cGuardada.nombre.startsWith("EDIFICIO COPROPIEDAD #")) {

        if (typeof CATALOGO_OFICIAL_DBPLUS !== "undefined" && CATALOGO_OFICIAL_DBPLUS[cod]) {

          cGuardada.nombre = CATALOGO_OFICIAL_DBPLUS[cod].nombre;

          cGuardada.nit = CATALOGO_OFICIAL_DBPLUS[cod].nit;

          cGuardada.direccion = CATALOGO_OFICIAL_DBPLUS[cod].direccion;

          cGuardada.administrador = CATALOGO_OFICIAL_DBPLUS[cod].administrador;

          cGuardada.banco = CATALOGO_OFICIAL_DBPLUS[cod].banco;

          cGuardada.cuenta = CATALOGO_OFICIAL_DBPLUS[cod].cuenta;

          cGuardada.telefono = CATALOGO_OFICIAL_DBPLUS[cod].telefono;

          cGuardada.email = CATALOGO_OFICIAL_DBPLUS[cod].email;

        }

      }

      const idx = listaCopropiedadesSuperadmin.findIndex(c => String(c.codigo).trim() === cod || c.id === cGuardada.id);

      if (idx >= 0) {

        listaCopropiedadesSuperadmin[idx] = { ...listaCopropiedadesSuperadmin[idx], ...cGuardada };

      } else {

        listaCopropiedadesSuperadmin.unshift(cGuardada);

      }



      // Sincronizar catálogo drive si existe

      if (typeof EDIFICIOS_CATALOGO_DRIVE !== "undefined" && !EDIFICIOS_CATALOGO_DRIVE[cod]) {

        EDIFICIOS_CATALOGO_DRIVE[cod] = {

          codigo: cod,

          nombre: cGuardada.nombre,

          administrador: cGuardada.administrador || "Administrador",

          nit: cGuardada.nit || "900.000.000-0",

          banco: cGuardada.banco || "Bancolombia",

          cuenta: cGuardada.cuenta || `Cta-${cod}`,

          direccion: cGuardada.direccion || "Dirección Oficial",

          ciudad: cGuardada.ciudad || "Colombia",

          anios: [2026, 2025, 2024],

          meses: (typeof LISTA_MESES_DRIVE !== "undefined") ? LISTA_MESES_DRIVE : ["ENERO", "FEBRERO", "MARZO", "ABRIL", "MAYO", "JUNIO", "JULIO", "AGOSTO", "SEPTIEMBRE", "OCTUBRE", "NOVIEMBRE", "DICIEMBRE"]

        };

      }

      // Sincronizar catálogo admin oficial si existe

      if (typeof CATALOGO_ADMINISTRADORES_OFICIAL_EDIFICIO !== "undefined" && !CATALOGO_ADMINISTRADORES_OFICIAL_EDIFICIO[cod]) {

        CATALOGO_ADMINISTRADORES_OFICIAL_EDIFICIO[cod] = {

          nombre: cGuardada.nombre,

          administrador: cGuardada.administrador || "Administrador",

          telefono: cGuardada.telefono || "3104445566",

          email: cGuardada.email || `administracion${cod}@lefacturamos.com`,

          banco: cGuardada.banco || "Bancolombia",

          cuenta: cGuardada.cuenta || "",

          nit: cGuardada.nit || ""

        };

      }

    });

  } catch (err) {

    console.warn("Aviso cargando copropiedades persistentes:", err);

  }

}



// Función para obtener todos los edificios asociados al prefijo de 2 dígitos del administrador
function obtenerEdificiosPorPrefijoAdministrador(prefijo, codEdificioActivo = null) {
  const pref = String(prefijo || "").trim().toUpperCase().slice(0, 2);
  if (!pref) return typeof listaCopropiedadesSuperadmin !== "undefined" ? [...listaCopropiedadesSuperadmin] : [];

  const codigosVistos = new Set();
  const resultado = [];

  // 1. Buscar en listaCopropiedadesSuperadmin
  if (typeof listaCopropiedadesSuperadmin !== "undefined" && Array.isArray(listaCopropiedadesSuperadmin)) {
    listaCopropiedadesSuperadmin.forEach(c => {
      if (!c || !c.codigo) return;
      const cod = String(c.codigo).trim().toUpperCase();
      if (cod.startsWith(pref) && !codigosVistos.has(cod)) {
        codigosVistos.add(cod);
        resultado.push(c);
      }
    });
  }

  // 2. Buscar en CATALOGO_OFICIAL_DBPLUS (248 Edificios oficiales)
  if (typeof CATALOGO_OFICIAL_DBPLUS !== "undefined") {
    Object.keys(CATALOGO_OFICIAL_DBPLUS).forEach(codKey => {
      const cod = String(codKey).trim().toUpperCase();
      if (cod.startsWith(pref) && !codigosVistos.has(cod)) {
        codigosVistos.add(cod);
        const item = CATALOGO_OFICIAL_DBPLUS[codKey];
        resultado.push({
          id: "cj_" + cod,
          codigo: cod,
          nombre: item.nombre || `Edificio #${cod}`,
          nit: item.nit || "900.000.000-0",
          direccion: item.direccion || "",
          ciudad: item.ciudad || "Medellín • Antioquia",
          administrador: item.administrador || "",
          telefono: item.telefono || "",
          email: item.email || "",
          banco: item.banco || "BANCOLOMBIA AHO",
          cuenta: item.cuenta || ""
        });
      }
    });
  }

  // 3. Buscar en EDIFICIOS_CATALOGO_DRIVE
  if (typeof EDIFICIOS_CATALOGO_DRIVE !== "undefined") {
    Object.values(EDIFICIOS_CATALOGO_DRIVE).forEach(item => {
      if (!item || !item.codigo) return;
      const cod = String(item.codigo).trim().toUpperCase();
      if (cod.startsWith(pref) && !codigosVistos.has(cod)) {
        codigosVistos.add(cod);
        resultado.push({
          id: "cj_" + cod,
          codigo: cod,
          nombre: item.nombre || `Edificio #${cod}`,
          nit: item.nit || "900.000.000-0",
          ciudad: item.ciudad || "Medellín • Antioquia"
        });
      }
    });
  }

  // 4. Si el edificio activo no está por alguna razón, garantizar su inclusión
  if (codEdificioActivo) {
    const codAct = String(codEdificioActivo).replace(/^cj_/, "").trim().toUpperCase();
    if (!codigosVistos.has(codAct)) {
      const copAct = typeof obtenerDatosCopropiedad === "function" ? obtenerDatosCopropiedad(codAct) : null;
      if (copAct) {
        resultado.unshift(copAct);
      }
    }
  }

  // Ordenar alfanuméricamente por código
  resultado.sort((a, b) => String(a.codigo).localeCompare(String(b.codigo)));

  return resultado;
}

function actualizarTodosLosSelectsDeCopropiedad(codigoSeleccionado = null) {

  // 1. Selector de Pantalla de Entrada #login-edificio-select

  const selLogin = document.getElementById("login-edificio-select");

  if (selLogin) {

    const currentVal = codigoSeleccionado || selLogin.value || "";

    let htmlLogin = '<option value="">-- Seleccione o escriba el código del edificio --</option>';

    const codigosVistos = new Set();

    listaCopropiedadesSuperadmin.forEach(c => {

      if (!c.codigo || codigosVistos.has(c.codigo)) return;

      codigosVistos.add(c.codigo);

      htmlLogin += `<option value="${c.codigo}" ${c.codigo === currentVal ? "selected" : ""}>${c.codigo} - ${c.nombre}</option>`;

    });

    if (typeof EDIFICIOS_CATALOGO_DRIVE !== "undefined") {

      Object.values(EDIFICIOS_CATALOGO_DRIVE).forEach(e => {

        if (!e.codigo || codigosVistos.has(e.codigo)) return;

        codigosVistos.add(e.codigo);

        htmlLogin += `<option value="${e.codigo}" ${e.codigo === currentVal ? "selected" : ""}>${e.codigo} - ${e.nombre}</option>`;

      });

    }

    selLogin.innerHTML = htmlLogin;

    if (currentVal && codigosVistos.has(currentVal)) {

      selLogin.value = currentVal;

    }

  }



  // 1b. Selector de Menú Vertical: ¿A qué edificio vas a hacerle cambio?

  const selSidebarCambio = document.getElementById("sidebar-sel-cambio-edificio");

  if (selSidebarCambio) {

    const currentVal = codigoSeleccionado || (typeof AppState !== "undefined" && (AppState.conjuntoId || AppState.codigoEdificio)) || selSidebarCambio.value || "";

    let htmlSide = '<option value="">-- Selecciona el edificio a arreglar --</option>';

    const codigosVistos = new Set();

    listaCopropiedadesSuperadmin.forEach(c => {

      if (!c.codigo || codigosVistos.has(c.codigo)) return;

      codigosVistos.add(c.codigo);

      const optVal = c.id || c.codigo;

      const isSel = (optVal === currentVal || c.codigo === currentVal || c.id === currentVal);

      htmlSide += `<option value="${optVal}" ${isSel ? "selected" : ""}>[${c.codigo}] ${c.nombre}</option>`;

    });

    if (typeof EDIFICIOS_CATALOGO_DRIVE !== "undefined") {

      Object.values(EDIFICIOS_CATALOGO_DRIVE).forEach(e => {

        if (!e.codigo || codigosVistos.has(e.codigo)) return;

        codigosVistos.add(e.codigo);

        const optVal = e.id || e.codigo;

        const isSel = (optVal === currentVal || e.codigo === currentVal);

        htmlSide += `<option value="${optVal}" ${isSel ? "selected" : ""}>[${e.codigo}] ${e.nombre}</option>`;

      });

    }

    selSidebarCambio.innerHTML = htmlSide;

    const sideInputCod = document.getElementById("sidebar-input-codigo-edificio");

    if (sideInputCod) {

      sideInputCod.value = currentVal ? String(currentVal).replace(/^cj_/, '') : '';

    }

    if (currentVal) {

      selSidebarCambio.value = currentVal;

    }

  }



  // 2. Selector de Barra Superior #sel-conjunto (Dropdown interactivo con chevron para seleccionar edificio a administrar)
  const selConjunto = document.getElementById("sel-conjunto");
  if (selConjunto) {
    const activeCod = String(codigoSeleccionado || (typeof AppState !== "undefined" && (AppState.codigoEdificio || AppState.conjuntoId)) || selConjunto.value || "0361").replace(/^cj_/, "").trim();
    const activeId = activeCod ? ("cj_" + activeCod) : (typeof AppState !== "undefined" && AppState.conjuntoId ? AppState.conjuntoId : selConjunto.value);

    // Regla de plataforma: Los 2 primeros dígitos del código del edificio corresponden a los que tiene
    // cada administrador con sus edificios, y esos son los únicos que se deben mostrar arriba.
    const prefijoAdmin = activeCod.length >= 2 ? activeCod.slice(0, 2).toUpperCase() : "";

    let edificiosParaMostrar = [];
    if (prefijoAdmin) {
      edificiosParaMostrar = obtenerEdificiosPorPrefijoAdministrador(prefijoAdmin, activeCod);
    }
    if (!edificiosParaMostrar || edificiosParaMostrar.length === 0) {
      if (typeof AppState !== "undefined" && AppState.rol === "admin") {
        edificiosParaMostrar = obtenerEdificiosDeAdministrador(AppState.adminNombre, AppState.adminCedula, activeCod);
      } else {
        edificiosParaMostrar = typeof listaCopropiedadesSuperadmin !== "undefined" ? [...listaCopropiedadesSuperadmin] : [];
      }
    }

    const codigosVistos = new Set();
    let htmlCj = "";
    edificiosParaMostrar.forEach(c => {
      if (!c || !c.codigo) return;
      const codLimpio = String(c.codigo).trim();
      if (codigosVistos.has(codLimpio)) return;
      codigosVistos.add(codLimpio);

      const cId = c.id || ("cj_" + codLimpio);
      const isSel = (codLimpio.toLowerCase() === activeCod.toLowerCase() || cId.toLowerCase() === activeId.toLowerCase());
      htmlCj += `<option value="${cId}" ${isSel ? "selected" : ""} class="bg-slate-900 text-white font-semibold">${c.codigo} ${c.nombre.toUpperCase()}</option>`;
    });

    selConjunto.innerHTML = htmlCj;
    if (activeId) {
      selConjunto.value = activeId;
    }

    // Mantener sincronizado el span oculto para compatibilidad
    const topNombre = document.getElementById("top-header-edificio-nombre");
    if (topNombre) {
      const copActual = typeof obtenerDatosCopropiedad === "function" ? obtenerDatosCopropiedad(activeCod) : null;
      if (copActual) {
        topNombre.innerText = `${copActual.codigo} ${copActual.nombre.toUpperCase()}`;
      }
    }

    safeCreateIcons();
  }

  // 3. Selector de Carga Masiva Superadmin #sa-cargamasiva-select

  const selCM = document.getElementById("sa-cargamasiva-select");

  if (selCM) {

    const valCM = codigoSeleccionado || selCM.value || (typeof copropiedadCargaMasivaActiva !== "undefined" ? copropiedadCargaMasivaActiva : "");

    let htmlCM = "";

    listaCopropiedadesSuperadmin.forEach(c => {

      htmlCM += `<option value="${c.codigo}" ${c.codigo === valCM ? "selected" : ""}>[${c.codigo}] ${c.nombre}</option>`;

    });

    selCM.innerHTML = htmlCM;

    if (valCM) selCM.value = valCM;

  }



  // 4. Selector en Modal de Carga Masiva #modal-cm-select-edificio

  const selModalCM = document.getElementById("modal-cm-select-edificio");

  if (selModalCM) {

    const valMCM = codigoSeleccionado || selModalCM.value || "";

    let htmlMCM = "";

    listaCopropiedadesSuperadmin.forEach(c => {

      htmlMCM += `<option value="${c.codigo}" ${c.codigo === valMCM ? "selected" : ""}>[${c.codigo}] ${c.nombre}</option>`;

    });

    selModalCM.innerHTML = htmlMCM;

    if (valMCM) selModalCM.value = valMCM;

  }



  // 5. Selector en Modal Borrar Edificio #modal-borrar-select-edificio

  const selBorrar = document.getElementById("modal-borrar-select-edificio");

  if (selBorrar) {

    let htmlBorrar = "";

    listaCopropiedadesSuperadmin.forEach(c => {

      htmlBorrar += `<option value="${c.id || c.codigo}">[${c.codigo}] ${c.nombre} (${c.ciudad || 'Colombia'})</option>`;

    });

    selBorrar.innerHTML = htmlBorrar;

  }



  // 6. Selector de Drive #drive-select-edificio
  const selDrive = document.getElementById("drive-select-edificio");
  if (selDrive && typeof EDIFICIOS_CATALOGO_DRIVE !== "undefined") {
    const valDrive = selDrive.value || (typeof driveEdificioSeleccionado !== "undefined" ? driveEdificioSeleccionado : "0361");
    selDrive.innerHTML = Object.values(EDIFICIOS_CATALOGO_DRIVE).map(e => `
      <option value="${e.codigo}" ${e.codigo === valDrive ? 'selected' : ''}>
        ${e.codigo} • ${e.nombre} (${(e.ciudad || 'Colombia').split('•')[0].trim()})
      </option>
    `).join("");
    if (valDrive) selDrive.value = valDrive;

    // Sincronizar dinámicamente con el backend oficial
    try {
      fetch("/api/google-drive/edificios")
        .then(r => r.json())
        .then(lista => {
          if (Array.isArray(lista) && lista.length > 0) {
            let cambio = false;
            lista.forEach(e => {
              if (e && e.codigo && !EDIFICIOS_CATALOGO_DRIVE[e.codigo]) {
                EDIFICIOS_CATALOGO_DRIVE[e.codigo] = {
                  codigo: e.codigo,
                  nombre: e.nombre,
                  administrador: e.administrador || "Administración",
                  nit: e.nit || `900.${e.codigo}.000-1`,
                  banco: e.banco || "BANCOLOMBIA",
                  cuenta: e.cuenta || `Cta-${e.codigo}`,
                  direccion: e.direccion || "Dirección Oficial",
                  ciudad: e.ciudad || "Medellín • Antioquia",
                  anios: e.anios || [2026, 2025, 2024],
                  meses: (typeof LISTA_MESES_DRIVE !== "undefined" ? LISTA_MESES_DRIVE : ["ENERO","FEBRERO","MARZO","ABRIL","MAYO","JUNIO","JULIO","AGOSTO","SEPTIEMBRE","OCTUBRE","NOVIEMBRE","DICIEMBRE"])
                };
                cambio = true;
              }
            });
            if (cambio && selDrive) {
              const currentVal = selDrive.value || driveEdificioSeleccionado;
              selDrive.innerHTML = Object.values(EDIFICIOS_CATALOGO_DRIVE).map(e => `
                <option value="${e.codigo}" ${e.codigo === currentVal ? 'selected' : ''}>
                  ${e.codigo} • ${e.nombre} (${(e.ciudad || 'Colombia').split('•')[0].trim()})
                </option>
              `).join("");
              if (currentVal) selDrive.value = currentVal;
            }
          }
        }).catch(() => {});
    } catch(e) {}
  }

}



async function guardarCopropiedadGlobal(cop, unidades = []) {

  if (!cop || !cop.codigo) return false;

  const cod = String(cop.codigo).trim();

  cop.codigo = cod;

  if (!cop.id) cop.id = `cj_${cod}`;



  if (unidades && unidades.length > 0) {
    cop.unidades = unidades;
  }
  if (!cop.unidades || cop.unidades.length === 0) {
    if (typeof obtenerUnidadesRealesParaFusion === "function") {
      cop.unidades = obtenerUnidadesRealesParaFusion(cod, cop.nombre);
    } else {
      cop.unidades = [
        { unidad: "0101", propietario: cop.administrador || "ADMINISTRACIÓN", coeficiente: "100%", estado: "Al Día" }
      ];
    }
  }
  cop.inmueblesCount = cop.unidades.length;
  cop.inmueblesOcupados = cop.unidades.length;
  cop.censoCount = cop.unidades.length;

  const idx = listaCopropiedadesSuperadmin.findIndex(c => String(c.codigo).trim() === cod || c.id === cop.id);
  if (idx >= 0) {
    listaCopropiedadesSuperadmin[idx] = { ...listaCopropiedadesSuperadmin[idx], ...cop, unidades: cop.unidades };
  } else {
    listaCopropiedadesSuperadmin.unshift(cop);
  }



  try {

    localStorage.setItem("lefacturamos_copropiedades_custom", JSON.stringify(listaCopropiedadesSuperadmin));

  } catch (err) {

    console.warn("Error guardando en localStorage:", err);

  }



  if (typeof EDIFICIOS_CATALOGO_DRIVE !== "undefined") {

    EDIFICIOS_CATALOGO_DRIVE[cod] = {

      codigo: cod,

      nombre: cop.nombre,

      administrador: cop.administrador || "Administrador Designado",

      nit: cop.nit || "900.000.000-0",

      banco: cop.banco || "Bancolombia",

      cuenta: cop.cuenta || `Cta-${cod}`,

      direccion: cop.direccion || "Dirección Oficial",

      ciudad: cop.ciudad || "Colombia",

      anios: [2026, 2025, 2024],

      meses: (typeof LISTA_MESES_DRIVE !== "undefined") ? LISTA_MESES_DRIVE : ["ENERO", "FEBRERO", "MARZO", "ABRIL", "MAYO", "JUNIO", "JULIO", "AGOSTO", "SEPTIEMBRE", "OCTUBRE", "NOVIEMBRE", "DICIEMBRE"]

    };

  }



  if (typeof CATALOGO_ADMINISTRADORES_OFICIAL_EDIFICIO !== "undefined") {

    CATALOGO_ADMINISTRADORES_OFICIAL_EDIFICIO[cod] = {

      nombre: cop.nombre,

      administrador: cop.administrador || "Administrador Designado",

      telefono: cop.telefono || "3104445566",

      email: cop.email || `administracion${cod}@lefacturamos.com`,

      banco: cop.banco || "Bancolombia",

      cuenta: cop.cuenta || "",

      nit: cop.nit || ""

    };

  }



  actualizarTodosLosSelectsDeCopropiedad(cod);



  try {

    const urlApi = (typeof AppState !== "undefined" && AppState.apiBaseUrl) ? AppState.apiBaseUrl : "";

    await fetch(`${urlApi}/api/conjuntos`, {

      method: "POST",

      headers: { "Content-Type": "application/json" },

      body: JSON.stringify({

        codigo: cop.codigo,

        nombre: cop.nombre,

        tipo: cop.tipo || "Conjunto Residencial",

        nit: cop.nit || "900.000.000-0",

        direccion: cop.direccion || "",

        telefono: cop.telefono || "",

        email: cop.email || "",

        banco: cop.banco || "",

        tipo_cuenta: cop.tipoCuenta || "Ahorros",

        numero_cuenta: cop.cuenta || "",

        titular_cuenta: cop.nombre,

        bre_b_codigo_entidad: cop.breb || `BREB-${cod}`

      })

    });

  } catch (errApi) {

    console.log("Servidor backend local no disponible para sincronizar conjunto:", errApi);

  }



  return true;

}



async function sincronizarCopropiedadesBackend() {

  try {

    const urlApi = (typeof AppState !== "undefined" && AppState.apiBaseUrl) ? AppState.apiBaseUrl : "";

    const res = await fetch(`${urlApi}/api/conjuntos`);

    if (res.ok) {

      const data = await res.json();

      if (data && Array.isArray(data.conjuntos) && data.conjuntos.length > 0) {

        data.conjuntos.forEach(cj => {

          const cod = String(cj.codigo).trim();

          if (!cod) return;

          const idx = listaCopropiedadesSuperadmin.findIndex(c => String(c.codigo).trim() === cod || c.id === cj.id);
          if (idx !== -1) {
            if (cj.codigo_admin) listaCopropiedadesSuperadmin[idx].codigoAdmin = cj.codigo_admin;
            if (cj.password_admin) listaCopropiedadesSuperadmin[idx].passwordAdmin = cj.password_admin;
            if (cj.administrador) listaCopropiedadesSuperadmin[idx].administrador = cj.administrador;
            if (cj.activo !== undefined) listaCopropiedadesSuperadmin[idx].bloqueadoMora = !cj.activo;

            const cedLimpia = String(listaCopropiedadesSuperadmin[idx].cedulaAdmin || "").replace(/[^0-9a-zA-Z]/g, "");
            if (cedLimpia && typeof DIRECTORIO_ADMINISTRADORES !== "undefined") {
              if (!DIRECTORIO_ADMINISTRADORES[cedLimpia]) {
                const pref = cod.slice(0, 2);
                DIRECTORIO_ADMINISTRADORES[cedLimpia] = {
                  nombre: cj.administrador || listaCopropiedadesSuperadmin[idx].administrador,
                  cedula: typeof formatearCedulaConPuntos === "function" ? formatearCedulaConPuntos(cedLimpia) : cedLimpia,
                  codigoEdificio: cod,
                  nombreEdificio: (listaCopropiedadesSuperadmin[idx].nombre || "").replace(/DO[¥]A/g, "DOÑA"),
                  password: cj.password_admin || listaCopropiedadesSuperadmin[idx].passwordAdmin || "Admin123*",
                  edificios: typeof obtenerCodigosEdificiosPorPrefijo === "function" ? obtenerCodigosEdificiosPorPrefijo(pref) : [cod]
                };
              } else {
                if (cj.password_admin) DIRECTORIO_ADMINISTRADORES[cedLimpia].password = cj.password_admin;
                if (cj.administrador) DIRECTORIO_ADMINISTRADORES[cedLimpia].nombre = cj.administrador;
              }
            }
          } else {

            const uGen = (typeof obtenerUnidadesRealesParaFusion === "function") 

              ? obtenerUnidadesRealesParaFusion(cod, cj.nombre)

              : [{ unidad: "0101", propietario: "ADMINISTRACIÓN", coeficiente: "100%", estado: "Al Día" }];

            const nuevo = {

              id: cj.id || `cj_${cod}`,

              codigo: cod,

              nombre: cj.nombre,

              tipo: cj.tipo || "Conjunto Residencial",

              nit: cj.nit || "900.000.000-0",

              direccion: cj.direccion || `Copropiedad #${cod}`,

              ciudad: "Colombia",

              telefono: cj.telefono || "3104445566",

              email: cj.email || `administracion${cod}@lefacturamos.com`,

              banco: cj.banco || "Bancolombia",

              tipoCuenta: cj.tipo_cuenta || "Ahorros",

              cuenta: cj.numero_cuenta || "",

              breb: cj.bre_b_codigo_entidad || `BREB-${cod}`,

              pasarela: `Wompi (pub_${cod})`,

              codigoAdmin: cj.codigo_admin || `ADM-${cod}`,

              passwordAdmin: cj.password_admin || "Admin123*",

              administrador: cj.administrador || cj.titular_cuenta || "Administrador",

              inmueblesCount: uGen.length,

              inmueblesOcupados: uGen.length,

              censoCount: uGen.length,

              estado: "A Paz y Salvo",

              bloqueadoMora: false,

              unidades: uGen

            };

            listaCopropiedadesSuperadmin.push(nuevo);

          }

        });

        try {
          localStorage.setItem("lefacturamos_copropiedades_custom", JSON.stringify(listaCopropiedadesSuperadmin));
          if (typeof DIRECTORIO_ADMINISTRADORES !== "undefined") {
            localStorage.setItem("lefacturamos_directorio_admins", JSON.stringify(DIRECTORIO_ADMINISTRADORES));
          }
        } catch (e) {}



        actualizarTodosLosSelectsDeCopropiedad();

        if (typeof renderizarCopropiedadesSuperadmin === "function") {

          renderizarCopropiedadesSuperadmin();

        }

      }

    }

  } catch (err) {

    // Offline / Standalone APK

  }

}



