function obtenerDatosCopropiedad(codigoOId) {

  if (!codigoOId) return null;

  const limpio = String(codigoOId).trim();

  const limpioSinCj = limpio.replace(/^cj_/, "");

  

  // 1. Sincronizar desde localStorage si hay datos custom actualizados
  try {
    const customStr = localStorage.getItem("lefacturamos_copropiedades_custom");
    if (customStr) {
      const parsedCustom = JSON.parse(customStr);
      if (Array.isArray(parsedCustom)) {
        parsedCustom.forEach(cGuardada => {
          if (!cGuardada || !cGuardada.codigo) return;
          const codG = String(cGuardada.codigo).trim();
          const idxG = listaCopropiedadesSuperadmin.findIndex(c => String(c.codigo).trim() === codG || c.id === cGuardada.id);
          if (idxG >= 0) {
            if (cGuardada.passwordAdmin) listaCopropiedadesSuperadmin[idxG].passwordAdmin = cGuardada.passwordAdmin;
            if (cGuardada.administrador) listaCopropiedadesSuperadmin[idxG].administrador = cGuardada.administrador;
            if (cGuardada.cedulaAdmin) listaCopropiedadesSuperadmin[idxG].cedulaAdmin = cGuardada.cedulaAdmin;
            if (cGuardada.codigoAdmin) listaCopropiedadesSuperadmin[idxG].codigoAdmin = cGuardada.codigoAdmin;
            if (cGuardada.unidades && Array.isArray(cGuardada.unidades) && cGuardada.unidades.length > 0) {
              listaCopropiedadesSuperadmin[idxG].unidades = cGuardada.unidades;
              listaCopropiedadesSuperadmin[idxG].inmueblesCount = cGuardada.unidades.length;
              listaCopropiedadesSuperadmin[idxG].inmueblesOcupados = cGuardada.unidades.length;
              listaCopropiedadesSuperadmin[idxG].censoCount = cGuardada.unidades.length;
            }
          }
        });
      }
    }
  } catch(e) {}

  // 1. Buscar en listaCopropiedadesSuperadmin

  let cop = listaCopropiedadesSuperadmin.find(c => 

    (c.codigo && c.codigo.toLowerCase() === limpio.toLowerCase()) ||

    (c.id && c.id.toLowerCase() === limpio.toLowerCase()) ||

    (c.codigo && c.codigo.toLowerCase() === limpioSinCj.toLowerCase()) ||

    (c.id && c.id.toLowerCase() === ("cj_" + limpioSinCj).toLowerCase()) ||

    (c.aliasCodigo && c.aliasCodigo.toLowerCase() === limpioSinCj.toLowerCase())

  );

    if (cop) {
      if (cop.unidades && cop.unidades.length > 0 && cop.unidades[0].actual !== undefined) {
        // Preservar unidades actualizadas en memoria
      } else if (limpioSinCj === "0361") {
        cop.unidades = (typeof getUnidadesDonaRosa0361Master === "function") ? getUnidadesDonaRosa0361Master() : [];
        cop.inmueblesCount = 12;
        cop.inmueblesOcupados = 12;
        cop.censoCount = 12;
        cop.coeficienteTotal = "100.000%";
      } else if (limpioSinCj === "0950") {
        cop.unidades = (typeof getUnidadesFortaleza0950Master === "function") ? getUnidadesFortaleza0950Master() : [];
        cop.coeficienteTotal = "0.000%";
      } else if (limpioSinCj === "4159") {
        cop.unidades = (typeof getUnidadesFrontera4159Master === "function") ? getUnidadesFrontera4159Master() : [];
        cop.inmueblesCount = cop.unidades.length;
        cop.inmueblesOcupados = cop.unidades.length;
        cop.censoCount = cop.unidades.length;
        cop.coeficienteTotal = "100.000%";
      } else if (limpioSinCj === "4160") {
        cop.unidades = (typeof getUnidadesRiachuelo4160Master === "function") ? getUnidadesRiachuelo4160Master() : [];
      } else if (limpioSinCj === "4901") {
        cop.unidades = (typeof getUnidadesRobleAlto4901Master === "function") ? getUnidadesRobleAlto4901Master() : [];
      } else if (limpioSinCj === "7480") {
        cop.unidades = (typeof getUnidadesManchester7480Master === "function") ? getUnidadesManchester7480Master() : [];
      } else if ((!cop.unidades || cop.unidades.length === 0) && typeof obtenerUnidadesRealesParaFusion === "function") {
        cop.unidades = obtenerUnidadesRealesParaFusion(cop.codigo, cop.nombre);
      }

    if (cop.unidades && cop.unidades.length > 0) {

      cop.inmueblesCount = cop.unidades.length;

      cop.inmueblesOcupados = cop.unidades.length;

      cop.censoCount = cop.unidades.length;

    }

    return cop;

  }  // 1b. Buscar en CATALOGO_OFICIAL_DBPLUS (248 Edificios Reales de C:\dbplus\EDIFICIO.DBF)

  if (typeof CATALOGO_OFICIAL_DBPLUS !== "undefined") {

    let dbpEdif = CATALOGO_OFICIAL_DBPLUS[limpio] || CATALOGO_OFICIAL_DBPLUS[limpioSinCj];

    if (dbpEdif) {

      const unidadesReales = (dbpEdif.codigo === "0950" && typeof getUnidadesFortaleza0950Master === "function")
        ? getUnidadesFortaleza0950Master()
        : ((typeof obtenerUnidadesRealesParaFusion === "function") 
          ? obtenerUnidadesRealesParaFusion(dbpEdif.codigo, dbpEdif.nombre) 
          : []);

      const numU = (unidadesReales && unidadesReales.length > 0) ? unidadesReales.length : (dbpEdif.codigo === "4901" ? 83 : (dbpEdif.codigo === "0950" ? 16 : 30));

      const nuevo = {

        id: "cj_" + dbpEdif.codigo,

        nombre: dbpEdif.nombre,

        codigo: dbpEdif.codigo,

        nit: dbpEdif.nit || "900.000.000-0",

        direccion: dbpEdif.direccion || `Sede ${dbpEdif.nombre}`,

        ciudad: dbpEdif.ciudad || "Medellín • Antioquia",

        tipo: dbpEdif.tipo || "Propiedad Horizontal",

        banco: dbpEdif.banco || "BANCOLOMBIA AHO",

        tipoCuenta: dbpEdif.tipoCuenta || "Ahorros",

        cuenta: dbpEdif.cuenta || "",

        breb: `BREB-BAN-${dbpEdif.codigo}`,

        pasarela: `Wompi (pub_prod_${dbpEdif.codigo})`,

        codigoAdmin: `ADM-${dbpEdif.codigo}`,

        passwordAdmin: "Admin123*",

        administrador: dbpEdif.administrador || "Administrador",

        telefono: dbpEdif.telefono || "",

        email: dbpEdif.email || "",

        interesMora: dbpEdif.interesMora || "2.118%",

        inmueblesCount: numU,

        inmueblesOcupados: numU,

        censoCount: numU,

        vehiculosAuditoria: 5,

        reservasConfirmadas: 2,

        pqrAtencion: 1,

        coeficienteTotal: (dbpEdif.codigo === "0950" || dbpEdif.coeficienteTotal === "0.000%") ? "0.000%" : (dbpEdif.coeficienteTotal || "100.000%"),

        recaudoTotal: "$36.000.000",

        recaudoPagos: `${numU} pagos procesados`,

        carteraPendiente: "$5.000.000",

        totalFinalEdificio: "$41.000.000",

        carteraInmuebles: "5 inmuebles con saldo",

        carteraVencida: "$2.000.000",

        carteraJuridica: "0 cuentas en mora jurídica",

        estado: "A Paz y Salvo",

        bloqueadoMora: false,

        unidades: unidadesReales

      };

      return nuevo;

    }

  }



  // 2. Buscar en EDIFICIOS_CATALOGO_DRIVE

  if (typeof EDIFICIOS_CATALOGO_DRIVE !== "undefined") {

    let driveEdif = EDIFICIOS_CATALOGO_DRIVE[limpio] || EDIFICIOS_CATALOGO_DRIVE[limpioSinCj];

    if (driveEdif) {

      return {

        id: "cj_" + driveEdif.codigo,

        nombre: driveEdif.nombre,

        codigo: driveEdif.codigo,

        nit: driveEdif.nit || "900.000.000-0",

        direccion: driveEdif.direccion || `Copropiedad #${driveEdif.codigo}`,

        ciudad: driveEdif.ciudad || "Medellín • Antioquia",

        tipo: "Propiedad Horizontal",

        banco: driveEdif.banco || "BANCOLOMBIA AHO",

        tipoCuenta: "Ahorros",

        cuenta: driveEdif.cuenta || "10022286922",

        breb: `BREB-BAN-${driveEdif.codigo}`,

        pasarela: `Wompi (pub_prod_${driveEdif.codigo})`,

        codigoAdmin: `ADM-${driveEdif.codigo}`,

        passwordAdmin: "Admin123*",

        administrador: "Administrador Copropiedad",

        inmueblesCount: 44,

        inmueblesOcupados: 44,

        censoCount: 44,

        vehiculosAuditoria: 5,

        reservasConfirmadas: 2,

        pqrAtencion: 1,

        coeficienteTotal: (dbpEdif.codigo === "0950" || dbpEdif.coeficienteTotal === "0.000%") ? "0.000%" : (dbpEdif.coeficienteTotal || "100.000%"),

        recaudoTotal: "$12.000.000",

        recaudoPagos: "44 pagos procesados",

        carteraPendiente: "$5.000.000",

        totalFinalEdificio: "$17.000.000",

        carteraInmuebles: "5 inmuebles con saldo",

        carteraVencida: "$2.000.000",

        carteraJuridica: "0 cuentas en mora jurídica",

        estado: "A Paz y Salvo",

        bloqueadoMora: false,

        unidades: (typeof obtenerUnidadesRealesParaFusion === "function") 

          ? obtenerUnidadesRealesParaFusion(driveEdif.codigo, driveEdif.nombre) 

          : []

      };

    }

  }



  // Si no existe en las bases de datos registradas, retornar null (NUNCA crear edificio ficticio)
  return null;
}



function actualizarPreviewEdificioLogin(codigo) {

  sincronizarPoliticaDatosEdificio(codigo);

  const codLimpio = String(codigo || "").trim();

  const previewBadge = document.getElementById("login-preview-badge");

  const previewNombre = document.getElementById("login-preview-nombre");

  const previewDetalles = document.getElementById("login-preview-detalles");

  const previewStatus = document.getElementById("login-preview-status");

  const previewIconWrapper = document.getElementById("login-preview-icon-wrapper");

  const inputCodUsuario = document.getElementById("login-codigo-usuario");

  const selectEdificio = document.getElementById("login-edificio-select");



  if (!codLimpio || codLimpio === "0" || codLimpio === "0000") {

    if (previewBadge) {

      previewBadge.innerText = "0000";

      previewBadge.className = "px-1.5 py-0.5 rounded bg-slate-800 border border-slate-700 text-[10px] font-mono font-bold text-slate-400";

    }

    if (previewNombre) {

      previewNombre.innerText = "Ingrese el código de la copropiedad";

      previewNombre.className = "font-bold text-slate-400 truncate text-xs sm:text-sm";

    }

    if (previewDetalles) {

      previewDetalles.innerText = "Escriba el código de 4 dígitos (ej: 5304, 7480, 0127) o elíjalo en la lista para validar.";

    }

    if (previewStatus) {

      previewStatus.innerText = "En espera";

      previewStatus.className = "shrink-0 text-[10px] font-bold text-slate-500 bg-slate-900 border border-slate-800 px-2 py-1 rounded-lg";

    }

    if (previewIconWrapper) {

      previewIconWrapper.className = "w-9 h-9 rounded-xl bg-slate-800 border border-slate-700 flex items-center justify-center text-slate-400 shrink-0";

    }

    if (selectEdificio && selectEdificio.value !== "") {

      selectEdificio.value = "";

    }

    if (inputCodUsuario && rolSeleccionadoLogin === "admin") {

      inputCodUsuario.value = "";

      inputCodUsuario.placeholder = "Código de Administrador (ej: ADM-4901)";

    }

    return;

  }



  // Sincronizar el select si tiene este valor

  if (selectEdificio) {

    const optExiste = Array.from(selectEdificio.options).some(o => o.value === codLimpio);

    if (optExiste) {

      selectEdificio.value = codLimpio;

    } else {

      selectEdificio.value = "";

    }

  }



  // Actualizar placeholder de usuario según rol y código sin sobreescribir valor

  if (inputCodUsuario) {
    if (rolSeleccionadoLogin === "admin") {
      const copPreview = (typeof obtenerDatosCopropiedad === "function") ? obtenerDatosCopropiedad(codLimpio) : null;
      const codAdmSugerido = (copPreview && copPreview.codigoAdmin) ? copPreview.codigoAdmin : `ADM-${codLimpio}`;
      const claveSugerida = (copPreview && copPreview.passwordAdmin) ? copPreview.passwordAdmin : "Admin123*";
      inputCodUsuario.placeholder = `Código de Administrador (ej: ${codAdmSugerido})`;
      const hintDemo = document.getElementById("login-demo-hint");
      if (hintDemo) {
        hintDemo.innerText = `Clave: ${claveSugerida}`;
      }
    } else if (rolSeleccionadoLogin === "porteria") {

      inputCodUsuario.placeholder = "Portería Principal (24 Horas)";

      if (!inputCodUsuario.value) inputCodUsuario.value = "Portería Principal";

    } else if (rolSeleccionadoLogin === "residente") {

      inputCodUsuario.placeholder = "Ej: 0301, 101, Local 1";

    }

  }



  // Buscar información de la copropiedad

  const copropiedad = obtenerDatosCopropiedad(codLimpio);



  if (copropiedad) {

    if (previewBadge) {

      previewBadge.innerText = copropiedad.codigo;

      previewBadge.className = "px-1.5 py-0.5 rounded bg-emerald-950 border border-emerald-500/50 text-[10px] font-mono font-bold text-emerald-400 shadow-sm";

    }

    if (previewNombre) {

      previewNombre.innerText = copropiedad.nombre;

      previewNombre.className = "font-extrabold text-white truncate text-xs sm:text-sm";

    }

    if (previewDetalles) {

      const bancoInfo = copropiedad.banco ? ` • Banco: ${copropiedad.banco}` : "";

      const ciudadInfo = copropiedad.ciudad ? ` • ${copropiedad.ciudad}` : "";

      previewDetalles.innerText = `NIT: ${copropiedad.nit}${bancoInfo}${ciudadInfo}`;

    }

    if (previewStatus) {

      previewStatus.innerText = "✓ Copropiedad Verificada";

      previewStatus.className = "shrink-0 text-[10px] font-bold text-emerald-400 bg-emerald-950/80 border border-emerald-500/40 px-2 py-1 rounded-lg flex items-center gap-1 shadow-sm";

    }

    if (previewIconWrapper) {

      previewIconWrapper.className = "w-9 h-9 rounded-xl bg-emerald-500/20 border border-emerald-500/40 flex items-center justify-center text-emerald-300 shrink-0";

    }



    // Sincronizar inmediatamente la barra superior con el edificio ingresado

    AppState.codigoEdificio = copropiedad.codigo;

    AppState.conjuntoId = copropiedad.id;

    const selConjunto = document.getElementById("sel-conjunto");

    if (selConjunto) {

      let optCoincidente = Array.from(selConjunto.options).find(o => o.value === copropiedad.id || o.value === copropiedad.codigo || o.value === `cj_${copropiedad.codigo}`);

      if (!optCoincidente) {

        const nuevaOpt = document.createElement("option");

        nuevaOpt.value = copropiedad.id;

        nuevaOpt.text = `${copropiedad.codigo} ${copropiedad.nombre}`;

        selConjunto.appendChild(nuevaOpt);

        selConjunto.value = copropiedad.id;

      } else {

        selConjunto.value = optCoincidente.value;

      }

    }

    const topCiudad = document.getElementById("top-header-ciudad");

    if (topCiudad) topCiudad.innerText = copropiedad.ciudad || "Medellín • Antioquia";

    if (rolSeleccionadoLogin === "admin") {

      sincronizarAdministradorEdificio(copropiedad.codigo);

    }

  } else {
    // Codigo no existe en el sistema: CODIGO INCORRECTO (nunca crear edificio ficticio)
    if (previewBadge) {
      previewBadge.innerText = codLimpio;
      previewBadge.className = "px-1.5 py-0.5 rounded bg-rose-950 border border-rose-500/50 text-[10px] font-mono font-bold text-rose-400 shadow-sm";
    }
    if (previewNombre) {
      previewNombre.innerText = "Código Incorrecto";
      previewNombre.className = "font-bold text-rose-400 truncate text-xs sm:text-sm";
    }
    if (previewDetalles) {
      previewDetalles.innerText = "El código ingresado no corresponde a ningún edificio registrado en la plataforma.";
    }
    if (previewStatus) {
      previewStatus.innerText = "⚠️ Código Incorrecto";
      previewStatus.className = "shrink-0 text-[10px] font-bold text-rose-400 bg-rose-950/80 border border-rose-500/40 px-2 py-1 rounded-lg flex items-center gap-1 shadow-sm";
    }
    if (previewIconWrapper) {
      previewIconWrapper.className = "w-9 h-9 rounded-xl bg-rose-500/20 border border-rose-500/40 flex items-center justify-center text-rose-400 shrink-0";
    }
  }

}



// ==============================================================================

// GESTIÓN DE CONTRASEÑA DE PORTERÍA POR LA ADMINISTRACIÓN

// ==============================================================================

function obtenerClavePorteria(codigoEdificio) {

  const cod = String(codigoEdificio || (typeof AppState !== "undefined" && AppState.codigoEdificio) || "4901").replace(/^cj_/, "").trim();

  const guardada = localStorage.getItem(`clave_porteria_${cod}`);

  if (guardada) return guardada;

  return "Porteria123*";

}



async function guardarClavePorteria(codigoEdificio, nuevaClave) {

  const cod = String(codigoEdificio || (typeof AppState !== "undefined" && AppState.codigoEdificio) || "4901").replace(/^cj_/, "").trim();

  const claveLimpia = String(nuevaClave || "").trim();

  if (!claveLimpia) {

    if (typeof mostrarToast === "function") mostrarToast("⚠️ Por favor escriba una contraseña válida para la portería.", "warning");

    return false;

  }

  if (claveLimpia.length < 4) {

    if (typeof mostrarToast === "function") mostrarToast("⚠️ La contraseña debe tener al menos 4 caracteres.", "warning");

    return false;

  }

  

  localStorage.setItem(`clave_porteria_${cod}`, claveLimpia);



  // Sincronizar con backend si está disponible

  try {

    const apiBase = (typeof AppState !== "undefined" && AppState.apiBaseUrl) || (typeof getApiBaseUrl === "function" ? getApiBaseUrl() : "http://127.0.0.1:8000");

    await fetch(`${apiBase}/api/conjuntos/cj_${cod}/clave-porteria`, {

      method: "PUT",

      headers: { "Content-Type": "application/json" },

      body: JSON.stringify({ clave: claveLimpia })

    });

  } catch (e) {

    console.log("Aviso sincronizando clave porteria backend:", e);

  }



  sincronizarClavePorteriaAdmin(cod);

  if (typeof mostrarToast === "function") {

    mostrarToast(`🔐 Contraseña de portería guardada para el edificio #${cod}.`);

  }

  return true;

}



function guardarClavePorteriaAdmin() {

  const inp = document.getElementById("admin-input-clave-porteria");

  const cod = (typeof AppState !== "undefined" && AppState.codigoEdificio) || "4901";

  if (!inp) return;

  const exito = guardarClavePorteria(cod, inp.value);

  if (exito) {

    const badge = document.getElementById("badge-vigilancia-status");

    if (badge) {

      badge.innerHTML = `<span class="w-2 h-2 rounded-full bg-emerald-400 animate-pulse"></span><span>Clave Actualizada (${inp.value.length} car.)</span>`;

    }

  }

}



function sincronizarClavePorteriaAdmin(codigoEdificio) {

  const cod = String(codigoEdificio || (typeof AppState !== "undefined" && AppState.codigoEdificio) || "4901").replace(/^cj_/, "").trim();

  const inp = document.getElementById("admin-input-clave-porteria");

  const lblEdif = document.getElementById("lbl-admin-edificio-clave-porteria");

  

  const claveActual = obtenerClavePorteria(cod);

  if (inp) inp.value = claveActual;



  const copropiedad = (typeof obtenerDatosCopropiedad === "function") ? obtenerDatosCopropiedad(cod) : null;

  const nomEdif = copropiedad ? copropiedad.nombre : `EDIFICIO #${cod}`;

  if (lblEdif) lblEdif.innerText = `${cod} - ${nomEdif}`;

}



function toggleClavePorteriaAdminVisibilidad() {

  const inp = document.getElementById("admin-input-clave-porteria");

  const eye = document.getElementById("btn-toggle-eye-porteria-admin");

  if (!inp) return;

  if (inp.type === "password") {

    inp.type = "text";

    if (eye) eye.setAttribute("data-lucide", "eye-off");

  } else {

    inp.type = "password";

    if (eye) eye.setAttribute("data-lucide", "eye");

  }

  safeCreateIcons();

}



function copiarClavePorteriaParaGuardas() {

  const cod = (typeof AppState !== "undefined" && AppState.codigoEdificio) || "4901";

  const clave = obtenerClavePorteria(cod);

  if (navigator && navigator.clipboard && navigator.clipboard.writeText) {

    navigator.clipboard.writeText(clave).then(() => {

      mostrarToast(`📋 Contraseña de portería (${clave}) copiada al portapapeles.`);

    }).catch(() => {

      mostrarToast(`Clave de portería: ${clave}`);

    });

  } else {

    mostrarToast(`Clave de portería: ${clave}`);

  }

}



