function abrirManualRol(rol) {
  const modal = document.getElementById("modal-manuales-sistema");
  if (!modal) {
    console.warn("Modal de manuales no encontrado en DOM");
    return;
  }

  // Determinar rol del módulo activo (por defecto el rol que se pase, o AppState.rol, o admin)
  let rolObjetivo = rol;
  if (!rolObjetivo) {
    if (typeof AppState !== "undefined" && AppState.rol) {
      rolObjetivo = AppState.rol;
    } else if (typeof rolActual !== "undefined" && rolActual) {
      rolObjetivo = rolActual;
    } else {
      rolObjetivo = "admin";
    }
  }

  // En cada módulo SOLO se muestra el manual correspondiente a ese módulo
  // y se ocultan los selectores / pestañas de otros manuales para no mostrar todos los iconos
  rolManualActivo = rolObjetivo;
  modal.classList.remove("hidden");

  // Ocultar barra de selectores por rol para que solo quede el manual de este módulo
  const selectorTabs = document.getElementById("selector-tabs-manuales");
  if (selectorTabs) {
    selectorTabs.classList.add("hidden");
  }

  // Configuración visual personalizada del manual del módulo
  const cfg = CONFIG_MANUAL_POR_ROL[rolObjetivo] || CONFIG_MANUAL_POR_ROL.admin;

  const lblTitulo = document.getElementById("modal-manual-titulo");
  if (lblTitulo) lblTitulo.textContent = cfg.titulo;

  const lblSubtitulo = document.getElementById("modal-manual-subtitulo");
  if (lblSubtitulo) lblSubtitulo.textContent = cfg.subtitulo;

  const badgeRol = document.getElementById("modal-manual-badge-rol");
  if (badgeRol) {
    badgeRol.textContent = cfg.badge;
    badgeRol.className = `px-2.5 py-0.5 rounded-full ${cfg.badgeBg} ${cfg.badgeText} border ${cfg.badgeBorder} text-[10px] font-black uppercase tracking-wider`;
  }

  const iconBox = document.getElementById("modal-manual-icono-box");
  if (iconBox) {
    iconBox.className = `w-12 h-12 rounded-2xl ${cfg.colorFondo} border ${cfg.colorBorde} flex items-center justify-center ${cfg.colorTexto} shrink-0 shadow-inner`;
    iconBox.innerHTML = `<i data-lucide="${cfg.icono}" class="w-6 h-6"></i>`;
  }

  const inputBuscar = document.getElementById("input-buscar-manual");
  if (inputBuscar) {
    inputBuscar.placeholder = cfg.placeholder;
    inputBuscar.value = "";
  }

  // Mostrar ÚNICAMENTE la sección del manual correspondiente a este módulo
  const tabs = ["superadmin", "admin", "residente", "porteria"];
  tabs.forEach(t => {
    const sec = document.getElementById(`manual-seccion-${t}`);
    if (sec) {
      if (t === rolObjetivo) {
        sec.classList.remove("hidden");
      } else {
        sec.classList.add("hidden");
      }
    }
  });

  const scrollCont = document.getElementById("manual-contenido-scroll");
  if (scrollCont) {
    scrollCont.scrollTop = 0;
  }

  if (typeof safeCreateIcons === "function") {
    safeCreateIcons();
  }
}

