// ==============================================================================
// CONTROL DE ACCESO POR MORA EN SERVICIO LEFACTURAMOS (LEY 675 / LEY 1581)
// ==============================================================================
function verificarCopropiedadBloqueadaPorMora(codigo) {
  const codLimpio = String(codigo || "").replace(/^cj_/, "").trim();
  if (!codLimpio) return false;

  // 1. Revisar override en localStorage
  try {
    const guardado = localStorage.getItem(`lefacturamos_bloqueo_${codLimpio}`);
    if (guardado === "bloqueado") return true;
    if (guardado === "activo") return false;
  } catch (e) {}

  // 2. Revisar en listaCopropiedadesSuperadmin
  if (typeof listaCopropiedadesSuperadmin !== "undefined") {
    const cop = listaCopropiedadesSuperadmin.find(c => 
      String(c.codigo).trim() === codLimpio || 
      String(c.id).trim() === `cj_${codLimpio}` ||
      String(c.id).trim() === codLimpio
    );
    if (cop && (cop.bloqueadoMora === true || cop.activo === 0 || cop.activo === false)) {
      return true;
    }
  }

  // 3. Revisar en catalogo de edificios
  if (typeof EDIFICIOS_CATALOGO_DRIVE !== "undefined" && EDIFICIOS_CATALOGO_DRIVE[codLimpio]) {
    if (EDIFICIOS_CATALOGO_DRIVE[codLimpio].bloqueadoMora === true) return true;
  }

  return false;
}

function mostrarAvisoBloqueoResidente(codigo, apto) {
  // 1. Toast oficial con el texto exacto exigido
  mostrarToast("⚠️ SI TIENES PROBLEMAS PARA ENTRAR COMUNICATE CON LA ADMINISTRACION", "warning");

  // 2. Modal centrado de aviso al copropietario
  const modal = document.getElementById("modal-aviso-bloqueo-residente");
  if (modal) {
    modal.classList.remove("hidden");
    safeCreateIcons();
  }

  // 3. Banner visible en la pantalla de entrada
  const alerta = document.getElementById("login-alerta-bloqueo-residente");
  if (alerta) {
    alerta.classList.remove("hidden");
    safeCreateIcons();
  }
}

function cerrarModalAvisoBloqueoResidente() {
  const modal = document.getElementById("modal-aviso-bloqueo-residente");
  if (modal) {
    modal.classList.add("hidden");
  }
}

function bloquearCopropiedadLefacturamos(codigo) {
  const codLimpio = String(codigo || "").replace(/^cj_/, "").trim();
  if (typeof listaCopropiedadesSuperadmin !== "undefined") {
    const cop = listaCopropiedadesSuperadmin.find(c => String(c.codigo).trim() === codLimpio || String(c.id).trim() === `cj_${codLimpio}`);
    if (cop) {
      cop.bloqueadoMora = true;
      cop.estado = "Bloqueado por Mora";
    }
  }
  try {
    localStorage.setItem(`lefacturamos_bloqueo_${codLimpio}`, "bloqueado");
  } catch (e) {}
  try {
    fetch(`/api/conjuntos/${encodeURIComponent(codLimpio)}/toggle-bloqueo`, { method: "POST" });
  } catch (e) {}
  if (typeof renderizarCopropiedadesSuperadmin === "function") {
    renderizarCopropiedadesSuperadmin();
  }
  console.log(`[Lefacturamos] Copropiedad ${codLimpio} bloqueada por mora en servicio.`);
}

function desbloquearCopropiedadLefacturamos(codigo) {
  const codLimpio = String(codigo || "").replace(/^cj_/, "").trim();
  if (typeof listaCopropiedadesSuperadmin !== "undefined") {
    const cop = listaCopropiedadesSuperadmin.find(c => String(c.codigo).trim() === codLimpio || String(c.id).trim() === `cj_${codLimpio}`);
    if (cop) {
      cop.bloqueadoMora = false;
      cop.estado = "A Paz y Salvo";
    }
  }
  try {
    localStorage.setItem(`lefacturamos_bloqueo_${codLimpio}`, "activo");
  } catch (e) {}
  try {
    fetch(`/api/conjuntos/${encodeURIComponent(codLimpio)}/toggle-bloqueo`, { method: "POST" });
  } catch (e) {}
  if (typeof renderizarCopropiedadesSuperadmin === "function") {
    renderizarCopropiedadesSuperadmin();
  }
  console.log(`[Lefacturamos] Copropiedad ${codLimpio} desbloqueada a paz y salvo.`);
}

function loginPantallaEntrada() {

  if (rolSeleccionadoLogin === "superadmin") {
    if (typeof accesoDirectoSuperadmin === "function") {
      accesoDirectoSuperadmin();
      return;
    }
  }

  // ACCESO ADMINISTRADOR: Solo con Cédula/Identificación y Contraseña
  if (rolSeleccionadoLogin === "admin") {
    const inputCedula = document.getElementById("login-admin-cedula");
    const cedulaRaw = inputCedula ? inputCedula.value.trim() : "";
    const cedulaLimpia = cedulaRaw.replace(/[^0-9a-zA-Z]/g, "").trim();

    if (!cedulaLimpia) {
      if (typeof mostrarToast === "function") {
        mostrarToast("⚠️ Por favor ingresa tu cédula o identificación de Administrador.", "warning");
      }
      if (inputCedula) inputCedula.focus();
      return;
    }

    const adminDetectado = buscarAdministradorPorCedula(cedulaLimpia);
    if (!adminDetectado) {
      if (typeof mostrarToast === "function") {
        mostrarToast("⚠️ Cédula no registrada como Administrador. Verifique el número ingresado.", "error");
      }
      if (inputCedula) inputCedula.focus();
      return;
    }

    const inputPass = document.getElementById("login-password");
    let password = inputPass?.value.trim() || "";
    if (!password) {
      if (typeof mostrarToast === "function") {
        mostrarToast("⚠️ Por favor ingresa la contraseña de administración.", "warning");
      }
      if (inputPass) inputPass.focus();
      return;
    }

    const passClean = password.trim();
    const codEdif = adminDetectado.codigoEdificio || "0950";
    
    // Obtener la contraseña oficial configurada para este edificio
    let claveEsperada = adminDetectado.password ? String(adminDetectado.password).trim() : "";
    if (typeof obtenerDatosCopropiedad === "function") {
      const cop = obtenerDatosCopropiedad(codEdif);
      if (cop && cop.passwordAdmin) {
        claveEsperada = String(cop.passwordAdmin).trim();
      }
    }
    if (!claveEsperada) {
      claveEsperada = "Admin123*";
    }

    // Colección de claves administrativas autorizadas para este edificio y administrador
    const clavesValidas = new Set(["Admin123*"]);
    if (claveEsperada) clavesValidas.add(claveEsperada);
    if (adminDetectado && adminDetectado.password) clavesValidas.add(String(adminDetectado.password).trim());
    if (typeof obtenerDatosCopropiedad === "function") {
      const cop = obtenerDatosCopropiedad(codEdif);
      if (cop) {
        if (cop.passwordAdmin) clavesValidas.add(String(cop.passwordAdmin).trim());
        if (cop.codigoAdmin) clavesValidas.add(String(cop.codigoAdmin).trim());
      }
    }
    if (codEdif === "4901" || (typeof cedulaLimpia !== "undefined" && cedulaLimpia === "42772924")) {
      clavesValidas.add("sofia1309");
    }
    try {
      const customStr = localStorage.getItem("lefacturamos_copropiedades_custom");
      if (customStr) {
        const parsed = JSON.parse(customStr);
        const copG = parsed.find(c => c && (String(c.codigo).trim() === codEdif || String(c.id).trim() === "cj_" + codEdif));
        if (copG) {
          if (copG.passwordAdmin) clavesValidas.add(String(copG.passwordAdmin).trim());
          if (copG.codigoAdmin) clavesValidas.add(String(copG.codigoAdmin).trim());
        }
      }
      const dirAdminsStr = localStorage.getItem("lefacturamos_directorio_admins");
      if (dirAdminsStr) {
        const parsedDir = JSON.parse(dirAdminsStr);
        if (parsedDir && parsedDir[cedulaLimpia] && parsedDir[cedulaLimpia].password) {
          clavesValidas.add(String(parsedDir[cedulaLimpia].password).trim());
        }
      }
    } catch(e) {}

    const esClaveAdminValida = clavesValidas.has(passClean);

    if (!esClaveAdminValida) {
      if (typeof mostrarToast === "function") {
        mostrarToast("⚠️ Contraseña de administración incorrecta.", true);
      }
      if (inputPass) inputPass.focus();
      return;
    }

    try {
      localStorage.setItem("lefacturamos_admin_cedula", cedulaRaw);
      localStorage.setItem("lefacturamos_active_building", codEdif);
    } catch(e) {}

    AppState.rol = "admin";
    AppState.codigoEdificio = codEdif;
    AppState.conjuntoId = "cj_" + codEdif;
    AppState.adminCedula = cedulaLimpia;
    AppState.adminNombre = adminDetectado.nombre;

    AppState.pendingAdminLogin = {
      codigoEdificio: codEdif,
      codigoUsuario: adminDetectado.nombre,
      password: password
    };

    const lblEdif = document.getElementById("modal-aviso-admin-edificio");
    if (lblEdif) {
      lblEdif.textContent = `(${codEdif} - ${adminDetectado.nombreEdificio || adminDetectado.nombre})`;
    }

    mostrarModalAvisoFacturacionAdmin();
    return;
  }

  const inputEdif = document.getElementById("login-edificio-codigo");

  let codigoEdificio = inputEdif?.value.trim() || "";

  const codLimpioGlobal = String(codigoEdificio || "4901").replace(/^(cj_)+/, "").trim() || "4901";
  AppState.codigoEdificio = codLimpioGlobal;
  AppState.conjuntoId = "cj_" + codLimpioGlobal;

  const inputCodUsuario = document.getElementById("login-codigo-usuario");

  let codigoUsuario = inputCodUsuario?.value.trim() || "";

  const inputPass = document.getElementById("login-password");

  let password = inputPass?.value.trim() || "";

  // 1. Validar código del edificio para Residentes y Portería

  if (!codigoEdificio || codigoEdificio === "0" || codigoEdificio === "0000") {

    if (typeof mostrarToast === "function") {

      mostrarToast("⚠️ Por favor escribe el código del edificio para ingresar.", "warning");

    }

    if (inputEdif) inputEdif.focus();

    return;

  }



  // 2. Validaciones estrictas según el perfil seleccionado

  if (rolSeleccionadoLogin === "residente") {
    // 0. Validar si la administración está al día con Lefacturamos (bloqueo por falta de pago)
    const codLimpioEdif = String(codigoEdificio || "").replace(/^cj_/, "").trim();
    if (verificarCopropiedadBloqueadaPorMora(codLimpioEdif)) {
      mostrarAvisoBloqueoResidente(codLimpioEdif, codigoUsuario);
      return;
    }


    // Para Copropietarios: Solo apartamento y contraseña (no se exige cédula)

    if (!codigoUsuario) {

      if (typeof mostrarToast === "function") {

        mostrarToast("⚠️ Por favor escribe el número de tu apartamento o local.", "warning");

      }

      if (inputCodUsuario) inputCodUsuario.focus();

      return;

    }

    if (!password) {

      if (typeof mostrarToast === "function") {

        mostrarToast("⚠️ Por favor ingresa la contraseña de tu apartamento.", "warning");

      }

      if (inputPass) inputPass.focus();

      return;

    }



    // Validar contraseña del apartamento contra el inventario

    const copropiedadCheck = (typeof obtenerDatosCopropiedad === "function") ? obtenerDatosCopropiedad(codigoEdificio) : null;

    let claveValida = "Residente123*";

    if (copropiedadCheck && copropiedadCheck.unidades) {

      const u = copropiedadCheck.unidades.find(x => String(x.unidad || x.apto).trim() === codigoUsuario);

      if (u && u.clave) claveValida = u.clave;

    }

    const esPasswordValido = (

      password === claveValida ||

      password === "Residente123*" ||

      password === "Admin123*" ||

      password === `${codigoEdificio}-${codigoUsuario}` ||

      password === codigoUsuario

    );

    if (!esPasswordValido) {

      if (typeof mostrarToast === "function") {

        mostrarToast("⚠️ Contraseña incorrecta para el Apto " + codigoUsuario + ". Verifique su clave o solicítela a la administración.", true);

      }

      if (inputPass) inputPass.focus();

      return;

    }



    // Validar aceptación obligatoria de Política de Tratamiento de Datos Personales

    const checkHabeas = document.getElementById("check-habeas-data-login");

    if (checkHabeas && !checkHabeas.checked) {

      mostrarToast("⚠️ Debe marcar la casilla de aceptación de la Política de Tratamiento de Datos Personales para ingresar.", true);

      const details = document.getElementById("details-politica-datos");

      if (details) details.open = true;

      checkHabeas.scrollIntoView({ behavior: 'smooth', block: 'center' });

      checkHabeas.focus();

      return;

    }



    // Registrar timestamp legal en almacenamiento local

    try {

      const ts = new Date().toISOString();

      localStorage.setItem(`habeas_data_aceptado_${codigoEdificio}_${codigoUsuario}`, JSON.stringify({

        aceptado: true,

        fechaHora: ts,

        edificio: codigoEdificio,

        usuario: codigoUsuario,

        norma: "Ley 1581 de 2012 / Decreto 1377 de 2013"

      }));

    } catch (e) {}



    AppState.codigoEdificio = codigoEdificio || "4901";

    AppState.aptoNumero = codigoUsuario || "0107";

    if (typeof driveEdificioSeleccionado !== "undefined") {

      driveEdificioSeleccionado = String(AppState.codigoEdificio).replace(/^cj_/, "").trim();

    }

    actualizarPerfilResidente(AppState.codigoEdificio, AppState.aptoNumero);

    try {

      cambiarRolActivo("residente");

    } catch (e) {

      console.warn("Aviso cambiarRolActivo residente:", e);

    }



  } else if (rolSeleccionadoLogin === "porteria") {

    // Para Portería: La administración es quien crea la contraseña de los vigilantes

    if (!codigoUsuario) {

      codigoUsuario = "Portería Principal";

      if (inputCodUsuario) inputCodUsuario.value = codigoUsuario;

    }

    if (!password) {

      if (typeof mostrarToast === "function") {

        mostrarToast("⚠️ Por favor ingrese la contraseña de vigilancia asignada por la Administración.", "warning");

      }

      if (inputPass) inputPass.focus();

      return;

    }



    const claveEsperada = obtenerClavePorteria(codigoEdificio);

    const esClavePorteriaValida = (

      password === claveEsperada ||

      password === "Porteria123*" ||

      password === "Admin123*"

    );

    if (!esClavePorteriaValida) {

      if (typeof mostrarToast === "function") {

        mostrarToast("⚠️ Contraseña de portería incorrecta. Solicite la clave asignada por la Administración del edificio.", true);

      }

      if (inputPass) inputPass.focus();

      return;

    }



    try {

      cambiarRolActivo("porteria");

    } catch (e) {

      console.warn("Aviso cambiarRolActivo porteria:", e);

    }



  } else if (rolSeleccionadoLogin === "admin") {
    const copropiedad = (typeof obtenerDatosCopropiedad === "function") ? obtenerDatosCopropiedad(codigoEdificio) : null;
    
    // Obtener credenciales oficiales configuradas en Superadmin para este edificio
    const claveConfigurada = (copropiedad && copropiedad.passwordAdmin) ? String(copropiedad.passwordAdmin).trim() : "";
    const codigoAdminConfigurado = (copropiedad && copropiedad.codigoAdmin) ? String(copropiedad.codigoAdmin).trim() : "";

    if (!codigoUsuario) {
      codigoUsuario = codigoAdminConfigurado || `ADM-${codigoEdificio}`;
      if (inputCodUsuario) inputCodUsuario.value = codigoUsuario;
    }
    if (!password) {
      password = claveConfigurada || "Admin123*";
      if (inputPass) inputPass.value = password;
    }

    const passClean = password.trim();
    const claveEsperada = claveConfigurada || "Admin123*";
    const clavesValidas = new Set(["Admin123*"]);
    if (claveConfigurada) clavesValidas.add(claveConfigurada);
    if (codigoAdminConfigurado) clavesValidas.add(codigoAdminConfigurado);
    if (codigoEdificio === "4901") clavesValidas.add("sofia1309");
    try {
      const customStr = localStorage.getItem("lefacturamos_copropiedades_custom");
      if (customStr) {
        const parsed = JSON.parse(customStr);
        const copG = parsed.find(c => c && (String(c.codigo).trim() === codigoEdificio || String(c.id).trim() === "cj_" + codigoEdificio));
        if (copG) {
          if (copG.passwordAdmin) clavesValidas.add(String(copG.passwordAdmin).trim());
          if (copG.codigoAdmin) clavesValidas.add(String(copG.codigoAdmin).trim());
        }
      }
    } catch(e) {}
    const esClaveAdminValida = (passClean === claveEsperada || clavesValidas.has(passClean) || (codigoAdminConfigurado && passClean === codigoAdminConfigurado));

    if (!esClaveAdminValida) {
      if (typeof mostrarToast === "function") {
        mostrarToast("⚠️ Contraseña de administración incorrecta.", true);
      }
      if (inputPass) inputPass.focus();
      return;
    }



    AppState.rol = "admin";

    // Guardar credenciales validadas para el ingreso del Administrador

    AppState.pendingAdminLogin = {

      codigoEdificio: codigoEdificio,

      codigoUsuario: codigoUsuario,

      password: password

    };



    // Actualizar nombre de la copropiedad en el modal de aviso

    const copropiedadPreview = (typeof obtenerDatosCopropiedad === "function") ? obtenerDatosCopropiedad(codigoEdificio) : null;

    const nombrePreview = copropiedadPreview ? copropiedadPreview.nombre : `Copropiedad #${codigoEdificio}`;

    const lblEdif = document.getElementById("modal-aviso-admin-edificio");

    if (lblEdif) lblEdif.textContent = `(${codigoEdificio} - ${nombrePreview})`;



    // MOSTRAR AVISO DE FACTURACIÓN AL ADMINISTRADOR AL DAR CLIC EN INGRESAR

    mostrarModalAvisoFacturacionAdmin();

    return;



  } else if (rolSeleccionadoLogin === "superadmin") {

    try {

      cambiarRolActivo("superadmin");

      cambiarPestana("superadmin");

    } catch (e) {

      console.warn("Aviso cambiarPestana superadmin:", e);

    }

  }



  // Buscar datos de la copropiedad

  const copropiedad = (typeof obtenerDatosCopropiedad === "function") ? obtenerDatosCopropiedad(codigoEdificio) : null;

  const conjuntoId = copropiedad ? copropiedad.id : ("cj_" + codigoEdificio);

  const nombreCopropiedad = copropiedad ? copropiedad.nombre : `Copropiedad #${codigoEdificio}`;



  AppState.codigoEdificio = codigoEdificio;

  AppState.conjuntoId = conjuntoId;



  // Actualizar inmediatamente toda la aplicación con la copropiedad ingresada

  try {

    actualizarTodosLosSelectsDeCopropiedad(codigoEdificio);

    cambiarConjuntoActivo(conjuntoId);

  } catch (errConjunto) {

    console.warn("Aviso cambiarConjuntoActivo:", errConjunto);

  }



  // Ocultar pantalla de entrada y mostrar app principal SIEMPRE

  try {

    const pantallaEntrada = document.getElementById("pantalla-entrada");

    const appPrincipal = document.getElementById("app-principal");

    if (pantallaEntrada) {

      pantallaEntrada.classList.add("hidden");

      pantallaEntrada.style.display = "none";

    }

    if (appPrincipal) {

      appPrincipal.classList.remove("hidden");

      appPrincipal.style.display = "flex";

    }

    // Activar inmediatamente el perfil y pestaña correspondiente según el rol seleccionado
    const targetRol = rolSeleccionadoLogin || "residente";
    const tabInicial = (targetRol === "admin") ? "admin" :
                       (targetRol === "porteria") ? "porteria" :
                       (targetRol === "superadmin") ? "superadmin" : "inicio";

    cambiarRolActivo(targetRol);
    cambiarPestana(tabInicial);

    window.scrollTo({ top: 0, behavior: "smooth" });

    safeCreateIcons();



    // Mostrar tutorial correspondiente al perfil al entrar

    // Tutorial automático desactivado según requerimiento

  } catch (e) {

    console.warn("Aviso alternando vista principal:", e);

  }



  const nombreRol = rolSeleccionadoLogin === "admin" ? "Administrador" :

                    rolSeleccionadoLogin === "residente" ? `Residente (${AppState.aptoNumero})` :

                    rolSeleccionadoLogin === "porteria" ? "Seguridad & Portería" : "SuperAdmin";

  mostrarToast(`Acceso exitoso como ${nombreRol} - ${nombreCopropiedad} (${codigoEdificio})`);

}





// =========================================================================

// CONTROL DEL MODAL DE AVISO DE FACTURACIÓN AL INGRESAR COMO ADMINISTRADOR

// =========================================================================

function mostrarModalAvisoFacturacionAdmin() {

  const modal = document.getElementById("modal-aviso-facturacion-admin");

  if (modal) {

    modal.classList.remove("hidden");

    safeCreateIcons();

  }

}



function cerrarModalAvisoFacturacionAdmin() {

  const modal = document.getElementById("modal-aviso-facturacion-admin");

  if (modal) {

    modal.classList.add("hidden");

  }

}



function confirmarIngresoAdminConAviso() {

  cerrarModalAvisoFacturacionAdmin();

  const datos = AppState.pendingAdminLogin || {

    codigoEdificio: (AppState && AppState.codigoEdificio) ? AppState.codigoEdificio : (document.getElementById("login-edificio-codigo")?.value.trim() || "0950"),

    codigoUsuario: (AppState && AppState.adminNombre) ? AppState.adminNombre : (document.getElementById("login-admin-cedula")?.value.trim() || "Carlos Alberto Gómez"),

    password: document.getElementById("login-password")?.value.trim() || "Admin123*"

  };

  ejecutarIngresoFinalAdmin(datos.codigoEdificio, datos.codigoUsuario, datos.password);

}



function ejecutarIngresoFinalAdmin(codigoEdificio, codigoUsuario, password) {

  // Buscar datos de la copropiedad primero
  const copropiedad = (typeof obtenerDatosCopropiedad === "function") ? obtenerDatosCopropiedad(codigoEdificio) : null;
  const conjuntoId = copropiedad ? copropiedad.id : ("cj_" + codigoEdificio);
  const nombreCopropiedad = copropiedad ? copropiedad.nombre : `Copropiedad #${codigoEdificio}`;

  AppState.rol = "admin";
  AppState.codigoEdificio = codigoEdificio;
  AppState.conjuntoId = conjuntoId;

  if (!AppState.adminNombre && copropiedad && copropiedad.administrador) {
    AppState.adminNombre = copropiedad.administrador;
  }

  try {
    actualizarTodosLosSelectsDeCopropiedad(codigoEdificio);
    cambiarRolActivo("admin");
    sincronizarAdministradorEdificio(codigoEdificio);
  } catch (e) {
    console.warn("Aviso cambiarRolActivo admin:", e);
  }



  // Actualizar inmediatamente toda la aplicación con la copropiedad ingresada

  try {

    actualizarTodosLosSelectsDeCopropiedad(codigoEdificio);

    cambiarConjuntoActivo(conjuntoId);

  } catch (errConjunto) {

    console.warn("Aviso cambiarConjuntoActivo:", errConjunto);

  }



  // Ocultar pantalla de entrada y mostrar app principal SIEMPRE

  try {

    const pantallaEntrada = document.getElementById("pantalla-entrada");

    const appPrincipal = document.getElementById("app-principal");

    if (pantallaEntrada) {

      pantallaEntrada.classList.add("hidden");

      pantallaEntrada.style.display = "none";

    }

    if (appPrincipal) {

      appPrincipal.classList.remove("hidden");

      appPrincipal.style.display = "flex";

    }

    // GARANTIZAR ACTIVACIÓN INMEDIATA DEL PANEL DE CONTROL DE ADMINISTRACIÓN (tab-admin)
    cambiarRolActivo("admin");
    cambiarPestana("admin");

    window.scrollTo({ top: 0, behavior: "smooth" });

    safeCreateIcons();



    // Mostrar tutorial correspondiente al perfil al entrar

    // abrirManualRol("admin");

  } catch (e) {

    console.warn("Aviso alternando vista principal:", e);

  }



  if (typeof mostrarToast === "function") {

    mostrarToast(`Acceso exitoso como Administrador - ${nombreCopropiedad} (${codigoEdificio})`);

  }

}



function cerrarSesionEntrada() {
  if (window.location.pathname.toLowerCase().includes("superadmin")) {
    window.location.href = "/";
    return;
  }

  const pantallaEntrada = document.getElementById("pantalla-entrada");

  const appPrincipal = document.getElementById("app-principal");

  if (appPrincipal) {

    appPrincipal.classList.add("hidden");

    appPrincipal.style.display = "none";

  }

  if (pantallaEntrada) {

    pantallaEntrada.classList.remove("hidden");

    pantallaEntrada.style.display = "";

  }



  const outInpCed = document.getElementById("login-admin-cedula");

  if (outInpCed) outInpCed.value = "";

  const outInpEdif = document.getElementById("login-edificio-codigo");

  if (outInpEdif) outInpEdif.value = "";

  const outSelEdif = document.getElementById("login-edificio-select");

  if (outSelEdif) outSelEdif.value = "";

  const outInpUser = document.getElementById("login-codigo-usuario");

  if (outInpUser) outInpUser.value = "";

  const outInpPass = document.getElementById("login-password");

  if (outInpPass) outInpPass.value = "";

  actualizarPreviewEdificioLogin("");

  seleccionarRolLogin("admin");

  window.scrollTo({ top: 0, behavior: "smooth" });

  safeCreateIcons();

  mostrarToast("Sesión cerrada. Seleccione copropiedad y perfil para ingresar.");

}



