window.accesoDirectoSuperadmin = function() {
  console.log("👑 Invocando accesoDirectoSuperadmin()...");
  try {
    AppState.rol = "superadmin";
    rolSeleccionadoLogin = "superadmin";

    const pe = document.getElementById("pantalla-entrada");
    const ap = document.getElementById("app-principal");
    const btnTop = document.getElementById("btn-top-pantalla-entrada");

    if (pe) {
      pe.classList.add("hidden");
      pe.style.display = "none";
    }
    if (ap) {
      ap.classList.remove("hidden");
      ap.style.display = "flex";
    }
    if (btnTop) {
      btnTop.classList.remove("hidden");
    }

    if (typeof cargarCopropiedadesGuardadasPersistentes === "function") cargarCopropiedadesGuardadasPersistentes();
    if (typeof inicializarDatos === "function") inicializarDatos();
    if (typeof renderizarSidebarPorRol === "function") renderizarSidebarPorRol("superadmin");
    if (typeof actualizarVisibilidadPorRol === "function") actualizarVisibilidadPorRol("superadmin");
    if (typeof cambiarRolActivo === "function") cambiarRolActivo("superadmin");
    if (typeof cambiarPestana === "function") cambiarPestana("superadmin");

    // Forzar activación explícita de la pestaña Superadministrador
    const tabSA = document.getElementById("tab-superadmin");
    if (tabSA) {
      document.querySelectorAll(".tab-content").forEach(el => {
        if (el.id !== "tab-superadmin") {
          el.classList.remove("active");
          el.style.display = "none";
        }
      });
      tabSA.classList.add("active");
      tabSA.classList.remove("hidden");
      tabSA.style.removeProperty("display");
      tabSA.style.display = "block";
    }

    // Avatar y Header oficial de Superadmin
    const topAvatarCircle = document.getElementById("top-avatar-circle");
    const topAvatarNombre = document.getElementById("top-avatar-nombre");
    const topAvatarRol = document.getElementById("top-avatar-rol");
    if (topAvatarCircle) {
      topAvatarCircle.innerText = "SA";
      topAvatarCircle.className = "w-8 h-8 rounded-full bg-purple-600 text-white font-black text-xs flex items-center justify-center shadow-md";
    }
    if (topAvatarNombre) topAvatarNombre.innerText = "SuperAdmin Master";
    if (topAvatarRol) topAvatarRol.innerText = "Consola Enterprise";

    const sideRoleTitle = document.getElementById("sidebar-role-title");
    if (sideRoleTitle) {
      sideRoleTitle.innerHTML = '<span>Superadministrador de la Plataforma</span> <i data-lucide="globe" class="w-3.5 h-3.5 text-purple-400"></i>';
    }

    if (typeof cargarCopropiedadesSuperadmin === "function") cargarCopropiedadesSuperadmin();
    if (typeof sincronizarCopropiedadesBackend === "function") sincronizarCopropiedadesBackend();

    window.scrollTo({ top: 0, behavior: "smooth" });
    if (typeof safeCreateIcons === "function") safeCreateIcons();
    if (typeof mostrarToast === "function") {
      mostrarToast("👑 Consola de Super Administrador (Desarrollador) activa.");
    }
  } catch (errSA) {
    console.error("Error en accesoDirectoSuperadmin:", errSA);
  }
};

// Inicialización de la aplicación
document.addEventListener("DOMContentLoaded", () => {

  const pantallaEntrada = document.getElementById("pantalla-entrada");
  const appPrincipal = document.getElementById("app-principal");

  // Soporte de enlace directo a Superadministrador vía URL (?rol=superadmin o #superadmin)
  function verificarRutaDirectaUrl() {
    try {
      const params = new URLSearchParams(window.location.search);
      const rawHash = (window.location.hash || "").replace("#", "").replace(/^\/+/, "").toLowerCase().trim();
      const rawPath = (window.location.pathname || "").toLowerCase().trim();
      const rolUrl = (params.get("rol") || rawHash || "").toLowerCase().trim();

      const pantallaEntrada = document.getElementById("pantalla-entrada");
      const appPrincipal = document.getElementById("app-principal");

      if (rawHash === "parqueaderos" || rawHash === "pq" || rolUrl === "parqueaderos") {
        if (pantallaEntrada) {
          pantallaEntrada.classList.add("hidden");
          pantallaEntrada.style.display = "none";
        }
        if (appPrincipal) {
          appPrincipal.classList.remove("hidden");
          appPrincipal.style.display = "flex";
        }
        if (typeof inicializarDatos === "function") inicializarDatos();
        cambiarRolActivo("admin");
        cambiarPestana("parqueaderos");
        mostrarToast("🚗 Acceso directo a Inventario de Parqueaderos (PQ Moto / Carro).");
        return true;
      } else if (
        window.ES_RUTA_SUPERADMIN ||
        rolUrl === "superadmin" || 
        rolUrl.includes("superadmin") || 
        rawHash.includes("superadmin") || 
        rawPath.includes("superadmin") ||
        window.location.href.toLowerCase().includes("superadmin")
      ) {
        window.accesoDirectoSuperadmin();
        return true;
      } else if (rolUrl === "porteria" || rolUrl.includes("porteria") || rolUrl.startsWith("port-")) {
        if (pantallaEntrada) {
          pantallaEntrada.classList.add("hidden");
          pantallaEntrada.style.display = "none";
        }
        if (appPrincipal) {
          appPrincipal.classList.remove("hidden");
          appPrincipal.style.display = "flex";
        }
        const codEdif = params.get("edificio") || params.get("codigo") || AppState.codigoEdificio || "4901";
        AppState.codigoEdificio = codEdif;
        if (typeof inicializarDatos === "function") inicializarDatos();
        cambiarRolActivo("porteria");
        cambiarPestana("porteria");
        if (typeof cambiarSubtabPorteria === "function") {
          cambiarSubtabPorteria("accesos");
        }
        mostrarToast("🛡️ Acceso directo a Pantalla de Portería y Control de Acceso.");
        return true;
      } else if (rolUrl === "admin" || rolUrl === "administrador" || rolUrl.includes("admin")) {
        if (pantallaEntrada) {
          pantallaEntrada.classList.add("hidden");
          pantallaEntrada.style.display = "none";
        }
        if (appPrincipal) {
          appPrincipal.classList.remove("hidden");
          appPrincipal.style.display = "flex";
        }
        if (typeof inicializarDatos === "function") inicializarDatos();
        cambiarRolActivo("admin");
        cambiarPestana("admin");
        mostrarToast("🏢 Acceso directo a Panel de Administración concedido.");
        return true;
      }
    } catch (e) {}
    return false;
  }

  window.addEventListener("hashchange", verificarRutaDirectaUrl);
  const esRutaDirecta = verificarRutaDirectaUrl();

  cargarCopropiedadesGuardadasPersistentes();
  inicializarDatos();
  renderizarSidebarPorRol(AppState.rol);
  actualizarTodosLosSelectsDeCopropiedad();
  cargarCopropiedadesSuperadmin();
  sincronizarCopropiedadesBackend();
  cargarComunicados();
  inicializarModuloReservas();
  inicializarModuloAsamblea();
  cargarPQR();
  cargarMascotas();
  cargarLey675();
  cargarGastosAdmin();
  inicializarModuloPagos();
  renderizarPorteria();
  renderizarInventarioInmuebles();
  renderizarDirectorioResidentes();
  renderizarBaseSaldosMatriz();
  renderizarModuloPagosAdmin();
  renderizarModuloManualReglamento();

  if (esRutaDirecta) {
    if (AppState.rol === "superadmin" || window.ES_RUTA_SUPERADMIN) {
      window.accesoDirectoSuperadmin();
    } else {
      actualizarVisibilidadPorRol(AppState.rol);
      renderizarSidebarPorRol(AppState.rol);
    }
  } else {
    const initConjuntoId = AppState.conjuntoId || AppState.codigoEdificio || (document.getElementById("sel-conjunto") ? document.getElementById("sel-conjunto").value : "4901");
    if (typeof cambiarConjuntoActivo === "function") {
      cambiarConjuntoActivo(initConjuntoId);
    }
    actualizarVisibilidadPorRol(AppState.rol);
    seleccionarRolLogin("admin");
    actualizarPreviewEdificioLogin("");
    const initInpCed = document.getElementById("login-admin-cedula");
    if (initInpCed) initInpCed.value = "";
    detectarNombreAdministrador("");
    const initInpEdif = document.getElementById("login-edificio-codigo");
    if (initInpEdif) initInpEdif.value = "";
    const initSelEdif = document.getElementById("login-edificio-select");
    if (initSelEdif) initSelEdif.value = "";
    const initInpUser = document.getElementById("login-codigo-usuario");
    if (initInpUser) initInpUser.value = "";
    const initInpPass = document.getElementById("login-password");
    if (initInpPass) initInpPass.value = "";

    // Reafirmar visualización inicial en Pantalla de Entrada
    if (pantallaEntrada) {
      pantallaEntrada.classList.remove("hidden");
      pantallaEntrada.style.display = "";
    }
    if (appPrincipal) {
      appPrincipal.classList.add("hidden");
      appPrincipal.style.display = "none";
    }
  }

  safeCreateIcons();
});



// ==============================================================================

// GESTIÓN DE NAVEGACIÓN Y MENÚS POR ROL (MODO OSCURO MÓVIL Y ESCRITORIO)

// ==============================================================================



function toggleMenuVerticalMovil(forzarEstado = null) {

  const sidebar = document.getElementById("sidebar-principal");

  const backdrop = document.getElementById("sidebar-movil-backdrop");

  if (!sidebar) return;



  const estaAbierto = sidebar.classList.contains("movil-abierto");

  const nuevoEstado = forzarEstado !== null ? forzarEstado : !estaAbierto;



  if (nuevoEstado) {

    sidebar.classList.add("movil-abierto");

    if (backdrop) backdrop.classList.remove("hidden");

    safeCreateIcons();

  } else {

    sidebar.classList.remove("movil-abierto");

    if (backdrop) backdrop.classList.add("hidden");

  }

}



window.toggleSubmenuSidebar = function(subId, btn) {
  const cont = document.getElementById(subId);
  const icon = document.getElementById(`icon-chevron-${subId}`);
  if (!cont) return;
  const isHidden = cont.classList.contains("hidden");
  if (isHidden) {
    cont.classList.remove("hidden");
    if (icon) icon.style.transform = "rotate(0deg)";
  } else {
    cont.classList.add("hidden");
    if (icon) icon.style.transform = "rotate(-90deg)";
  }
};

function renderizarSidebarPorRol(rol) {

  const conf = MENUS_POR_ROL[rol] || MENUS_POR_ROL.residente;

  const boxCambioEdificio = document.getElementById("sidebar-seccion-cambio-edificio");

  if (boxCambioEdificio) {

    if (rol === "superadmin") {

      boxCambioEdificio.classList.remove("hidden");

    } else {

      boxCambioEdificio.classList.add("hidden");

    }

  }

  

  // 1. Actualizar Título del Menú en Sidebar de Escritorio y Móvil

  const titleEl = document.getElementById("sidebar-role-title");

  if (titleEl) {

    titleEl.innerHTML = `

      <span>${conf.titulo}</span>

      <i data-lucide="${conf.icono}" class="w-3.5 h-3.5 text-brand-400"></i>

    `;

  }

  const mobileTitle = document.getElementById("mobile-menu-toggle-title");

  if (mobileTitle) {

    mobileTitle.innerText = conf.titulo || "Menú de Navegación";

  }



  // 2. Generar Botones del Sidebar (Escritorio) con soporte de Badges

  const itemsCont = document.getElementById("sidebar-menu-items");

  if (itemsCont) {

    itemsCont.innerHTML = conf.items.map((item, idx) => {

      // Soporte para Submenús Dinámicos (ej: Creación de Edificio y Facturación)
      if (item.subitems && item.subitems.length > 0) {
        const subId = `sidebar-subgroup-${item.id || idx}`;
        const subItemsHtml = item.subitems.map((sub, sIdx) => {
          const subBadge = sub.badge 
            ? `<span class="ml-auto px-1.5 py-0.5 rounded-md bg-emerald-500/20 text-emerald-300 font-bold text-[9px] border border-emerald-500/30">${sub.badge}</span>` 
            : '';
          const subClick = sub.action 
            ? sub.action 
            : `cambiarPestana('${sub.id}', this)`;

          return `
            <button id="btn-side-sub-${sub.id}-${sIdx}" data-tab="${sub.id}" onclick="${subClick}" class="sidebar-item-btn w-full flex items-center gap-2.5 px-2.5 py-2 rounded-xl text-xs font-semibold text-slate-300 hover:text-white hover:bg-slate-800/90 transition-all group">
              <i data-lucide="${sub.icono || 'circle'}" class="w-3.5 h-3.5 text-slate-400 group-hover:text-emerald-400 shrink-0"></i>
              <span class="truncate">${sub.label}</span>
              ${subBadge}
            </button>
          `;
        }).join("");

        return `
          <div class="sidebar-submenu-box space-y-1 mb-2 bg-slate-950/70 rounded-2xl p-2 border border-slate-800/80 shadow-md">
            <button type="button" onclick="toggleSubmenuSidebar('${subId}', this)" class="w-full flex items-center justify-between px-2.5 py-1.5 rounded-xl text-xs font-black text-amber-300 hover:text-amber-200 hover:bg-slate-800/60 transition-all cursor-pointer">
              <span class="flex items-center gap-2">
                <i data-lucide="${item.icono}" class="w-4 h-4 text-amber-400 shrink-0"></i>
                <span class="tracking-wide">${item.label}</span>
              </span>
              <span class="flex items-center gap-1.5">
                ${item.badge ? `<span class="px-2 py-0.5 rounded-full bg-amber-500/20 text-amber-300 font-bold text-[9px] border border-amber-500/30">${item.badge}</span>` : ''}
                <i id="icon-chevron-${subId}" data-lucide="chevron-down" class="w-3.5 h-3.5 text-slate-400 transition-transform duration-200"></i>
              </span>
            </button>
            <div id="${subId}" class="space-y-0.5 pt-1 pl-1.5 border-l-2 border-amber-500/40 ml-2">
              ${subItemsHtml}
            </div>
          </div>
        `;
      }

      const badgeHtml = item.badge 
        ? `<span class="ml-auto px-2 py-0.5 rounded-full bg-amber-500 text-slate-950 font-black text-[10px] min-w-[18px] text-center shadow-sm">${item.badge}</span>` 
        : '';

      const onclickAttr = (item.id === "entrada" || item.action === "cerrarSesionEntrada")
        ? "cerrarSesionEntrada()"
        : (item.id === "pqr" && rol === "residente")
          ? "cambiarPestana('pqr', this); setTimeout(abrirModalRadicarPQR, 150);"
          : item.action
          ? item.action
          : (item.id && item.id.startsWith("manual-"))
          ? `abrirManualRol('${item.id.replace("manual-", "")}')`
          : `cambiarPestana('${item.id}', this)`;

      return `

        <button id="btn-side-${item.id}-${idx}" data-tab="${item.id}" onclick="${onclickAttr}" class="sidebar-item-btn w-full flex items-center gap-3 px-3.5 py-2.5 rounded-xl text-xs font-semibold text-slate-300 hover:text-white hover:bg-slate-800/80 transition-all border border-transparent group">

          <i data-lucide="${item.icono}" class="w-4 h-4 text-slate-400 group-hover:text-emerald-400 shrink-0"></i>

          <span class="truncate">${(rol === "residente" && item.id === "inicio") ? `Mi Inmueble (Apto ${AppState.aptoNumero || "0107"})` : item.label}</span>

          ${badgeHtml}

        </button>

      `;

    }).join("");

  }



  // 3. Generar Botones de la Barra Inferior Móvil (Bottom Navigation)

  const bottomBar = document.getElementById("bottom-nav-bar");

  if (bottomBar) {

    bottomBar.innerHTML = conf.itemsMovil.map(item => {

      const clickAction = (item.id === "entrada" || item.action === "cerrarSesionEntrada")

        ? "cerrarSesionEntrada()"

        : item.action

        ? item.action

        : (item.id && item.id.startsWith("manual-"))

        ? `abrirManualRol('${item.id.replace("manual-", "")}')`

        : `cambiarPestana('${item.id}')`;

      return `

      <button onclick="${clickAction}" data-tab="${item.id}" class="bottom-nav-btn flex flex-col items-center justify-center gap-1 py-1.5 px-2 rounded-xl text-slate-400 hover:text-emerald-400 transition-all min-w-[54px] active:scale-95">

        <i data-lucide="${item.icono}" class="w-5 h-5"></i>

        <span class="text-[9px] font-bold tracking-tight leading-none">${item.label}</span>

      </button>

    `;}).join("");

  }





  // Segmented control sincronizado unificadamente en cambiarRolActivo



  // 6. Actualizar Texto del Badge de Rol

  const badgeTexto = document.getElementById("badge-rol-texto");

  if (badgeTexto) {

    badgeTexto.innerText = conf.badgeTexto;

  }



  safeCreateIcons();

}



function cambiarPestana(tabId, btnElement = null) {

if (tabId && tabId.startsWith("manual-")) {

  abrirManualRol(tabId.replace("manual-", ""));

  return;

}

  // Si estamos en pantalla móvil y el sidebar vertical está abierto, cerrarlo

  if (typeof toggleMenuVerticalMovil === "function" && window.innerWidth < 768) {

    toggleMenuVerticalMovil(false);

  }



  // Actualizar indicador móvil de pestaña activa

  const mobileBadge = document.getElementById("mobile-menu-active-badge");

  if (mobileBadge) {

    const rolActual = AppState.rol || "admin";

    const itemActive = (MENUS_POR_ROL[rolActual]?.items || []).find(i => i.id === tabId);

    if (itemActive) mobileBadge.innerText = itemActive.label;

  }



  // Redirección especial si se solicita directamente la planilla de pagos
  let abrirSubtabPlanilla = false;
  if (tabId === "planilla-novedades") {
    tabId = "facturacion";
    abrirSubtabPlanilla = true;
  }

  // 1. Ocultar de manera estricta todas las pestañas y activar la seleccionada

  document.querySelectorAll(".tab-content").forEach(el => {

    el.classList.remove("active");

    el.style.display = "none";

  });

  const activeTab = document.getElementById(`tab-${tabId}`);
  if (activeTab) {
    activeTab.classList.add("active");
    activeTab.classList.remove("hidden");
    activeTab.style.removeProperty("display");
    activeTab.style.display = "block";
  }

  if (tabId === "facturacion") {
    try {
      if (abrirSubtabPlanilla && typeof cambiarSubtabFacturacion === "function") {
        cambiarSubtabFacturacion('planilla');
      } else {
        const contPlan = document.getElementById("subtab-fac-content-planilla");
        if (contPlan && !contPlan.classList.contains("hidden")) {
          if (typeof renderizarPlanillaNovedades === "function") renderizarPlanillaNovedades();
        } else {
          if (typeof renderizarTabFacturacion === "function") renderizarTabFacturacion();
        }
      }
    } catch (e) {
      console.error("Error al renderizar facturación:", e);
    }
  }

  if (tabId === "parqueaderos") {
    try {
      renderizarInventarioParqueaderos();
      poblarDatalistAptosParqueaderos();
      cargarParqueaderosDesdeBackend();
    } catch (e) {
      console.error("Error al renderizar parqueaderos:", e);
    }
  }

  // Garantizar que tab-superadmin quede 100% oculto si no estamos en superadmin

  const tabSuperadmin = document.getElementById("tab-superadmin");

  if (tabSuperadmin && tabId !== "superadmin") {

    tabSuperadmin.classList.remove("active");

    tabSuperadmin.style.display = "none";

  }



  if (tabId === "superadmin") {

    actualizarVisibilidadPorRol("superadmin");

  } else {

    actualizarVisibilidadPorRol(AppState.rol || "admin");

  }



  // 2. Resaltar INMEDIATAMENTE en Sidebar (Escritorio) con Verde Esmeralda Oficial

  // Limpiar primero el estado activo de TODOS los botones del menú lateral

  document.querySelectorAll("#sidebar-menu-items button").forEach(btn => {

    btn.classList.remove("bg-emerald-600", "text-white", "font-bold", "shadow-md");

    btn.classList.add("text-slate-300");

  });



  // Localizar el botón correspondiente en el sidebar

  let targetBtn = (btnElement && btnElement.closest && btnElement.closest("#sidebar-menu-items")) ? btnElement : null;

  if (!targetBtn) {

    if (tabId === "porteria") {
      const targetSideId = (typeof subtabPorteriaActiva !== "undefined" && subtabPorteriaActiva === "accesos") ? "accesos-porteria" :
                           (typeof subtabPorteriaActiva !== "undefined" && subtabPorteriaActiva === "reservas") ? "reservas-porteria" : "porteria";
      targetBtn = document.querySelector(`#sidebar-menu-items button[data-tab='${targetSideId}']`);
    } else {
      targetBtn = document.querySelector(`#sidebar-menu-items button[data-tab='${tabId}']`) ||

                  document.querySelector(`#sidebar-menu-items button[id^='btn-side-${tabId}']`) ||

                  document.querySelector(`#sidebar-menu-items button[onclick*="'${tabId}'"]`);
    }

  }

  if (targetBtn) {

    targetBtn.classList.add("bg-emerald-600", "text-white", "font-bold", "shadow-md");

    targetBtn.classList.remove("text-slate-300");

    try { targetBtn.scrollIntoView({ block: "nearest", behavior: "smooth" }); } catch (e) {}

  }



  // 3. Resaltar en la Barra Inferior Móvil (Bottom Navigation)

  document.querySelectorAll(".bottom-nav-btn").forEach(btn => {

    if (btn.getAttribute("data-tab") === tabId) {

      btn.classList.add("text-emerald-400", "font-black");

      btn.classList.remove("text-slate-400");

    } else {

      btn.classList.remove("text-emerald-400", "font-black");

      btn.classList.add("text-slate-400");

    }

  });



  // 4. Renderizado seguro por módulo con protección try-catch

  try {

    if (tabId === "admin") {
      const cod = AppState.codigoEdificio || "4901";
      if (typeof sincronizarAdministradorEdificio === "function") sincronizarAdministradorEdificio(cod);
    }
    else if (tabId === "inicio") {
      const cod = AppState.codigoEdificio || "4901";
      const apto = AppState.aptoNumero || "0107";
      if (typeof actualizarPerfilResidente === "function") actualizarPerfilResidente(cod, apto);
    }
    else if (tabId === "apartamentos") renderizarInventarioInmuebles();

    else if (tabId === "residentes") renderizarDirectorioResidentes();

    else if (tabId === "saldos") renderizarBaseSaldosMatriz();

    else if (tabId === "pagosadmin") renderizarModuloPagosAdmin();

    else if (tabId === "manual") renderizarModuloManualReglamento();

    else if (tabId === "pqr") {
      renderizarModuloPQR();
      cargarPQRsDesdeServidor();
    }

    else if (tabId === "comunicados") renderizarModuloComunicados();

    else if (tabId === "votaciones") renderizarModuloAsambleaVotaciones();

    else if (tabId === "zonas") { cargarZonasEdificioStorage(); renderizarModuloZonasComunes(); }
    else if (tabId === "reservas") {
      inicializarModuloReservas();
    }
    else if (tabId === "visitantes") {
      const esAdmin = (typeof AppState !== "undefined" && (AppState.rol === "admin" || AppState.rol === "superadmin"));
      const seccionGeneradorQR = document.getElementById("seccion-generador-qr-residente");
      if (seccionGeneradorQR) {
        if (esAdmin) {
          seccionGeneradorQR.classList.add("hidden");
          seccionGeneradorQR.style.display = "none";
        } else {
          seccionGeneradorQR.classList.remove("hidden");
          seccionGeneradorQR.style.display = "block";
        }
      }
      if (esAdmin && typeof renderizarVisitasAdmin === "function") {
        renderizarVisitasAdmin();
      }
    }

    else if (tabId === "documentos") renderizarModuloDocumentosDrive();

    else if (tabId === "ley675") cargarLey675();

  } catch (err) {

    console.error(`Error al renderizar módulo ${tabId}:`, err);

  }



  window.scrollTo({ top: 0, behavior: 'smooth' });

  safeCreateIcons();

}



function obtenerUnidadesActivas() {

  const activeCode = (typeof AppState !== "undefined" && (AppState.codigoEdificio || AppState.conjuntoId)) || "4901";

  const codLimpio = String(activeCode).replace(/^cj_/, "").trim();

  if (codLimpio === "0361" && typeof getUnidadesDonaRosa0361Master === "function") {
    return getUnidadesDonaRosa0361Master();
  }
  if (codLimpio === "0950" && typeof getUnidadesFortaleza0950Master === "function") {
    return getUnidadesFortaleza0950Master();
  }
  if (codLimpio === "4160" && typeof getUnidadesRiachuelo4160Master === "function") {
    return getUnidadesRiachuelo4160Master();
  }
  if (codLimpio === "4901" && typeof getUnidadesRobleAlto4901Master === "function") {
    return getUnidadesRobleAlto4901Master();
  }
  if (codLimpio === "7480" && typeof getUnidadesManchester7480Master === "function") {
    return getUnidadesManchester7480Master();
  }

  const cj = (typeof obtenerDatosCopropiedad === "function")

    ? obtenerDatosCopropiedad(codLimpio)

    : null;

  if (cj && cj.unidades && cj.unidades.length > 0) {

    return cj.unidades;

  }

  if (typeof obtenerUnidadesRealesParaFusion === "function") {

    const list = obtenerUnidadesRealesParaFusion(codLimpio, cj ? cj.nombre : "");

    if (list && list.length > 0) return list;

  }

  if (codLimpio === "4901") {
    return (typeof getUnidadesRobleAlto4901Master === "function") ? getUnidadesRobleAlto4901Master() : [];
  }

  return [];

}



function sincronizarFormularioBancarioAdmin(cop) {
  if (!cop) {
    cop = (typeof obtenerDatosCopropiedad === "function") 
      ? obtenerDatosCopropiedad(AppState.conjuntoId || AppState.codigoEdificio) 
      : null;
  }
  if (!cop) return;

  const banco = cop.banco || "";
  const tipoCuenta = cop.tipoCuenta || cop.tipo_cuenta || "Ahorros";
  const cuenta = cop.cuenta || cop.numero_cuenta || cop.numeroCuenta || "";
  const nombre = cop.nombre || cop.titular_cuenta || "";
  const nit = cop.nit || "";
  const breb = cop.breb || `BREB-${cop.codigo || ''}`;

  // Actualizar AppState.datosBancarios para que todo el sistema lo tenga sincronizado
  if (!AppState.datosBancarios) AppState.datosBancarios = {};
  AppState.datosBancarios.banco = banco;
  AppState.datosBancarios.tipoCuenta = (String(tipoCuenta).toUpperCase().includes("CORRIENTE") ? "Cuenta Corriente" : "Cuenta de Ahorros");
  AppState.datosBancarios.numeroCuenta = cuenta;
  AppState.datosBancarios.titular = nombre;
  AppState.datosBancarios.nit = nit;
  AppState.datosBancarios.breb = breb;
  if (cop.wompiKey) AppState.datosBancarios.wompiKey = cop.wompiKey;
  if (cop.boldKey) AppState.datosBancarios.boldKey = cop.boldKey;
  if (cop.payuId) AppState.datosBancarios.payuId = cop.payuId;

  // 1. Selector de Banco Receptor en Configuración de Pasarelas (sección-pagos-admin)
  const bSel = document.getElementById("admin-banco-sel");
  if (bSel) {
    if (banco) {
      const bUpper = banco.trim().toUpperCase();
      let optCoincidente = Array.from(bSel.options).find(o => {
        if (!o.value) return false;
        const valUpper = o.value.trim().toUpperCase();
        return valUpper === bUpper || bUpper.includes(valUpper) || valUpper.includes(bUpper);
      });
      if (optCoincidente) {
        bSel.value = optCoincidente.value;
      } else {
        const nuevaOpt = document.createElement("option");
        nuevaOpt.value = banco;
        nuevaOpt.text = banco;
        bSel.appendChild(nuevaOpt);
        bSel.value = banco;
      }
    } else {
      bSel.value = "";
    }
  }

  // 2. Tipo de Cuenta
  const tSel = document.getElementById("admin-tipo-cuenta-sel");
  if (tSel) {
    const tUpper = String(tipoCuenta).trim().toUpperCase();
    if (tUpper.includes("CORRIENTE")) {
      tSel.value = "Corriente";
    } else {
      tSel.value = "Ahorros";
    }
  }

  // 3. Número de Cuenta
  const numEl = document.getElementById("admin-numero-cuenta");
  if (numEl) numEl.value = cuenta;

  // 4. Titular
  const titEl = document.getElementById("admin-titular-cuenta");
  if (titEl) titEl.value = nombre;

  // 5. NIT
  const nitEl = document.getElementById("admin-nit-cuenta");
  if (nitEl) nitEl.value = nit;

  // 6. Llave Bre-B
  const brebEl = document.getElementById("admin-breb-llave");
  if (brebEl) brebEl.value = breb;

  // 7. Pasarelas de Recaudo
  const wompiEl = document.getElementById("admin-wompi-pub");
  if (wompiEl) wompiEl.value = cop.wompiKey || `pub_prod_${cop.codigo}_lefacturamos`;
  const boldEl = document.getElementById("admin-bold-key");
  if (boldEl) boldEl.value = cop.boldKey || `bold_live_${cop.codigo}_key`;
  const payuEl = document.getElementById("admin-payu-id");
  if (payuEl) payuEl.value = cop.payuId || "";

  // 8. Actualizar vista de Pagos de los Copropietarios (Residentes)
  const pBanco = document.getElementById("pago-copropiedad-banco");
  if (pBanco) pBanco.innerText = banco || "--";

  const pTipo = document.getElementById("pago-copropiedad-tipo");
  if (pTipo) pTipo.innerText = AppState.datosBancarios.tipoCuenta;

  const pCuenta = document.getElementById("pago-copropiedad-cuenta");
  if (pCuenta) pCuenta.innerText = cuenta || "--";

  const pNit = document.getElementById("pago-copropiedad-nit");
  if (pNit) pNit.innerText = nit || "--";

  const pTitular = document.getElementById("pago-copropiedad-titular");
  if (pTitular) pTitular.innerText = nombre || "--";

  const pBreb = document.getElementById("pago-copropiedad-breb");
  if (pBreb) pBreb.innerText = `${breb}/${AppState.aptoNumero || '0101'}/${AppState.saldoTotal || '0'}`;
}
window.sincronizarFormularioBancarioAdmin = sincronizarFormularioBancarioAdmin;

