  // Cuadro de Solicitud y Formulario de Nueva Reserva (EXCLUSIVO RESIDENTES/COPROPIETARIOS - OCULTO EN ADMINISTRACION)
  const seccionFormularioReserva = document.getElementById("seccion-gestion-reservas-completo");
