let filtroSuperadminActivo = "todos";

let subtabSuperadminActivo = "conjuntos";

let edificioIdSeleccionado = null;

let copropiedadCargaMasivaActiva = "4901";

let tipoArchivoExcelActivo = "maestro";



function cambiarSubtabSuperadmin(subtab) {

  subtabSuperadminActivo = subtab;

  const subtabs = ["conjuntos", "cargamasiva", "pasarelas", "dian", "conciliacion", "reembolsos"];

  

  subtabs.forEach(s => {

    const btn = document.getElementById(`subtab-sa-${s}`);

    const view = document.getElementById(`sa-view-${s}`);

    if (btn) {

      if (s === subtab) {

        if (s === "cargamasiva") {

          btn.className = "subtab-sa-btn active-emerald px-3.5 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap border border-emerald-500 bg-emerald-950/50 text-emerald-400 shadow-md shadow-emerald-950/40 inline-flex items-center gap-1.5";

        } else {

          btn.className = "subtab-sa-btn active px-3.5 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap border border-purple-500 bg-purple-950/50 text-purple-300 shadow-md shadow-purple-950/40 inline-flex items-center gap-1.5";

        }

      } else {

        btn.className = "subtab-sa-btn px-3.5 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap text-slate-400 hover:text-white inline-flex items-center gap-1.5";

      }

    }

    if (view) {

      if (s === subtab) view.classList.remove("hidden");

      else view.classList.add("hidden");

    }

  });



  if (subtab === "conjuntos") {

    renderizarCopropiedadesSuperadmin(filtroSuperadminActivo);

  } else if (subtab === "cargamasiva") {

    actualizarVistaCargaMasiva();

  }

  safeCreateIcons();

}



function cambiarCopropiedadCargaMasiva(codigo) {

  copropiedadCargaMasivaActiva = codigo;

  actualizarVistaCargaMasiva();

  const cop = listaCopropiedadesSuperadmin.find(c => c.codigo === codigo);

  if (cop) {

    mostrarToast(`Copropiedad activa para carga: ${cop.nombre}`);

  }

}



function actualizarVistaCargaMasiva() {

  const sel = document.getElementById("sa-cargamasiva-select");

  if (sel && sel.value !== copropiedadCargaMasivaActiva) {

    sel.value = copropiedadCargaMasivaActiva;

  }



  const cop = listaCopropiedadesSuperadmin.find(c => c.codigo === copropiedadCargaMasivaActiva) || listaCopropiedadesSuperadmin[0];

  if (!cop) return;



  const prevNom = document.getElementById("sa-cm-prev-nombre");

  const prevCod = document.getElementById("sa-cm-prev-codigo");

  const prevNit = document.getElementById("sa-cm-prev-nit");

  const prevAdm = document.getElementById("sa-cm-prev-admin");

  const prevAdmCod = document.getElementById("sa-cm-prev-admincod");

  const prevInm = document.getElementById("sa-cm-prev-inmuebles");

  const btnText = document.getElementById("sa-cm-btn-text");



  if (prevNom) prevNom.innerText = cop.nombre;

  if (prevCod) prevCod.innerText = `#${cop.codigo}`;

  if (prevNit) prevNit.innerText = cop.nit;

  if (prevAdm) prevAdm.innerText = cop.administrador || "Administrador Designado";

  if (prevAdmCod) prevAdmCod.innerText = cop.codigoAdmin || `ADM-${cop.codigo}`;

  if (prevInm) prevInm.innerText = cop.inmueblesCount || (cop.unidades ? cop.unidades.length : 80);

  if (btnText) btnText.innerText = `Abrir Carga Masiva para ${cop.nombre}`;



  // Encabezados del módulo detallado inferior

  const detNom = document.getElementById("cm-detalle-edificio-nombre");

  if (detNom) detNom.innerText = cop.nombre;



  const detBadge = document.getElementById("cm-detalle-edificio-badge");

  if (detBadge) detBadge.innerText = `[${cop.codigo}] NIT: ${cop.nit}`;



  renderizarTablaPreviewCargaMasiva(cop);

  safeCreateIcons();

}



