async function guardarNuevaCopropiedadSuperadmin() {

  const nom = document.getElementById("modal-nc-nombre")?.value.trim();

  const cod = document.getElementById("modal-nc-codigo")?.value.trim();

  const nit = document.getElementById("modal-nc-nit")?.value.trim() || "900.842.119-4";

  const ciu = document.getElementById("modal-nc-ciudad")?.value.trim() || "Bogotá D.C.";

  const dir = document.getElementById("modal-nc-direccion")?.value.trim() || "Calle 100 # 15 - 20";

  const adminNom = document.getElementById("modal-nc-admin-nom")?.value.trim() || "Carlos Alberto Gómez";

  const adminCed = document.getElementById("modal-nc-admin-cedula")?.value.trim() || "79.845.120";

  const adminPass = document.getElementById("modal-nc-admin-pass")?.value.trim() || "Admin123*";

  const ban = document.getElementById("modal-nc-banco")?.value.trim() || "Bancolombia";

  const tipoCta = document.getElementById("modal-nc-tipo-cuenta")?.value.trim() || "Cuenta Corriente";

  const cta = document.getElementById("modal-nc-cuenta")?.value.trim() || "031-894520-11";

  const adminCod = `ADM-${cod}`;



  if (!nom || !cod) {

    mostrarToast("Complete el nombre y código de la copropiedad.", true);

    return;

  }



  const unidadesReales = (typeof obtenerUnidadesRealesParaFusion === "function")

    ? obtenerUnidadesRealesParaFusion(cod, nom)

    : [{ unidad: "0101", apto: "0101", bloq: "01", propietario: adminNom, coeficiente: "100.000%", admon: 350000, admonFmt: "$350.000", totalPagar: "$350.000", totalNum: 350000, estado: "Al Día" }];



  const nueva = {

    id: `cj_${cod}`,

    nombre: nom,

    codigo: cod,

    nit: nit,

    ciudad: ciu,

    direccion: `${dir} • ${ciu}`,

    tipo: "Conjunto Residencial",

    banco: ban,

    tipoCuenta: tipoCta,

    cuenta: cta,

    breb: `BREB-${cod}`,

    pasarela: `Wompi (pub_${cod})`,

    codigoAdmin: adminCod,

    administrador: adminNom,

    cedulaAdmin: adminCed,

    passwordAdmin: adminPass,

    inmueblesCount: unidadesReales.length,

    inmueblesOcupados: unidadesReales.length,

    censoCount: unidadesReales.length,

    vehiculosAuditoria: 2,

    reservasConfirmadas: 1,

    pqrAtencion: 0,

    coeficienteTotal: (unidadesReales.reduce((acc, u) => acc + (parseFloat(u.coefNum || String(u.coeficiente || "").replace("%", "")) || 0), 0) > 0) ? `${unidadesReales.reduce((acc, u) => acc + (parseFloat(u.coefNum || String(u.coeficiente || "").replace("%", "")) || 0), 0).toFixed(3)}%` : "0.000%",

    recaudoTotal: "$0",

    recaudoPagos: `${unidadesReales.length} unidades activas`,

    carteraPendiente: "$0",

    totalFinalEdificio: "$0",

    estado: "A Paz y Salvo",

    bloqueadoMora: false,

    unidades: unidadesReales

  };



  await guardarCopropiedadGlobal(nueva, nueva.unidades);

  const limpiaCed = adminCed.replace(/[^0-9a-zA-Z]/g, "");
  if (limpiaCed && typeof DIRECTORIO_ADMINISTRADORES !== "undefined") {
    DIRECTORIO_ADMINISTRADORES[limpiaCed] = {
      nombre: adminNom,
      cedula: adminCed,
      codigoEdificio: cod,
      nombreEdificio: nom,
      password: adminPass
    };
  }



  cerrarModalNuevaCopropiedad();

  renderizarCopropiedadesSuperadmin();

  mostrarToast(`✓ Copropiedad '${nom}' (#${cod}) guardada permanentemente.`);

}



