function abrirModalImportarExcelEdificio(id = null, tabInicial = "carga") {

  if (id === "fusion3en1") {

    tabInicial = "fusion3en1";

    id = codigoEdificioActivoFusion || edificioFiltroCodigoSuperadmin || AppState.codigoEdificio || "4901";

  }

  let codigoEd = (id ? String(id).replace(/^cj_/, "").trim() : null) || 

                 edificioFiltroCodigoSuperadmin || 

                 AppState.codigoEdificio || 

                 copropiedadCargaMasivaActiva || 

                 codigoEdificioActivoFusion || 

                 "4901";

  

  codigoEdificioActivoFusion = codigoEd;

  edificioIdSeleccionado = id || `cj_${codigoEd}`;



  // Resetear la pantalla de carga masiva para que inicie LIMPIA y sin archivos de otros edificios

  limpiarAnalisisModalCM();



  // Poblar opciones del select modal con las copropiedades registradas y la seleccionada

  const sel = document.getElementById("modal-cm-select-edificio");

  if (sel) {

    const codigosExistentes = new Set(listaCopropiedadesSuperadmin.map(c => c.codigo));

    let opts = listaCopropiedadesSuperadmin.map(c => `

      <option value="${c.codigo}">[${c.codigo}] ${c.nombre}</option>

    `);

    if (!codigosExistentes.has(codigoEd)) {

      const nomEd = (codigoNuevoEdificioEnCreacion === codigoEd && nombreNuevoEdificioEnCreacion)

        ? nombreNuevoEdificioEnCreacion

        : (obtenerDatosCopropiedad(codigoEd)?.nombre || `Copropiedad #${codigoEd}`);

      opts.unshift(`<option value="${codigoEd}">[${codigoEd}] ${nomEd}</option>`);

    }

    sel.innerHTML = opts.join("");

    sel.value = codigoEd;

  }



  seleccionarEdificioEnModalCM(codigoEd);

  cambiarSubtabModalConversor(tabInicial);



  const m = document.getElementById("modal-importar-excel-edificio");

  if (m) {

    m.classList.remove("hidden");

    safeCreateIcons();

  }

}



function cerrarModalImportarExcelEdificio() {

  const m = document.getElementById("modal-importar-excel-edificio");

  if (m) m.classList.add("hidden");

}



function seleccionarEdificioEnModalCM(codigo) {

  if (!codigo) {
    const inpCod = document.getElementById("modal-cm-input-codigo");
    const inpNom = document.getElementById("modal-cm-input-nombre");
    const destCod = document.getElementById("modal-cm-dest-codigo");
    const destNom = document.getElementById("modal-cm-dest-nombre");
    if (inpCod) inpCod.value = "";
    if (inpNom) inpNom.value = "";
    if (destCod) destCod.innerText = "Código [----]";
    if (destNom) destNom.innerText = "Seleccione o cree un edificio";
    return;
  }

  let cop = listaCopropiedadesSuperadmin.find(c => c.codigo === codigo || c.id === codigo || c.id === `cj_${codigo}`);

  if (!cop) {

    const driveEd = typeof EDIFICIOS_CATALOGO_DRIVE !== "undefined" ? EDIFICIOS_CATALOGO_DRIVE[codigo] : null;

    if (driveEd) {

      cop = {

        codigo: driveEd.codigo,

        nombre: driveEd.nombre,

        nit: driveEd.nit || "900.000.000-0"

      };

    } else if (codigoNuevoEdificioEnCreacion === codigo && nombreNuevoEdificioEnCreacion) {

      cop = {

        codigo: codigo,

        nombre: nombreNuevoEdificioEnCreacion,

        nit: "900.000.000-0"

      };

    } else {

      cop = (typeof obtenerDatosCopropiedad === "function") ? obtenerDatosCopropiedad(codigo) : null;

      if (!cop) cop = listaCopropiedadesSuperadmin[0];

    }

  }

  if (!cop) return;



  codigoEdificioActivoFusion = cop.codigo;

  copropiedadCargaMasivaActiva = cop.codigo;



  const hNom = document.getElementById("modal-cm-header-nombre");

  const hNit = document.getElementById("modal-cm-header-nit");

  const inpCod = document.getElementById("modal-cm-input-codigo");

  const inpNom = document.getElementById("modal-cm-input-nombre");

  const destCod = document.getElementById("modal-cm-dest-codigo");

  const destNom = document.getElementById("modal-cm-dest-nombre");

  const footEd = document.getElementById("modal-cm-footer-edificio");

  const analCopNom = document.getElementById("modal-cm-analisis-copropiedad-nombre");

  const analTagEd = document.getElementById("modal-cm-analisis-tag-edificio");

  const analBtnEd = document.getElementById("modal-cm-btn-edificio-nombre");

  const analFootCod = document.getElementById("modal-cm-footer-cod");



  if (hNom) hNom.innerText = cop.nombre;

  if (hNit) hNit.innerText = cop.nit;

  if (inpCod) inpCod.value = cop.codigo;

  if (inpNom) inpNom.value = cop.nombre;

  if (destCod) destCod.innerText = `Código [${cop.codigo}]`;

  if (destNom) destNom.innerText = cop.nombre;

  if (footEd) footEd.innerText = cop.nombre;

  if (analCopNom) analCopNom.innerText = cop.nombre;

  if (analTagEd) analTagEd.innerText = cop.nombre;

  if (analBtnEd) analBtnEd.innerText = "Crear Edificio";

  if (analFootCod) analFootCod.innerText = cop.codigo;



  // Botón rápido para cargar directo desde C:\dbplus\{codigo} si existen archivos

  const quickBox = document.getElementById("modal-cm-dbplus-quick-box");

  if (quickBox) {

    quickBox.innerHTML = `

      <button type="button" onclick="cargarDirectoDesdeDbplus('${cop.codigo}')" class="px-4 py-2 rounded-xl bg-gradient-to-r from-amber-600 via-amber-500 to-emerald-600 hover:from-amber-500 hover:to-emerald-500 text-slate-950 font-black text-xs inline-flex items-center gap-2 shadow-lg shadow-amber-950/40 transition-all cursor-pointer">

        <i data-lucide="zap" class="w-4 h-4 text-slate-950"></i>

        <span>⚡ Cargar Datos Oficiales de C:\dbplus\\${cop.codigo} (Archivos MM${cop.codigo} y SS${cop.codigo})</span>

      </button>

    `;

  }



  actualizarBotonCargarDatosRealesFusion(cop.nombre, cop.codigo);

  safeCreateIcons();

}



function toggleModoAsignacionEdificio(modo) {

  const btnEx = document.getElementById("btn-toggle-edificio-existente");

  const btnNv = document.getElementById("btn-toggle-edificio-nuevo");

  const badge = document.getElementById("badge-tipo-operacion-cm");

  const inpCod = document.getElementById("modal-cm-input-codigo");

  const inpNom = document.getElementById("modal-cm-input-nombre");



  if (modo === "nuevo") {

    if (btnNv) {

      btnNv.className = "px-3 py-1.5 rounded-lg bg-emerald-600 text-white font-bold text-xs shadow-sm transition-all";

    }

    if (btnEx) {

      btnEx.className = "px-3 py-1.5 rounded-lg text-slate-400 hover:text-white font-semibold text-xs transition-all";

    }

    if (badge) {

      badge.innerText = "Crear Nuevo Edificio";

      badge.className = "px-2 py-0.5 rounded-lg bg-blue-950/80 text-blue-300 border border-blue-700/60 font-bold text-[10px]";

    }

    if (inpCod) {

      inpCod.removeAttribute("readonly");

      inpCod.value = "";

      inpCod.placeholder = "Ej: 7480";

      inpCod.focus();

    }

    if (inpNom) {

      inpNom.removeAttribute("readonly");

      inpNom.value = "";

      inpNom.placeholder = "Razón Social o Nombre del Edificio";

    }

    mostrarToast("Modo 'Crear Nuevo Edificio' activo: escriba el código y nombre del nuevo edificio.");

  } else {

    if (btnEx) {

      btnEx.className = "px-3 py-1.5 rounded-lg bg-emerald-600 text-white font-bold text-xs shadow-sm transition-all";

    }

    if (btnNv) {

      btnNv.className = "px-3 py-1.5 rounded-lg text-slate-400 hover:text-white font-semibold text-xs transition-all";

    }

    if (badge) {

      badge.innerText = "Actualizar Existente";

      badge.className = "px-2 py-0.5 rounded-lg bg-teal-950/80 text-teal-300 border border-teal-700/60 font-bold text-[10px]";

    }

    if (inpCod) inpCod.setAttribute("readonly", "true");

    if (inpNom) inpNom.setAttribute("readonly", "true");

    const sel = document.getElementById("modal-cm-select-edificio");

    if (sel) seleccionarEdificioEnModalCM(sel.value);

  }

}



function cambiarSubtabModalConversor(subtab) {
  const tabs = ["carga", "fusion3en1", "mapeador", "plantillas", "python"];
  tabs.forEach(t => {
    const btn = document.getElementById(`subtab-modal-cm-${t}`);
    const view = document.getElementById(`modal-cm-view-${t}`);
    if (btn) {
      if (t === 'plantillas' || t === 'python') {
        btn.className = "hidden";
      } else if (t === subtab) {
        if (t === 'fusion3en1') {
          btn.className = "subtab-modal-cm-btn active px-4 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap bg-amber-950/40 text-amber-300 border border-amber-500/50 flex items-center gap-2 shadow-sm";
        } else if (t === 'mapeador') {
          btn.className = "subtab-modal-cm-btn active px-4 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap bg-teal-950/40 text-teal-300 border border-teal-500/50 flex items-center gap-2 shadow-sm";
        } else {
          btn.className = "subtab-modal-cm-btn active px-4 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap bg-emerald-950/40 text-emerald-300 border border-emerald-500/50 flex items-center gap-2 shadow-sm";
        }
      } else {
        if (t === 'fusion3en1') {
          btn.className = "subtab-modal-cm-btn px-4 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap text-amber-300/80 hover:text-white flex items-center gap-2 border border-transparent hover:border-amber-500/40";
        } else if (t === 'mapeador') {
          btn.className = "subtab-modal-cm-btn px-4 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap text-teal-300/80 hover:text-white flex items-center gap-2 border border-transparent hover:border-teal-500/40";
        } else {
          btn.className = "subtab-modal-cm-btn px-4 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap text-slate-400 hover:text-white flex items-center gap-2 border border-transparent hover:border-slate-800";
        }
      }
    }
    if (view) {
      if (t === subtab) view.classList.remove("hidden");
      else view.classList.add("hidden");
    }
  });

  if (subtab === "fusion3en1") {
    inicializarVistaFusion3en1();
  } else if (subtab === "mapeador") {
    inicializarVistaMapeadorVisual();
  }
  safeCreateIcons();
}



