// Lector Nativo DBF en JS

function leerDBFEnJS(arrayBuffer) {

  const view = new DataView(arrayBuffer);

  const numRecords = view.getUint32(4, true);

  const headerLen = view.getUint16(8, true);

  const recordLen = view.getUint16(10, true);

  const numFields = Math.floor((headerLen - 33) / 32);

  const fields = [];

  const textDecoder = new TextDecoder("latin1");



  for (let i = 0; i < numFields; i++) {

    const offset = 32 + (i * 32);

    const rawName = new Uint8Array(arrayBuffer, offset, 11);

    const fname = textDecoder.decode(rawName).replace(/\0/g, "").trim().toUpperCase();

    const ftype = String.fromCharCode(view.getUint8(offset + 11));

    const flen = view.getUint8(offset + 16);

    fields.push({ name: fname, type: ftype, length: flen });

  }



  const records = [];

  let curOffset = headerLen;

  for (let r = 0; r < numRecords; r++) {

    if (curOffset + recordLen > arrayBuffer.byteLength) break;

    const isDeleted = view.getUint8(curOffset) === 0x2A;

    if (!isDeleted) {

      const rec = {};

      let fieldOffset = curOffset + 1;

      for (const f of fields) {

        const rawVal = new Uint8Array(arrayBuffer, fieldOffset, f.length);

        const valStr = textDecoder.decode(rawVal).trim();

        rec[f.name] = (f.type === "N") ? (parseFloat(valStr) || 0) : valStr;

        fieldOffset += f.length;

      }

      records.push(rec);

    }

    curOffset += recordLen;

  }

  return records;

}



// Lector CSV en JS

function leerCSVEnJS(texto) {

  const lineas = texto.split(/\r?\n/).filter(l => l.trim().length > 0);

  if (lineas.length === 0) return [];

  const sep = lineas[0].includes(";") ? ";" : ",";

  const headers = lineas[0].split(sep).map(h => h.trim().replace(/^["']|["']$/g, "").toUpperCase());

  const records = [];

  for (let i = 1; i < lineas.length; i++) {

    const cols = lineas[i].split(sep).map(c => c.trim().replace(/^["']|["']$/g, ""));

    const rec = {};

    headers.forEach((h, idx) => {

      rec[h] = cols[idx] !== undefined ? cols[idx] : "";

    });

    records.push(rec);

  }

  return records;

}



// ==============================================================================

// LECTORES Y PARSERS REALES DE EXCEL (.XLSX, .XLS), CSV, DBF Y JSON

// ==============================================================================



async function leerArchivoEnJSON(file) {

  return new Promise((resolve, reject) => {

    const fn = (file.name || "").toLowerCase();

    const reader = new FileReader();



    if (fn.endsWith(".pdf")) {
      const formData = new FormData();
      formData.append("file", file);
      const urlApi = (typeof getApiBaseUrl === "function") ? getApiBaseUrl() : "";
      fetch(`${urlApi}/api/extraer-datos-archivo`, {
        method: "POST",
        body: formData
      })
      .then(res => res.json())
      .then(data => {
        if (data && data.codigo_detectado) {
          const inpCod = document.getElementById("modal-cm-input-codigo");
          if (inpCod && (!inpCod.value || inpCod.value === "4901")) inpCod.value = data.codigo_detectado;
        }
        if (data && data.nombre_detectado) {
          const inpNom = document.getElementById("modal-cm-input-nombre");
          if (inpNom && (!inpNom.value || inpNom.value === "EDIFICIO ROBLE ALTO P.H.")) inpNom.value = data.nombre_detectado;
        }
        resolve(data && data.rows ? data.rows : []);
      })
      .catch(err => {
        console.warn("Fallo al extraer PDF desde backend:", err);
        resolve([]);
      });
      return;
    }

    if (fn.endsWith(".csv") || fn.endsWith(".txt")) {

      reader.onload = (e) => {

        try {

          const texto = e.target.result;

          const rows = leerCSVEnJS(texto);

          resolve(rows);

        } catch (err) { reject(err); }

      };

      reader.onerror = reject;

      reader.readAsText(file, "ISO-8859-1");

      return;

    }



    if (fn.endsWith(".dbf")) {

      reader.onload = (e) => {

        try {

          const buf = e.target.result;

          const rows = leerDBFEnJS(buf);

          resolve(rows);

        } catch (err) { reject(err); }

      };

      reader.onerror = reject;

      reader.readAsArrayBuffer(file);

      return;

    }



    // Para archivos Excel .xlsx y .xls usando SheetJS

    reader.onload = (e) => {

      try {

        const data = new Uint8Array(e.target.result);

        if (typeof XLSX !== "undefined") {

          const wb = XLSX.read(data, { type: "array" });

          const sheetName = wb.SheetNames[0];

          const sheet = wb.Sheets[sheetName];

          const json = XLSX.utils.sheet_to_json(sheet, { defval: "" });

          resolve(json);

        } else {

          console.warn("SheetJS no disponible, intentando leer texto plano");

          resolve([]);

        }

      } catch (err) {

        reject(err);

      }

    };

    reader.onerror = reject;

    reader.readAsArrayBuffer(file);

  });

}



function procesarDatosEdificio(rows, fileName = "") {

  if (!rows || rows.length === 0) return;

  const codActivo = estadoFusion3en1.edificio?.codigo || codigoEdificioActivoFusion || codigoNuevoEdificioEnCreacion;

  let fila = null;

  if (codActivo) {

    fila = rows.find(r => String(r.CODIGO || r.codigo || "").trim() === String(codActivo).trim());

  }

  if (!fila) {

    // Si algún archivo cargado tenía código (ej 4901), buscarlo

    if (codigoEdificioActivoFusion) {

      fila = rows.find(r => String(r.CODIGO || r.codigo || "").trim() === String(codigoEdificioActivoFusion).trim());

    }

    if (!fila) fila = rows[0];

  }



  const cod = String(fila.CODIGO || fila.codigo || codActivo || "").trim();

  const nom = String(fila.NOMURBAN || fila.NOMADMON || fila.NOM || fila.NOMBRE || fila.nombre || (cod ? `Edificio ${cod}` : "Edificio")).trim();

  const nit = String(fila.NITURBAN || fila.NIT || fila.nit || "").trim();

  const dir = String(fila.DIREC || fila.DIRECCION || fila.direccion || "").trim();

  let tel = String(fila.TEL || fila.TELEFONO || fila.CELULAR || fila.NOMTEL || fila.telefono || "").trim();

  if (tel === "0") tel = "";

  const email = String(fila.EMAILURBAN || fila.EMAIL || fila.CORREO || fila.email || "").trim();

  const banco = String(fila.BANCO || fila.banco || "").trim();

  const cta = String(fila.CUENTA || fila.cuenta || "").trim();

  const admin = String(fila.ADMINISTRADOR || fila.NOMADMON || fila.administrador || "").trim();

  let intMora = String(fila.MORA || fila.INTPORC || fila.INTERES || fila.interesMora || "").trim();

  if (intMora.toUpperCase() === "SUPER") intMora = "";

  if (intMora && !intMora.includes("%")) intMora += "%";



  estadoFusion3en1.edificio = {

    codigo: cod,

    nombre: nom,

    nit: nit,

    direccion: dir,

    ciudad: "Medellín • Antioquia",

    banco: banco,

    tipoCuenta: banco.toUpperCase().includes("AHO") ? "Ahorros" : "Corriente",

    cuenta: cta,

    administrador: admin,

    telefono: tel,

    email: email,

    interesMora: intMora,

    tipo: "Propiedad Horizontal"

  };



  codigoEdificioActivoFusion = cod;

  codigoNuevoEdificioEnCreacion = cod;

  nombreNuevoEdificioEnCreacion = nom;

  estadoFusion3en1.archivosCargados.edificio = true;

  estadoFusion3en1.archivosNombres.edificio = `${fileName || 'EDIFICIO.DBF'} (${nom})`;



  const inpDb = document.getElementById("f3-input-codigo-dbplus");

  if (inpDb) inpDb.value = cod;

  const l1 = document.getElementById("f3-label-codigo-dbplus");

  const l2 = document.getElementById("f3-label-codigo-dbplus2");

  if (l1) l1.innerText = cod;

  if (l2) l2.innerText = cod;



  actualizarBadgesArchivosFusion();

  actualizarEstadisticasFusion(nom, cod);

  actualizarBotonCargarDatosRealesFusion(nom, cod);

  renderizarTablaFusion3en1();

  mostrarToast(`✓ Directorio de '${nom}' (#${cod}) cargado exitosamente.`);

}



function procesarDatosInmuebles(rows, fileName = "") {

  if (!rows || rows.length === 0) return;



  // Auto-detectar código si el archivo MM trae CODIGO

  if (rows[0] && rows[0].CODIGO) {

    const codInm = String(rows[0].CODIGO).trim();

    if (codInm && (!estadoFusion3en1.edificio?.codigo || estadoFusion3en1.edificio.codigo === "7480" || estadoFusion3en1.edificio.codigo === "5304")) {

      codigoEdificioActivoFusion = codInm;

      codigoNuevoEdificioEnCreacion = codInm;

      if (!estadoFusion3en1.edificio) estadoFusion3en1.edificio = {};

      estadoFusion3en1.edificio.codigo = codInm;

      const inpDb = document.getElementById("f3-input-codigo-dbplus");

      if (inpDb) inpDb.value = codInm;

    }

  }



  estadoFusion3en1.rawInmuebles = rows;

  const unidadesMap = new Map();



  rows.forEach((r, idx) => {

    const rawApto = r.APTO || r.UNIDAD || r.INMUEBLE || r.APARTAMENTO || r.IDENT || r.NUMERO || "";

    const apto = String(rawApto).trim();

    if (!apto) return;



    const bloq = String(r.BLOQ || r.BLOQUE || r.TORRE || "AP").trim();

    const prop = String(r.NOM || r.PROPIETARIO || r.NOMBRE || r.TITULAR || `PROPIETARIO APTO ${apto}`).trim();

    const cc = String(r.CC_NIT || r.CC || r.NIT || r.CEDULA || r.DOCUMENTO || "").trim();

    const tipo = String(r.TIPO || r.TIPO_INMUEBLE || "APTO").trim();

    const ubica = String(r.UBICA || r.UBICACION || r.PARQUEADERO || r.UTIL || "").trim();

    let tel = String(r.TEL || r.CEL || r.TELEFONO || r.BEP_CEL || "").trim();

    if (tel === "0") tel = "";

    const email = String(r.EMAIL || r.EMAIL1 || r.CORREO || "").trim();

    const fac = r.FAC || r.FACTURA || "";



    // Coeficiente en DBPLUS (prioridad COEF_URB sobre COEF_APA)

    let rawCoef = 0;

    const cUrb = parseFloat(String(r.COEF_URB || 0).replace("%", "").replace(",", ".")) || 0;

    const cApa = parseFloat(String(r.COEF_APA || 0).replace("%", "").replace(",", ".")) || 0;

    const cGen = parseFloat(String(r.COEFICIENTE || r.COEF || r.COEF_MOD_A || 0).replace("%", "").replace(",", ".")) || 0;

    rawCoef = cUrb > 0 ? cUrb : (cApa > 0 ? cApa : cGen);



    const admon = parseFloat(r.ACTUAL || r.VALOR || r.ADMON || r.CUOTA || 0) || 0;



    unidadesMap.set(apto, {

      unidad: apto,

      apto: apto,

      bloque: bloq,

      bloq: bloq,

      propietario: prop,

      cc: cc,

      tipo: tipo,

      ubicacion: ubica,

      telefono: tel,

      email: email,

      fac: fac,

      coefNum: rawCoef,

      coeficiente: rawCoef > 0 ? (rawCoef.toFixed(3) + "%") : "0.000%",

      admon: admon,

      admonFmt: "$" + Math.round(admon).toLocaleString("es-CO"),

      interes: 0,

      interesFmt: "$0",

      otros: 0,

      otrosFmt: "$0",

      extra: 0,

      extraFmt: "$0",

      multa: 0,

      multaFmt: "$0",

      ser_pub: 0,

      serPubFmt: "$0",

      ser_serv: 0,

      serServFmt: "$0",

      notas_dc: 0,

      notasDcFmt: "$0",

      saldoPendiente: "$0",

      cuotaMensual: "$" + Math.round(admon).toLocaleString("es-CO"),

      totalPagar: "$" + Math.round(admon).toLocaleString("es-CO"),

      totalNum: admon,

      estado: "Al Día"

    });

  });



  if (estadoFusion3en1.rawCartera && estadoFusion3en1.rawCartera.length > 0) {

    fusionarCarteraConUnidades(unidadesMap, estadoFusion3en1.rawCartera);

  }



  // Respetar estrictamente los coeficientes que vienen en los archivos sin inventar ni recalcular
  let sumaCoef = 0;
  unidadesMap.forEach(u => { sumaCoef += (u.coefNum || 0); });



  estadoFusion3en1.unidades = Array.from(unidadesMap.values());

  estadoFusion3en1.archivosCargados.inmuebles = true;

  estadoFusion3en1.archivosNombres.inmuebles = `${fileName || 'MMxxxx.DBF'} (${estadoFusion3en1.unidades.length} unidades)`;



  actualizarBadgesArchivosFusion();

  actualizarChecklistFusion();

  actualizarEstadisticasFusion(estadoFusion3en1.edificio?.nombre, estadoFusion3en1.edificio?.codigo);

  renderizarTablaFusion3en1();

  mostrarToast(`✓ ${estadoFusion3en1.unidades.length} unidades y propietarios cargados exitosamente de '${fileName}'.`);

}



function procesarDatosCartera(rows, fileName = "") {

  if (!rows || rows.length === 0) return;



  estadoFusion3en1.rawCartera = rows;



  let unidadesMap = new Map();

  if (estadoFusion3en1.unidades && estadoFusion3en1.unidades.length > 0) {

    estadoFusion3en1.unidades.forEach(u => unidadesMap.set(u.unidad, u));

  } else {

    rows.forEach(r => {

      const apto = String(r.APTO || r.UNIDAD || r.INMUEBLE || "").trim();

      if (!apto) return;

      unidadesMap.set(apto, {

        unidad: apto,

        apto: apto,

        bloque: String(r.BLOQ || "01").trim(),

        propietario: String(r.NOM || r.PROPIETARIO || `PROPIETARIO APTO ${apto}`).trim(),

        cc: "",

        tipo: "APTO",

        ubicacion: "",

        coefNum: 0,

        coeficiente: "0.000%",

        estado: "Al Día"

      });

    });

  }



  fusionarCarteraConUnidades(unidadesMap, rows);



  estadoFusion3en1.unidades = Array.from(unidadesMap.values());

  estadoFusion3en1.archivosCargados.cartera = true;

  estadoFusion3en1.archivosNombres.cartera = `${fileName || 'SSxxxx.xlsx'} (${rows.length} saldos)`;



  actualizarBadgesArchivosFusion();

  actualizarChecklistFusion();

  actualizarEstadisticasFusion(estadoFusion3en1.edificio?.nombre, estadoFusion3en1.edificio?.codigo);

  mostrarToast(`✓ Saldos de cartera y 8 conceptos Ley 675 aplicados de '${fileName}'.`);

}



function fusionarCarteraConUnidades(unidadesMap, rowsCartera) {
  rowsCartera.forEach(r => {
    const apto = String(r.APTO || r.UNIDAD || r.INMUEBLE || "").trim();
    if (!apto || !unidadesMap.has(apto)) return;

    const u = unidadesMap.get(apto);
    if (r.FAC) u.fac = r.FAC;

    const p_admon = parseFloat(r.ACTUAL || r.ADMON || r.CUOTA || 0) || 0;
    const p_pend = parseFloat(r.PEND || r.SALDO || r.ANTERIOR || 0) || 0;
    const p_inta = parseFloat(r.INTA || r.INT || 0) || 0;
    const p_intp = parseFloat(r.INTP || 0) || 0;
    const p_int = p_inta + p_intp;
    const p_otrosa = parseFloat(r.OTROSA || r.OTROS || 0) || 0;
    const p_otrosp = parseFloat(r.OTROSP || 0) || 0;
    const p_otr = p_otrosa + p_otrosp;
    const p_extraa = parseFloat(r.EXTRAA || r.EXTRA || 0) || 0;
    const p_extrap = parseFloat(r.EXTRAP || 0) || 0;
    const p_ext = p_extraa + p_extrap;
    const p_multaa = parseFloat(r.MULTAA || r.MULTA || 0) || 0;
    const p_multap = parseFloat(r.MULTAP || 0) || 0;
    const p_mul = p_multaa + p_multap;
    const p_serpua = parseFloat(r.SERPUA || r.SER_PUB || 0) || 0;
    const p_serpup = parseFloat(r.SERPUP || 0) || 0;
    const p_sp = p_serpua + p_serpup;
    const p_servia = parseFloat(r.SERVIA || r.SER_SERV || 0) || 0;
    const p_servip = parseFloat(r.SERVIP || 0) || 0;
    const p_ss = p_servia + p_servip;
    const p_ndnca = parseFloat(r.NDNCA || r.NOTAS_DC || 0) || 0;
    const p_ndncp = parseFloat(r.NDNCP || 0) || 0;
    const p_nd = p_ndnca + p_ndncp;

    // Campos oficiales de sumaria SSxxxx: VALDESC (Descuento pronto pago) y VALPAG (Valor a pagar con descuento)
    const p_valdesc = parseFloat(r.VALDESC !== undefined ? r.VALDESC : (r.DESCUENTO || r.DESC || 0)) || 0;
    const totalCalculado = p_admon + p_pend + p_int + p_otr + p_ext + p_mul + p_sp + p_ss + p_nd;
    const p_valpag = (r.VALPAG !== undefined && r.VALPAG !== null && !isNaN(r.VALPAG)) ? (parseFloat(r.VALPAG) || 0) : 0;
    const totalPagar = (r.TOTAL !== undefined && r.TOTAL !== null && !isNaN(r.TOTAL)) ? (parseFloat(r.TOTAL) || 0) : totalCalculado;

    u.actual = p_admon;
    u.pend = p_pend;
    u.inta = p_inta;
    u.intp = p_intp;
    u.otrosa = p_otrosa;
    u.otrosp = p_otrosp;
    u.extraa = p_extraa;
    u.extrap = p_extrap;
    u.multaa = p_multaa;
    u.multap = p_multap;
    u.serpua = p_serpua;
    u.serpup = p_serpup;
    u.servia = p_servia;
    u.servip = p_servip;
    u.ndnca = p_ndnca;
    u.ndncp = p_ndncp;
    u.bloq = u.bloque || String(r.BLOQ || "00").trim();
    u.apto = u.unidad || String(r.APTO || "").trim();

    u.admon = p_admon;
    u.admonFmt = "$" + Math.round(p_admon).toLocaleString("es-CO");
    u.interes = p_int;
    u.interesFmt = "$" + Math.round(p_int).toLocaleString("es-CO");
    u.otros = p_otr;
    u.otrosFmt = "$" + Math.round(p_otr).toLocaleString("es-CO");
    u.extra = p_ext;
    u.extraFmt = "$" + Math.round(p_ext).toLocaleString("es-CO");
    u.multa = p_mul;
    u.multaFmt = "$" + Math.round(p_mul).toLocaleString("es-CO");
    u.ser_pub = p_sp;
    u.serPubFmt = "$" + Math.round(p_sp).toLocaleString("es-CO");
    u.ser_serv = p_ss;
    u.serServFmt = "$" + Math.round(p_ss).toLocaleString("es-CO");
    u.notas_dc = p_nd;
    u.notasDcFmt = "$" + Math.round(p_nd).toLocaleString("es-CO");
    u.valdesc = p_valdesc;
    u.valdescFmt = "$" + Math.round(p_valdesc).toLocaleString("es-CO");
    u.valpag = p_valpag;
    u.valpagFmt = "$" + Math.round(p_valpag).toLocaleString("es-CO");
    u.saldoPendiente = "$" + Math.round(p_pend).toLocaleString("es-CO");
    u.cuotaMensual = "$" + Math.round(p_admon).toLocaleString("es-CO");
    u.totalNum = totalPagar;
    u.totalPagar = "$" + Math.round(totalPagar).toLocaleString("es-CO");
    u.estado = totalPagar > p_admon ? "En Mora" : "Al Día";
  });
}

async function procesarArchivosFusionMultiples(event) {
  const files = Array.from(event.target.files || []);
  if (files.length === 0) return;

  mostrarToast(`Analizando y procesando ${files.length} archivo(s)...`);

  // Paso A: Detectar código del edificio desde los nombres de archivo (MM4901.DBF -> 4901)
  let codigoDetectado = "";
  // 1. Priorizar archivos MMxxxx para el código del edificio (ya que SS puede ser el mes contable SS2611)
  for (const f of files) {
    const fn = (f.name || "").toUpperCase();
    const matchMM = fn.match(/^MM([0-9A-Z]{3,6})/i);
    if (matchMM && matchMM[1]) {
      codigoDetectado = matchMM[1];
      break;
    }
  }
  // 2. Si no hay MM, buscar en otros archivos evitando códigos de mes contable (ej. SS2611)
  if (!codigoDetectado) {
    for (const f of files) {
      const fn = (f.name || "").toUpperCase();
      const match = fn.match(/(?:MM|EDIFICIO|RC|PE|PA|SS)([0-9A-Z]{3,6})/i);
      if (match && match[1]) {
        const cVal = match[1];
        if (/^2[3-9](0[1-9]|1[0-2])$/.test(cVal) && (AppState.codigoEdificio || codigoEdificioActivoFusion)) {
          continue;
        }
        codigoDetectado = cVal;
        break;
      }
    }
  }



  if (codigoDetectado) {

    codigoEdificioActivoFusion = codigoDetectado;

    codigoNuevoEdificioEnCreacion = codigoDetectado;

    if (!estadoFusion3en1.edificio) estadoFusion3en1.edificio = {};

    estadoFusion3en1.edificio.codigo = codigoDetectado;

    const inpDb = document.getElementById("f3-input-codigo-dbplus");

    if (inpDb) inpDb.value = codigoDetectado;

    const l1 = document.getElementById("f3-label-codigo-dbplus");

    const l2 = document.getElementById("f3-label-codigo-dbplus2");

    if (l1) l1.innerText = codigoDetectado;

    if (l2) l2.innerText = codigoDetectado;

  }



  // Paso B: Ordenar para que EDIFICIO vaya primero, MM segundo y SS tercero

  const getOrder = (f) => {

    const fn = f.name.toUpperCase();

    if (fn.includes("EDIFICIO")) return 1;

    if (fn.startsWith("MM") || fn.includes("INMUEBLE") || fn.includes("PROPIETARIO")) return 2;

    if (fn.startsWith("SS") || fn.includes("CARTERA") || fn.includes("SALDO")) return 3;

    return 4;

  };

  files.sort((a, b) => getOrder(a) - getOrder(b));



  // Paso C: Procesar cada archivo secuencialmente

  for (const file of files) {

    try {

      const rows = await leerArchivoEnJSON(file);

      if (!rows || rows.length === 0) continue;



      if (!codigoDetectado && rows[0] && rows[0].CODIGO) {

        codigoDetectado = String(rows[0].CODIGO).trim();

        codigoEdificioActivoFusion = codigoDetectado;

        codigoNuevoEdificioEnCreacion = codigoDetectado;

        if (!estadoFusion3en1.edificio) estadoFusion3en1.edificio = {};

        estadoFusion3en1.edificio.codigo = codigoDetectado;

      }



      const fn = file.name.toUpperCase();

      if (fn.includes("EDIFICIO")) {

        procesarDatosEdificio(rows, file.name);

      } else if (fn.startsWith("MM") || fn.includes("INMUEBLE") || fn.includes("PROPIETARIO")) {

        procesarDatosInmuebles(rows, file.name);

      } else if (fn.startsWith("SS") || fn.includes("CARTERA") || fn.includes("SALDO")) {

        procesarDatosCartera(rows, file.name);

      } else {

        const first = rows[0] || {};

        if (first.NOMURBAN || first.NITURBAN || first.NOMADMON) {

          procesarDatosEdificio(rows, file.name);

        } else if (first.PEND !== undefined || first.INTP !== undefined || first.TOTAL !== undefined) {

          procesarDatosCartera(rows, file.name);

        } else {

          procesarDatosInmuebles(rows, file.name);

        }

      }

    } catch (err) {

      console.warn("Aviso procesando archivo múltiple:", file.name, err);

    }

  }



  // Paso D: Actualizaciones visuales y renderizado garantizado de la tabla

  actualizarBadgesArchivosFusion();

  actualizarChecklistFusion();

  actualizarEstadisticasFusion(estadoFusion3en1.edificio?.nombre, estadoFusion3en1.edificio?.codigo);

  renderizarTablaFusion3en1();

  event.target.value = "";

  safeCreateIcons();

}



async function procesarArchivoFusionIndividual(event, tipo) {

  const file = event.target.files && event.target.files[0];

  if (!file) return;



  mostrarToast(`Leyendo y procesando '${file.name}'...`);

  try {

    const rows = await leerArchivoEnJSON(file);

    if (!rows || rows.length === 0) {

      mostrarToast(`⚠️ El archivo '${file.name}' está vacío o no contiene filas leíbles.`, true);

      return;

    }



    if (tipo === "edificio") {

      procesarDatosEdificio(rows, file.name);

    } else if (tipo === "inmuebles") {

      procesarDatosInmuebles(rows, file.name);

    } else if (tipo === "cartera") {

      procesarDatosCartera(rows, file.name);

    }



    actualizarBadgesArchivosFusion();

    actualizarChecklistFusion();

    actualizarEstadisticasFusion(estadoFusion3en1.edificio?.nombre, estadoFusion3en1.edificio?.codigo);

    renderizarTablaFusion3en1();

    safeCreateIcons();

  } catch (err) {

    console.error("Error leyendo archivo:", err);

    mostrarToast(`❌ Error al procesar '${file.name}': ${err.message}`, true);

  } finally {

    event.target.value = "";

  }

}



