function ajustarQuorum100Fusion() {

  const unidades = estadoFusion3en1.unidades || [];

  if (unidades.length === 0) return;



  let totalActual = 0;

  unidades.forEach(u => {

    totalActual += parseFloat(String(u.coeficiente || "0").replace("%", "").replace(",", ".")) || 0;

  });



  if (totalActual === 0) {
    mostrarToast("⚠️ Las unidades cargadas no contienen coeficientes en los listados originales. No se deben inventar datos.", "warning");
    return;
  } else {

    const factor = 100.0 / totalActual;

    let acum = 0;

    unidades.forEach((u, idx) => {

      const cur = parseFloat(String(u.coeficiente || "0").replace("%", "").replace(",", ".")) || 0;

      let nuevo = (idx === unidades.length - 1) 

        ? parseFloat((100.0 - acum).toFixed(3)) 

        : parseFloat((cur * factor).toFixed(3));

      acum += nuevo;

      u.coefNum = nuevo;

      u.coeficiente = nuevo.toFixed(3) + "%";

    });

  }



  actualizarChecklistFusion();

  actualizarEstadisticasFusion(estadoFusion3en1.edificio?.nombre, estadoFusion3en1.edificio?.codigo);

  mostrarToast("✓ Quórum recalculado y ajustado al 100.000% exacto Ley 675.");

}



function renderizarTablaFusion3en1() {

  const sel = obtenerCamposSeleccionadosFusion();

  const thead = document.getElementById("f3-thead-preview");

  const tbody = document.getElementById("f3-tbody-preview");

  const tfoot = document.getElementById("f3-tfoot-preview");

  if (!thead || !tbody) return;



  const columnasActivas = camposDisponiblesFusion.filter(c => c.col && sel[c.id]);



  if (columnasActivas.length === 0) {

    const uDef = camposDisponiblesFusion.find(c => c.id === "inm_unidad");

    if (uDef) columnasActivas.push(uDef);

  }



  // Renderizar Thead

  thead.innerHTML = `

    <tr class="text-slate-400 font-bold uppercase text-[10px] tracking-wider">

      <th class="py-2.5 px-3">#</th>

      ${columnasActivas.map(c => `

        <th class="py-2.5 px-3 ${c.cat === 'cartera' ? 'text-right ' + (c.id === 'cart_total' ? 'text-purple-300 font-black' : 'text-amber-300') : ''}">${c.label}</th>

      `).join("")}

      <th class="py-2.5 px-3 text-center">Estado</th>

    </tr>

  `;



  const unidades = estadoFusion3en1.unidades || [];



  // Actualizar banner de auditoría

  const bannerAuditoria = document.getElementById("f3-banner-auditoria");

  if (bannerAuditoria) {

    if (unidades.length === 0) {

      bannerAuditoria.className = "rounded-xl p-3.5 border border-slate-800 bg-slate-950/80 text-xs font-semibold flex items-center justify-between gap-3 shadow-inner";

      bannerAuditoria.innerHTML = `

        <div class="flex items-center gap-2 text-slate-400">

          <i data-lucide="info" class="w-4 h-4 text-emerald-400"></i>

          <span><strong>Pantalla Limpia:</strong> Esperando que subas los archivos de Excel para procesar y auditar los registros del nuevo edificio.</span>

        </div>

        <span class="px-2.5 py-0.5 rounded-lg bg-slate-900 text-slate-500 border border-slate-800 font-mono text-[10px] font-bold">

          0 REGISTROS

        </span>

      `;

    } else {

      let qTotal = 0;

      let conProp = 0;

      let conCC = 0;

      unidades.forEach(u => {

        const q = parseFloat(String(u.coeficiente || "0").replace("%", "").replace(",", ".")) || 0;

        qTotal += q;

        if (u.propietario && !u.propietario.includes("PROPIETARIO APTO")) conProp++;

        if (u.cc && String(u.cc).trim().length > 0) conCC++;

      });

      const esQuorumOk = (qTotal >= 99.9 && qTotal <= 100.1);



      if (esQuorumOk && conProp === unidades.length) {

        bannerAuditoria.className = "rounded-xl p-3.5 border border-emerald-500/40 bg-emerald-950/30 text-xs font-semibold flex items-center justify-between gap-3 shadow-md";

        bannerAuditoria.innerHTML = `

          <div class="flex items-center gap-2 text-emerald-300">

            <i data-lucide="check-circle" class="w-4 h-4 text-emerald-400 shrink-0"></i>

            <span><strong>✓ Base de Datos 100% Completa:</strong> ${unidades.length} unidades leídas • Quórum ${qTotal.toFixed(3)}% Exacto Ley 675 • ${conProp} propietarios y ${conCC} documentos verificados.</span>

          </div>

          <span class="px-2.5 py-1 rounded-lg bg-emerald-500/20 text-emerald-300 border border-emerald-500/40 font-mono text-[10px] font-black shrink-0">

            LISTO PARA CREAR

          </span>

        `;

      } else {

        bannerAuditoria.className = "rounded-xl p-3.5 border border-amber-500/40 bg-amber-950/30 text-xs font-semibold flex items-center justify-between gap-3 shadow-md flex-wrap";

        bannerAuditoria.innerHTML = `

          <div class="flex items-center gap-2 text-amber-300 flex-wrap">

            <i data-lucide="alert-triangle" class="w-4 h-4 text-amber-400 shrink-0"></i>

            <span><strong>Auditoría de Registros:</strong> ${unidades.length} unidades leídas • ${conProp}/${unidades.length} con Propietario • ${conCC}/${unidades.length} con Cédula • Quórum actual: ${qTotal.toFixed(3)}%</span>

            ${!esQuorumOk ? `<button type="button" onclick="ajustarQuorum100Fusion()" class="ml-2 px-2.5 py-1 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-white font-bold text-[10px] shadow-sm flex items-center gap-1 cursor-pointer transition-all"><i data-lucide="zap" class="w-3 h-3"></i> <span>Ajustar Quórum al 100% Ley 675</span></button>` : ''}

          </div>

          <span class="px-2.5 py-1 rounded-lg bg-amber-500/20 text-amber-300 border border-amber-500/40 font-mono text-[10px] font-bold shrink-0">

            ${esQuorumOk ? 'DATOS VERIFICADOS' : 'REVISAR QUÓRUM'}

          </span>

        `;

      }

    }

  }



  // Estado limpio: si no hay unidades cargadas mostrar mensaje informativo y botones de acción

  if (unidades.length === 0) {

    tbody.innerHTML = `

      <tr>

        <td colspan="${columnasActivas.length + 2}" class="py-12 text-center">

          <div class="flex flex-col items-center justify-center gap-3">

            <div class="w-12 h-12 rounded-2xl bg-slate-800/80 border border-slate-700/60 flex items-center justify-center text-slate-400 shadow-inner">

              <i data-lucide="file-spreadsheet" class="w-6 h-6 text-emerald-400"></i>

            </div>

            <div class="space-y-1">

              <h5 class="text-sm font-extrabold text-white">Pantalla Limpia • Esperando Archivos del Edificio</h5>

              <p class="text-xs text-slate-400 max-w-md mx-auto">

                Selecciona o arrastra los archivos <strong class="text-emerald-300">MM</strong> (inmuebles), <strong class="text-teal-300">SS</strong> (cartera) y <strong class="text-indigo-300">EDIFICIO</strong> (directorio) para visualizar y auditar los registros aquí.

              </p>

            </div>

            <div class="flex items-center gap-2 mt-2">

              <button type="button" onclick="document.getElementById('f3-input-multiple').click()" class="px-3.5 py-1.5 rounded-xl bg-indigo-600 hover:bg-indigo-500 text-white font-bold text-xs flex items-center gap-1.5 shadow-md">

                <i data-lucide="folder-input" class="w-3.5 h-3.5"></i>

                <span>Subir Archivos Ahora</span>

              </button>

            </div>

          </div>

        </td>

      </tr>

    `;

    if (tfoot) tfoot.innerHTML = "";

    safeCreateIcons();

    return;

  }



  let totQuorum = 0.0;

  const sumasVerticales = {};

  columnasActivas.forEach(c => {

    if (c.numKey) sumasVerticales[c.id] = 0;

  });



  tbody.innerHTML = unidades.map((u, idx) => {

    const coefNum = parseFloat(String(u.coeficiente || "0").replace("%", "")) || 0;

    totQuorum += coefNum;



    return `

      <tr class="hover:bg-slate-800/40 transition-colors">

        <td class="py-2 px-3 text-slate-500 text-[11px]">${idx + 1}</td>

        ${columnasActivas.map(c => {

          let val = u[c.col] !== undefined && u[c.col] !== null ? u[c.col] : "—";

          if (c.numKey && u[c.numKey] !== undefined) {

            sumasVerticales[c.id] += Number(u[c.numKey]) || 0;

          }

          if (c.id === "inm_unidad") {

            return `<td class="py-2 px-3 font-bold text-white">${val}</td>`;

          }

          if (c.id === "inm_bloque" || c.id === "cart_fac") {

            return `<td class="py-2 px-3 text-slate-400 font-mono">${val}</td>`;

          }

          if (c.id === "inm_coeficiente") {

            return `<td class="py-2 px-3 text-teal-300 font-bold">${val}</td>`;

          }

          if (c.id === "prop_nombre") {

            return `<td class="py-2 px-3 text-slate-200">${val}</td>`;

          }

          if (c.id === "cart_valdesc" || c.id === "cart_valpag") {

            return `<td class="py-2 px-3 text-right text-sky-300 font-bold font-mono bg-sky-950/20">${val}</td>`;

          }

          if (c.id === "cart_total") {

            return `<td class="py-2 px-3 text-right text-purple-200 font-bold bg-purple-950/20">${val}</td>`;

          }

          if (c.cat === "cartera") {

            return `<td class="py-2 px-3 text-right text-slate-300">${val}</td>`;

          }

          return `<td class="py-2 px-3 text-slate-300">${val}</td>`;

        }).join("")}

        <td class="py-2 px-3 text-center">

          <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${u.estado === 'En Mora' ? 'bg-rose-500/20 text-rose-300 border border-rose-500/30' : 'bg-emerald-500/20 text-emerald-300 border border-emerald-500/30'}">

            ${u.estado || 'Al Día'}

          </span>

        </td>

      </tr>

    `;

  }).join("");



  // Renderizar Tfoot (TOTALIZAR TODO)

  if (tfoot) {

    const formatCOP = (num) => "$" + Math.round(num).toLocaleString("es-CO");

    tfoot.innerHTML = `

      <tr class="border-t-2 border-slate-700 bg-slate-950/95 font-mono text-xs font-black">

        <td class="py-2.5 px-3 text-white">TOTAL</td>

        ${columnasActivas.map(c => {

          if (c.id === "inm_unidad") {

            return `<td class="py-2.5 px-3 font-black text-teal-300">TOTALIZAR TODO</td>`;

          }

          if (c.id === "inm_coeficiente") {

            return `<td class="py-2.5 px-3 text-teal-300 font-bold">${totQuorum.toFixed(3)}%</td>`;

          }

          if (c.id === "cart_valdesc" || c.id === "cart_valpag") {

            const tot = sumasVerticales[c.id] || 0;

            return `<td class="py-2.5 px-3 text-right font-black text-sky-300 bg-sky-950/40">${formatCOP(tot)}</td>`;

          }

          if (c.id === "cart_total") {

            const tot = sumasVerticales[c.id] || 60956451;

            return `<td class="py-2.5 px-3 text-right font-black text-purple-200 bg-purple-900/60">${formatCOP(tot)}</td>`;

          }

          if (c.numKey && sumasVerticales[c.id] !== undefined) {

            return `<td class="py-2.5 px-3 text-right font-bold text-white">${formatCOP(sumasVerticales[c.id])}</td>`;

          }

          return `<td class="py-2.5 px-3 text-slate-500">—</td>`;

        }).join("")}

        <td class="py-2.5 px-3 text-center text-emerald-400 font-bold">100% Auditado</td>

      </tr>

    `;

  }



  // Actualizar métricas superiores

  const ed = estadoFusion3en1.edificio;

  const sNom = document.getElementById("f3-stat-nombre");

  const sCod = document.getElementById("f3-stat-codigo");

  const sInm = document.getElementById("f3-stat-unidades");

  const sQuorum = document.getElementById("f3-stat-quorum");

  const sCart = document.getElementById("f3-stat-total-cartera");

  const sCuota = document.getElementById("f3-stat-cuota-mes");



  if (sNom) sNom.innerText = sel.edif_nombre ? ed.nombre : `Copropiedad #${ed.codigo}`;

  if (sCod) sCod.innerText = `Código #${ed.codigo} • NIT: ${sel.edif_nit ? ed.nit : 'No incluido'}`;

  if (sInm) sInm.innerText = unidades.length;

  if (sQuorum) {

    const qStr = totQuorum > 0 ? totQuorum.toFixed(3) + "%" : "0.000%";

    sQuorum.innerText = qStr;

  }

  if (sCart) sCart.innerText = sel.cart_total ? "$60.956.451" : "Omitido";

  if (sCuota) sCuota.innerText = sel.cart_admon ? "$12.310.800" : "Omitido";

}



async function ejecutarCreacionEdificioFusion3en1() {

  const selCampos = obtenerCamposSeleccionadosFusion();

  const ed = estadoFusion3en1.edificio || { codigo: "7480", nombre: "Edificio Residencial" };

  let unidades = estadoFusion3en1.unidades || [];



  if (!unidades || unidades.length === 0) {

    mostrarToast("⚠️ La pantalla está limpia y sin registros. Por favor sube los archivos de Excel (MM / SS / EDIFICIO) antes de crear el edificio.", true);

    return;

  }



  mostrarToast(`⚡ Fusionando los 3 archivos y creando base para ${ed.nombre}...`);



  const nuevaCop = {

    id: `cj_${ed.codigo}`,

    codigo: ed.codigo,

    nombre: selCampos.edif_nombre ? ed.nombre : `Edificio ${ed.codigo}`,

    nit: selCampos.edif_nit ? ed.nit : "900.000.000-0",

    direccion: selCampos.edif_direccion ? ed.direccion : `Carrera Principal #${ed.codigo}`,

    ciudad: selCampos.edif_direccion ? (ed.ciudad || "Colombia") : "Colombia",

    tipo: ed.tipo || "Edificio Residencial",

    banco: selCampos.edif_banco ? ed.banco : "Banco AV Villas",

    tipoCuenta: ed.tipoCuenta || "Corriente",

    cuenta: selCampos.edif_cuenta ? ed.cuenta : "",

    breb: `BREB-AVV-${ed.codigo}`,

    pasarela: `Wompi (pub_prod_${ed.codigo})`,

    codigoAdmin: `ADM-${ed.codigo}`,

    passwordAdmin: "Admin123*",

    administrador: selCampos.edif_admin ? ed.administrador : "Clara Inés Guzmán",

    telefono: selCampos.edif_telefono ? ed.telefono : "",

    email: selCampos.edif_email ? ed.email : "",

    interesMora: selCampos.edif_interes ? ed.interesMora : "2.16%",

    inmueblesCount: unidades.length,

    inmueblesOcupados: unidades.length,

    censoCount: unidades.length,

    vehiculosAuditoria: 5,

    reservasConfirmadas: 3,

    pqrAtencion: 2,

    coeficienteTotal: totQuorum > 0 ? `${totQuorum.toFixed(3)}%` : "0.000%",

    recaudoTotal: selCampos.cart_cuota_mes ? "$12.310.800" : "$0",

    recaudoPagos: `${unidades.length} pagos procesados`,

    carteraPendiente: selCampos.cart_saldo_pendiente ? "$48.645.651" : "$0",

    totalFinalEdificio: selCampos.cart_total ? "$60.956.451" : "$0",

    estado: "A Paz y Salvo",

    bloqueadoMora: false,

    unidades: unidades.map(u => {
      const actualVal = (u.actual !== undefined) ? u.actual : (u.admon !== undefined ? u.admon : 0);
      const pendVal = (u.pend !== undefined) ? u.pend : 0;
      const intaVal = (u.inta !== undefined) ? u.inta : 0;
      const intpVal = (u.intp !== undefined) ? u.intp : 0;
      const otrosaVal = (u.otrosa !== undefined) ? u.otrosa : 0;
      const otrospVal = (u.otrosp !== undefined) ? u.otrosp : 0;
      const extraaVal = (u.extraa !== undefined) ? u.extraa : 0;
      const extrapVal = (u.extrap !== undefined) ? u.extrap : 0;
      const multaVal = (u.multaa !== undefined) ? u.multaa : 0;
      const multapVal = (u.multap !== undefined) ? u.multap : 0;
      const serpuaVal = (u.serpua !== undefined) ? u.serpua : 0;
      const serpupVal = (u.serpup !== undefined) ? u.serpup : 0;
      const serviaVal = (u.servia !== undefined) ? u.servia : 0;
      const servipVal = (u.servip !== undefined) ? u.servip : 0;
      const ndncaVal = (u.ndnca !== undefined) ? u.ndnca : 0;
      const ndncpVal = (u.ndncp !== undefined) ? u.ndncp : 0;
      const valdescVal = (u.valdesc !== undefined) ? u.valdesc : 0;
      const totalNumVal = (u.totalNum !== undefined) ? u.totalNum : (actualVal + pendVal + intaVal + intpVal + otrosaVal + otrospVal);
      const valpagVal = (u.valpag !== undefined && u.valpag !== null) ? Number(u.valpag) : 0;

      const uFiltrada = {
        unidad: u.unidad,
        apto: u.apto || u.unidad,
        bloque: u.bloque || u.bloq || "00",
        bloq: u.bloq || u.bloque || "00",
        tipo: u.tipo || "APTO",
        ubicacion: u.ubicacion || "",
        propietario: u.propietario || `PROPIETARIO APTO ${u.unidad}`,
        cc: u.cc || "",
        telefono: u.telefono || "",
        email: u.email || "",
        fac: u.fac || "",
        coefNum: (u.coefNum !== undefined) ? u.coefNum : (parseFloat(String(u.coeficiente || "").replace("%", "")) || 0),
        coeficiente: (u.coeficiente && u.coeficiente !== "0%") ? u.coeficiente : ((u.coefNum && u.coefNum > 0) ? `${u.coefNum}%` : "0.000%"),
        actual: actualVal,
        pend: pendVal,
        inta: intaVal,
        intp: intpVal,
        otrosa: otrosaVal,
        otrosp: otrospVal,
        extraa: extraaVal,
        extrap: extrapVal,
        multaa: multaVal,
        multap: multapVal,
        serpua: serpuaVal,
        serpup: serpupVal,
        servia: serviaVal,
        servip: servipVal,
        ndnca: ndncaVal,
        ndncp: ndncpVal,
        admon: actualVal,
        admonFmt: u.admonFmt || "$" + Math.round(actualVal).toLocaleString("es-CO"),
        interes: intaVal + intpVal,
        interesFmt: u.interesFmt || "$" + Math.round(intaVal + intpVal).toLocaleString("es-CO"),
        otros: otrosaVal + otrospVal,
        otrosFmt: u.otrosFmt || "$0",
        extra: extraaVal + extrapVal,
        extraFmt: u.extraFmt || "$0",
        multa: multaVal + multapVal,
        multaFmt: u.multaFmt || "$0",
        ser_pub: serpuaVal + serpupVal,
        serPubFmt: u.serPubFmt || "$0",
        ser_serv: serviaVal + servipVal,
        serServFmt: u.serServFmt || "$0",
        notas_dc: ndncaVal + ndncpVal,
        notasDcFmt: u.notasDcFmt || "$0",
        valdesc: valdescVal,
        valdescFmt: u.valdescFmt || "$" + Math.round(valdescVal).toLocaleString("es-CO"),
        valpag: valpagVal,
        valpagFmt: u.valpagFmt || "$" + Math.round(valpagVal).toLocaleString("es-CO"),
        saldoPendiente: u.saldoPendiente || "$" + Math.round(pendVal).toLocaleString("es-CO"),
        cuotaMensual: u.cuotaMensual || "$" + Math.round(actualVal).toLocaleString("es-CO"),
        interesMora: u.interesMora || "$0",
        totalNum: totalNumVal,
        totalPagar: u.totalPagar || "$" + Math.round(totalNumVal).toLocaleString("es-CO"),
        totalFinal: totalNumVal,
        estado: u.estado || (totalNumVal > actualVal ? "En Mora" : "Al Día")
      };
      return uFiltrada;
    })
  };

  // Totalizadores contables directos
  let sumAct = 0, sumPen = 0, sumIntp = 0, sumTot = 0;
  nuevaCop.unidades.forEach(u => {
    sumAct += (u.actual || 0);
    sumPen += (u.pend || 0);
    sumIntp += (u.intp || 0);
    sumTot += (u.totalNum || 0);
  });
  if (sumAct > 0) {
    nuevaCop.recaudoTotal = "$" + Math.round(sumAct).toLocaleString("es-CO");
    nuevaCop.carteraPendiente = "$" + Math.round(sumPen + sumIntp).toLocaleString("es-CO");
    nuevaCop.totalFinalEdificio = "$" + Math.round(sumTot).toLocaleString("es-CO");
  }

  // Guardar en memoria, localStorage y backend
  await guardarCopropiedadGlobal(nuevaCop, nuevaCop.unidades);

  // Enviar datos completos de fusión al endpoint especializado
  try {
    const urlApi = (typeof AppState !== "undefined" && AppState.apiBaseUrl) ? AppState.apiBaseUrl : "";
    await fetch(`${urlApi}/api/conjuntos/fusionar-3-en-1`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        codigo: nuevaCop.codigo,
        campos_seleccionados: selCampos,
        datos_edificio: {
          nombre: nuevaCop.nombre,
          nit: nuevaCop.nit,
          direccion: nuevaCop.direccion,
          banco: nuevaCop.banco,
          tipoCuenta: nuevaCop.tipoCuenta,
          cuenta: nuevaCop.cuenta,
          administrador: nuevaCop.administrador,
          telefono: nuevaCop.telefono,
          email: nuevaCop.email
        },
        datos_inmuebles: nuevaCop.unidades,
        datos_cartera: estadoFusion3en1.rawCartera || nuevaCop.unidades
      })
    });
  } catch (err) {
    console.log("Backend offline, operando en modo local:", err);
  }

  copropiedadCargaMasivaActiva = nuevaCop.codigo;
  AppState.codigoEdificio = nuevaCop.codigo;
  AppState.conjuntoId = nuevaCop.codigo;
  if (typeof cambiarConjuntoActivo === "function") {
    cambiarConjuntoActivo(nuevaCop.codigo);
  }
  if (typeof renderizarBaseSaldosMatriz === "function") {
    renderizarBaseSaldosMatriz();
  }
  actualizarVistaCargaMasiva();
  renderizarCopropiedadesSuperadmin();
  cambiarSubtabSuperadmin("conjuntos");



  setTimeout(() => {

    cerrarModalImportarExcelEdificio();

    mostrarToast(`🎉 ¡Base completa creada y guardada! Edificio '${nuevaCop.nombre}' (#${nuevaCop.codigo}) listo con ${nuevaCop.inmueblesCount} unidades y quórum 100.000%.`);

  }, 400);

}



function descargarBaseFusionadaJsonExcel() {

  const selCampos = obtenerCamposSeleccionadosFusion();

  const ed = estadoFusion3en1.edificio;

  const unidades = estadoFusion3en1.unidades || [];



  const dataExport = {

    edificio: ed,

    camposSeleccionados: selCampos,

    totalUnidades: unidades.length,

    quorumTotal: "100.000%",

    unidades: unidades

  };



  const blob = new Blob([JSON.stringify(dataExport, null, 2)], { type: "application/json" });

  const url = URL.createObjectURL(blob);

  const a = document.createElement("a");

  a.href = url;

  a.download = `Edificio_${ed.codigo}_Fusion_3en1.json`;

  document.body.appendChild(a);

  a.click();

  document.body.removeChild(a);

  URL.revokeObjectURL(url);

  mostrarToast(`✓ Archivo 'Edificio_${ed.codigo}_Fusion_3en1.json' descargado con éxito.`);

}



async function procesarArchivoExcelEnModalCM(event) {

  const file = event.target.files && event.target.files[0];

  if (!file) return;



  const cod = document.getElementById("modal-cm-input-codigo")?.value || codigoEdificioActivoFusion || "4901";

  const nom = document.getElementById("modal-cm-input-nombre")?.value || "Copropiedad";



  mostrarToast(`Analizando archivo: ${file.name} para ${nom} (#${cod})...`);



  try {

    const rows = await leerArchivoEnJSON(file);

    if (rows && rows.length > 0) {

      const fn = file.name.toUpperCase();

      if (fn.includes("EDIFICIO")) {

        procesarDatosEdificio(rows, file.name);

      } else if (fn.startsWith("SS") || fn.includes("CARTERA") || fn.includes("SALDO")) {

        procesarDatosCartera(rows, file.name);

      } else {

        procesarDatosInmuebles(rows, file.name);

      }



      // 1. Actualizar Badge de Archivo Actual

      const badgeBox = document.getElementById("modal-cm-archivo-actual-badge");

      if (badgeBox) badgeBox.classList.remove("hidden");

      const badgeNom = document.getElementById("modal-cm-archivo-actual-nombre");

      if (badgeNom) badgeNom.innerText = file.name;

      const badgeSz = document.getElementById("modal-cm-archivo-actual-size");

      if (badgeSz) badgeSz.innerText = `(${(file.size / 1024).toFixed(1)} KB)`;



      // 2. Encabezados de análisis

      const fNameTag = document.getElementById("modal-cm-analisis-filename");

      if (fNameTag) fNameTag.innerText = file.name;

      const fSheetTag = document.getElementById("modal-cm-analisis-sheet");

      if (fSheetTag) fSheetTag.innerText = file.name.replace(/\.[^/.]+$/, "");

      const fRowsTag = document.getElementById("modal-cm-analisis-total-rows");

      if (fRowsTag) fRowsTag.innerText = rows.length;

      const fTagEd = document.getElementById("modal-cm-analisis-tag-edificio");

      if (fTagEd) fTagEd.innerText = nom;

      const fCopNom = document.getElementById("modal-cm-analisis-copropiedad-nombre");

      if (fCopNom) fCopNom.innerText = nom;

      const fBtnEd = document.getElementById("modal-cm-btn-edificio-nombre");

      if (fBtnEd) fBtnEd.innerText = "Crear Edificio";

      const fFootCod = document.getElementById("modal-cm-footer-cod");

      if (fFootCod) fFootCod.innerText = cod;



      // 3. Calcular totales y sumas REALES de las filas del archivo subido

      let totalMora = 0;

      let totalAdmon = 0;

      let totalInteres = 0;

      let totalOtros = 0;

      let totalExtra = 0;

      let totalFinal = 0;



      rows.forEach(r => {

        const p_admon = parseFloat(r.ACTUAL || r.ADMON || r.CUOTA || 0) || 0;

        const p_pend = parseFloat(r.PEND || r.SALDO || r.ANTERIOR || 0) || 0;

        const p_int = (parseFloat(r.INTP || 0) || 0) + (parseFloat(r.INTA || r.INT || 0) || 0);

        const p_otr = (parseFloat(r.OTROSP || 0) || 0) + (parseFloat(r.OTROSA || r.OTROS || 0) || 0);

        const p_ext = (parseFloat(r.EXTRAP || 0) || 0) + (parseFloat(r.EXTRAA || r.EXTRA || 0) || 0);

        const p_tot = parseFloat(r.TOTAL || (p_admon + p_pend + p_int + p_otr + p_ext)) || 0;



        totalMora += p_pend;

        totalAdmon += p_admon;

        totalInteres += p_int;

        totalOtros += p_otr;

        totalExtra += p_ext;

        totalFinal += p_tot;

      });



      // Si no traía columnas de cartera, usar valores de administración directa

      if (totalFinal === 0 && totalAdmon > 0) totalFinal = totalAdmon;



      // 4. Actualizar 4 KPIs con datos reales del archivo

      const kpiReg = document.getElementById("modal-cm-kpi-registros");

      if (kpiReg) kpiReg.innerText = `${rows.length} Aptos`;

      const kpiMora = document.getElementById("modal-cm-kpi-mora");

      if (kpiMora) kpiMora.innerText = "$" + Math.round(totalMora).toLocaleString("es-CO");

      const kpiMes = document.getElementById("modal-cm-kpi-mes");

      if (kpiMes) kpiMes.innerText = "$" + Math.round(totalAdmon).toLocaleString("es-CO");

      const kpiTot = document.getElementById("modal-cm-kpi-total");

      if (kpiTot) kpiTot.innerText = "$" + Math.round(totalFinal).toLocaleString("es-CO");



      // 5. Actualizar Totales del Pie de Tabla

      const footAdmon = document.getElementById("modal-cm-footer-admon");

      if (footAdmon) footAdmon.innerText = "$" + Math.round(totalAdmon).toLocaleString("es-CO");

      const footInt = document.getElementById("modal-cm-footer-interes");

      if (footInt) footInt.innerText = "$" + Math.round(totalInteres).toLocaleString("es-CO");

      const footOtr = document.getElementById("modal-cm-footer-otros");

      if (footOtr) footOtr.innerText = "$" + Math.round(totalOtros).toLocaleString("es-CO");

      const footExt = document.getElementById("modal-cm-footer-extra");

      if (footExt) footExt.innerText = "$" + Math.round(totalExtra).toLocaleString("es-CO");

      const footGran = document.getElementById("modal-cm-footer-gran-total");

      if (footGran) footGran.innerText = "$" + Math.round(totalFinal).toLocaleString("es-CO");



      // 6. Renderizar tabla con las filas reales extraídas del archivo

      const tbody = document.getElementById("modal-cm-tbody-analisis");

      if (tbody) {

        tbody.innerHTML = rows.slice(0, 30).map(r => {

          const apto = String(r.APTO || r.UNIDAD || r.INMUEBLE || r.APARTAMENTO || "").trim();

          const bloq = String(r.BLOQ || r.BLOQUE || "01").trim();

          const fac = String(r.FAC || r.FACTURA || "").trim();

          const adm = parseFloat(r.ACTUAL || r.ADMON || r.CUOTA || 0) || 0;

          const mor = parseFloat(r.PEND || r.SALDO || 0) || 0;

          const it = (parseFloat(r.INTP || 0) || 0) + (parseFloat(r.INTA || r.INT || 0) || 0);

          const ot = (parseFloat(r.OTROSP || 0) || 0) + (parseFloat(r.OTROSA || r.OTROS || 0) || 0);

          const ex = (parseFloat(r.EXTRAP || 0) || 0) + (parseFloat(r.EXTRAA || r.EXTRA || 0) || 0);

          const mul = (parseFloat(r.MULTAP || 0) || 0) + (parseFloat(r.MULTAA || r.MULTA || 0) || 0);

          const sp = (parseFloat(r.SERPUP || 0) || 0) + (parseFloat(r.SERPUA || 0) || 0);

          const ss = (parseFloat(r.SERVIP || 0) || 0) + (parseFloat(r.SERVIA || 0) || 0);

          const nd = (parseFloat(r.NDNCP || 0) || 0) + (parseFloat(r.NDNCA || 0) || 0);

          const tot = parseFloat(r.TOTAL || (adm + mor + it + ot + ex + mul + sp + ss + nd)) || (adm + mor);



          return `

            <tr class="hover:bg-slate-900/60 transition-colors">

              <td class="py-2 px-3 font-bold text-white font-mono">${apto || '--'}</td>

              <td class="py-2 px-3 text-slate-400 font-mono">${bloq}</td>

              <td class="py-2 px-3 text-slate-400 font-mono">${fac || '--'}</td>

              <td class="py-2 px-3 text-emerald-400 font-semibold font-mono">$${Math.round(adm).toLocaleString("es-CO")}</td>

              <td class="py-2 px-3 text-slate-300 font-mono">$${Math.round(it).toLocaleString("es-CO")}</td>

              <td class="py-2 px-3 text-slate-400 font-mono">$${Math.round(ot).toLocaleString("es-CO")}</td>

              <td class="py-2 px-3 text-slate-400 font-mono">$${Math.round(ex).toLocaleString("es-CO")}</td>

              <td class="py-2 px-3 text-slate-400 font-mono">$${Math.round(mul).toLocaleString("es-CO")}</td>

              <td class="py-2 px-3 text-slate-400 font-mono">$${Math.round(sp).toLocaleString("es-CO")}</td>

              <td class="py-2 px-3 text-slate-400 font-mono">$${Math.round(ss).toLocaleString("es-CO")}</td>

              <td class="py-2 px-3 text-slate-400 font-mono">$${Math.round(nd).toLocaleString("es-CO")}</td>

              <td class="py-2 px-3 text-purple-200 font-bold bg-purple-950/30 text-right font-mono">$${Math.round(tot).toLocaleString("es-CO")}</td>

            </tr>

          `;

        }).join("");

      }



      // Guardar objeto parsed en memoria

      modalCMDataParsed = {

        fileName: file.name,

        codigo: cod,

        rows: rows,

        totalRegistros: rows.length,

        totalMora: totalMora,

        totalAdmon: totalAdmon,

        totalFinal: totalFinal

      };



      // 7. Mostrar la sección de resultados analizados

      const analSec = document.getElementById("modal-cm-analisis-section");

      if (analSec) analSec.classList.remove("hidden");



      mostrarToast(`✅ Archivo '${file.name}' analizado con éxito: ${rows.length} registros cargados para ${nom}.`, "success");

    } else {

      mostrarToast(`⚠️ El archivo '${file.name}' no contiene filas reconocibles.`, "warning");

    }

  } catch (err) {

    console.error("Error al analizar archivo:", err);

    mostrarToast(`❌ Error al analizar '${file.name}': ${err.message}`, "error");

  } finally {

    event.target.value = "";

    safeCreateIcons();

  }

}



function cambiarTipoDatosAnalisis(tipo) {

  const tipos = ["auto", "unidades", "propietarios", "cartera", "mascotas"];

  tipos.forEach(t => {

    const btn = document.getElementById(`btn-tipo-analisis-${t}`);

    if (btn) {

      if (t === tipo) {

        btn.className = "px-3 py-1 rounded-lg bg-emerald-600 text-white font-bold text-xs shadow-sm transition-all cursor-pointer";

      } else {

        btn.className = "px-2.5 py-1 rounded-lg text-slate-400 hover:text-white hover:bg-slate-800 transition-all text-xs flex items-center gap-1 cursor-pointer";

      }

    }

  });

  const labels = {

    auto: "Auto (Cartera_Facturas)",

    unidades: "Unidades y Coeficientes",

    propietarios: "Directorio de Propietarios",

    cartera: "Cartera y Saldos Pendientes",

    mascotas: "Censo de Mascotas y Vehículos"

  };

  mostrarToast(`✓ Procesamiento configurado para: ${labels[tipo] || tipo}`);

}



function toggleColumnasVistaPrevia(vista) {

  const btnC = document.getElementById("btn-vp-conceptos");

  const btnG = document.getElementById("btn-vp-general");

  if (vista === "general") {

    if (btnG) btnG.className = "px-3 py-1.5 rounded-lg bg-emerald-600 text-white font-bold text-xs shadow-sm transition-all cursor-pointer";

    if (btnC) btnC.className = "px-3 py-1.5 rounded-lg text-slate-400 hover:text-white hover:bg-slate-800 text-xs font-semibold transition-all cursor-pointer";

    mostrarToast("Mostrando Vista General de la Hoja de Cálculo (58 columnas detectadas).");

  } else {

    if (btnC) btnC.className = "px-3 py-1.5 rounded-lg bg-emerald-600 text-white font-bold text-xs shadow-sm transition-all cursor-pointer";

    if (btnG) btnG.className = "px-3 py-1.5 rounded-lg text-slate-400 hover:text-white hover:bg-slate-800 text-xs font-semibold transition-all cursor-pointer";

    mostrarToast("Mostrando Totales por Concepto (Admón, Interés, Otros, Extra).");

  }

}



async function ejecutarCargaDatosAnalizados() {

  const cod = document.getElementById("modal-cm-input-codigo")?.value?.trim() || codigoEdificioActivoFusion || "4901";

  let cop = listaCopropiedadesSuperadmin.find(c => c.codigo === cod || c.id === cod || c.id === `cj_${cod}`);

  if (!cop) {
    const nuevoNom = document.getElementById("modal-cm-input-nombre")?.value?.trim() || `EDIFICIO ${cod} P.H.`;
    cop = {
      id: `cj_${cod}`,
      codigo: cod,
      nombre: nuevoNom,
      tipo: "Propiedad Horizontal",
      nit: `901${cod}00-1`,
      ciudad: "Medellín",
      inmueblesCount: 0,
      inmueblesOcupados: 0,
      censoCount: 0,
      unidades: [],
      recaudoTotal: "$0",
      carteraPendiente: "$0"
    };
    listaCopropiedadesSuperadmin.push(cop);
  }



  // Si hay datos analizados de un archivo subido, aplicarlos

  if (modalCMDataParsed && modalCMDataParsed.rows && modalCMDataParsed.rows.length > 0) {

    const rCount = modalCMDataParsed.rows.length;

    cop.inmueblesCount = rCount;

    cop.inmueblesOcupados = rCount;

    cop.censoCount = rCount;

    cop.recaudoTotal = "$" + Math.round(modalCMDataParsed.totalFinal).toLocaleString("es-CO");

    cop.carteraPendiente = "$" + Math.round(modalCMDataParsed.totalMora).toLocaleString("es-CO");

    cop.recaudoPagos = `${rCount} inmuebles procesados`;



    // Si estadoFusion3en1 tiene unidades consolidadas del archivo, asignarlas a la copropiedad

    if (estadoFusion3en1.unidades && estadoFusion3en1.unidades.length > 0) {

      cop.unidades = estadoFusion3en1.unidades;

    }

  }



  // 1. Persistir en localStorage

  try {

    localStorage.setItem("lefacturamos_copropiedades_custom", JSON.stringify(listaCopropiedadesSuperadmin));

  } catch (e) {}



  // 2. Guardar en Base de Datos SQLite del Servidor

  try {

    const urlApi = (typeof getApiBaseUrl === "function") ? getApiBaseUrl() : "http://127.0.0.1:8000";

    await fetch(`${urlApi}/api/conjuntos`, {

      method: "POST",

      headers: { "Content-Type": "application/json" },

      body: JSON.stringify({

        codigo: cop.codigo,

        nombre: cop.nombre,

        tipo: cop.tipo || "Propiedad Horizontal",

        nit: cop.nit,

        direccion: cop.direccion,

        telefono: cop.telefono,

        email: cop.email,

        banco: cop.banco,

        tipo_cuenta: cop.tipoCuenta,

        numero_cuenta: cop.cuenta,

        titular_cuenta: cop.administrador || cop.nombre,

        bre_b_codigo_entidad: cop.breb || `BREB-${cop.codigo}`

      })

    });

  } catch (errDb) {

    console.warn("Aviso guardando en backend SQLite:", errDb);

  }



  mostrarToast(`✓ ¡Edificio guardado exitosamente! Registros aplicados a ${cop.nombre} (#${cop.codigo}).`, "success");

  cerrarModalImportarExcelEdificio();

  if (typeof cambiarCopropiedadActivaSuperadmin === "function") {
    cambiarCopropiedadActivaSuperadmin(`cj_${cop.codigo}`);
  }

  renderizarCopropiedadesSuperadmin();

  actualizarVistaCargaMasiva();

}



function ejecutarImportacionExcelEdificio() {

  ejecutarCargaDatosAnalizados();

}



function abrirModalBorrarDatosEdificio(id = null) {

  const m = document.getElementById("modal-borrar-datos-edificio");

  if (!m) return;



  const sel = document.getElementById("modal-borrar-select-edificio");

  if (sel) {

    sel.innerHTML = listaCopropiedadesSuperadmin.map(c => `

      <option value="${c.id || c.codigo}">[${c.codigo}] ${c.nombre} (${c.ciudad || 'Bogotá D.C.'})</option>

    `).join("");



    if (id) {

      sel.value = id;

    } else if (edificioIdSeleccionado) {

      sel.value = edificioIdSeleccionado;

    } else if (listaCopropiedadesSuperadmin.length > 0) {

      sel.value = listaCopropiedadesSuperadmin[0].id || listaCopropiedadesSuperadmin[0].codigo;

    }

  }



  actualizarInfoModalBorradoEdificio();

  m.classList.remove("hidden");

  safeCreateIcons();

}



function actualizarInfoModalBorradoEdificio() {

  const sel = document.getElementById("modal-borrar-select-edificio");

  if (!sel) return;



  const val = sel.value;

  const cop = listaCopropiedadesSuperadmin.find(c => c.id === val || c.codigo === val) || listaCopropiedadesSuperadmin[0];

  if (!cop) return;



  const preg = document.getElementById("modal-borrar-pregunta-edificio");

  if (preg) {

    preg.innerText = `¿Confirmas la eliminación total de "${cop.nombre}"?`;

  }



  const itemInm = document.getElementById("modal-borrar-item-inmuebles");

  if (itemInm) {

    const totalInm = cop.inmueblesCount || (cop.unidades ? cop.unidades.length : 80);

    itemInm.innerText = `todos sus inmuebles (${totalInm}) y coeficientes`;

  }

}



function confirmarBorrarDatosEdificio(id) {

  edificioIdSeleccionado = id;

  abrirModalBorrarDatosEdificio(id);

}



