async function ejecutarBorradoDatosEdificio() {

  const sel = document.getElementById("modal-borrar-select-edificio");

  const val = sel ? sel.value : edificioIdSeleccionado;

  const idx = listaCopropiedadesSuperadmin.findIndex(c => c.id === val || c.codigo === val);



  let nombreBorrado = "Copropiedad";

  if (idx !== -1) {

    nombreBorrado = listaCopropiedadesSuperadmin[idx].nombre;

    const cod = listaCopropiedadesSuperadmin[idx].codigo;

    const idCj = listaCopropiedadesSuperadmin[idx].id || `cj_${cod}`;

    listaCopropiedadesSuperadmin.splice(idx, 1);



    try {

      localStorage.setItem("lefacturamos_copropiedades_custom", JSON.stringify(listaCopropiedadesSuperadmin));

    } catch (e) {}



    if (typeof EDIFICIOS_CATALOGO_DRIVE !== "undefined" && EDIFICIOS_CATALOGO_DRIVE[cod]) {

      delete EDIFICIOS_CATALOGO_DRIVE[cod];

    }

    if (typeof CATALOGO_ADMINISTRADORES_OFICIAL_EDIFICIO !== "undefined" && CATALOGO_ADMINISTRADORES_OFICIAL_EDIFICIO[cod]) {

      delete CATALOGO_ADMINISTRADORES_OFICIAL_EDIFICIO[cod];

    }



    try {

      const urlApi = (typeof AppState !== "undefined" && AppState.apiBaseUrl) ? AppState.apiBaseUrl : "";

      await fetch(`${urlApi}/api/conjuntos/${idCj}`, { method: "DELETE" });

    } catch (e) {}



    actualizarTodosLosSelectsDeCopropiedad();

  }



  cerrarModalBorrarDatosEdificio();

  renderizarCopropiedadesSuperadmin();

  mostrarToast(`🗑️ Todos los datos de "${nombreBorrado}" han sido eliminados permanentemente.`);

}



