// Inicialización del Módulo de Pagos

function inicializarModuloPagos() {

  poblarSelectBancosColombia();

  actualizarDatosCuentaBancariaUI();

  actualizarLinkBancoOficial();



  // Generar QR dinámico Bre-B inicial si existe el contenedor

  const qrContainer = document.getElementById("pago-breb-qrcode");

  if (qrContainer && typeof QRCode !== "undefined") {

    qrContainer.innerHTML = "";

    new QRCode(qrContainer, {

      text: `breb://transfer?key=${AppState.datosBancarios.breb}&val=329800&ref=LF-7480-0301`,

      width: 128,

      height: 128,

      colorDark: "#022c22",

      colorLight: "#ffffff",

      correctLevel: QRCode.CorrectLevel.H

    });

  }



  seleccionarMetodoPago(AppState.metodoPagoActivo || "bre-b");

}



// Poblar selector de bancos con el catálogo completo de Colombia

function poblarSelectBancosColombia() {

  const sel = document.getElementById("pago-pse-banco");

  if (!sel) return;



  sel.innerHTML = BANCOS_COLOMBIA_OFICIALES.map(b => `

    <option value="${b.nombre}" data-url="${b.urlOficial}" data-portal="${b.portalTransaccional}">

      ${b.nombre} (${b.categoria})

    </option>

  `).join("");

}



// Actualizar el enlace al portal oficial del banco seleccionado (100% oficial)

function actualizarLinkBancoOficial() {

  const sel = document.getElementById("pago-pse-banco");

  const btn = document.getElementById("btn-portal-banco-oficial");

  const txt = document.getElementById("txt-portal-banco-oficial");

  if (!sel || !btn || !txt) return;



  const opt = sel.options[sel.selectedIndex];

  if (!opt) return;



  const bancoObj = BANCOS_COLOMBIA_OFICIALES.find(b => b.nombre === opt.value) || BANCOS_COLOMBIA_OFICIALES[0];

  btn.href = bancoObj.portalTransaccional || bancoObj.urlOficial;

  txt.innerText = `Ir a Portal Oficial ${bancoObj.nombre}`;

}



// Selector de Métodos de Pago

function seleccionarMetodoPago(metodoId) {

  AppState.metodoPagoActivo = metodoId;



  // Actualizar estilos de los botones de pestañas

  const tabs = document.querySelectorAll(".tab-metodo-pago");

  tabs.forEach(t => {

    t.classList.remove("border-brand-500", "bg-brand-950/40");

    t.classList.add("border-slate-800", "bg-slate-800/40");

  });



  const activeTab = document.getElementById(`btn-metodo-${metodoId}`);

  if (activeTab) {

    activeTab.classList.remove("border-slate-800", "bg-slate-800/40");

    activeTab.classList.add("border-brand-500", "bg-brand-950/40");

  }



  // Ocultar todos los subpaneles y mostrar el activo

  const panels = document.querySelectorAll(".panel-sub-pago");

  panels.forEach(p => p.classList.add("hidden"));



  const activePanel = document.getElementById(`panel-pago-${metodoId}`);

  if (activePanel) {

    activePanel.classList.remove("hidden");

  }



  // Actualizar texto del botón principal

  const txtBtn = document.getElementById("txt-btn-procesar-pago");

  if (txtBtn) {

    const nombresMetodo = {

      "bre-b": "Pagar con Bre-B Inmediato ($329.800 COP)",

      "pse": "Continuar a PSE Banco Seguro ($329.800 COP)",

      "nequi-daviplata": "Autorizar con Nequi / Daviplata ($329.800 COP)",

      "boton-bancolombia": "Autorizar con Botón Bancolombia ($329.800 COP)",

      "tarjetas": "Pagar con Tarjeta Segura ($329.800 COP)",

      "efectivo": "Generar PIN / Recibo Efectivo ($329.800 COP)",

      "transferencia": "Confirmar Transferencia Bancaria ($329.800 COP)"

    };

    txtBtn.innerText = nombresMetodo[metodoId] || "Procesar Pago Seguro de $329.800 COP";

  }



  safeCreateIcons();

}



// Ejecución unificada de Pago Multi-Método con Máquina de Estados

function ejecutarPagoMultiMetodo() {

  const metodo = AppState.metodoPagoActivo || "bre-b";

  let bancoNombre = AppState.datosBancarios.banco;



  if (metodo === "pse") {

    const pseSel = document.getElementById("pago-pse-banco");

    if (pseSel) bancoNombre = pseSel.value;

  } else if (metodo === "nequi-daviplata") {

    const bilSel = document.getElementById("pago-billetera-tipo");

    if (bilSel) bancoNombre = bilSel.value;

  } else if (metodo === "tarjetas") {

    const tarSel = document.getElementById("pago-tarjeta-proveedor");

    if (tarSel) bancoNombre = tarSel.value;

  } else if (metodo === "efectivo") {

    const efecSel = document.getElementById("pago-efectivo-red");

    if (efecSel) bancoNombre = efecSel.value;

  } else if (metodo === "boton-bancolombia") {

    bancoNombre = "Bancolombia";

  }



  const ref = `LF-${AppState.codigoEdificio}-${AppState.aptoNumero}-${Date.now().toString().slice(-6)}`;

  const codAprob = `AP-${Math.floor(100000 + Math.random() * 900000)}`;

  const reciboNum = `RC-2026-${Date.now().toString().slice(-4)}`;



  // Mostrar máquina de estados

  const container = document.getElementById("contenedor-maquina-estados");

  if (container) container.classList.remove("hidden");



  // Paso 1: INICIADA

  actualizarPasoStepper("iniciada");

  mostrarToast(`Iniciando transacción ${ref} con ${metodo.toUpperCase()}...`);



  // Simular transiciones de estado en tiempo real (Máquina de Estados)

  setTimeout(() => {

    // Paso 2: PENDIENTE

    actualizarPasoStepper("pendiente");

  }, 400);



  setTimeout(() => {

    // Paso 3: APROBADA

    actualizarPasoStepper("aprobada");

  }, 900);



  setTimeout(() => {

    // Paso 4: CONCILIADA

    actualizarPasoStepper("conciliada");



    // Renderizar Recibo de Caja Conciliado

    const box = document.getElementById("resultado-pago-box");

    if (box) {

      box.innerHTML = `

        <div class="flex items-center justify-between border-b border-emerald-900/60 pb-2">

          <div class="flex items-center gap-2 text-emerald-400 font-bold">

            <i data-lucide="check-circle" class="w-5 h-5 text-emerald-400"></i>

            <span>¡Transacción Aprobada y Conciliada Exitosamente!</span>

          </div>

          <span class="px-2 py-0.5 rounded bg-emerald-950 text-emerald-300 font-mono text-[10px] font-bold">FE-3889 CANCELADA</span>

        </div>



        <div class="grid grid-cols-1 sm:grid-cols-2 gap-2 text-xs pt-1">

          <div><strong>Referencia Transacción:</strong> <span class="font-mono text-emerald-300">${ref}</span></div>

          <div><strong>Código de Aprobación:</strong> <span class="font-mono text-white">${codAprob}</span></div>

          <div><strong>Método Utilizado:</strong> <span class="text-white">${metodo.toUpperCase()} (${bancoNombre})</span></div>

          <div><strong>Valor Acreditado:</strong> <span class="font-mono font-bold text-brand-300">$329.800 COP</span></div>

        </div>



        <div class="mt-2 p-3 bg-emerald-950/60 border border-emerald-800/60 rounded-xl flex flex-col sm:flex-row sm:items-center justify-between gap-2">

          <div>

            <span class="text-[10px] text-slate-400 font-bold uppercase block">Recibo Oficial de Caja Generado</span>

            <span class="font-mono font-bold text-white text-xs">${reciboNum} • Sincronizado en Drive</span>

          </div>

          <button onclick="descargarDocumentoDrive('recibo')" class="px-3 py-1.5 rounded-lg bg-emerald-700 hover:bg-emerald-600 text-white font-bold text-xs flex items-center gap-1.5 shadow-md">

            <i data-lucide="download" class="w-3.5 h-3.5"></i>

            <span>Descargar Recibo (PDF)</span>

          </button>

        </div>

      `;

      safeCreateIcons();

    }



    // Despachar Notificación Push FCM

    dispararNotificacionPushFCM(

      "¡Pago Aprobado y Conciliado!",

      `Se acreditó $329.800 COP para Apto 0301 (${metodo.toUpperCase()}). Recibo No. ${reciboNum}.`

    );



    mostrarToast("Pago procesado, conciliado y registrado en contabilidad.");

  }, 1400);

}



// Alias para compatibilidad con código anterior

function ejecutarPago() {

  ejecutarPagoMultiMetodo();

}



// Actualizador visual de los pasos en la máquina de estados

function actualizarPasoStepper(pasoActivo) {

  const pasos = ["iniciada", "pendiente", "aprobada", "conciliada"];

  const badge = document.getElementById("badge-estado-pago");



  pasos.forEach(p => {

    const el = document.getElementById(`step-${p}`);

    if (!el) return;



    el.classList.remove("border-brand-500", "bg-brand-950/40", "border-emerald-500", "bg-emerald-950/60");

    el.classList.add("border-slate-800", "bg-slate-900");

  });



  if (badge) {

    badge.innerText = pasoActivo.toUpperCase();

    badge.className = "px-2.5 py-0.5 rounded font-mono font-bold text-xs " + 

      (pasoActivo === "conciliada" || pasoActivo === "aprobada" 

        ? "bg-emerald-950 text-emerald-400 border border-emerald-800" 

        : "bg-amber-950 text-amber-300 border border-amber-800");

  }



  const elActivo = document.getElementById(`step-${pasoActivo}`);

  if (elActivo) {

    elActivo.classList.remove("border-slate-800", "bg-slate-900");

    elActivo.classList.add("border-brand-500", "bg-brand-950/60");

  }

}



// Actualizar datos de cuenta bancaria receptora en la UI del Copropietario

