// Guardar configuración de cuenta bancaria y pasarelas (Administrador)

function guardarCuentaBancariaAdmin() {

  const banco = document.getElementById("admin-banco-sel").value;

  const tipo = document.getElementById("admin-tipo-cuenta-sel").value;

  const num = document.getElementById("admin-numero-cuenta").value.trim();

  const tit = document.getElementById("admin-titular-cuenta").value.trim();

  const nit = document.getElementById("admin-nit-cuenta").value.trim();

  const breb = document.getElementById("admin-breb-llave").value.trim();

  const wompi = document.getElementById("admin-wompi-pub").value.trim();

  const bold = document.getElementById("admin-bold-key").value.trim();

  const payu = document.getElementById("admin-payu-id").value.trim();



  if (!num || !tit) {

    mostrarToast("Complete el número de cuenta y el titular.", true);

    return;

  }



  const tipoNormalizado = (tipo === "Corriente" ? "Cuenta Corriente" : "Ahorros");

  AppState.datosBancarios = {

    banco: banco,

    tipoCuenta: tipo === "Corriente" ? "Cuenta Corriente" : "Cuenta de Ahorros",

    numeroCuenta: num,

    titular: tit,

    nit: nit,

    breb: breb,

    wompiKey: wompi,

    boldKey: bold,

    payuId: payu

  };

  // Sincronizar copropiedad activa en catálogo y almacenamiento local
  let cop = (typeof obtenerDatosCopropiedad === "function") 
    ? obtenerDatosCopropiedad(AppState.conjuntoId || AppState.codigoEdificio) 
    : null;

  if (cop) {
    cop.banco = banco;
    cop.tipoCuenta = tipoNormalizado;
    cop.cuenta = num;
    cop.nombre = tit;
    cop.nit = nit;
    cop.breb = breb;
    cop.wompiKey = wompi;
    cop.boldKey = bold;
    cop.payuId = payu;

    if (typeof CATALOGO_OFICIAL_DBPLUS !== "undefined" && CATALOGO_OFICIAL_DBPLUS[cop.codigo]) {
      Object.assign(CATALOGO_OFICIAL_DBPLUS[cop.codigo], {
        banco: cop.banco,
        tipoCuenta: cop.tipoCuenta,
        cuenta: cop.cuenta,
        nombre: cop.nombre,
        nit: cop.nit,
        breb: cop.breb
      });
    }

    try {
      localStorage.setItem("lefacturamos_copropiedades_custom", JSON.stringify(listaCopropiedadesSuperadmin));
    } catch (e) {}
  }

  // Sincronizar también campos del modal de edición si está abierto o se abre luego
  const editBanco = document.getElementById("edit-cop-banco");
  if (editBanco) editBanco.value = banco;
  const editTipo = document.getElementById("edit-cop-tipo-cuenta");
  if (editTipo) editTipo.value = tipoNormalizado;
  const editCuenta = document.getElementById("edit-cop-cuenta");
  if (editCuenta) editCuenta.value = num;

  if (typeof sincronizarFormularioBancarioAdmin === "function") {
    sincronizarFormularioBancarioAdmin(cop);
  }

  actualizarDatosCuentaBancariaUI();



  // Enviar al backend si está disponible

  fetch(`${AppState.apiBaseUrl}/api/conjuntos/${AppState.conjuntoId}/cuenta-bancaria`, {

    method: "PUT",

    headers: { "Content-Type": "application/json" },

    body: JSON.stringify({

      banco: banco,

      tipo_cuenta: tipo,

      numero_cuenta: num,

      titular_cuenta: tit,

      nit: nit,

      bre_b_codigo_entidad: breb,

      wompi_public_key: wompi,

      bold_api_key: bold,

      payu_merchant_id: payu

    })

  }).catch(() => {});



  mostrarToast("Cuenta bancaria receptora y pasarelas actualizadas con éxito.");

}



// Modo Sandbox: Simulación interactiva de cada método de pago

function simularPagoSandbox(estadoDeseado) {

  const metodo = AppState.metodoPagoActivo || "bre-b";

  const ref = `LF-SANDBOX-${AppState.codigoEdificio}-${AppState.aptoNumero}-${Date.now().toString().slice(-4)}`;

  const codAprob = estadoDeseado === "APROBADO" ? `SANDBOX-${Math.floor(100000 + Math.random() * 900000)}` : "N/A";

  const reciboNum = estadoDeseado === "APROBADO" ? `RC-SANDBOX-${Date.now().toString().slice(-4)}` : "N/A";



  const logBox = document.getElementById("sandbox-log-box");

  if (logBox) {

    logBox.classList.remove("hidden");

    logBox.innerHTML = `

      <div class="text-amber-400 font-bold mb-1">[SANDBOX WEBHOOK DISPATCH] Proveedor: ${metodo.toUpperCase()}</div>

      <div>&gt; Evento: transaction.updated</div>

      <div>&gt; Endpoint: https://tu-dominio/api/pagos/webhook/${metodo}/</div>

      <div>&gt; Referencia: ${ref}</div>

      <div>&gt; Estado Simulado: <strong class="${estadoDeseado === 'APROBADO' ? 'text-emerald-400' : (estadoDeseado === 'PENDIENTE' ? 'text-amber-400' : 'text-rose-400')}">${estadoDeseado}</strong></div>

      <div>&gt; Signature HMAC-SHA256: 7f8a91bc029e44... [VÁLIDA]</div>

      <div>&gt; Recibo de Caja Generado: ${reciboNum}</div>

    `;

  }



  // Activar contenedor de máquina de estados

  const container = document.getElementById("contenedor-maquina-estados");

  if (container) container.classList.remove("hidden");



  if (estadoDeseado === "APROBADO") {

    actualizarPasoStepper("conciliada");

    dispararNotificacionPushFCM(

      "¡Pago Sandbox Aprobado!",

      `Transacción ${ref} conciliada con éxito. Recibo: ${reciboNum}.`

    );

    mostrarToast("Sandbox: Pago Aprobado y Conciliado.");

  } else if (estadoDeseado === "PENDIENTE") {

    actualizarPasoStepper("pendiente");

    dispararNotificacionPushFCM(

      "Pago en Proceso (Sandbox)",

      `Transacción ${ref} en estado pendiente en red bancaria.`

    );

    mostrarToast("Sandbox: Transacción en estado PENDIENTE.");

  } else {

    actualizarPasoStepper("iniciada");

    const badge = document.getElementById("badge-estado-pago");

    if (badge) {

      badge.innerText = "RECHAZADA";

      badge.className = "px-2.5 py-0.5 rounded font-mono font-bold text-xs bg-rose-950 text-rose-400 border border-rose-800";

    }

    dispararNotificacionPushFCM(

      "Pago Rechazado (Sandbox)",

      `Transacción ${ref} rechazada por fondos insuficientes o rechazo de pasarela.`

    );

    mostrarToast("Sandbox: Transacción RECHAZADA.", true);

  }

}



// Alternar cajón de documentación de webhooks

function toggleCajonWebhooks() {

  const cajon = document.getElementById("cajon-webhooks-info");

  if (cajon) {

    cajon.classList.toggle("hidden");

  }

}



// Copiar texto genérico al portapapeles

function copiarTextoPortapapeles(txt) {

  if (navigator.clipboard) {

    navigator.clipboard.writeText(txt);

  }

  mostrarToast("Copiado al portapapeles: " + txt.slice(0, 35) + "...");

}



// Disparador de Notificación Push FCM Simulada (Banner nativo flotante)

function dispararNotificacionPushFCM(titulo, mensaje) {

  const banner = document.getElementById("fcm-push-banner");

  const tEl = document.getElementById("fcm-push-title");

  const bEl = document.getElementById("fcm-push-body");



  if (tEl) tEl.innerText = titulo;

  if (bEl) bEl.innerText = mensaje;



  if (banner) {

    banner.classList.remove("hidden");



    // Vibración háptica en móvil si el dispositivo lo soporta

    if (navigator.vibrate) {

      try {

        navigator.vibrate([100, 50, 100]);

      } catch (e) {}

    }



    // Auto-cierre tras 6 segundos

    setTimeout(() => {

      cerrarBannerFCM();

    }, 6000);

  }

}



// Cerrar banner FCM

function cerrarBannerFCM() {

  const banner = document.getElementById("fcm-push-banner");

  if (banner) {

    banner.classList.add("hidden");

  }

}



function descargarDocumentoDrive(tipo) {

  const nombre = tipo === "factura" 

    ? `FACTURA_OCTUBRE_2026_APTO_${AppState.aptoNumero}.pdf` 

    : `RECIBO_DE_CAJA_SEPTIEMBRE_2026_APTO_${AppState.aptoNumero}.pdf`;

  

  mostrarToast(`Descargando ${nombre}...`);

  window.open("https://drive.google.com/drive/folders/1u1remh8F3vwpk108ZhibqfDhHErBtYBv?usp=drive_link", "_blank");

}



