// Lista de zonas comunes del edificio activo (Entregar VACÍO por defecto para cada edificio)
let listaZonasComunesGestion = [];

function obtenerCodigoEdificioZonas() {
  return String(
    (typeof AppState !== "undefined" && AppState.codigoEdificio) ||
    (typeof driveEdificioSeleccionado !== "undefined" && driveEdificioSeleccionado) ||
    localStorage.getItem("lefacturamos_active_building") ||
    "4901"
  ).replace(/^cj_/, "").trim();
}

function cargarZonasEdificioStorage() {
  const cod = obtenerCodigoEdificioZonas();
  const raw = localStorage.getItem(`lefacturamos_zonas_edificio_${cod}`);
  if (raw !== null) {
    try {
      const arr = JSON.parse(raw);
      if (Array.isArray(arr)) {
        listaZonasComunesGestion = arr;
        // Restaurar zonas personalizadas al catalogo maestro
        listaZonasComunesGestion.forEach(item => {
          const yaEnCat = CATALOGO_MAESTRO_ZONAS_DEFAULT.some(c => c.clave === item.clave || c.nombre.toLowerCase().trim() === item.nombre.toLowerCase().trim());
          if (!yaEnCat) {
            CATALOGO_MAESTRO_ZONAS_DEFAULT.push({
              clave: item.clave || item.id.replace(/^z_/, ''),
              nombre: item.nombre,
              categoria: item.categoria || "Social",
              descripcion: item.descripcion || "",
              aforoDefault: item.aforo || 10,
              esGratisDefault: item.esGratis !== undefined ? item.esGratis : true,
              precioDefault: item.precio || 0,
              horarioDefault: item.horario || "08:00 - 21:00",
              maxHorasDefault: item.maxHoras || "2h"
            });
          }
        });
        sincronizarCatalogoReservas();
        return;
      }
    } catch (e) {}
  }
  listaZonasComunesGestion = [];
  sincronizarCatalogoReservas();
}

function guardarZonasEdificioStorage() {
  const cod = obtenerCodigoEdificioZonas();
  localStorage.setItem(`lefacturamos_zonas_edificio_${cod}`, JSON.stringify(listaZonasComunesGestion));
  sincronizarCatalogoReservas();
}

function sincronizarCatalogoReservas() {
  if (typeof ZONAS_COMUNES_CATALOGO !== "undefined") {
    ZONAS_COMUNES_CATALOGO.length = 0;
    listaZonasComunesGestion.forEach(z => {
      ZONAS_COMUNES_CATALOGO.push({
        id: z.id,
        nombre: z.nombre,
        categoria: z.categoria || "Social",
        costoAlquiler: z.precio || 0,
        reglas: z.descripcion || `Aforo máximo: ${z.aforo || 10} personas. Horario: ${z.horario || "08:00 - 21:00"}`
      });
    });
  }
}

function renderizarModuloZonasComunes() {
  cargarZonasEdificioStorage();

  const badgeCont = document.getElementById("badge-contador-zonas");
  if (badgeCont) {
    badgeCont.textContent = `(${listaZonasComunesGestion.length} ${listaZonasComunesGestion.length === 1 ? 'activa' : 'activas'})`;
  }

  const contenedor = document.getElementById("grid-zonas-comunes-admin");
  if (!contenedor) return;

  contenedor.innerHTML = CATALOGO_MAESTRO_ZONAS_DEFAULT.map(z => {
    // Verificar si la zona ya pertenece a este edificio
    const enEdificio = listaZonasComunesGestion.find(item => 
      item.id === `z_${z.clave}` || 
      item.clave === z.clave || 
      item.nombre.toLowerCase().trim() === z.nombre.toLowerCase().trim()
    );

    const estaHabilitada = !!enEdificio;
    const precioActual = enEdificio ? (enEdificio.precio !== undefined ? enEdificio.precio : (z.precioDefault || 0)) : (z.precioDefault || 0);

    return `
      <div id="card-tarifa-${z.clave}" class="p-4 rounded-2xl border transition-all ${
        estaHabilitada 
          ? 'bg-slate-900 border-emerald-500/80 ring-1 ring-emerald-500/40 shadow-md shadow-emerald-950/40' 
          : 'bg-slate-950/70 border-slate-800/80 opacity-60 hover:opacity-100'
      } flex flex-col justify-between gap-3">
        <div class="space-y-1.5">
          <div class="flex items-start justify-between gap-2">
            <!-- Cuadrito / Checkbox para escoger si el edificio tiene esta zona -->
            <label class="flex items-center gap-2.5 cursor-pointer select-none">
              <input type="checkbox" id="check-tarifa-${z.clave}" ${estaHabilitada ? 'checked' : ''} onchange="toggleZonaEdificioDesdeTarifas('${z.clave}')" class="w-4 h-4 rounded border-slate-700 bg-slate-800 text-emerald-500 focus:ring-emerald-500 cursor-pointer">
              <span class="font-bold ${estaHabilitada ? 'text-white' : 'text-slate-300'} text-xs sm:text-sm">${z.nombre}</span>
            </label>
            <span class="text-[9px] px-2 py-0.5 rounded bg-slate-800 text-slate-400 font-medium shrink-0">${z.categoria}</span>
          </div>
          <p class="text-[10px] sm:text-xs text-slate-400 leading-relaxed">
            ${z.descripcion}
          </p>
        </div>

        <div class="pt-2.5 border-t border-slate-800/80 space-y-2">
          <div class="flex items-center justify-between text-xs">
            <span class="text-slate-400 font-medium">Tarifa fijada por Admin:</span>
            <span id="badge-estado-${z.clave}" class="text-[11px] font-bold ${estaHabilitada ? 'text-emerald-400' : 'text-slate-500'}">
              ${estaHabilitada ? (precioActual === 0 ? '✓ Gratis ($0)' : '$' + precioActual.toLocaleString('es-CO') + ' COP') : '✕ No asignada'}
            </span>
          </div>

          <div class="flex items-center gap-2">
            <span class="text-xs text-slate-400 font-bold">$</span>
            <input type="number" id="tarifa-input-${z.clave}" value="${precioActual}" min="0" step="5000" oninput="alCambiarPrecioTarifa('${z.clave}', this.value)" class="w-full bg-slate-800 border border-slate-700 rounded-lg px-2.5 py-1.5 text-xs font-mono font-bold text-emerald-400 focus:outline-none focus:ring-1 focus:ring-emerald-500" placeholder="0">
            <span class="text-[10px] text-slate-500 font-semibold">COP</span>
          </div>

          <div class="flex items-center justify-between text-[10px] text-slate-400 pt-0.5">
            <span>Aforo: ${z.aforoDefault} personas</span>
            <span>Horario: ${z.horarioDefault}</span>
          </div>

          ${estaHabilitada ? `
            <div class="pt-1.5 flex items-center gap-2 border-t border-slate-800/60">
              <button type="button" onclick="abrirModalConfigurarZona('${enEdificio.id}')" class="flex-1 py-1.5 px-2 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-200 text-[11px] font-semibold flex items-center justify-center gap-1 transition-all active:scale-95 cursor-pointer">
                <i data-lucide="edit-3" class="w-3 h-3 text-emerald-400"></i>
                <span>Modificar</span>
              </button>
              <button type="button" onclick="eliminarZonaComun('${enEdificio.id}')" class="py-1.5 px-2 rounded-lg bg-rose-950/60 hover:bg-rose-900 border border-rose-800/60 text-rose-300 text-[11px] font-semibold flex items-center justify-center gap-1 transition-all active:scale-95 cursor-pointer" title="Eliminar de este edificio">
                <i data-lucide="trash-2" class="w-3 h-3 text-rose-400"></i>
                <span>Eliminar</span>
              </button>
            </div>
          ` : `
            <button type="button" onclick="document.getElementById('check-tarifa-${z.clave}').click()" class="w-full py-1.5 px-2 rounded-lg bg-slate-900 hover:bg-slate-800 border border-slate-800 text-slate-400 hover:text-emerald-400 text-[11px] font-semibold flex items-center justify-center gap-1 transition-all cursor-pointer">
              <i data-lucide="plus" class="w-3 h-3"></i>
              <span>Activar en este edificio</span>
            </button>
          `}
        </div>
      </div>
    `;
  }).join("");

  safeCreateIcons();
}

function abrirModalConfigurarZona(zonaId) {
  const z = listaZonasComunesGestion.find(item => item.id === zonaId);
  if (!z) return;

  const m = document.getElementById("modal-configurar-zona");
  if (!m) return;

  const elId = document.getElementById("modal-cfg-zona-id");
  if (elId) elId.value = z.id;

  const elNom = document.getElementById("modal-cfg-nombre");
  if (elNom) elNom.value = z.nombre;

  const elDesc = document.getElementById("modal-cfg-descripcion");
  if (elDesc) elDesc.value = z.descripcion;

  const elAforo = document.getElementById("modal-cfg-aforo");
  if (elAforo) elAforo.value = z.aforo;

  const elPrecio = document.getElementById("modal-cfg-precio");
  if (elPrecio) elPrecio.value = z.precio || 0;

  // Formato de horas ej: "07:00 a. m." y "10:00 p. m."
  let horaIni = "07:00 a. m.";
  let horaFin = "10:00 p. m.";
  if (z.horario && z.horario.includes("-")) {
    const parts = z.horario.split("-");
    const h1Raw = parts[0].trim();
    const h2Raw = parts[1].trim();
    const h1Num = parseInt(h1Raw.split(":")[0], 10);
    const h2Num = parseInt(h2Raw.split(":")[0], 10);
    horaIni = h1Raw.includes("m.") ? h1Raw : (h1Num < 12 ? `${h1Raw} a. m.` : `${(h1Num === 12 ? 12 : h1Num - 12).toString().padStart(2, '0')}:${h1Raw.split(":")[1] || '00'} p. m.`);
    horaFin = h2Raw.includes("m.") ? h2Raw : (h2Num < 12 ? `${h2Raw} a. m.` : `${(h2Num === 12 ? 12 : h2Num - 12).toString().padStart(2, '0')}:${h2Raw.split(":")[1] || '00'} p. m.`);
  }
  const elIni = document.getElementById("modal-cfg-hora-ini");
  if (elIni) elIni.value = horaIni;

  const elFin = document.getElementById("modal-cfg-hora-fin");
  if (elFin) elFin.value = horaFin;

  const numDuracion = parseInt(z.maxHoras, 10) || 2;
  const elDur = document.getElementById("modal-cfg-duracion");
  if (elDur) elDur.value = numDuracion;

  const header = document.getElementById("modal-cfg-titulo-header");
  if (header) header.textContent = z.nombre;

  actualizarPreviewAforo(z.aforo);
  actualizarHelperPrecio(z.precio);

  m.classList.remove("hidden");
  safeCreateIcons();
}

function actualizarPreviewAforo(val) {
  const preview = document.getElementById("modal-cfg-aforo-preview");
  if (preview) {
    const num = parseInt(val, 10) || 0;
    preview.textContent = `${num} personas`;
  }
}

function actualizarHelperPrecio(val) {
  const num = parseFloat(val) || 0;
  const helper = document.getElementById("modal-cfg-helper-precio");
  const btnToggle = document.getElementById("btn-toggle-gratuito");

  if (helper) {
    if (num > 0) {
      helper.textContent = `La administración facturará $${num.toLocaleString("es-CO")} COP en la cuenta de cobro del residente.`;
    } else {
      helper.textContent = "El uso de esta zona no genera cobro en la cuenta de administración del residente.";
    }
  }

  if (btnToggle) {
    if (num > 0) {
      btnToggle.textContent = "Poner Gratuito ($0)";
    } else {
      btnToggle.textContent = "Fijar Tarifa ($)";
    }
  }
}

function alternarGratuitoZona() {
  const inputPrecio = document.getElementById("modal-cfg-precio");
  if (!inputPrecio) return;
  const actual = parseFloat(inputPrecio.value) || 0;
  if (actual > 0) {
    inputPrecio.value = 0;
    actualizarHelperPrecio(0);
  } else {
    inputPrecio.value = 20000;
    actualizarHelperPrecio(20000);
  }
}

function cerrarModalConfigurarZona() {
  const m = document.getElementById("modal-configurar-zona");
  if (m) m.classList.add("hidden");
}

function guardarConfiguracionZonaModal(event) {
  if (event) event.preventDefault();
  const id = document.getElementById("modal-cfg-zona-id")?.value;
  const z = listaZonasComunesGestion.find(item => item.id === id);
  if (!z) return;

  const nuevoNombre = document.getElementById("modal-cfg-nombre")?.value.trim();
  const desc = document.getElementById("modal-cfg-descripcion")?.value.trim();
  const aforo = parseInt(document.getElementById("modal-cfg-aforo")?.value, 10) || z.aforo;
  const precio = parseFloat(document.getElementById("modal-cfg-precio")?.value) || 0;
  const horaIni = document.getElementById("modal-cfg-hora-ini")?.value.trim() || "07:00 a. m.";
  const horaFin = document.getElementById("modal-cfg-hora-fin")?.value.trim() || "10:00 p. m.";
  const duracion = parseInt(document.getElementById("modal-cfg-duracion")?.value, 10) || 2;

  if (nuevoNombre) z.nombre = nuevoNombre;
  z.descripcion = desc || z.descripcion;
  z.aforo = aforo;
  z.esGratis = (precio === 0);
  z.precio = precio;
  z.horario = `${horaIni.replace(/\s*[ap]\.\s*m\./i, '').trim()} - ${horaFin.replace(/\s*[ap]\.\s*m\./i, '').trim()}`;
  z.maxHoras = `${duracion}h`;

  if (z.esGratis) {
    z.precioTexto = "Gratuito ($0)";
    z.badgeTexto = "✓ Gratis ($0)";
    z.badgeClase = "bg-emerald-50 text-emerald-700 border-emerald-200";
  } else {
    z.precioTexto = `$${precio.toLocaleString("es-CO")} COP`;
    z.badgeTexto = `$${precio.toLocaleString("es-CO")} COP`;
    z.badgeClase = "bg-amber-50 text-amber-800 border-amber-200";
  }

  guardarZonasEdificioStorage();
  cerrarModalConfigurarZona();
  renderizarModuloZonasComunes();
  mostrarToast(`Zona común "${z.nombre}" actualizada exitosamente.`);
}

function eliminarZonaComun(zonaId) {
  const z = listaZonasComunesGestion.find(item => item.id === zonaId);
  if (!z) return;

  const confirmar = confirm(`¿Está seguro de eliminar "${z.nombre}" de las zonas comunes de este edificio?\n\nLos residentes ya no podrán reservarla.`);
  if (!confirmar) return;

  listaZonasComunesGestion = listaZonasComunesGestion.filter(item => item.id !== zonaId);
  guardarZonasEdificioStorage();
  renderizarModuloZonasComunes();
  mostrarToast(`Zona común "${z.nombre}" eliminada de este edificio.`);
}

function eliminarZonaComunDesdeModal() {
  const id = document.getElementById("modal-cfg-zona-id")?.value;
  if (!id) return;
  cerrarModalConfigurarZona();
  eliminarZonaComun(id);
}

function abrirModalNuevaZonaComun() {
  const m = document.getElementById("modal-nueva-zona-comun");
  if (!m) {
    console.error("modal-nueva-zona-comun no encontrado");
    return;
  }

  const elNom = document.getElementById("modal-nz-nombre");
  if (elNom) elNom.value = "";
  const elDesc = document.getElementById("modal-nz-descripcion");
  if (elDesc) elDesc.value = "";
  const elAforo = document.getElementById("modal-nz-aforo");
  if (elAforo) elAforo.value = 10;
  const elTipo = document.getElementById("modal-nz-tipo-tarifa");
  if (elTipo) elTipo.value = "gratis";
  const elPrecio = document.getElementById("modal-nz-precio");
  if (elPrecio) elPrecio.value = "";
  const elHorario = document.getElementById("modal-nz-horario");
  if (elHorario) elHorario.value = "08:00 - 21:00";
  const elMax = document.getElementById("modal-nz-maxhoras");
  if (elMax) elMax.value = "2h";

  actualizarVisibilidadPrecioNuevaZona();

  m.classList.remove("hidden");
  m.style.display = "flex";
  m.style.zIndex = "99999";
  safeCreateIcons();

  if (elNom) setTimeout(() => elNom.focus(), 100);
}

function cerrarModalNuevaZonaComun() {
  const m = document.getElementById("modal-nueva-zona-comun");
  if (m) {
    m.classList.add("hidden");
    m.style.display = "none";
  }
}

function actualizarVisibilidadPrecioNuevaZona() {
  const tipo = document.getElementById("modal-nz-tipo-tarifa")?.value;
  const cont = document.getElementById("modal-nz-contenedor-precio");
  if (!cont) return;
  if (tipo === "pago") {
    cont.classList.remove("hidden");
    cont.style.display = "block";
  } else {
    cont.classList.add("hidden");
    cont.style.display = "none";
  }
}

function guardarNuevaZonaComunModal(event) {
  if (event) event.preventDefault();
  const nombre = document.getElementById("modal-nz-nombre")?.value.trim();
  const categoria = document.getElementById("modal-nz-categoria")?.value || "Social";
  const desc = document.getElementById("modal-nz-descripcion")?.value.trim();
  const aforo = parseInt(document.getElementById("modal-nz-aforo")?.value, 10) || 10;
  const tipo = document.getElementById("modal-nz-tipo-tarifa")?.value;
  const precio = tipo === "pago" ? (parseFloat(document.getElementById("modal-nz-precio")?.value) || 0) : 0;
  const horario = document.getElementById("modal-nz-horario")?.value.trim() || "08:00 - 21:00";
  const maxHoras = document.getElementById("modal-nz-maxhoras")?.value.trim() || "2h";

  if (!nombre) {
    mostrarToast("Escriba el nombre de la zona común personalizada.", true);
    return;
  }

  const yaExiste = listaZonasComunesGestion.find(z => z.nombre.toLowerCase().trim() === nombre.toLowerCase().trim());
  if (yaExiste) {
    mostrarToast(`La zona común "${nombre}" ya está registrada en este edificio.`, true);
    return;
  }

  const claveCustom = `custom_${Date.now()}`;
  const esGratis = (tipo === "gratis" || precio === 0);
  const nuevaZona = {
    id: `z_${claveCustom}`,
    clave: claveCustom,
    nombre: nombre,
    categoria: categoria,
    descripcion: desc || `Espacio común de copropiedad. Aforo: ${aforo} personas.`,
    aforo: aforo,
    esGratis: esGratis,
    precio: precio,
    precioTexto: esGratis ? "Gratuito ($0)" : `$${precio.toLocaleString("es-CO")} COP`,
    badgeTexto: esGratis ? "✓ Gratis ($0)" : `$${precio.toLocaleString("es-CO")} COP`,
    badgeClase: esGratis ? "bg-emerald-50 text-emerald-700 border-emerald-200" : "bg-amber-50 text-amber-800 border-amber-200",
    horario: horario,
    maxHoras: maxHoras
  };

  // Agregar al catálogo maestro para que se renderice como tarjeta en Zonas Comunes
  CATALOGO_MAESTRO_ZONAS_DEFAULT.push({
    clave: claveCustom,
    nombre: nombre,
    categoria: categoria,
    descripcion: nuevaZona.descripcion,
    aforoDefault: aforo,
    esGratisDefault: esGratis,
    precioDefault: precio,
    horarioDefault: horario,
    maxHorasDefault: maxHoras
  });

  listaZonasComunesGestion.push(nuevaZona);
  guardarZonasEdificioStorage();

  cerrarModalNuevaZonaComun();
  renderizarModuloZonasComunes();
  cargarOpcionesZonasSelect();
  mostrarToast(`✓ Zona personalizada "${nombre}" creada y agregada al edificio.`);
}

