function inicializarModuloReservas() {
  const esAdmin = (typeof AppState !== "undefined" && (AppState.rol === "admin" || AppState.rol === "superadmin"));
  const seccionAdminReservas = document.getElementById("seccion-admin-solicitudes-reservas");
  const seccionFormularioReserva = document.getElementById("seccion-gestion-reservas-completo");

  if (seccionAdminReservas) {
    if (esAdmin) {
      seccionAdminReservas.classList.remove("hidden");
      seccionAdminReservas.style.display = "block";
    } else {
      seccionAdminReservas.classList.add("hidden");
      seccionAdminReservas.style.display = "none";
    }
  }

  if (seccionFormularioReserva) {
    if (esAdmin) {
      seccionFormularioReserva.classList.add("hidden");
      seccionFormularioReserva.style.display = "none";
    } else {
      seccionFormularioReserva.classList.remove("hidden");
      seccionFormularioReserva.style.display = "block";
    }
  }

  const inputFecha = document.getElementById("reserva-fecha");
  if (inputFecha) {
    const hoy = new Date().toISOString().split("T")[0];
    if (!inputFecha.value || inputFecha.value === "2026-10-22") {
      inputFecha.value = hoy;
    }
    inputFecha.min = hoy;
  }

  try {
    const guardadasRes = localStorage.getItem("lefacturamos_reservas_copropiedad");
    if (guardadasRes) {
      const arr = JSON.parse(guardadasRes);
      if (Array.isArray(arr) && arr.length > 0) {
        listaReservasCopropiedad = arr;
      }
    }
  } catch (e) {}

  cargarZonasEdificioStorage();
  renderizarReservasCopropietarios();
  cargarOpcionesZonasSelect();
  cambioZonaSeleccionada();
  actualizarHorariosOcupados();
  cargarMisReservas();
}

let vistaReservasAdminActual = "vigentes"; // "vigentes" (hoy y posteriores) o "historial" (pasadas)

function cambiarVistaReservasAdmin(vista) {
  vistaReservasAdminActual = vista;
  const tabVigentes = document.getElementById("tab-reservas-vigentes");
  const tabHistorial = document.getElementById("tab-reservas-historial");
  
  if (tabVigentes && tabHistorial) {
    if (vista === "vigentes") {
      tabVigentes.className = "px-3 py-1.5 rounded-xl text-xs font-bold flex items-center gap-2 transition-all cursor-pointer bg-emerald-950 text-emerald-300 border border-emerald-700/80 shadow";
      tabHistorial.className = "px-3 py-1.5 rounded-xl text-xs font-bold flex items-center gap-2 transition-all cursor-pointer bg-slate-800/60 hover:bg-slate-800 text-slate-400 border border-slate-700/60";
    } else {
      tabHistorial.className = "px-3 py-1.5 rounded-xl text-xs font-bold flex items-center gap-2 transition-all cursor-pointer bg-amber-950 text-amber-300 border border-amber-700/80 shadow";
      tabVigentes.className = "px-3 py-1.5 rounded-xl text-xs font-bold flex items-center gap-2 transition-all cursor-pointer bg-slate-800/60 hover:bg-slate-800 text-slate-400 border border-slate-700/60";
    }
  }
  
  renderizarReservasCopropietarios();
}

function renderizarReservasCopropietarios() {
  const cont = document.getElementById("lista-reservas-copropietarios");
  const badgeCont = document.getElementById("badge-contador-reservas");
  const badgeVigentes = document.getElementById("badge-tab-vigentes");
  const badgeHistorial = document.getElementById("badge-tab-historial");
  if (!cont) return;

  const esAdmin = (typeof AppState !== "undefined" && (AppState.rol === "admin" || AppState.rol === "superadmin" || AppState.rol === "administrador"));
  const hoy = new Date().toISOString().split("T")[0];
  const filtroFecha = document.getElementById("filtro-fecha-reservas-admin")?.value;

  // Separar reservas activas (hoy y posteriores) del historial (fechas anteriores)
  const vigentesTodas = listaReservasCopropiedad.filter(r => r.fecha >= hoy);
  const historialTodas = listaReservasCopropiedad.filter(r => r.fecha < hoy);

  // Actualizar badges de conteo en las pestañas
  if (badgeVigentes) badgeVigentes.textContent = vigentesTodas.length;
  if (badgeHistorial) badgeHistorial.textContent = historialTodas.length;

  let reservasAMostrar = [];

  if (filtroFecha) {
    // Si el administrador eligió una fecha específica en el calendario
    reservasAMostrar = listaReservasCopropiedad.filter(r => r.fecha === filtroFecha);
  } else {
    // Modo pestaña: hoy y posteriores (por defecto) o historial de pasadas
    if (vistaReservasAdminActual === "vigentes") {
      reservasAMostrar = [...vigentesTodas].sort((a, b) => (a.fecha + a.horaIni).localeCompare(b.fecha + b.horaIni));
    } else {
      reservasAMostrar = [...historialTodas].sort((a, b) => (b.fecha + b.horaIni).localeCompare(a.fecha + a.horaIni));
    }
  }

  if (badgeCont) {
    if (filtroFecha) {
      badgeCont.textContent = `(${reservasAMostrar.length} el ${filtroFecha})`;
    } else if (vistaReservasAdminActual === "vigentes") {
      badgeCont.textContent = `(${reservasAMostrar.length} ${reservasAMostrar.length === 1 ? 'vigente' : 'vigentes'})`;
    } else {
      badgeCont.textContent = `(${reservasAMostrar.length} en historial)`;
    }
  }

  if (reservasAMostrar.length === 0) {
    if (filtroFecha) {
      cont.innerHTML = `
        <div class="py-8 text-center text-xs text-slate-400 space-y-1">
          <div class="w-10 h-10 mx-auto rounded-full bg-slate-800 text-slate-400 flex items-center justify-center mb-2">
            <i data-lucide="calendar-x" class="w-5 h-5"></i>
          </div>
          <p class="font-bold text-slate-300">No hay reservas para la fecha ${filtroFecha}</p>
          <button type="button" onclick="limpiarFiltroReservas()" class="text-xs text-emerald-400 underline hover:text-emerald-300 cursor-pointer pt-1">
            Limpiar filtro de fecha
          </button>
        </div>
      `;
    } else if (vistaReservasAdminActual === "vigentes") {
      cont.innerHTML = `
        <div class="py-8 text-center text-xs text-slate-400 space-y-2">
          <div class="w-12 h-12 mx-auto rounded-2xl bg-slate-800/80 border border-slate-700/80 text-emerald-400 flex items-center justify-center shadow-lg">
            <i data-lucide="calendar-check-2" class="w-6 h-6"></i>
          </div>
          <p class="font-bold text-white text-sm">No hay reservas programadas para hoy ni días posteriores</p>
          <p class="text-[11px] text-slate-400 max-w-md mx-auto">
            Las nuevas solicitudes de zonas comunes reservadas para hoy o fechas futuras se mostrarán aquí automáticamente en tiempo real.
          </p>
          ${historialTodas.length > 0 ? `
            <div class="pt-2">
              <button type="button" onclick="cambiarVistaReservasAdmin('historial')" class="px-3.5 py-1.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-amber-300 border border-amber-900/60 font-bold text-xs inline-flex items-center gap-1.5 cursor-pointer transition-all shadow">
                <i data-lucide="history" class="w-3.5 h-3.5"></i>
                <span>Consultar Historial de Reservas Pasadas (${historialTodas.length})</span>
              </button>
            </div>
          ` : ""}
        </div>
      `;
    } else {
      cont.innerHTML = `
        <div class="py-8 text-center text-xs text-slate-400 space-y-1">
          <div class="w-10 h-10 mx-auto rounded-full bg-slate-800 text-slate-400 flex items-center justify-center mb-2">
            <i data-lucide="history" class="w-5 h-5"></i>
          </div>
          <p class="font-bold text-slate-300">El historial de reservas se encuentra vacío</p>
          <p class="text-[11px] text-slate-500">Las reservas concluidas se archivarán aquí automáticamente.</p>
        </div>
      `;
    }
    safeCreateIcons();
    return;
  }

  cont.innerHTML = reservasAMostrar.map(r => {
    const esMiApto = (typeof AppState !== "undefined" && (r.apto === AppState.aptoNumero || r.residente === AppState.propietario));
    const puedeCancelar = esAdmin || esMiApto;
    const esPasada = (r.fecha < hoy);

    return `
      <div class="pt-3 first:pt-0 flex flex-col sm:flex-row sm:items-center justify-between gap-3 text-xs hover:bg-slate-800/40 p-3 rounded-xl transition-all ${esPasada ? 'opacity-85' : ''}">
        <div class="space-y-1">
          <div class="flex items-center gap-2 flex-wrap">
            <h4 class="font-black text-white text-sm">${r.zona}</h4>
            ${esPasada ? `
              <span class="px-2 py-0.5 rounded-full bg-slate-800 text-amber-300 border border-amber-800/60 text-[10px] font-bold flex items-center gap-1">
                <i data-lucide="history" class="w-3 h-3"></i>
                <span>Historial (Pasada)</span>
              </span>
            ` : `
              <span class="px-2 py-0.5 rounded-full bg-emerald-950/90 text-emerald-400 border border-emerald-800 text-[10px] font-bold flex items-center gap-1">
                <i data-lucide="check-circle" class="w-3 h-3"></i>
                <span>${r.estado || 'Confirmada'}</span>
              </span>
            `}
            <span class="px-2 py-0.5 rounded bg-slate-800 text-emerald-400 font-mono text-[11px] font-bold">Apto ${r.apto}</span>
            ${r.fecha === hoy ? `
              <span class="px-2 py-0.5 rounded-full bg-brand-500 text-slate-950 text-[10px] font-black uppercase tracking-wider animate-pulse">
                Hoy
              </span>
            ` : ''}
          </div>
          <div class="text-xs text-slate-300 flex flex-wrap items-center gap-x-3 gap-y-0.5">
            <span>📅 Fecha: <strong class="text-white">${r.fecha}</strong></span>
            <span>⏰ Horario: <strong class="text-white">${r.horario || (r.horaIni + ' - ' + r.horaFin)}</strong></span>
            <span>👥 Aforo: <strong class="text-white">${r.personas || 4} personas</strong></span>
          </div>
          <div class="text-xs text-slate-400">
            <span>👤 Copropietario Solicitante: <strong class="text-slate-200">${r.residente || 'Residente'}</strong></span>
          </div>
        </div>

        <div class="flex sm:flex-col items-center sm:items-end justify-between sm:justify-center gap-2 shrink-0">
          <span class="font-mono font-black text-emerald-400 text-xs sm:text-sm bg-slate-800/80 px-2.5 py-1 rounded-lg border border-slate-700/60">${r.costo || '$0 COP'}</span>
          ${puedeCancelar && !esPasada ? `
            <button type="button" onclick="cancelarReserva('${r.id}')" class="px-3 py-1 rounded-lg bg-rose-950/70 hover:bg-rose-900 border border-rose-800 text-rose-300 font-bold text-[11px] flex items-center gap-1 transition-all active:scale-95 cursor-pointer" title="Cancelar reserva y liberar el horario">
              <i data-lucide="x" class="w-3.5 h-3.5 text-rose-400"></i>
              <span>Cancelar / Liberar</span>
            </button>
          ` : (puedeCancelar && esPasada ? `
            <span class="text-[10px] text-slate-500 font-medium px-2 py-1 rounded bg-slate-800/50">Turno finalizado</span>
          ` : "")}
        </div>
      </div>
    `;
  }).join("");

  safeCreateIcons();
}

function limpiarFiltroReservas() {
  const inp = document.getElementById("filtro-fecha-reservas-admin");
  if (inp) inp.value = "";
  renderizarReservasCopropietarios();
}

function renderizarTarifasAdmin() {
  renderizarModuloZonasComunes();
}

function toggleZonaEdificioDesdeTarifas(clave) {
  const z = CATALOGO_MAESTRO_ZONAS_DEFAULT.find(c => c.clave === clave);
  if (!z) return;

  const checkbox = document.getElementById(`check-tarifa-${clave}`);
  const estaCheckeada = checkbox ? checkbox.checked : false;

  const idxExistente = listaZonasComunesGestion.findIndex(item => 
    item.id === `z_${z.clave}` || 
    item.clave === z.clave || 
    item.nombre.toLowerCase().trim() === z.nombre.toLowerCase().trim()
  );

  const inputPrecio = document.getElementById(`tarifa-input-${clave}`);
  const precioIngresado = inputPrecio ? (parseFloat(inputPrecio.value) || 0) : (z.precioDefault || 0);

  if (estaCheckeada) {
    const esGratis = (precioIngresado === 0);
    const zonaActualizada = {
      id: `z_${z.clave}`,
      clave: z.clave,
      nombre: z.nombre,
      categoria: z.categoria,
      descripcion: z.descripcion,
      aforo: z.aforoDefault,
      esGratis: esGratis,
      precio: precioIngresado,
      precioTexto: esGratis ? "Gratuito ($0)" : `$${precioIngresado.toLocaleString("es-CO")} COP`,
      badgeTexto: esGratis ? "✓ Gratis ($0)" : `$${precioIngresado.toLocaleString("es-CO")} COP`,
      badgeClase: esGratis ? "bg-emerald-50 text-emerald-700 border-emerald-200" : "bg-amber-50 text-amber-800 border-amber-200",
      horario: z.horarioDefault,
      maxHoras: z.maxHorasDefault
    };

    if (idxExistente >= 0) {
      listaZonasComunesGestion[idxExistente] = zonaActualizada;
    } else {
      listaZonasComunesGestion.push(zonaActualizada);
    }

    guardarZonasEdificioStorage();
    mostrarToast(`✓ "${z.nombre}" habilitada para este edificio (${zonaActualizada.precioTexto}).`);
  } else {
    if (idxExistente >= 0) {
      listaZonasComunesGestion.splice(idxExistente, 1);
      guardarZonasEdificioStorage();
      mostrarToast(`"${z.nombre}" retirada de este edificio.`);
    }
  }

  cargarOpcionesZonasSelect();
  cambioZonaSeleccionada();
  renderizarModuloZonasComunes();
}

function alCambiarPrecioTarifa(clave, valorStr) {
  const nuevoValor = parseFloat(valorStr) || 0;
  const z = CATALOGO_MAESTRO_ZONAS_DEFAULT.find(c => c.clave === clave);
  if (!z) return;

  const enEdificio = listaZonasComunesGestion.find(item => 
    item.id === `z_${z.clave}` || 
    item.clave === z.clave || 
    item.nombre.toLowerCase().trim() === z.nombre.toLowerCase().trim()
  );

  if (enEdificio) {
    enEdificio.precio = nuevoValor;
    enEdificio.esGratis = (nuevoValor === 0);
    enEdificio.precioTexto = (nuevoValor === 0) ? "Gratuito ($0)" : `$${nuevoValor.toLocaleString("es-CO")} COP`;
    enEdificio.badgeTexto = (nuevoValor === 0) ? "✓ Gratis ($0)" : `$${nuevoValor.toLocaleString("es-CO")} COP`;
    enEdificio.badgeClase = (nuevoValor === 0) ? "bg-emerald-50 text-emerald-700 border-emerald-200" : "bg-amber-50 text-amber-800 border-amber-200";
    guardarZonasEdificioStorage();
    cargarOpcionesZonasSelect();
    cambioZonaSeleccionada();
    const badge = document.getElementById(`badge-estado-${clave}`);
    if (badge) {
      badge.textContent = nuevoValor === 0 ? "✓ Gratis ($0)" : `$${nuevoValor.toLocaleString("es-CO")} COP`;
    }
  }
}

function guardarTarifasAdmin() {
  CATALOGO_MAESTRO_ZONAS_DEFAULT.forEach(z => {
    const cb = document.getElementById(`check-tarifa-${z.clave}`);
    const input = document.getElementById(`tarifa-input-${z.clave}`);
    const precio = input ? (parseFloat(input.value) || 0) : (z.precioDefault || 0);

    const idx = listaZonasComunesGestion.findIndex(item => 
      item.id === `z_${z.clave}` || 
      item.clave === z.clave || 
      item.nombre.toLowerCase().trim() === z.nombre.toLowerCase().trim()
    );

    if (cb && cb.checked) {
      const esGratis = (precio === 0);
      const obj = {
        id: `z_${z.clave}`,
        clave: z.clave,
        nombre: z.nombre,
        categoria: z.categoria,
        descripcion: z.descripcion,
        aforo: z.aforoDefault,
        esGratis: esGratis,
        precio: precio,
        precioTexto: esGratis ? "Gratuito ($0)" : `$${precio.toLocaleString("es-CO")} COP`,
        badgeTexto: esGratis ? "✓ Gratis ($0)" : `$${precio.toLocaleString("es-CO")} COP`,
        badgeClase: esGratis ? "bg-emerald-50 text-emerald-700 border-emerald-200" : "bg-amber-50 text-amber-800 border-amber-200",
        horario: z.horarioDefault,
        maxHoras: z.maxHorasDefault
      };
      if (idx >= 0) {
        listaZonasComunesGestion[idx] = obj;
      } else {
        listaZonasComunesGestion.push(obj);
      }
    } else {
      if (idx >= 0) {
        listaZonasComunesGestion.splice(idx, 1);
      }
    }
  });

  guardarZonasEdificioStorage();
  cargarOpcionesZonasSelect();
  cambioZonaSeleccionada();
  renderizarModuloZonasComunes();
  mostrarToast("✓ Zonas comunes y tarifas del edificio guardadas y aplicadas con éxito.");
}

function cargarOpcionesZonasSelect() {
  const sel = document.getElementById("reserva-zona-sel");
  if (!sel) return;

  if (!Array.isArray(listaZonasComunesGestion) || listaZonasComunesGestion.length === 0) {
    sel.innerHTML = '<option value="">(No hay zonas comunes configuradas en este edificio)</option>';
    const reglasEl = document.getElementById("reserva-reglas-txt");
    if (reglasEl) reglasEl.innerText = "Este edificio aún no tiene zonas comunes configuradas por la administración.";
    const tarifaDisplay = document.getElementById("reserva-tarifa-display");
    if (tarifaDisplay) {
      tarifaDisplay.innerText = "Sin zonas disponibles";
      tarifaDisplay.className = "font-mono font-medium text-slate-400 text-xs";
    }
    return;
  }

  const zonaSeleccionadaPrevia = sel.value;
  sel.innerHTML = listaZonasComunesGestion.map(z => `
    <option value="${z.id}" ${z.id === zonaSeleccionadaPrevia ? "selected" : ""}>
      ${z.nombre} (${z.esGratis || z.precio === 0 ? "Gratuito" : "$" + (z.precio||0).toLocaleString("es-CO") + " COP"})
    </option>
  `).join("");

  cambioZonaSeleccionada();
}



function cambioZonaSeleccionada() {
  const sel = document.getElementById("reserva-zona-sel");
  if (!sel) return;

  const zid = sel.value;
  if (!zid) {
    const reglasEl = document.getElementById("reserva-reglas-txt");
    if (reglasEl) reglasEl.innerText = "No hay zonas comunes disponibles para este edificio.";
    const tarifaDisplay = document.getElementById("reserva-tarifa-display");
    if (tarifaDisplay) {
      tarifaDisplay.innerText = "Sin zonas disponibles";
      tarifaDisplay.className = "font-mono font-medium text-slate-400 text-xs";
    }
    return;
  }

  const zona = (Array.isArray(listaZonasComunesGestion) ? listaZonasComunesGestion.find(z => z.id === zid) : null) || 
               (typeof ZONAS_COMUNES_CATALOGO !== "undefined" ? ZONAS_COMUNES_CATALOGO.find(z => z.id === zid) : null);
  if (!zona) return;

  const reglasEl = document.getElementById("reserva-reglas-txt");
  if (reglasEl) {
    reglasEl.innerText = zona.descripcion || zona.reglas || `Aforo máximo: ${zona.aforo || 10} personas. Horario: ${zona.horario || "08:00 - 21:00"}`;
  }

  const tarifaDisplay = document.getElementById("reserva-tarifa-display");
  if (tarifaDisplay) {
    const costo = (typeof zona.precio !== "undefined") ? zona.precio : (zona.costoAlquiler || 0);
    if (costo === 0 || zona.esGratis) {
      tarifaDisplay.innerText = "Gratuito (Incluido en Administración)";
      tarifaDisplay.className = "font-mono font-bold text-sky-400 text-xs";
    } else {
      tarifaDisplay.innerText = `$${costo.toLocaleString("es-CO")} COP`;
      tarifaDisplay.className = "font-mono font-black text-emerald-400 text-sm";
    }
  }

  actualizarHorariosOcupados();
}



// Franjas Horarias Oficiales para Reserva de Zonas Comunes (Hora por hora: 06:00 a 23:00)
const FRANJAS_HORARIAS_ESTANDAR = [
  { ini: "06:00", fin: "07:00", label: "06:00 AM - 07:00 AM" },
  { ini: "07:00", fin: "08:00", label: "07:00 AM - 08:00 AM" },
  { ini: "08:00", fin: "09:00", label: "08:00 AM - 09:00 AM" },
  { ini: "09:00", fin: "10:00", label: "09:00 AM - 10:00 AM" },
  { ini: "10:00", fin: "11:00", label: "10:00 AM - 11:00 AM" },
  { ini: "11:00", fin: "12:00", label: "11:00 AM - 12:00 PM" },
  { ini: "12:00", fin: "13:00", label: "12:00 PM - 01:00 PM" },
  { ini: "13:00", fin: "14:00", label: "01:00 PM - 02:00 PM" },
  { ini: "14:00", fin: "15:00", label: "02:00 PM - 03:00 PM" },
  { ini: "15:00", fin: "16:00", label: "03:00 PM - 04:00 PM" },
  { ini: "16:00", fin: "17:00", label: "04:00 PM - 05:00 PM" },
  { ini: "17:00", fin: "18:00", label: "05:00 PM - 06:00 PM" },
  { ini: "18:00", fin: "19:00", label: "06:00 PM - 07:00 PM" },
  { ini: "19:00", fin: "20:00", label: "07:00 PM - 08:00 PM" },
  { ini: "20:00", fin: "21:00", label: "08:00 PM - 09:00 PM" },
  { ini: "21:00", fin: "22:00", label: "09:00 PM - 10:00 PM" },
  { ini: "22:00", fin: "23:00", label: "10:00 PM - 11:00 PM" }
];

function formatearHora12(hora) {
  if (!hora) return "";
  const partes = hora.split(":");
  let h = parseInt(partes[0], 10);
  const m = partes[1] || "00";
  const ampm = h >= 12 ? "PM" : "AM";
  h = h % 12;
  if (h === 0) h = 12;
  const strH = h < 10 ? "0" + h : "" + h;
  return `${strH}:${m} ${ampm}`;
}

function cambioHoraInicio() {
  const elIni = document.getElementById("reserva-hora-ini");
  const elFin = document.getElementById("reserva-hora-fin");
  if (elIni && elFin) {
    if (elFin.value <= elIni.value) {
      const hIniVal = parseInt(elIni.value.split(":")[0], 10);
      const nuevaHoraFin = Math.min(23, hIniVal + 1);
      elFin.value = (nuevaHoraFin < 10 ? '0' : '') + nuevaHoraFin + ":00";
    }
  }
  actualizarHorariosOcupados();
}

function actualizarOpcionesDropdownsHoras(ocupadas) {
  const elIni = document.getElementById("reserva-hora-ini");
  const elFin = document.getElementById("reserva-hora-fin");
  if (!elIni || !elFin) return;

  Array.from(elIni.options).forEach(opt => {
    const hora = opt.value;
    const formato12h = formatearHora12(hora);
    const estaOcupada = ocupadas.some(r => r.horaIni <= hora && r.horaFin > hora);
    if (estaOcupada) {
      opt.textContent = `${formato12h} (⛔ Ocupada)`;
    } else {
      opt.textContent = formato12h;
    }
  });

  Array.from(elFin.options).forEach(opt => {
    const hora = opt.value;
    const formato12h = formatearHora12(hora);
    const estaOcupada = ocupadas.some(r => r.horaIni < hora && r.horaFin >= hora);
    if (estaOcupada) {
      opt.textContent = `${formato12h} (⛔ Ocupada)`;
    } else {
      opt.textContent = formato12h;
    }
  });
}

function seleccionarFranjaHoraria(hIni, hFin) {
  const elIni = document.getElementById("reserva-hora-ini");
  const elFin = document.getElementById("reserva-hora-fin");
  if (elIni) elIni.value = hIni;
  if (elFin) elFin.value = hFin;

  const alertaEl = document.getElementById("reserva-alerta-conflicto");
  if (alertaEl) alertaEl.classList.add("hidden");

  actualizarHorariosOcupados();
  mostrarToast(`⏰ Horario seleccionado: ${formatearHora12(hIni)} a ${formatearHora12(hFin)}`);
}

function cancelarReserva(rid) {
  const idx = listaReservasCopropiedad.findIndex(r => r.id === rid);
  if (idx === -1) return;
  const r = listaReservasCopropiedad[idx];
  if (!confirm(`¿Deseas cancelar y liberar la reserva #${r.id} para ${r.zona} el ${r.fecha} (${r.horario})?`)) {
    return;
  }
  listaReservasCopropiedad.splice(idx, 1);
  try {
    localStorage.setItem("lefacturamos_reservas_copropiedad", JSON.stringify(listaReservasCopropiedad));
  } catch (e) {}
  mostrarToast(`✅ Reserva #${rid} cancelada. El horario ahora está disponible.`);
  actualizarHorariosOcupados();
  cargarMisReservas();
  renderizarReservasCopropietarios();
  if (typeof renderizarReservasPorteria === 'function') renderizarReservasPorteria();
  safeCreateIcons();
}

function actualizarHorariosOcupados() {
  const sel = document.getElementById("reserva-zona-sel");
  if (!sel) return;
  const zonaId = sel.value;
  const zonaObj = ZONAS_COMUNES_CATALOGO.find(z => z.id === zonaId);
  const zonaNombre = zonaObj ? zonaObj.nombre : (sel.options[sel.selectedIndex]?.text || "Zona Común");

  const elFecha = document.getElementById("reserva-fecha");
  const fecha = elFecha ? elFecha.value : "";
  const elIni = document.getElementById("reserva-hora-ini");
  const elFin = document.getElementById("reserva-hora-fin");
  const hIni = elIni ? elIni.value : "08:00";
  const hFin = elFin ? elFin.value : "10:00";

  const listaEl = document.getElementById("lista-horarios-ocupados");
  const alertaEl = document.getElementById("reserva-alerta-conflicto");

  // Reservas confirmadas para esta zona y fecha
  const ocupadas = listaReservasCopropiedad.filter(r => 
    r.zonaId === zonaId && r.fecha === fecha && r.estado === "Confirmada"
  );

  // Actualizar indicadores de ocupado en los selects
  actualizarOpcionesDropdownsHoras(ocupadas);

  // Mapear cada una de las franjas horarias con su disponibilidad real
  const franjasConEstado = FRANJAS_HORARIAS_ESTANDAR.map(f => {
    const resOcupada = ocupadas.find(r => (f.ini < r.horaFin && f.fin > r.horaIni));
    return {
      ...f,
      ocupada: !!resOcupada,
      reserva: resOcupada || null
    };
  });

  // Filtrar exclusivamente los horarios libres (excluyendo los que ya están seleccionados/ocupados)
  const franjasLibres = franjasConEstado.filter(f => !f.ocupada);
  const franjasOcupadas = franjasConEstado.filter(f => f.ocupada);

  if (listaEl) {
    let headerHtml = "";
    if (franjasOcupadas.length === 0) {
      headerHtml = `
        <div class="p-3 rounded-xl bg-emerald-950/50 border border-emerald-800/60 space-y-1">
          <div class="flex items-center justify-between">
            <span class="font-bold text-white text-xs flex items-center gap-2">
              <i data-lucide="check-circle-2" class="w-4 h-4 text-emerald-400"></i>
              <span>Todos los horarios se encuentran 100% LIBRES</span>
            </span>
            <span class="px-2 py-0.5 rounded-full bg-emerald-500/20 text-emerald-300 font-mono text-[10px] font-bold border border-emerald-500/30">
              ${franjasLibres.length} de ${FRANJAS_HORARIAS_ESTANDAR.length} Horas Disponibles
            </span>
          </div>
          <p class="text-[11px] text-emerald-300/90">
            No hay ninguna reserva en esta fecha (${fecha}). Haz clic en cualquiera de las horas disponibles para seleccionarla:
          </p>
        </div>
      `;
    } else {
      headerHtml = `
        <div class="p-3 rounded-xl bg-slate-900/90 border border-slate-700/80 space-y-2">
          <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-1.5">
            <span class="font-bold text-amber-300 text-xs flex items-center gap-2">
              <i data-lucide="calendar" class="w-4 h-4 text-amber-400 shrink-0"></i>
              <span>Disponibilidad en Fecha: <strong class="text-white">${fecha}</strong></span>
            </span>
            <div class="flex items-center gap-1.5 font-mono text-[10px] font-bold">
              <span class="px-2 py-0.5 rounded bg-emerald-950 text-emerald-300 border border-emerald-800">${franjasLibres.length} DISPONIBLES</span>
              <span class="px-2 py-0.5 rounded bg-rose-950 text-rose-300 border border-rose-800">${ocupadas.length} RESERVADA(S)</span>
            </div>
          </div>
          <div class="p-2 rounded-lg bg-rose-950/30 border border-rose-900/40 text-[11px] text-slate-300 space-y-1">
            <div class="flex items-center gap-1.5 text-rose-300 font-semibold">
              <i data-lucide="alert-circle" class="w-3.5 h-3.5 text-rose-400 shrink-0"></i>
              <span>Horarios ya reservados/ocupados (excluidos de la lista):</span>
            </div>
            <div class="flex flex-wrap gap-1.5 pt-0.5">
              ${ocupadas.map(o => `
                <span class="px-2 py-0.5 rounded bg-rose-950/80 border border-rose-800/80 text-rose-300 font-mono text-[10px] font-bold">
                  ⛔ ${o.horaIni} - ${o.horaFin} (Horario Ocupado)
                </span>
              `).join("")}
            </div>
          </div>
          <div class="text-[11px] text-emerald-300/90">
            👉 A continuación se muestran todas las <strong>${franjasLibres.length} horas disponibles</strong> para reservar (haz clic en cualquiera para elegir):
          </div>
        </div>
      `;
    }

    let gridHtml = "";
    if (franjasLibres.length === 0) {
      gridHtml = `
        <div class="p-4 rounded-xl bg-rose-950/40 border border-rose-800 text-center space-y-1 mt-2">
          <p class="text-xs text-rose-300 font-bold">No quedan horarios disponibles en esta fecha (${fecha}).</p>
          <p class="text-[11px] text-slate-400">Por favor selecciona otra fecha en el calendario para realizar tu reserva.</p>
        </div>
      `;
    } else {
      gridHtml = `
        <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2 pt-1">
          ${franjasLibres.map(f => {
            const esSeleccionado = (f.ini === hIni && f.fin === hFin) || (f.ini >= hIni && f.fin <= hFin);
            return `
              <button type="button" onclick="seleccionarFranjaHoraria('${f.ini}', '${f.fin}')" 
                class="flex items-center justify-between p-2.5 rounded-xl border transition-all cursor-pointer text-left ${
                  esSeleccionado 
                    ? 'bg-emerald-900/70 border-emerald-400 shadow-md shadow-emerald-950 ring-2 ring-emerald-500/60' 
                    : 'bg-emerald-950/30 hover:bg-emerald-900/40 border-emerald-800/40 hover:border-emerald-600'
                }">
                <div class="flex items-center gap-2">
                  <span class="w-2.5 h-2.5 rounded-full ${esSeleccionado ? 'bg-emerald-400 animate-pulse' : 'bg-emerald-500'} shrink-0"></span>
                  <div>
                    <span class="font-bold text-white text-xs block">${f.label}</span>
                    <span class="text-[10px] ${esSeleccionado ? 'text-emerald-300 font-bold' : 'text-emerald-400'}">
                      ${esSeleccionado ? '✓ Horario Seleccionado' : '🟢 LIBRE • Clic para elegir'}
                    </span>
                  </div>
                </div>
                <span class="text-[10px] px-2 py-0.5 rounded font-black uppercase ${esSeleccionado ? 'bg-emerald-500 text-slate-950' : 'bg-emerald-500/20 text-emerald-300 border border-emerald-500/30'}">
                  ${esSeleccionado ? 'Activo' : 'Elegir'}
                </span>
              </button>
            `;
          }).join("")}
        </div>
      `;
    }

    listaEl.innerHTML = headerHtml + gridHtml;
  }

  // Comprobar conflicto con el horario actualmente seleccionado
  const conflicto = ocupadas.find(r => (hIni < r.horaFin && hFin > r.horaIni));
  if (alertaEl) {
    if (conflicto) {
      alertaEl.classList.remove("hidden");
      let msgHtml = `
        <div class="text-xs text-slate-200">
          La zona <strong>${zonaNombre}</strong> ya se encuentra reservada por el <strong>Apartamento ${conflicto.apto}</strong> (${conflicto.residente}) el <strong>${fecha}</strong> en la franja de <strong>${conflicto.horaIni} a ${conflicto.horaFin}</strong>.
        </div>
      `;
      if (franjasLibres.length > 0) {
        msgHtml += `
          <div class="mt-2.5 pt-2 border-t border-rose-800/60">
            <span class="font-bold text-emerald-300 text-xs block mb-1.5">
              👉 Horarios que están LIBRES en esta fecha (haz clic para seleccionarlo):
            </span>
            <div class="flex flex-wrap gap-1.5">
              ${franjasLibres.map(fl => `
                <button type="button" onclick="seleccionarFranjaHoraria('${fl.ini}', '${fl.fin}')" class="px-2.5 py-1 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-slate-950 font-black text-[11px] flex items-center gap-1 shadow cursor-pointer transition-all">
                  <i data-lucide="check" class="w-3 h-3"></i>
                  <span>${fl.label}</span>
                </button>
              `).join("")}
            </div>
          </div>
        `;
      } else {
        msgHtml += `
          <p class="mt-1 text-xs text-rose-300 font-semibold">
            No quedan horarios libres en esta fecha. Por favor seleccione otra fecha diferente.
          </p>
        `;
      }
      const msgCont = document.getElementById("alerta-conflicto-msg");
      if (msgCont) msgCont.innerHTML = msgHtml;
    } else {
      alertaEl.classList.add("hidden");
    }
  }

  safeCreateIcons();
}

function cargarMisReservas() {
  const cont = document.getElementById("lista-reservas-usuario");
  if (!cont) return;

  const esAdmin = (typeof AppState !== "undefined" && (AppState.rol === "admin" || AppState.rol === "superadmin" || AppState.rol === "administrador"));
  const esPortero = (typeof AppState !== "undefined" && (AppState.rol === "porteria" || AppState.rol === "vigilante"));
  
  const aptoActualNorm = String(AppState?.aptoNumero || "").replace(/\D/g, "");
  const propActualNorm = String(AppState?.propietario || "").trim().toLowerCase();

  const tituloEl = document.getElementById("titulo-seccion-reservas-residente");
  if (tituloEl) {
    if (AppState?.aptoNumero) {
      tituloEl.textContent = `Mis Reservas Confirmadas (Apto ${AppState.aptoNumero})`;
    } else {
      tituloEl.textContent = "Mis Reservas Confirmadas";
    }
  }

  // Filtrar estrictamente:
  // Si es residente, SOLO se muestran las reservas de su propio apartamento / usuario
  // Las demas reservas de la copropiedad solo las pueden ver el Administrador y en Porteria
  let misReservas = [];
  if (esAdmin || esPortero) {
    misReservas = [...listaReservasCopropiedad];
  } else {
    misReservas = listaReservasCopropiedad.filter(r => {
      const rAptoNorm = String(r.apto || "").replace(/\D/g, "");
      const rPropNorm = String(r.residente || "").trim().toLowerCase();

      // Coincidencia por numero de apartamento
      if (aptoActualNorm && rAptoNorm && (aptoActualNorm === rAptoNorm || parseInt(aptoActualNorm, 10) === parseInt(rAptoNorm, 10))) {
        return true;
      }
      // Coincidencia por nombre de residente/propietario
      if (propActualNorm && rPropNorm && (propActualNorm === rPropNorm || propActualNorm.includes(rPropNorm) || rPropNorm.includes(propActualNorm))) {
        return true;
      }
      return false;
    });
  }

  if (misReservas.length === 0) {
    cont.innerHTML = `
      <div class="py-8 px-4 text-center rounded-xl bg-slate-900/60 border border-slate-800/80 space-y-2">
        <div class="w-10 h-10 mx-auto rounded-full bg-slate-800 text-slate-400 flex items-center justify-center">
          <i data-lucide="calendar" class="w-5 h-5 text-slate-400"></i>
        </div>
        <p class="font-bold text-slate-300 text-xs">No tienes reservas activas en este momento</p>
        <p class="text-[11px] text-slate-500 max-w-sm mx-auto">
          Selecciona una zona común, fecha y horario en el formulario superior para registrar tu reserva.
        </p>
      </div>
    `;
    safeCreateIcons();
    return;
  }

  cont.innerHTML = misReservas.map(r => {
    return `
      <div class="p-3.5 rounded-xl bg-slate-900 border border-slate-800 flex items-center justify-between text-xs hover:border-slate-700 transition-all">
        <div>
          <div class="flex items-center gap-2">
            <span class="font-bold text-white">${r.zona}</span>
            <span class="px-1.5 py-0.5 rounded bg-slate-800 text-[10px] font-mono text-emerald-400">Apto ${r.apto}</span>
            ${r.residente ? `<span class="text-[10px] text-slate-400">(${r.residente})</span>` : ""}
          </div>
          <span class="text-[11px] text-slate-400">${r.fecha} • ${r.horario} • ${r.personas || 4} pers.</span>
        </div>
        <div class="text-right flex flex-col items-end gap-1">
          <div class="flex items-center gap-1.5">
            <span class="px-2 py-0.5 rounded bg-emerald-950 text-emerald-300 border border-emerald-800 font-bold text-[10px] block">${r.estado}</span>
            <button type="button" onclick="cancelarReserva('${r.id}')" title="Cancelar y liberar esta reserva" class="px-2 py-0.5 rounded bg-rose-950/70 hover:bg-rose-900 border border-rose-800 text-rose-300 font-bold text-[10px] flex items-center gap-1 cursor-pointer transition-all">
              <i data-lucide="x" class="w-3 h-3 text-rose-400"></i>
              <span>Cancelar</span>
            </button>
          </div>
          <span class="text-[11px] font-mono font-bold text-slate-300">${r.costo}</span>
        </div>
      </div>
    `;
  }).join("");
  safeCreateIcons();
}

function confirmarReserva() {
  const cb = document.getElementById("reserva-condiciones-cb");
  if (!cb || !cb.checked) {
    mostrarToast("Debe aceptar el reglamento interno y condiciones de uso.", true);
    return;
  }

  const sel = document.getElementById("reserva-zona-sel");
  const zonaId = sel.value;
  const zonaObj = ZONAS_COMUNES_CATALOGO.find(z => z.id === zonaId);
  const zonaNombre = zonaObj ? zonaObj.nombre : (sel.options[sel.selectedIndex]?.text || "Zona Común");
  const fecha = document.getElementById("reserva-fecha").value;
  const hIni = document.getElementById("reserva-hora-ini").value;
  const hFin = document.getElementById("reserva-hora-fin").value;
  const personas = document.getElementById("reserva-personas").value || 4;

  if (hIni >= hFin) {
    mostrarToast("La hora de inicio debe ser anterior a la hora de fin.", true);
    return;
  }

  // CONTROL ESTRICTO: Mirar si choca con una reserva existente
  const conflicto = listaReservasCopropiedad.find(r => 
    r.zonaId === zonaId && 
    r.fecha === fecha && 
    r.estado === "Confirmada" && 
    (hIni < r.horaFin && hFin > r.horaIni)
  );

  if (conflicto) {
    const alertaEl = document.getElementById("reserva-alerta-conflicto");
    if (alertaEl) {
      alertaEl.classList.remove("hidden");
      actualizarHorariosOcupados();
    }
    mostrarToast(`⚠️ Conflicto: Horario ya reservado por el Apartamento ${conflicto.apto}.`, true);
    return;
  }

  // Costo oficial fijado por la administración
  const costoNumero = zonaObj ? zonaObj.costoAlquiler : 0;
  const costoTexto = costoNumero === 0 ? "$0 (Gratuito)" : `$${costoNumero.toLocaleString("es-CO")} COP`;
  const rid = `RES-${Date.now().toString().slice(-4)}`;

  const nuevaReserva = {
    id: rid,
    zonaId: zonaId,
    zona: zonaNombre,
    apto: AppState.aptoNumero || "0301",
    residente: AppState.propietario || "Beatriz Elena Uribe Higuita",
    fecha: fecha,
    horaIni: hIni,
    horaFin: hFin,
    horario: `${hIni} - ${hFin}`,
    costo: costoTexto,
    personas: parseInt(personas),
    estado: "Confirmada"
  };

  listaReservasCopropiedad.unshift(nuevaReserva);
  try {
    localStorage.setItem("lefacturamos_reservas_copropiedad", JSON.stringify(listaReservasCopropiedad));
  } catch (e) {}

  // Ocultar alerta de conflicto de manera estricta
  const alertaEl = document.getElementById("reserva-alerta-conflicto");
  if (alertaEl) alertaEl.classList.add("hidden");

  // Mostrar mensaje de confirmación visible en pantalla
  const box = document.getElementById("reserva-confirmada-box");
  if (box) {
    box.classList.remove("hidden");
    box.innerHTML = `
      <div class="flex items-center gap-2 font-black text-emerald-400 text-sm">
        <i data-lucide="check-circle" class="w-5 h-5 text-emerald-400 shrink-0"></i>
        <span>¡Reserva #${rid} Confirmada Exitosamente!</span>
      </div>
      <p class="text-white text-xs mt-1">
        Zona: <strong class="text-emerald-300">${zonaNombre}</strong> • Fecha: <strong>${fecha}</strong> (${hIni} a ${hFin}).
      </p>
      <p class="text-slate-300 text-xs">
        Apartamento: <strong>${nuevaReserva.apto}</strong> (${nuevaReserva.residente}) • Valor: <strong class="text-emerald-400 font-mono">${costoTexto}</strong>.
      </p>
      <div class="text-[11px] text-emerald-300/90 pt-1 flex items-center gap-1.5">
        <i data-lucide="bell" class="w-3.5 h-3.5 text-emerald-400"></i>
        <span>Notificación push despachada a tu celular y registrada en la administración.</span>
      </div>
    `;
    box.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }

  // Auto-seleccionar la siguiente franja libre en los dropdowns para no dejar la franja ocupada
  const siguienteLibre = FRANJAS_HORARIAS_ESTANDAR.find(f => 
    !listaReservasCopropiedad.some(r => r.zonaId === zonaId && r.fecha === fecha && r.estado === "Confirmada" && (f.ini < r.horaFin && f.fin > r.horaIni))
  );
  if (siguienteLibre) {
    const elIni = document.getElementById("reserva-hora-ini");
    const elFin = document.getElementById("reserva-hora-fin");
    if (elIni) elIni.value = siguienteLibre.ini;
    if (elFin) elFin.value = siguienteLibre.fin;
  }

  actualizarHorariosOcupados();
  cargarMisReservas();
  if (typeof renderizarReservasPorteria === 'function') renderizarReservasPorteria();
  safeCreateIcons();
  mostrarToast(`¡Reserva #${rid} confirmada. Valor: ${costoTexto}.`);
}



