// 4. VISITANTES Y CÓDIGO QR INTELIGENTE (WHATSAPP & PORTERÍA 2 SEG)

// ==============================================================================

let tokenGeneradoActual = "";
let listaVisitantesAutorizados = [];
try {
  listaVisitantesAutorizados = JSON.parse(localStorage.getItem("lefacturamos_visitantes_autorizados") || "[]");
} catch (e) {
  listaVisitantesAutorizados = [];
}



function construirMensajeWhatsAppVisitante() {
  const elNombre = document.getElementById("vis-nombre");
  const elDoc = document.getElementById("vis-doc");
  const elPlaca = document.getElementById("vis-placa");
  const elFecha = document.getElementById("vis-fecha");
  const nom = elNombre && elNombre.value.trim() ? elNombre.value.trim() : "Visitante";
  const doc = elDoc && elDoc.value.trim() ? elDoc.value.trim() : "";
  const placa = elPlaca && elPlaca.value.trim() ? elPlaca.value.trim() : "Peatonal";
  const fecha = elFecha && elFecha.value ? elFecha.value : new Date().toISOString().split("T")[0];
  const aptoActual = AppState.aptoNumero || "0103";
  const edifNombre = (typeof EDIFICIOS_CATALOGO_DRIVE !== "undefined" && EDIFICIOS_CATALOGO_DRIVE[AppState.codigoEdificio]
    ? EDIFICIOS_CATALOGO_DRIVE[AppState.codigoEdificio].nombre
    : "EDIFICIO ROBLE ALTO P.H.");
  const nombreResidente = AppState.propietario || "Copropietario";
  const qrImageUrl = `https://api.qrserver.com/v1/create-qr-code/?size=500x500&data=${encodeURIComponent(tokenGeneradoActual)}`;

  return (
    `*AUTORIZACIÓN DIGITAL DE VISITA - LEFACTURAMOS PH*\n\n` +
    `👋 Hola *${nom}* (Doc: ${doc}):\n` +
    `Tienes autorización para ingresar a *${edifNombre}*.\n\n` +
    `🏠 *Apartamento:* ${aptoActual}\n` +
    `👤 *Autorizado por:* ${nombreResidente}\n` +
    `🚗 *Vehículo/Placa:* ${placa}\n` +
    `📅 *Fecha de Ingreso:* ${fecha}\n` +
    `🔑 *Código QR:* *${tokenGeneradoActual}*\n\n` +
    `📸 *Ver imagen del Código QR en tu celular:*\n` +
    `${qrImageUrl}\n\n` +
    `⚡ Presenta este código en la portería para validación en 2 segundos.`
  );
}

function copiarMensajeCompletoWhatsApp() {
  if (!tokenGeneradoActual) {
    mostrarToast("Genere primero una autorización con código QR.", true);
    return;
  }
  const texto = construirMensajeWhatsAppVisitante();
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(texto).then(() => {
      mostrarToast("📋 ¡Mensaje completo con enlace copiado! Puedes pegarlo (Ctrl+V) en WhatsApp.");
    }).catch(() => {
      mostrarToast("Copie manualmente el código de autorización.", true);
    });
  } else {
    mostrarToast("Portapapeles no soportado directamente en este navegador.", true);
  }
}

function enviarWhatsAppVisitante() {
  if (!tokenGeneradoActual) {
    mostrarToast("Genere primero una autorización con código QR.", true);
    return;
  }

  const btnWa = document.getElementById("vis-btn-whatsapp");
  const elNombre = document.getElementById("vis-nombre");
  const elTel = document.getElementById("vis-tel");
  const nom = elNombre && elNombre.value.trim() ? elNombre.value.trim() : "Visitante";
  const tel = elTel && elTel.value.trim() ? elTel.value.trim() : "";

  const cleanTel = tel.replace(/\D/g, "");
  const fullPhone = cleanTel ? (cleanTel.startsWith("57") ? cleanTel : (cleanTel.length === 10 ? `57${cleanTel}` : cleanTel)) : "";

  // 1. Auditoría en servidor en segundo plano
  const isHttpsCtx = typeof window !== "undefined" && window.location && window.location.protocol === "https:";
  const originCtx = (typeof window !== "undefined" && window.location && window.location.origin) ? window.location.origin : "";

  const candidatos = [
    originCtx,
    "https://lefacturamosplus.onrender.com",
    (typeof getApiBaseUrl === "function") ? getApiBaseUrl() : "",
    ""
  ];
  if (!isHttpsCtx) {
    candidatos.push("http://192.168.1.24:8000");
  }
  const bases = [...new Set(candidatos.map(u => (u || "").replace(/\/$/, "")))];

  (async () => {
    for (const b of bases) {
      try {
        const ctrl = new AbortController();
        const tid = setTimeout(() => ctrl.abort(), 4000);
        await fetch(`${b}/api/visitantes/enviar-whatsapp`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          signal: ctrl.signal,
          body: JSON.stringify({ token_qr: tokenGeneradoActual })
        });
        clearTimeout(tid);
        break;
      } catch(e) {}
    }
  })();

  // 2. Construir enlace directo oficial de WhatsApp hacia el número del visitante
  const msgTexto = construirMensajeWhatsAppVisitante();
  const msgWa = encodeURIComponent(msgTexto);
  const esMovil = /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent || "");
  const waUrl = esMovil
    ? (fullPhone ? `https://api.whatsapp.com/send?phone=${fullPhone}&text=${msgWa}` : `https://api.whatsapp.com/send?text=${msgWa}`)
    : (fullPhone ? `https://web.whatsapp.com/send?phone=${fullPhone}&text=${msgWa}` : `https://web.whatsapp.com/send?text=${msgWa}`);

  // 3. Abrir WhatsApp (En PC va directo a WhatsApp Web sin pantallas intermedias; en móvil abre la App de WhatsApp)
  window.open(waUrl, "_blank");

  if (btnWa) {
    btnWa.innerHTML = `
      <i data-lucide="check" class="w-3.5 h-3.5 text-white"></i>
      <span>Abriendo WhatsApp...</span>
    `;
    setTimeout(() => {
      if (btnWa) {
        btnWa.innerHTML = `
          <i data-lucide="message-circle" class="w-3.5 h-3.5"></i>
          <span>Reenviar por WhatsApp</span>
        `;
        safeCreateIcons();
      }
    }, 3000);
    safeCreateIcons();
  }

  mostrarToast(`📲 Abriendo WhatsApp para enviar a ${nom} (${tel || "destino"}). Presione Enviar en el chat.`);
}

function generarQRAnticipado() {
  const elNombre = document.getElementById("vis-nombre");
  const elDoc = document.getElementById("vis-doc");
  const elTel = document.getElementById("vis-tel");
  const elPlaca = document.getElementById("vis-placa");
  const elFecha = document.getElementById("vis-fecha");

  const nombre = elNombre ? elNombre.value.trim() : "";
  const doc = elDoc ? elDoc.value.trim() : "";
  const tel = elTel ? elTel.value.trim() : "";
  const placa = elPlaca && elPlaca.value.trim() ? elPlaca.value.trim() : "Peatonal";
  const fecha = elFecha && elFecha.value ? elFecha.value : new Date().toISOString().split("T")[0];

  if (!nombre || !doc) {
    mostrarToast("⚠️ Por favor ingrese nombre y documento del visitante.", true);
    if (!nombre && elNombre) elNombre.focus();
    else if (elDoc) elDoc.focus();
    return;
  }

  // Generar Token QR Único
  tokenGeneradoActual = `QR-${Math.random().toString(16).substring(2, 10).toUpperCase()}`;

  // Formatear Teléfono para WhatsApp (quitar espacios, guiones y caracteres no numéricos)
  const cleanTel = tel.replace(/\D/g, "");
  const fullPhone = cleanTel ? (cleanTel.startsWith("57") ? cleanTel : (cleanTel.length === 10 ? `57${cleanTel}` : cleanTel)) : "";

  // Generar QR visual en canvas con Fallback infalible
  const canvasCont = document.getElementById("qrcode-canvas");
  if (canvasCont) {
    canvasCont.innerHTML = "";
    let qrOk = false;
    if (typeof QRCode !== "undefined") {
      try {
        new QRCode(canvasCont, {
          text: tokenGeneradoActual,
          width: 140,
          height: 140,
          colorDark: "#020617",
          colorLight: "#ffffff",
          correctLevel: QRCode.CorrectLevel.H
        });
        qrOk = true;
      } catch (e) {
        console.warn("Fallo QRCodeJS, usando fallback visual:", e);
      }
    }

    if (!qrOk || (!canvasCont.querySelector("canvas") && !canvasCont.querySelector("img"))) {
      const qrImg = document.createElement("img");
      qrImg.src = `https://api.qrserver.com/v1/create-qr-code/?size=140x140&data=${encodeURIComponent(tokenGeneradoActual)}`;
      qrImg.alt = `Código QR ${tokenGeneradoActual}`;
      qrImg.className = "w-[140px] h-[140px] rounded-lg shadow-sm block";
      qrImg.onerror = function() {
        canvasCont.innerHTML = `
          <div class="w-[140px] h-[140px] bg-slate-900 text-emerald-400 p-2 rounded-lg flex flex-col items-center justify-center text-center font-mono border-2 border-emerald-500/50">
            <i data-lucide="qr-code" class="w-10 h-10 text-emerald-400 mb-1"></i>
            <span class="text-[10px] font-black">${tokenGeneradoActual}</span>
          </div>
        `;
        safeCreateIcons();
      };
      canvasCont.innerHTML = "";
      canvasCont.appendChild(qrImg);
    }
  }

  const elResNombre = document.getElementById("vis-res-nombre");
  if (elResNombre) elResNombre.innerText = `${nombre} (C.C. ${doc})`;

  const elResToken = document.getElementById("vis-res-token");
  if (elResToken) elResToken.innerText = `TOKEN: ${tokenGeneradoActual}`;

  // Copropiedad y Residente
  const aptoActual = AppState.aptoNumero || "0103";
  const edifNombre = (typeof EDIFICIOS_CATALOGO_DRIVE !== "undefined" && EDIFICIOS_CATALOGO_DRIVE[AppState.codigoEdificio])
    ? EDIFICIOS_CATALOGO_DRIVE[AppState.codigoEdificio].nombre
    : "EDIFICIO ROBLE ALTO P.H.";
  const nombreResidente = AppState.propietario || "Copropietario";

  const qrImageUrl = `https://api.qrserver.com/v1/create-qr-code/?size=500x500&data=${encodeURIComponent(tokenGeneradoActual)}`;

  // Mensaje Preformateado para WhatsApp con link directo a la imagen del QR
  const msgTextoPlano = 
    `*AUTORIZACIÓN DIGITAL DE VISITA - LEFACTURAMOS PH*\n\n` +
    `👋 Hola *${nombre}* (Doc: ${doc}):\n` +
    `Tienes autorización para ingresar a *${edifNombre}*.\n\n` +
    `🏠 *Apartamento:* ${aptoActual}\n` +
    `👤 *Autorizado por:* ${nombreResidente}\n` +
    `🚗 *Vehículo/Placa:* ${placa}\n` +
    `📅 *Fecha de Ingreso:* ${fecha}\n` +
    `🔑 *Código QR:* *${tokenGeneradoActual}*\n\n` +
    `📸 *Ver / Abrir imagen del Código QR en tu celular:*\n` +
    `${qrImageUrl}\n\n` +
    `⚡ Presenta este código en la portería para validación en 2 segundos.`;

  // Conectar y activar enlace de WhatsApp sin abrir navegador web
  const btnWa = document.getElementById("vis-btn-whatsapp");
  if (btnWa) {
    btnWa.innerHTML = `
      <i data-lucide="message-circle" class="w-3.5 h-3.5"></i>
      <span>Enviar por WhatsApp</span>
    `;
    btnWa.className = "px-4 py-2.5 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-bold text-xs flex items-center justify-center gap-1.5 shadow-md shadow-emerald-950/40 cursor-pointer transition-all";
    btnWa.onclick = function(e) {
      if (e) e.preventDefault();
      enviarWhatsAppVisitante();
    };
  }

  // Mostrar caja de resultados
  const resBox = document.getElementById("vis-resultado-box");
  if (resBox) {
    resBox.classList.remove("hidden");
    resBox.scrollIntoView({ behavior: "smooth", block: "nearest" });
  }

  safeCreateIcons();
  mostrarToast(`✅ Código QR ${tokenGeneradoActual} generado exitosamente.`);

  // Registrar autorización en memoria local y localStorage persistente para portería
  const nuevoVisitante = {
    id: tokenGeneradoActual,
    token: tokenGeneradoActual,
    nombre: nombre,
    doc: doc,
    tel: cleanTel || tel,
    placa: placa,
    fecha: fecha,
    apto: aptoActual,
    residente: nombreResidente,
    estado: "AUTORIZADO",
    hora: new Date().toLocaleTimeString("es-CO", { hour: "2-digit", minute: "2-digit" })
  };

  if (typeof listaVisitantesAutorizados === "undefined") {
    listaVisitantesAutorizados = [];
  }
  listaVisitantesAutorizados.unshift(nuevoVisitante);
  try {
    let localSaved = JSON.parse(localStorage.getItem("lefacturamos_visitantes_autorizados") || "[]");
    localSaved.unshift(nuevoVisitante);
    if (localSaved.length > 50) localSaved = localSaved.slice(0, 50);
    localStorage.setItem("lefacturamos_visitantes_autorizados", JSON.stringify(localSaved));
  } catch (e) {
    console.warn("Error guardando en localStorage:", e);
  }

  // Despachar a backend para sincronización multi-dispositivo y portería (LAN, Túnel y Local)
  const isHttpsCtx = typeof window !== "undefined" && window.location && window.location.protocol === "https:";
  const originCtx = (typeof window !== "undefined" && window.location && window.location.origin) ? window.location.origin : "";

  const candidatosPost = [
    originCtx,
    "https://lefacturamosplus.onrender.com",
    (typeof getApiBaseUrl === "function") ? getApiBaseUrl() : "",
    ""
  ];
  if (!isHttpsCtx) {
    candidatosPost.push("http://192.168.1.24:8000");
    candidatosPost.push("http://127.0.0.1:8000");
  }
  const postUrls = [...new Set(candidatosPost.map(u => (u || "").replace(/\/$/, "")))];

  const codRawVis = String(AppState.codigoEdificio || AppState.conjuntoId || "4901").replace(/^(cj_)+/, "").trim() || "4901";
  const cjIdVis = `cj_${codRawVis}`;
  const payloadAutorizar = {
    conjunto_id: cjIdVis,
    unidad_id: `u_${codRawVis}_${aptoActual}`,
    residente_nombre: nombreResidente,
    visitante_nombre: nombre,
    visitante_doc: doc,
    visitante_telefono: cleanTel,
    fecha_esperada: fecha,
    hora_esperada: new Date().toLocaleTimeString("es-CO", { hour: "2-digit", minute: "2-digit" }),
    placa_vehiculo: placa,
    tipo_visita: "Visitante",
    token_qr: tokenGeneradoActual,
    observaciones: "Autorizado por residente"
  };

  (async () => {
    for (const base of postUrls) {
      try {
        const urlPost = `${base}/api/visitantes/autorizar`;
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 5000);
        const r = await fetch(urlPost, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          signal: controller.signal,
          body: JSON.stringify(payloadAutorizar)
        });
        clearTimeout(timeoutId);
        if (r.ok) {
          if (base && base.startsWith("http") && (!isHttpsCtx || base.startsWith("https://"))) {
            try { localStorage.setItem("lefacturamos_backend_url", base); } catch(e) {}
          }
          break;
        }
      } catch(e) {}
    }
  })();
}

function copiarTokenQR() {
  if (tokenGeneradoActual) {
    navigator.clipboard.writeText(tokenGeneradoActual);
    mostrarToast(`Token ${tokenGeneradoActual} copiado.`);
  }
}

// Genera una credencial visual de acceso VIP (Canvas de alta resolución con QR)
async function obtenerBlobImagenQR() {
  const container = document.getElementById("qrcode-canvas");
  const existingCanvas = container ? container.querySelector("canvas") : null;
  
  const c = document.createElement("canvas");
  c.width = 400;
  c.height = 460;
  const ctx = c.getContext("2d");

  // Fondo blanco nítido
  ctx.fillStyle = "#ffffff";
  ctx.fillRect(0, 0, 400, 460);

  // Encabezado corporativo oscuro
  ctx.fillStyle = "#0f172a";
  ctx.fillRect(0, 0, 400, 70);

  ctx.fillStyle = "#38bdf8";
  ctx.font = "bold 16px sans-serif";
  ctx.textAlign = "center";
  ctx.fillText("LEFACTURAMOS PH", 200, 30);

  const edifNombre = (typeof EDIFICIOS_CATALOGO_DRIVE !== "undefined" && EDIFICIOS_CATALOGO_DRIVE[AppState.codigoEdificio])
    ? EDIFICIOS_CATALOGO_DRIVE[AppState.codigoEdificio].nombre
    : "EDIFICIO ROBLE ALTO P.H.";
  ctx.fillStyle = "#ffffff";
  ctx.font = "12px sans-serif";
  ctx.fillText(edifNombre, 200, 52);

  // Datos visitante y apto
  const elNombre = document.getElementById("vis-nombre");
  const elDoc = document.getElementById("vis-doc");
  const nom = elNombre && elNombre.value.trim() ? elNombre.value.trim() : "Visitante Autorizado";
  const doc = elDoc && elDoc.value.trim() ? elDoc.value.trim() : "";
  const apto = AppState.aptoNumero || "0103";

  ctx.fillStyle = "#1e293b";
  ctx.font = "bold 14px sans-serif";
  ctx.fillText(`${nom} (Doc: ${doc})`, 200, 95);

  ctx.fillStyle = "#0284c7";
  ctx.font = "bold 13px sans-serif";
  ctx.fillText(`DESTINO: APARTAMENTO ${apto}`, 200, 115);

  // Dibujar QR de alta resolución
  if (existingCanvas) {
    try {
      ctx.drawImage(existingCanvas, 100, 130, 200, 200);
    } catch (e) {}
  } else {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = `https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(tokenGeneradoActual || "QR-VISITANTE")}`;
    await new Promise((resolve) => {
      img.onload = () => {
        try { ctx.drawImage(img, 100, 130, 200, 200); } catch(e){}
        resolve();
      };
      img.onerror = () => resolve();
    });
  }

  // Token alfanumérico
  ctx.fillStyle = "#0f172a";
  ctx.font = "bold 18px monospace";
  ctx.fillText(tokenGeneradoActual || "QR-ACCESO", 200, 360);

  ctx.fillStyle = "#64748b";
  ctx.font = "11px sans-serif";
  ctx.fillText("Presenta este código en portería para validación en 2 seg.", 200, 390);

  ctx.fillStyle = "#059669";
  ctx.font = "bold 12px sans-serif";
  ctx.fillText("✓ ACCESO VÁLIDO Y AUTORIZADO", 200, 420);

  return new Promise((resolve) => {
    c.toBlob((blob) => resolve(blob), "image/png");
  });
}

// Descargar credencial visual en PNG
async function descargarImagenQR() {
  if (!tokenGeneradoActual) {
    mostrarToast("Genere primero una autorización con código QR.", true);
    return;
  }
  mostrarToast("⏳ Preparando descarga de imagen QR...");
  try {
    const blob = await obtenerBlobImagenQR();
    if (!blob) return;
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `QR_Acceso_${tokenGeneradoActual}.png`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    mostrarToast("📥 Imagen del código QR descargada exitosamente.");
  } catch (e) {
    // Fallback: descargar directo de API
    const a = document.createElement("a");
    a.href = `https://api.qrserver.com/v1/create-qr-code/?size=500x500&data=${encodeURIComponent(tokenGeneradoActual)}`;
    a.download = `QR_${tokenGeneradoActual}.png`;
    a.target = "_blank";
    a.click();
  }
}

// Compartir imagen del QR directamente a WhatsApp mediante Web Share API
async function compartirImagenQRWhatsApp() {
  if (!tokenGeneradoActual) {
    mostrarToast("Genere primero una autorización con código QR.", true);
    return;
  }

  mostrarToast("📤 Preparando imagen del QR para compartir...");

  try {
    const blob = await obtenerBlobImagenQR();
    if (blob) {
      const file = new File([blob], `QR_Acceso_${tokenGeneradoActual}.png`, { type: "image/png" });
      const elNombre = document.getElementById("vis-nombre");
      const nom = elNombre ? elNombre.value.trim() : "Visitante";
      const apto = AppState.aptoNumero || "0103";
      const texto = `AUTORIZACIÓN QR - LEFACTURAMOS PH\nVisitante: ${nom}\nApto: ${apto}\nToken: ${tokenGeneradoActual}`;

      // Si el navegador o celular soporta compartir archivos directamente a WhatsApp
      if (navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({
          files: [file],
          title: `Código QR de Visita - ${tokenGeneradoActual}`,
          text: texto
        });
        mostrarToast("✅ Imagen del QR compartida con éxito.");
        return;
      }
    }
  } catch (err) {
    console.warn("Share de archivo no completado:", err);
  }

  // Fallback para computadores o navegadores sin soporte de share de archivos:
  // 1. Descargar la imagen automáticamente
  descargarImagenQR();
  
  // 2. Copiar al portapapeles si está disponible
  copiarImagenQRPortapapeles();

  // 3. Despacho silencioso por debajo sin abrir navegador
  enviarWhatsAppVisitante();
  mostrarToast("📲 Imagen descargada y copiada al portapapeles. Notificación WhatsApp enviada.");
}

// Copiar imagen PNG al portapapeles
async function copiarImagenQRPortapapeles() {
  try {
    const blob = await obtenerBlobImagenQR();
    if (!blob) return;
    if (navigator.clipboard && navigator.clipboard.write) {
      await navigator.clipboard.write([
        new ClipboardItem({ "image/png": blob })
      ]);
      mostrarToast("📋 ¡Imagen del QR copiada al portapapeles! Puedes pegarla con Ctrl+V.");
    }
  } catch(e) {
    console.warn("Clipboard de imagen no disponible:", e);
  }
}



