async function sincronizarVisitantesDesdeServidor() {
  const codRaw = String(AppState.codigoEdificio || AppState.conjuntoId || "4901").replace(/^(cj_)+/, "").trim() || "4901";
  const cjId = `cj_${codRaw}`;
  const cod = codRaw;
  const isHttps = typeof window !== "undefined" && window.location && window.location.protocol === "https:";
  const origin = (typeof window !== "undefined" && window.location && window.location.origin) ? window.location.origin : "";

  let candidateBases = [];
  if (origin && !origin.startsWith("file:") && !origin.startsWith("capacitor:")) {
    candidateBases.push(origin);
  }
  candidateBases.push("https://lefacturamosplus.onrender.com");
  if (typeof getApiBaseUrl === "function") {
    candidateBases.push(getApiBaseUrl());
  }
  candidateBases.push("");
  if (!isHttps) {
    candidateBases.push("http://192.168.1.24:8000");
    candidateBases.push("http://127.0.0.1:8000");
  }

  const basesUnicas = [...new Set(candidateBases.map(u => (u || "").replace(/\/$/, "")))];

  let listaServidor = [];
  for (const base of basesUnicas) {
    try {
      const url = `${base}/api/conjuntos/${cjId}/visitantes`;
      const ctrl = new AbortController();
      const tid = setTimeout(() => ctrl.abort(), 4000);
      const res = await fetch(url, { signal: ctrl.signal });
      clearTimeout(tid);
      if (res.ok) {
        const data = await res.json();
        if (data && Array.isArray(data.visitantes)) {
          listaServidor = data.visitantes;
          break;
        }
      }
    } catch (e) {}
  }

  if (listaServidor.length > 0) {
    // 1. Sincronizar Tokens Autorizados
    if (typeof listaVisitantesAutorizados === "undefined") {
      listaVisitantesAutorizados = [];
    }

    const formateados = listaServidor.map(v => ({
      id: v.token_qr || v.id,
      token: (v.token_qr || "").toUpperCase(),
      token_qr: (v.token_qr || "").toUpperCase(),
      nombre: v.visitante_nombre || "Visitante",
      doc: v.visitante_doc || "",
      tel: v.visitante_telefono || "",
      placa: v.placa_vehiculo || "Peatonal",
      apto: v.numero_unidad || (v.unidad_id ? v.unidad_id.split("_").pop() : "0301"),
      residente: v.residente_nombre || "",
      estado: v.estado || "AUTORIZADO",
      fecha: v.fecha_esperada || "",
      hora: v.hora_esperada || ""
    }));

    const mapaTokens = new Map();
    formateados.forEach(v => {
      if (v.token) mapaTokens.set(v.token, v);
    });
    listaVisitantesAutorizados.forEach(v => {
      const tok = (v.token || v.token_qr || v.id || "").toUpperCase();
      if (tok && !mapaTokens.has(tok)) {
        mapaTokens.set(tok, v);
      }
    });

    listaVisitantesAutorizados = Array.from(mapaTokens.values());
    try {
      localStorage.setItem("lefacturamos_visitantes_autorizados", JSON.stringify(listaVisitantesAutorizados.slice(0, 50)));
    } catch (e) {}

    actualizarBotonesTokensDinamicos(listaVisitantesAutorizados);

    // 2. Sincronizar Visitantes Activos dentro del Recinto (Multi-dispositivo en tiempo real)
    const enRecintoServidor = listaServidor.filter(v => v.estado === "INGRESADO" && (!v.salida_timestamp || v.salida_timestamp === ""));
    const recintoMapeado = enRecintoServidor.map(v => {
      const rawDoc = (v.visitante_doc || "").toString().trim();
      const docVis = rawDoc.toUpperCase().startsWith("CC") ? rawDoc : (rawDoc ? `CC ${rawDoc}` : "CC No registra");
      let horaIn = "";
      if (v.ingreso_timestamp) {
        try {
          const d = new Date(v.ingreso_timestamp);
          horaIn = isNaN(d.getTime()) ? v.ingreso_timestamp : d.toLocaleTimeString();
        } catch(e) {
          horaIn = (v.ingreso_timestamp.split("T")[1] || "").substring(0, 8);
        }
      }
      if (!horaIn) horaIn = v.hora_esperada || new Date().toLocaleTimeString();
      const aptoVis = v.numero_unidad || (v.unidad_id ? v.unidad_id.split("_").pop() : "0103");
      return {
        id: v.id || v.token_qr,
        nombre: v.visitante_nombre || "Visitante",
        documento: docVis,
        apto: aptoVis,
        vehiculo: v.placa_vehiculo || "Peatonal",
        horaIngreso: horaIn,
        token: (v.token_qr || "").toUpperCase()
      };
    });

    const sonIgualesRecinto = (typeof visitantesRecinto !== "undefined" && Array.isArray(visitantesRecinto)) &&
      (visitantesRecinto.length === recintoMapeado.length) &&
      recintoMapeado.every((item, i) => (visitantesRecinto[i] && (visitantesRecinto[i].token === item.token || visitantesRecinto[i].id === item.id)));

    if (!sonIgualesRecinto) {
      visitantesRecinto = recintoMapeado;
      try {
        localStorage.setItem("lefacturamos_visitantes_recinto", JSON.stringify(visitantesRecinto.slice(0, 50)));
      } catch(e) {}
      renderizarVisitantesRecinto();
      actualizarContadoresPorteria();
    }
  }

  // 3. Sincronizar Minuta de Portería desde el servidor
  let minutaServidor = [];
  for (const base of basesUnicas) {
    try {
      const urlMin = `${base}/api/conjuntos/${cjId}/minuta?limit=50`;
      const ctrlMin = new AbortController();
      const tidMin = setTimeout(() => ctrlMin.abort(), 4000);
      const resMin = await fetch(urlMin, { signal: ctrlMin.signal });
      clearTimeout(tidMin);
      if (resMin.ok) {
        const dataMin = await resMin.json();
        if (dataMin && Array.isArray(dataMin.minuta)) {
          minutaServidor = dataMin.minuta;
          break;
        }
      }
    } catch(e) {}
  }

  if (minutaServidor.length > 0) {
    const minMapeada = minutaServidor.map(m => ({
      id: m.id,
      tipo: m.tipo,
      fecha: m.fecha,
      hora: m.hora,
      inmueble: m.inmueble,
      portero: m.portero,
      titulo: m.titulo,
      descripcion: m.descripcion,
      estado: m.estado,
      token_qr: m.token_qr || ""
    }));

    const mapaMin = new Map();
    minMapeada.forEach(m => mapaMin.set(m.id || `${m.fecha}_${m.hora}_${m.titulo}`, m));
    (minutaPorteria || []).forEach(m => {
      const k = m.id || `${m.fecha}_${m.hora}_${m.titulo}`;
      if (!mapaMin.has(k)) {
        mapaMin.set(k, m);
      }
    });

    const minutaFusionada = Array.from(mapaMin.values());
    minutaFusionada.sort((a, b) => {
      const da = new Date(`${a.fecha} ${a.hora}`).getTime() || 0;
      const db = new Date(`${b.fecha} ${b.hora}`).getTime() || 0;
      return db - da;
    });
    const sonIgualesMin = (typeof minutaPorteria !== "undefined" && Array.isArray(minutaPorteria)) &&
      (minutaFusionada.length === minutaPorteria.length) &&
      (minutaFusionada[0]?.id === minutaPorteria[0]?.id);

    if (!sonIgualesMin) {
      minutaPorteria = minutaFusionada;
      try {
        localStorage.setItem("lefacturamos_minuta_porteria", JSON.stringify(minutaPorteria.slice(0, 100)));
      } catch(e) {}
      if (typeof buscarMinuta === "function") buscarMinuta();
      actualizarContadoresPorteria();
    }
  }
}

function actualizarBotonesTokensDinamicos(lista) {
  const cont = document.getElementById("porteria-tokens-dinamicos");
  if (!cont) return;

  const items = (lista || []).slice(0, 5);
  if (items.length === 0) return;

  cont.innerHTML = items.map(v => {
    const tok = v.token || v.token_qr || v.id;
    const apto = v.apto || v.numero_unidad || "0301";
    const nom = v.nombre || v.visitante_nombre || "Visitante";
    return `<button type="button" onclick="cargarTokenPrueba('${tok}')" class="px-2.5 py-1 rounded-lg bg-emerald-950/80 hover:bg-emerald-900 border border-emerald-600/60 text-emerald-300 font-bold text-[11px] flex items-center gap-1 cursor-pointer transition-all shadow-sm">
      <i data-lucide="user-check" class="w-3 h-3 text-emerald-400"></i>
      <span>${nom} (Apto ${apto})</span>
    </button>`;
  }).join("");
  safeCreateIcons();
}

