let inventarioPuesto = [];
try {
  const guardado = localStorage.getItem("lefacturamos_inventario_puesto");
  if (guardado) {
    inventarioPuesto = JSON.parse(guardado);
  }
} catch (e) {
  console.warn("Aviso cargando inventario puesto:", e);
}
if (!inventarioPuesto || !inventarioPuesto.length) {
  inventarioPuesto = JSON.parse(JSON.stringify(INVENTARIO_PUESTO_INICIAL));
}

function guardarInventarioStorage() {
  try {
    localStorage.setItem("lefacturamos_inventario_puesto", JSON.stringify(inventarioPuesto));
  } catch (e) {
    console.warn("Aviso guardando inventario puesto:", e);
  }
}

let filtroCategoriaInventarioActual = "";
let filtroTextoInventarioActual = "";

function renderizarInventarioPuestoGrid(cat, query) {
  if (cat !== undefined) filtroCategoriaInventarioActual = cat;
  if (query !== undefined) filtroTextoInventarioActual = query.toLowerCase().trim();

  const cont = document.getElementById("contenedor-grid-inventario-puesto");
  if (!cont) return;

  const kpiTot = document.getElementById("kpi-inventario-total");
  const kpiOpe = document.getElementById("kpi-inventario-operativo");
  const bInv = document.getElementById("badge-count-inventario");

  if (kpiTot) kpiTot.innerText = `${inventarioPuesto.length} items`;
  if (bInv) bInv.innerText = inventarioPuesto.length;

  const opCount = inventarioPuesto.filter(i => i.verificado).length;
  const pct = inventarioPuesto.length ? Math.round((opCount / inventarioPuesto.length) * 100) : 100;
  if (kpiOpe) kpiOpe.innerText = `${pct}% Operativo (${opCount}/${inventarioPuesto.length})`;

  let lista = inventarioPuesto;
  if (filtroCategoriaInventarioActual) {
    lista = lista.filter(i => i.categoria === filtroCategoriaInventarioActual);
  }
  if (filtroTextoInventarioActual) {
    lista = lista.filter(i => 
      i.nombre.toLowerCase().includes(filtroTextoInventarioActual) ||
      (i.detalle && i.detalle.toLowerCase().includes(filtroTextoInventarioActual)) ||
      i.categoria.toLowerCase().includes(filtroTextoInventarioActual)
    );
  }

  if (!lista.length) {
    cont.innerHTML = `
      <div class="col-span-full py-12 text-center bg-slate-900/60 border border-slate-800 rounded-3xl p-6 space-y-3">
        <div class="w-12 h-12 rounded-2xl bg-slate-800 border border-slate-700 flex items-center justify-center text-slate-400 mx-auto">
          <i data-lucide="inbox" class="w-6 h-6"></i>
        </div>
        <p class="text-xs text-slate-300 font-semibold">No se encontraron elementos en el inventario con el filtro actual.</p>
        <button type="button" onclick="abrirModalNuevoItemInventario()" class="px-4 py-2 rounded-xl bg-cyan-600 hover:bg-cyan-500 text-white font-bold text-xs inline-flex items-center gap-1.5 shadow-md">
          <i data-lucide="plus" class="w-3.5 h-3.5"></i>
          <span>Crear Nuevo Detalle</span>
        </button>
      </div>
    `;
    safeCreateIcons();
    return;
  }

  cont.innerHTML = lista.map(item => `
    <div class="p-4 rounded-2xl bg-slate-900/90 border border-slate-800 hover:border-slate-700 transition-all shadow-md flex flex-col justify-between space-y-3">
      <div class="flex items-start justify-between gap-3">
        <div class="flex items-center gap-3">
          <div class="w-10 h-10 rounded-xl ${item.colorFondo || 'bg-slate-800'} border ${item.colorBorde || 'border-slate-700'} flex items-center justify-center ${item.colorTexto || 'text-cyan-400'} shrink-0 shadow-sm">
            <i data-lucide="${item.icono || 'package'}" class="w-5 h-5"></i>
          </div>
          <div>
            <span class="px-2 py-0.5 rounded-full text-[9px] font-bold bg-slate-950 ${item.colorTexto || 'text-cyan-400'} border ${item.colorBorde || 'border-slate-800'} uppercase">${item.categoria}</span>
            <h4 class="font-bold text-white text-xs mt-1 leading-snug">${item.nombre}</h4>
          </div>
        </div>
        <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${item.verificado ? 'bg-emerald-950 text-emerald-400 border border-emerald-800' : 'bg-rose-950 text-rose-400 border border-rose-800'} shrink-0">
          ${item.estado || (item.verificado ? 'Operativo' : 'Novedad')}
        </span>
      </div>

      <p class="text-[11px] text-slate-300 bg-slate-950/60 p-2.5 rounded-xl border border-slate-800/80">
        ${item.detalle || 'Sin observaciones extraordinarias.'}
      </p>

      <div class="flex items-center justify-between text-[11px] pt-2 border-t border-slate-800/60 text-slate-400">
        <span class="font-medium">Dotación: <strong class="text-white">${item.cantidad || '1 unidad'}</strong></span>
        <div class="flex items-center gap-1.5">
          <button type="button" onclick="alternarEstadoItemInventario('${item.id}')" class="px-2.5 py-1 rounded-lg ${item.verificado ? 'bg-slate-800 hover:bg-slate-700 text-slate-300' : 'bg-emerald-900/60 hover:bg-emerald-800 text-emerald-200'} font-bold text-[10px] transition-all cursor-pointer">
            ${item.verificado ? 'Reportar Novedad' : 'Marcar Operativo'}
          </button>
          ${item.esPersonalizado ? `
          <button type="button" onclick="eliminarItemInventario('${item.id}')" class="p-1 rounded-lg bg-rose-950/40 text-rose-400 hover:bg-rose-900 border border-rose-800 text-[10px] cursor-pointer" title="Eliminar elemento">
            <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
          </button>
          ` : ''}
        </div>
      </div>
    </div>
  `).join("");

  safeCreateIcons();
}

function filtrarInventarioPuesto(query) {
  renderizarInventarioPuestoGrid(undefined, query);
}

function filtrarInventarioCategoria(cat) {
  renderizarInventarioPuestoGrid(cat, undefined);
}

function alternarEstadoItemInventario(id) {
  const it = inventarioPuesto.find(i => i.id === id);
  if (!it) return;
  it.verificado = !it.verificado;
  it.estado = it.verificado ? "Operativo" : "En Revisión / Novedad";
  guardarInventarioStorage();
  renderizarInventarioPuestoGrid();
  renderizarInventarioRelevo();
  if (typeof mostrarToast === "function") {
    mostrarToast(`Estado de "${it.nombre}" actualizado a: ${it.estado}.`);
  }
}

function renderizarInventarioRelevo() {
  const cont = document.getElementById("contenedor-items-relevo-inventario");
  if (!cont) return;

  const kpiConteo = document.getElementById("relevo-inventario-conteo");
  const countChecked = inventarioPuesto.filter(i => i.verificado).length;
  if (kpiConteo) {
    kpiConteo.innerText = `${countChecked} de ${inventarioPuesto.length} elementos verificados`;
  }

  cont.innerHTML = inventarioPuesto.map(item => `
    <div class="p-2.5 rounded-xl bg-slate-900 border ${item.verificado ? 'border-cyan-800/80 bg-cyan-950/20' : 'border-slate-800'} hover:border-slate-700 transition-all flex items-start gap-2.5 cursor-pointer" onclick="toggleVerificacionItem('${item.id}')">
      <input type="checkbox" id="chk-item-${item.id}" ${item.verificado ? 'checked' : ''} onclick="event.stopPropagation(); toggleVerificacionItem('${item.id}')" class="mt-0.5 rounded text-cyan-500 bg-slate-950 border-slate-700 cursor-pointer shrink-0">
      <div class="w-7 h-7 rounded-lg ${item.colorFondo || 'bg-slate-800'} border ${item.colorBorde || 'border-slate-700'} flex items-center justify-center ${item.colorTexto || 'text-cyan-400'} shrink-0 mt-0.5">
        <i data-lucide="${item.icono || 'package'}" class="w-3.5 h-3.5"></i>
      </div>
      <div class="flex-1 min-w-0">
        <div class="flex items-center justify-between gap-1 flex-wrap">
          <span class="font-bold text-white text-[11px] leading-tight truncate">${item.nombre}</span>
          <span class="px-1.5 py-0.2 rounded text-[9px] font-bold ${item.verificado ? 'bg-cyan-950 text-cyan-300 border border-cyan-800' : 'bg-slate-800 text-slate-400 border border-slate-700'}">${item.estado}</span>
        </div>
        <p class="text-[10px] text-slate-400 mt-0.5 line-clamp-1">${item.detalle || item.cantidad}</p>
      </div>
    </div>
  `).join("");

  safeCreateIcons();
}

function marcarTodosInventario(val) {
  inventarioPuesto.forEach(i => {
    i.verificado = Boolean(val);
    if (val) {
      if (i.estado === "En Revisión / Novedad") i.estado = "Operativo";
    }
  });
  guardarInventarioStorage();
  renderizarInventarioRelevo();
  renderizarInventarioPuestoGrid();
}

function toggleVerificacionItem(id) {
  const it = inventarioPuesto.find(i => i.id === id);
  if (!it) return;
  it.verificado = !it.verificado;
  guardarInventarioStorage();
  renderizarInventarioRelevo();
  renderizarInventarioPuestoGrid();
}

