function guardarRelevoTurno() {

  const entrante = document.getElementById("relevo-input-entrante").value.trim();

  const cedula = document.getElementById("relevo-input-cedula").value.trim() || "80.123.456";

  const turno = document.getElementById("relevo-input-turno").value;

  const obs = document.getElementById("relevo-input-obs").value.trim() || "Puesto recibido sin novedades extraordinarias.";



  if (!entrante) {

    mostrarToast("Indique el nombre del guarda entrante.", true);

    return;

  }

  // Recopilar elementos verificados del inventario completo
  const itemsVerificados = inventarioPuesto.filter(i => i.verificado);
  const inventario = itemsVerificados.length
    ? `${itemsVerificados.length} elementos operativos: ` + itemsVerificados.map(i => i.nombre).join("; ")
    : "Dotación general verificada sin novedades";



  minutaPorteria.unshift({

    id: `min-${Date.now()}`,

    tipo: "Relevos",

    fecha: new Date().toISOString().split("T")[0],

    hora: new Date().toLocaleTimeString(),

    inmueble: "Portería Principal",

    portero: `${entrante} (${turno})`,

    titulo: "Relevo e Inicio de Turno de Vigilancia",

    descripcion: `Recibe puesto ${entrante} (CC: ${cedula}) de manos del guarda saliente ${porteroActivo.nombre}. Inventario verificado: ${inventario}. Observaciones: ${obs}`,

    estado: "Registrado"

  });



  // Actualizar portero activo

  porteroActivo.nombre = entrante;

  porteroActivo.cedula = cedula;

  porteroActivo.turno = turno;



  cerrarModalRelevo();

  document.getElementById("relevo-input-entrante").value = "";

  document.getElementById("relevo-input-obs").value = "";

  renderizarPorteria();

  mostrarToast(`Relevo completado. Bienvenido al turno ${entrante}.`);

}



