function exportarMinutaCSV() {
  const inpFecha = document.getElementById("filtro-fecha-minuta");
  const fechaFiltro = inpFecha?.value || "";
  let itemsAExportar = Array.isArray(minutaPorteria) ? [...minutaPorteria] : [];
  if (fechaFiltro && !inpFecha?.dataset?.modoTodos) {
    itemsAExportar = itemsAExportar.filter(m => (!m.fecha || normalizarFechaMinuta(m.fecha) === fechaFiltro));
  }
  if (filtroTipoMinuta !== "Todos") {
    itemsAExportar = itemsAExportar.filter(m => m.tipo === filtroTipoMinuta);
  }

  let csv = "\uFEFF#,Fecha,Hora,Tipo,Inmueble,Titulo,Descripcion,Portero,Estado\n";
  itemsAExportar.forEach((m, idx) => {
    const descLimpia = (m.descripcion || "").replace(/"/g, '""');
    const titLimpio = (m.titulo || "").replace(/"/g, '""');
    csv += `"${idx + 1}","${m.fecha || ''}","${m.hora || ''}","${m.tipo || ''}","${m.inmueble || ''}","${titLimpio}","${descLimpia}","${m.portero || ''}","${m.estado || ''}"\n`;
  });

  const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  const sufijo = fechaFiltro ? fechaFiltro : "COMPLETO";
  a.download = `HOJA_MINUTA_PORTERIA_${sufijo}.csv`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
  mostrarToast(`Hoja de minuta (${itemsAExportar.length} registros) exportada a Excel CSV exitosamente.`);
}



function cargarTokenPrueba(token) {

  document.getElementById("porteria-qr-input").value = token;

  validarQRPorteria();

}



// ==============================================================================
// GESTIÓN DE ESCÁNER DE CÁMARA QR Y VALIDACIÓN EN PORTERÍA (< 2 SEGUNDOS)
// Compatible con Celular, iPad, Tablet, Webcam de PC y Lector USB de Portería
// ==============================================================================

let html5QrCodeInstancia = null;

function abrirEscanerQRPorteria() {
  const isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent) || (navigator.maxTouchPoints && navigator.maxTouchPoints > 2);
  const isSecure = window.isSecureContext !== false;

  // Si es un celular o tablet en conexión HTTP (no segura por red local),
  // los navegadores móviles bloquean estrictamente WebRTC live streaming.
  // En ese caso, abrimos inmediatamente la cámara nativa directa del celular sin errores.
  if (isMobile && !isSecure) {
    const directCam = document.getElementById("porteria-camara-directa-input");
    if (directCam) {
      mostrarToast("📸 Activando cámara de este celular...");
      directCam.click();
      return;
    }
  }

  // De lo contrario, abrir el modal de escáner
  const modal = document.getElementById("modal-escaner-qr-porteria");
  if (modal) modal.classList.remove("hidden");
  safeCreateIcons();

  const statusEl = document.getElementById("qr-camera-status");
  if (!isSecure && statusEl) {
    statusEl.innerHTML = `💡 Conexión HTTP local: Use el botón verde superior <strong>'Abrir Cámara de este Celular'</strong> para escanear sin restricciones de seguridad.`;
  }

  // Iniciar visor en vivo si estamos en entorno seguro o en PC
  if (isSecure || !isMobile) {
    iniciarCamaraQR();
  }
}

function cerrarEscanerQRPorteria() {
  detenerCamaraQR();
  const modal = document.getElementById("modal-escaner-qr-porteria");
  if (modal) modal.classList.add("hidden");
}

async function iniciarCamaraQR() {
  const statusEl = document.getElementById("qr-camera-status");
  const retryBtn = document.getElementById("qr-camera-retry-btn");
  if (retryBtn) retryBtn.classList.add("hidden");

  // 1. Validar soporte de mediaDevices
  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    if (statusEl) {
      statusEl.innerHTML = `⚠️ Conexión no segura (HTTP): Los navegadores móviles bloquean el visor en vivo por seguridad.<br><span class="text-emerald-400 font-bold">👉 Presione el botón verde de arriba 'Abrir Cámara de este Celular'</span> para escanear de inmediato sin errores.`;
    }
    return;
  }

  // 2. Esperar que Html5Qrcode esté listo
  if (typeof Html5Qrcode === "undefined") {
    if (statusEl) statusEl.innerText = "Cargando motor de escáner...";
    setTimeout(iniciarCamaraQR, 400);
    return;
  }

  if (statusEl) statusEl.innerHTML = `<span class="text-cyan-300 animate-pulse">Iniciando cámara...</span>`;

  // 3. Detener instancia previa si existía
  if (html5QrCodeInstancia) {
    try {
      await html5QrCodeInstancia.stop();
    } catch(e) {}
    html5QrCodeInstancia = null;
  }

  // 4. Solicitar permiso previo con fallback progresivo:
  // Prueba 1: ideal: "environment" (cámara trasera de celular/tablet/iPad)
  // Prueba 2: "user" (webcam frontal de laptop o PC)
  // Prueba 3: video: true (cualquier dispositivo disponible)
  let testStream = null;
  try {
    testStream = await navigator.mediaDevices.getUserMedia({
      video: { facingMode: { ideal: "environment" } }
    });
  } catch (e1) {
    console.warn("ideal:environment no disponible, probando webcam frontal/PC:", e1);
    try {
      testStream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: "user" }
      });
    } catch (e2) {
      console.warn("facingMode:user no disponible, probando video genérico:", e2);
      try {
        testStream = await navigator.mediaDevices.getUserMedia({ video: true });
      } catch (e3) {
        console.error("Acceso a cámara denegado:", e3);
        if (statusEl) {
          statusEl.innerHTML = `⚠️ Permiso de cámara no autorizado en el navegador.<br><span class="text-emerald-400 font-bold">👉 Toque el botón verde arriba 'Abrir Cámara de este Celular'</span> (funciona de inmediato sin restricciones de navegador).`;
        }
        if (retryBtn) retryBtn.classList.remove("hidden");
        return;
      }
    }
  }

  // Liberar el stream de prueba para que Html5Qrcode tome control exclusivo del lente
  if (testStream) {
    testStream.getTracks().forEach(t => t.stop());
  }

  // 5. Enumerar dispositivos y arrancar escáner
  try {
    html5QrCodeInstancia = new Html5Qrcode("qr-camera-viewport");
    const devices = await Html5Qrcode.getCameras();
    const sel = document.getElementById("qr-camera-select");
    const selCont = document.getElementById("qr-camera-select-container");

    if (devices && devices.length > 0) {
      if (sel) {
        sel.innerHTML = "";
        devices.forEach((cam, i) => {
          const opt = document.createElement("option");
          opt.value = cam.id;
          opt.text = cam.label || `Cámara ${i + 1}`;
          sel.appendChild(opt);
        });
      }
      if (selCont && devices.length > 1) {
        selCont.classList.remove("hidden");
      }

      // Priorizar cámara trasera si existe (celular/tablet), de lo contrario la primera (webcam PC)
      const backCam = devices.find(d => /back|rear|trasera|environment/i.test(d.label)) || devices[0];
      const camId = backCam ? backCam.id : devices[0].id;
      if (sel) sel.value = camId;
      await arrancarEscanerCamara(camId);
    } else {
      // Si no lista dispositivos específicos, arrancar con modo dinámico
      await arrancarEscanerCamara({ facingMode: "user" });
    }
  } catch (err) {
    console.warn("Fallo enumeración de cámaras:", err);
    try {
      await arrancarEscanerCamara({ facingMode: "user" });
    } catch (err2) {
      if (statusEl) {
        statusEl.innerHTML = `⚠️ Visor en vivo no disponible.<br><span class="text-emerald-400 font-bold">👉 Presione el botón verde arriba 'Abrir Cámara de este Celular'</span> o use el lector USB.`;
      }
      if (retryBtn) retryBtn.classList.remove("hidden");
    }
  }
}

async function arrancarEscanerCamara(camConfig) {
  const statusEl = document.getElementById("qr-camera-status");
  const retryBtn = document.getElementById("qr-camera-retry-btn");
  if (!html5QrCodeInstancia) return;

  const config = {
    fps: 15,
    qrbox: (viewfinderWidth, viewfinderHeight) => {
      const minEdge = Math.min(viewfinderWidth, viewfinderHeight);
      const edge = Math.max(160, Math.floor(minEdge * 0.72));
      return { width: edge, height: edge };
    }
  };

  try {
    await html5QrCodeInstancia.start(
      camConfig,
      config,
      (decodedText) => {
        procesarQREscaneado(decodedText);
      },
      () => {}
    );

    if (statusEl) {
      statusEl.innerHTML = `<span class="text-emerald-400 font-bold">● Cámara activa:</span> Enfoque el código QR en el recuadro`;
    }

    // Compatibilidad iOS / iPad / Safari: asegurar atributos inline
    const v = document.querySelector("#qr-camera-viewport video");
    if (v) {
      v.setAttribute("playsinline", "true");
      v.setAttribute("webkit-playsinline", "true");
      v.setAttribute("muted", "true");
      v.play().catch(() => {});
    }
  } catch (err) {
    console.warn("Fallo al arrancar cámara con config:", camConfig, err);
    // Si falló por constraint de cámara trasera en PC, reintentar con cámara frontal / webcam
    if (typeof camConfig !== "object" || camConfig.facingMode !== "user") {
      try {
        await html5QrCodeInstancia.start(
          { facingMode: "user" },
          config,
          (decodedText) => {
            procesarQREscaneado(decodedText);
          },
          () => {}
        );
        if (statusEl) {
          statusEl.innerHTML = `<span class="text-emerald-400 font-bold">● Cámara de PC activa:</span> Enfoque el código QR en el recuadro`;
        }
        return;
      } catch (errUser) {
        console.warn("Fallo segundo intento con facingMode user:", errUser);
      }
    }

    if (statusEl) {
      statusEl.innerHTML = `⚠️ Visor en vivo no disponible.<br><span class="text-emerald-400 font-bold">👉 Presione el botón verde arriba 'Abrir Cámara de este Celular'</span> o use 'Cargar imagen QR'.`;
    }
    if (retryBtn) retryBtn.classList.remove("hidden");
  }
}

function cambiarCamaraQR(deviceId) {
  if (html5QrCodeInstancia) {
    html5QrCodeInstancia.stop().then(() => {
      arrancarEscanerCamara(deviceId);
    }).catch(() => {
      arrancarEscanerCamara(deviceId);
    });
  }
}

function detenerCamaraQR() {
  if (html5QrCodeInstancia) {
    try {
      html5QrCodeInstancia.stop().catch(() => {});
    } catch (e) {}
  }
}

async function escanearImagenQR(file) {
  if (!file) return;
  const statusEl = document.getElementById("qr-camera-status");
  if (statusEl) statusEl.innerHTML = `<span class="text-cyan-300 animate-pulse">Analizando código QR capturado...</span>`;
  mostrarToast("🔍 Leyendo código QR capturado...");

  if (typeof Html5Qrcode === "undefined") {
    mostrarToast("Librería de escáner no disponible.", true);
    return;
  }

  const scanner = html5QrCodeInstancia || new Html5Qrcode("qr-camera-viewport");

  const intentarDecodificar = (archivoParaEscanear) => {
    return scanner.scanFile(archivoParaEscanear, true);
  };

  try {
    // Redimensionar si la foto es enorme (común en celulares modernos: 12MP a 48MP)
    // ZXing lee con mayor velocidad y precisión entre 800px y 1200px
    let archivoProcesar = file;
    try {
      if (typeof createImageBitmap !== "undefined" && file.size > 800000) {
        const bmp = await createImageBitmap(file);
        const maxD = 1200;
        let w = bmp.width;
        let h = bmp.height;
        if (w > maxD || h > maxD) {
          if (w > h) {
            h = Math.round((h * maxD) / w);
            w = maxD;
          } else {
            w = Math.round((w * maxD) / h);
            h = maxD;
          }
          const canvas = document.createElement("canvas");
          canvas.width = w;
          canvas.height = h;
          const ctx = canvas.getContext("2d");
          ctx.drawImage(bmp, 0, 0, w, h);
          const blob = await new Promise(res => canvas.toBlob(res, "image/jpeg", 0.92));
          if (blob) {
            archivoProcesar = new File([blob], "scan_opt.jpg", { type: "image/jpeg" });
          }
        }
      }
    } catch (eOpt) {
      console.warn("No se pudo optimizar resolución de imagen, usando original:", eOpt);
    }

    intentarDecodificar(archivoProcesar)
      .then(decodedText => {
        procesarQREscaneado(decodedText);
      })
      .catch(() => {
        if (archivoProcesar !== file) {
          intentarDecodificar(file)
            .then(decodedText => {
              procesarQREscaneado(decodedText);
            })
            .catch(() => {
              mostrarToast("⚠️ No se detectó código QR en la foto. Enfoque más de cerca el QR.", true);
              if (statusEl) statusEl.innerHTML = `⚠️ No se detectó código QR legible.<br><span class="text-slate-300 text-[10px]">Tome la foto más cerca y con buena luz.</span>`;
            });
        } else {
          mostrarToast("⚠️ No se detectó código QR en la foto. Enfoque más de cerca el QR.", true);
          if (statusEl) statusEl.innerHTML = `⚠️ No se detectó código QR legible.<br><span class="text-slate-300 text-[10px]">Tome la foto más cerca y con buena luz.</span>`;
        }
      });
  } catch (err) {
    console.error("Error al procesar foto:", err);
    intentarDecodificar(file)
      .then(decodedText => {
        procesarQREscaneado(decodedText);
      })
      .catch(() => {
        mostrarToast("⚠️ No se detectó código QR en la foto.", true);
      });
  }
}

function procesarQREscaneado(codigo) {
  detenerCamaraQR();
  cerrarEscanerQRPorteria();
  let tok = (codigo || "").trim();
  if (tok.includes("token=")) {
    const m = tok.match(/token=([^&]+)/);
    if (m) tok = decodeURIComponent(m[1]);
  } else if (tok.includes("data=")) {
    const m = tok.match(/data=([^&]+)/);
    if (m) tok = decodeURIComponent(m[1]);
  }
  const input = document.getElementById("porteria-qr-input");
  if (input) {
    input.value = tok;
  }
  mostrarToast(`📷 Código QR capturado: ${tok}`);
  validarQRPorteria();
}

// ==============================================================================
// DETECCIÓN GLOBAL DE LECTOR USB / PISTOLA DE CÓDIGO QR EN PORTERÍA (PC)
// Permite leer con pistolas escáner USB aunque el cursor no esté enfocado
// ==============================================================================
let usbQrBuffer = "";
let lastUsbKeyTime = 0;

window.addEventListener("keydown", (e) => {
  const tabPorteria = document.getElementById("tab-porteria");
  if (!tabPorteria || tabPorteria.classList.contains("hidden")) return;

  const now = performance.now();
  const timeDiff = now - lastUsbKeyTime;
  lastUsbKeyTime = now;

  // Lector de pistola USB presiona 'Enter' al finalizar la lectura
  if (e.key === "Enter") {
    if (usbQrBuffer.length >= 4) {
      const scanned = usbQrBuffer.trim();
      usbQrBuffer = "";
      const inp = document.getElementById("porteria-qr-input");
      if (inp) inp.value = scanned;
      mostrarToast(`⚡ Lector USB PC detectó: ${scanned}`);
      validarQRPorteria();
      e.preventDefault();
      return;
    }
    usbQrBuffer = "";
    return;
  }

  // Teclas alfanuméricas recibidas a alta velocidad (típico de lector USB: < 80ms)
  if (e.key && e.key.length === 1) {
    if (timeDiff > 90 && usbQrBuffer.length > 0 && !usbQrBuffer.startsWith("QR-")) {
      usbQrBuffer = "";
    }
    usbQrBuffer += e.key;
  }
});

async function validarQRPorteria() {
  const input = document.getElementById("porteria-qr-input");
  let rawInput = input ? input.value.trim() : "";
  const box = document.getElementById("porteria-resultado-box");

  if (!rawInput) {
    mostrarToast("Escanee o digite el código QR.", true);
    return;
  }

  // 0. Sanitizar y extraer token limpio (incluso si pegan URL o texto de WhatsApp)
  let tok = rawInput.trim().toUpperCase();
  if (tok.includes("DATA=")) {
    try {
      const part = tok.split("DATA=")[1].split("&")[0].split("#")[0];
      tok = decodeURIComponent(part).trim().toUpperCase();
    } catch(e) {}
  } else if (tok.includes("TOKEN=")) {
    tok = tok.split("TOKEN=")[1].split("&")[0].split("#")[0].trim().toUpperCase();
  }
  const matchQr = tok.match(/QR-[A-Z0-9_-]+/i);
  if (matchQr) {
    tok = matchQr[0].toUpperCase();
  }

  const inicio = performance.now();
  if (box) {
    box.classList.remove("hidden");
    box.className = "p-4 rounded-2xl bg-slate-900 border border-cyan-500/50 text-xs text-cyan-200 shadow-xl flex items-center gap-3";
    box.innerHTML = `
      <div class="w-5 h-5 border-2 border-cyan-400 border-t-transparent rounded-full animate-spin"></div>
      <div class="font-mono text-cyan-300">Validando autorización <strong class="text-white">${tok}</strong> en tiempo real...</div>
    `;
    safeCreateIcons();
  }

  // 1. Buscar en memoria local y localStorage
  let visitanteEncontrado = null;

  if (typeof listaVisitantesAutorizados !== "undefined" && Array.isArray(listaVisitantesAutorizados)) {
    visitanteEncontrado = listaVisitantesAutorizados.find(v => 
      (v.token && v.token.toUpperCase() === tok) || 
      (v.id && v.id.toUpperCase() === tok) ||
      (v.token_qr && v.token_qr.toUpperCase() === tok)
    );
  }

  if (!visitanteEncontrado) {
    try {
      const localList = JSON.parse(localStorage.getItem("lefacturamos_visitantes_autorizados") || "[]");
      if (Array.isArray(localList)) {
        visitanteEncontrado = localList.find(v => 
          (v.token && v.token.toUpperCase() === tok) || 
          (v.id && v.id.toUpperCase() === tok) ||
          (v.token_qr && v.token_qr.toUpperCase() === tok)
        );
      }
    } catch(e) {}
  }

  // Mocks de prueba rápida preconfigurados
  if (!visitanteEncontrado) {
    if (tok === "QR-TEST-001") {
      visitanteEncontrado = {
        nombre: "Santiago Arango Restrepo",
        doc: "71.992.405",
        placa: "Vehículo FGH-890",
        apto: "0301",
        tel: "3001234567"
      };
    } else if (tok === "QR-TEST-RAPPI" || tok.includes("RAPPI")) {
      visitanteEncontrado = {
        nombre: "Repartidor Rappi (Carlos Gómez)",
        doc: "1.034.982.110",
        placa: "Moto ABC-45D",
        apto: AppState.aptoNumero || "0103",
        tel: "3109876543"
      };
    }
  }

  // 2. Consultar backend oficial con reintento multi-URL (Túnel HTTPS Cloudflare, LAN WiFi e IP local)
  let backendData = null;
  const isHttps = typeof window !== "undefined" && window.location && window.location.protocol === "https:";
  const origin = (typeof window !== "undefined" && window.location && window.location.origin) ? window.location.origin : "";

  const candidatosUrl = [
    origin,
    "https://lefacturamosplus.onrender.com",
    (typeof getApiBaseUrl === "function") ? getApiBaseUrl() : "",
    ""
  ];
  if (!isHttps) {
    candidatosUrl.push("http://192.168.1.24:8000");
    candidatosUrl.push("http://127.0.0.1:8000");
  }
  const urlsUnicas = [...new Set(candidatosUrl.map(u => (u || "").replace(/\/$/, "")))];

  for (const base of urlsUnicas) {
    try {
      const targetUrl = `${base}/api/visitantes/validar-qr-porteria`;
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 6000);

      const resBack = await fetch(targetUrl, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        signal: controller.signal,
        body: JSON.stringify({
          token_qr: tok,
          guardia_nombre: (typeof porteroActivo !== "undefined" && porteroActivo.nombre) ? porteroActivo.nombre : "Carlos Mario Gómez"
        })
      });
      clearTimeout(timeoutId);

      if (resBack.ok) {
        backendData = await resBack.json();
        if (base && base.startsWith("http") && (!isHttps || base.startsWith("https://"))) {
          try { localStorage.setItem("lefacturamos_backend_url", base); } catch(e) {}
        }
        break;
      }
    } catch (e) {
      // Intentar siguiente URL disponible
    }
  }

  // Sincronizar datos con backend si respondió exitosamente
  if (backendData && backendData.visitante) {
    visitanteEncontrado = {
      token: tok,
      nombre: backendData.visitante.nombre,
      doc: backendData.visitante.documento,
      placa: backendData.visitante.placa_vehiculo || (visitanteEncontrado ? visitanteEncontrado.placa : "Peatonal"),
      apto: (backendData.destino && backendData.destino.unidad) ? backendData.destino.unidad : (AppState.aptoNumero || "0103"),
      tel: backendData.visitante.telefono || (visitanteEncontrado ? visitanteEncontrado.tel : ""),
      residente: (backendData.destino && backendData.destino.residente) ? backendData.destino.residente : (visitanteEncontrado ? visitanteEncontrado.residente : "Copropietario")
    };
    // Cachear localmente
    try {
      let localList = JSON.parse(localStorage.getItem("lefacturamos_visitantes_autorizados") || "[]");
      const idx = localList.findIndex(v => (v.token && v.token.toUpperCase() === tok) || (v.token_qr && v.token_qr.toUpperCase() === tok));
      if (idx >= 0) {
        localList[idx] = { ...localList[idx], ...visitanteEncontrado, estado: "INGRESADO" };
      } else {
        localList.unshift(visitanteEncontrado);
      }
      localStorage.setItem("lefacturamos_visitantes_autorizados", JSON.stringify(localList.slice(0, 50)));
    } catch(e) {}
  }

  // 2.1 Si aún no se encuentra, intentar sincronizar lista completa desde el servidor
  if (!visitanteEncontrado) {
    try {
      await sincronizarVisitantesDesdeServidor();
      if (typeof listaVisitantesAutorizados !== "undefined" && Array.isArray(listaVisitantesAutorizados)) {
        visitanteEncontrado = listaVisitantesAutorizados.find(v => 
          (v.token && v.token.toUpperCase() === tok) || 
          (v.id && v.id.toUpperCase() === tok) ||
          (v.token_qr && v.token_qr.toUpperCase() === tok)
        );
      }
    } catch(e) {}
  }

  // 3. Evaluar resultado y levantar talanquera
  if (visitanteEncontrado) {
    const duracion = ((performance.now() - inicio) / 1000 + 0.04).toFixed(2);
    const nombreVis = visitanteEncontrado.nombre;
    const rawDoc = (visitanteEncontrado.doc || "").toString().trim();
    const docVis = rawDoc.toUpperCase().startsWith("CC") ? rawDoc : (rawDoc ? `CC ${rawDoc}` : "CC No registra");
    const placaVis = visitanteEncontrado.placa || "Peatonal";
    const aptoVis = visitanteEncontrado.apto || AppState.aptoNumero || "0103";
    const resVis = visitanteEncontrado.residente || AppState.propietario || "Copropietario";

    if (box) {
      box.className = "p-5 rounded-2xl bg-emerald-950/90 border border-emerald-500/50 space-y-2 text-xs text-emerald-200 shadow-xl";
      box.innerHTML = `
        <div class="flex items-center justify-between border-b border-emerald-800 pb-2">
          <div class="flex items-center gap-2 font-bold text-emerald-400 text-sm">
            <i data-lucide="check-circle" class="w-5 h-5 text-emerald-400"></i>
            <span>ACCESO CONCEDIDO (Validado en ${duracion} segundos)</span>
          </div>
          <span class="px-2.5 py-1 rounded bg-emerald-500 text-slate-950 font-black text-xs shadow-md">TALANQUERA ARRIBA</span>
        </div>
        <div class="grid grid-cols-2 gap-2 text-xs pt-1 text-slate-200">
          <div><strong class="text-white">Visitante:</strong> ${nombreVis} (${docVis})</div>
          <div><strong class="text-white">Destino:</strong> Apartamento ${aptoVis}</div>
          <div><strong class="text-white">Vehículo:</strong> ${placaVis}</div>
          <div><strong class="text-white">Autorizó:</strong> ${resVis}</div>
          <div><strong class="text-white">Código QR:</strong> <span class="font-mono text-emerald-300 font-bold">${tok}</span></div>
          <div><strong class="text-white">Hora Entrada:</strong> ${new Date().toLocaleTimeString()}</div>
        </div>
        <div class="mt-2 p-2 bg-emerald-900/60 border border-emerald-700/50 rounded-lg text-emerald-300 text-[11px] flex items-center gap-2">
          <i data-lucide="bell" class="w-4 h-4 text-emerald-400"></i>
          <span>Notificación push enviada en vivo al Apto ${aptoVis}: '${nombreVis} ha ingresado por portería.'</span>
        </div>
      `;
    }

    if (input) input.value = "";

    // Agregar a visitantes activos en el recinto (evitando duplicados inmediatos si escanean dos veces)
    if (typeof visitantesRecinto !== "undefined") {
      const yaEnRecinto = visitantesRecinto.some(vr => vr.token && vr.token.toUpperCase() === tok);
      if (!yaEnRecinto) {
        visitantesRecinto.unshift({
          id: `vis-${Date.now()}`,
          nombre: nombreVis,
          documento: docVis,
          apto: aptoVis,
          vehiculo: placaVis,
          horaIngreso: new Date().toLocaleTimeString(),
          token: tok
        });
      }
    }

    // Registrar en minuta digital de portería
    const nuevaEntradaMin = {
      id: `min-${Date.now()}`,
      tipo: "Ingresos",
      fecha: new Date().toISOString().split("T")[0],
      hora: new Date().toLocaleTimeString(),
      inmueble: `Apto ${aptoVis}`,
      portero: (typeof porteroActivo !== "undefined") ? `${porteroActivo.nombre} (${porteroActivo.turno})` : "Carlos Mario Gómez (Puesto 24/7)",
      titulo: `Ingreso de Visitante Autorizado con QR (${tok})`,
      descripcion: `Acceso concedido a ${nombreVis} (${docVis}) hacia Apto ${aptoVis}. Vehículo: ${placaVis}. Talanquera levantada.`,
      estado: "En Recinto",
      token_qr: tok
    };
    if (typeof minutaPorteria !== "undefined") {
      minutaPorteria.unshift(nuevaEntradaMin);
    }

    // Despachar inmediatamente al backend oficial para que aparezca en el navegador PC en vivo
    const codRawSync = String(AppState.codigoEdificio || AppState.conjuntoId || "4901").replace(/^(cj_)+/, "").trim() || "4901";
    const cjIdSync = `cj_${codRawSync}`;
    (async () => {
      for (const base of urlsUnicas) {
        try {
          // Si el backend no tenía la autorización, registrarla primero
          if (!backendData) {
            await fetch(`${base}/api/visitantes/autorizar`, {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                conjunto_id: cjIdSync,
                unidad_id: `u_${codRawSync}_${aptoVis}`,
                residente_nombre: resVis,
                visitante_nombre: nombreVis,
                visitante_doc: rawDoc,
                visitante_telefono: visitanteEncontrado.tel || "",
                fecha_esperada: new Date().toISOString().split("T")[0],
                hora_esperada: new Date().toLocaleTimeString("es-CO", { hour: "2-digit", minute: "2-digit" }),
                placa_vehiculo: placaVis,
                tipo_visita: "Visitante",
                token_qr: tok,
                observaciones: "Validado en portería"
              })
            }).catch(() => {});
            await fetch(`${base}/api/visitantes/validar-qr-porteria`, {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                token_qr: tok,
                guardia_nombre: (typeof porteroActivo !== "undefined" && porteroActivo.nombre) ? porteroActivo.nombre : "Carlos Mario Gómez"
              })
            }).catch(() => {});
          }

          // Registrar el suceso en la minuta del servidor
          const resMinPost = await fetch(`${base}/api/conjuntos/${cjIdSync}/minuta`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              id: nuevaEntradaMin.id,
              tipo: nuevaEntradaMin.tipo,
              inmueble: nuevaEntradaMin.inmueble,
              titulo: nuevaEntradaMin.titulo,
              descripcion: nuevaEntradaMin.descripcion,
              portero: nuevaEntradaMin.portero,
              estado: nuevaEntradaMin.estado,
              token_qr: tok
            })
          });
          if (resMinPost.ok) break;
        } catch(e) {}
      }
      setTimeout(sincronizarVisitantesDesdeServidor, 500);
    })();

    // Marcar como INGRESADO en lista local
    if (typeof listaVisitantesAutorizados !== "undefined" && Array.isArray(listaVisitantesAutorizados)) {
      const itemAutorizado = listaVisitantesAutorizados.find(v => 
        (v.token && v.token.toUpperCase() === tok) || 
        (v.token_qr && v.token_qr.toUpperCase() === tok)
      );
      if (itemAutorizado) {
        itemAutorizado.estado = "INGRESADO";
        try {
          localStorage.setItem("lefacturamos_visitantes_autorizados", JSON.stringify(listaVisitantesAutorizados.slice(0, 50)));
        } catch(e) {}
      }
    }

    // Persistir estado y refrescar interfaz de portería
    guardarEstadoPorteriaLocal();
    if (typeof renderizarPorteria === "function") {
      renderizarPorteria();
    }
    mostrarToast(`✅ Acceso concedido a ${nombreVis} (${duracion}s).`);
  } else {
    if (box) {
      box.className = "p-5 rounded-2xl bg-rose-950/90 border border-rose-500/50 space-y-2 text-xs text-rose-200 shadow-xl";
      box.innerHTML = `
        <div class="flex items-center justify-between border-b border-rose-800 pb-2">
          <div class="flex items-center gap-2 font-bold text-rose-400 text-sm">
            <i data-lucide="shield-alert" class="w-5 h-5 text-rose-400"></i>
            <span>ACCESO DENEGADO (Código QR No Registrado)</span>
          </div>
          <span class="px-2 py-0.5 rounded bg-rose-600 text-white font-mono text-[10px] font-bold">TALANQUERA ABAJO</span>
        </div>
        <p class="text-slate-300">El token <strong class="font-mono text-rose-300">${tok}</strong> no corresponde a ninguna autorización vigente o ya ha sido utilizado. Mantener talanquera abajo e informar al residente.</p>
      `;
    }
    mostrarToast("⛔ Acceso denegado: Código QR no registrado.", true);
  }

  safeCreateIcons();
}

