function abrirModalConsultarLey675(articulo = null) {

  const m = document.getElementById("modal-consultar-ley675");

  if (m) {

    m.classList.remove("hidden");

    const input = document.getElementById("modal-ley-search-input");

    if (articulo) {

      if (input) input.value = String(articulo).toLowerCase().includes("art") ? articulo : `Art. ${articulo}`;

      filtrarArticulosModal(articulo);

    } else {

      if (input) input.value = "";

      filtrarArticulosModal("todos");

    }

    safeCreateIcons();

  }

}



function cerrarModalConsultarLey675() {

  const m = document.getElementById("modal-consultar-ley675");

  if (m) m.classList.add("hidden");

}



function filtrarArticulosModal(clave) {

  const input = document.getElementById("modal-ley-search-input");

  if (clave === "todos") {

    if (input) input.value = "";

  } else if (clave === "paragrafo") {

    if (input) input.value = "parágrafo";

  } else if (typeof clave === "string" && clave.startsWith("art")) {

    const num = clave.replace(/[^0-9]/g, "");

    if (input) input.value = num ? `Art. ${num}` : clave;

  } else if (clave) {

    if (input) input.value = clave;

  }

  buscarEnModalLey675();

}



function buscarEnModalLey675() {

  const input = document.getElementById("modal-ley-search-input");

  const extraCont = document.getElementById("modal-ley-extra-results");

  const noResEl = document.getElementById("modal-ley-no-results");

  if (!input) return;



  const rawQuery = (input.value || "").trim();

  const q = rawQuery.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");

  const numOnly = rawQuery.replace(/[^0-9]/g, "");



  const staticCards = [

    { id: "art38", num: "38", titulo: "ARTÍCULO 38. NATURALEZA Y FUNCIONES DE LA ASAMBLEA GENERAL", texto: "asamblea general de propietarios organo de direccion aprobar estados financieros presupuesto anual fijar cuotas ordinarias extraordinarias elegir consejo de administracion revisor fiscal funciones asamblea" },

    { id: "art39", num: "39", titulo: "ARTÍCULO 39. REUNIONES ORDINARIAS Y EXTRAORDINARIAS", texto: "reuniones ordinarias extraordinarias por lo menos una vez al ano dentro de los tres meses convocatoria administrador 15 dias calendario derecho propio paragrafo 1 primer dia habil cuarto mes 8 pm lugar administracion" },

    { id: "art45", num: "45", titulo: "ARTÍCULO 45. QUÓRUM Y MAYORÍAS ORDINARIAS", texto: "quorum mayorias ordinarias mayoria simple 50% 1 mitad de los coeficientes de copropiedad presentes sesion sesion deliberante votos segunda convocatoria paragrafo cualquier numero plural" },

    { id: "art46", num: "46", titulo: "ARTÍCULO 46. DECISIONES QUE EXIGEN MAYORÍA CALIFICADA (70%)", texto: "mayoria calificada setenta por ciento 70% coeficientes de copropiedad cambio destinacion bienes comunes expensas extraordinarias superiores a 4 veces cuota mensual desafectacion reformas reglamento reconstruccion demolicion paragrafo" },

    { id: "art25", num: "25", titulo: "ARTÍCULO 25. COEFICIENTES DE COPROPIEDAD", texto: "coeficientes de copropiedad proporcion derechos bienes comunes participacion asambleas porcentaje contribucion expensas comunes ponderacion area privada" }

  ];



  let visibleCount = 0;



  if (!q) {

    staticCards.forEach(c => {

      const el = document.getElementById(`card-${c.id}`);

      if (el) el.classList.remove("hidden");

    });

    if (extraCont) extraCont.innerHTML = "";

    if (noResEl) noResEl.classList.add("hidden");

    safeCreateIcons();

    return;

  }



  // Filtrar tarjetas estáticas

  staticCards.forEach(c => {

    const el = document.getElementById(`card-${c.id}`);

    if (!el) return;

    const txtComp = (c.titulo + " " + c.texto).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");

    const matchArt = (numOnly && c.num === numOnly) || q.includes(`art ${c.num}`) || q.includes(`articulo ${c.num}`) || q === c.num;

    const matchText = txtComp.includes(q);

    const matchParagrafo = (q.includes("paragrafo") || q.includes("parágrafo")) && (c.id === "art39" || c.id === "art45" || c.id === "art46");



    if (matchArt || matchText || matchParagrafo) {

      el.classList.remove("hidden");

      visibleCount++;

    } else {

      el.classList.add("hidden");

    }

  });



  // Buscar en el catálogo articulosLey675

  const resultadosExtra = articulosLey675.filter(a => {

    const artStr = String(a.articulo || "");

    const tit = (a.titulo || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");

    const preg = (a.pregunta || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");

    const res = (a.resolucion || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");

    const cont = (a.contenido || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");

    const pal = (a.palabras || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");

    const sub = (a.subindice || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");



    const matchArtNum = (numOnly && artStr === numOnly) || q === artStr || q.includes(`art ${artStr}`) || q.includes(`articulo ${artStr}`);

    const matchFull = tit.includes(q) || preg.includes(q) || res.includes(q) || cont.includes(q) || pal.includes(q) || sub.includes(q);

    const matchParagrafo = (q.includes("paragrafo") || q.includes("parágrafo")) && (

      cont.includes("paragrafo") || res.includes("paragrafo") || tit.includes("paragrafo") || pal.includes("paragrafo") ||

      [29, 30, 39, 45, 46, 50, 59].includes(Number(a.articulo))

    );



    return matchArtNum || matchFull || matchParagrafo;

  });



  if (extraCont) {

    if (resultadosExtra.length === 0) {

      extraCont.innerHTML = "";

    } else {

      extraCont.innerHTML = resultadosExtra.map(a => `

        <div class="p-3.5 rounded-2xl bg-slate-50 border border-purple-200/80 space-y-2 transition-all hover:border-purple-300">

          <div class="flex items-center justify-between gap-2 flex-wrap">

            <span class="font-black text-purple-900 text-xs">ARTÍCULO ${a.articulo}. ${a.titulo.toUpperCase()}</span>

            <span class="text-[9px] font-bold px-2 py-0.5 rounded bg-purple-100 text-purple-800 uppercase tracking-wider">${a.subindice}</span>

          </div>

          <div class="bg-white p-2.5 rounded-xl border border-slate-200/70 space-y-1">

            <span class="font-bold text-slate-800 text-[11px] flex items-center gap-1.5">

              <i data-lucide="help-circle" class="w-3.5 h-3.5 text-purple-600 shrink-0"></i>

              ${a.pregunta}

            </span>

            <p class="text-slate-600 leading-relaxed text-[11px] font-medium pl-5">${a.resolucion}</p>

          </div>

          <div class="text-[10px] text-slate-500 bg-amber-50/50 border border-amber-200/50 rounded-lg p-2 leading-relaxed">

            <strong class="text-amber-900">Texto Normativo / Parágrafo:</strong> ${a.contenido}

          </div>

          <div class="flex items-center gap-2 pt-1">

            <button type="button" onclick="copiarResolucionWeb('${a.articulo}')" class="px-2.5 py-1 rounded-lg bg-slate-200 hover:bg-slate-300 text-slate-800 font-bold text-[10px] flex items-center gap-1 transition-colors cursor-pointer">

              <i data-lucide="copy" class="w-3 h-3 text-slate-700"></i>

              <span>Copiar</span>

            </button>

          </div>

        </div>

      `).join("");

      visibleCount += resultadosExtra.length;

    }

  }



  if (noResEl) {

    if (visibleCount === 0) {

      noResEl.classList.remove("hidden");

    } else {

      noResEl.classList.add("hidden");

    }

  }



  safeCreateIcons();

}



