function cerrarVotacionActiva() {

  if (!estadoAsambleaLefacturamos.puntoActivo) {

    mostrarToast("No hay una votación activa en curso para cerrar.", true);

    return;

  }

  const punto = estadoAsambleaLefacturamos.puntoActivo;

  punto.estado = "APROBADO POR MAYORÍA LEY 675";

  punto.fechaCierre = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

  estadoAsambleaLefacturamos.puntosAprobados.unshift(punto);

  estadoAsambleaLefacturamos.puntoActivo = null;

  estadoAsambleaLefacturamos.subpestanaActual = "votados";

  renderizarModuloAsambleaVotaciones();

  mostrarToast("Votación cerrada y aprobada formalmente según el Art. 45 de la Ley 675.");

}



function cerrarYFormularSiguientePunto() {

  if (estadoAsambleaLefacturamos.puntoActivo) {

    const punto = estadoAsambleaLefacturamos.puntoActivo;

    punto.estado = "APROBADO POR MAYORÍA LEY 675";

    punto.fechaCierre = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

    estadoAsambleaLefacturamos.puntosAprobados.unshift(punto);

    estadoAsambleaLefacturamos.puntoActivo = null;

  }

  renderizarModuloAsambleaVotaciones();

  abrirModalNuevaPreguntaAsamblea();

  mostrarToast("Punto cerrado en acta. Formule el siguiente punto para la asamblea.");

}



function guardarNuevaPreguntaAsambleaModal(event) {

  if (event) event.preventDefault();

  const titulo = document.getElementById("modal-vot-titulo")?.value.trim();

  const descripcion = document.getElementById("modal-vot-descripcion")?.value.trim();

  const articulo = document.getElementById("modal-vot-articulo")?.value || "Art. 38";

  const mayoria = document.getElementById("modal-vot-mayoria")?.value || "Mayoría Simple (Ley 675 Art. 45: 50% + 1 del quórum)";



  if (!titulo || !descripcion) {

    mostrarToast("Por favor complete el título y la sustentación del punto.", true);

    return;

  }



  // Si había un punto activo, se archiva en aprobados

  if (estadoAsambleaLefacturamos.puntoActivo) {

    const puntoViejo = estadoAsambleaLefacturamos.puntoActivo;

    puntoViejo.estado = "APROBADO POR MAYORÍA LEY 675";

    estadoAsambleaLefacturamos.puntosAprobados.unshift(puntoViejo);

  }



  estadoAsambleaLefacturamos.puntoActivo = {

    id: `vot_${Date.now()}`,

    numero: `Punto #${estadoAsambleaLefacturamos.puntosAprobados.length + 1}`,

    titulo: `${titulo} (Ley 675 ${articulo})`,

    descripcion: descripcion,

    tipoMayoria: mayoria,

    articuloLey: "Ley 675 de 2001",

    articuloBadge: "NORMA VINCULANTE",

    articuloSustento: "Regula el quórum deliberatorio y decisorio según los coeficientes de copropiedad.",

    quorumVotadoAcumulado: 0.0,

    quorumTotalReferencia: "100% total",

    aptosVotantes: 0,

    totalCopropietarios: 249,

    aptosFaltantes: 249,

    umbralRequerido: mayoria.includes("70%") ? "70% de coeficientes" : "50% + 1 de presentes",

    umbralSubtexto: mayoria.includes("70%") ? "Art. 46: Mayoría calificada obligatoria" : "Art. 45: Mitad más uno del quórum deliberante",

    opciones: [

      { id: "1", num: "1", texto: "SÍ - Apruebo la moción propuesta", coeficiente: 0.0, pctEmitidos: 0.0, aptos: 0, barColor: "bg-emerald-500", textColor: "text-purple-700" },

      { id: "2", num: "2", texto: "NO - Rechazo la moción propuesta", coeficiente: 0.0, pctEmitidos: 0.0, aptos: 0, barColor: "bg-rose-500", textColor: "text-slate-700" },

      { id: "3", num: "3", texto: "Voto en Blanco", coeficiente: 0.0, pctEmitidos: 0.0, aptos: 0, barColor: "bg-slate-300", textColor: "text-slate-400" }

    ],

    votosEmitidos: {}

  };



  const form = event.target;

  if (form) form.reset();

  cerrarModalNuevaPreguntaAsamblea();

  estadoAsambleaLefacturamos.subpestanaActual = "activo";

  renderizarModuloAsambleaVotaciones();

  mostrarToast("Nuevo punto lanzado a votación en vivo con respaldo Ley 675.");

}



function emitirVotoAsambleaPunto(opcId) {

  if (!estadoAsambleaLefacturamos.puntoActivo) {

    mostrarToast("No hay una votación activa en curso.", true);

    return;

  }

  const punto = estadoAsambleaLefacturamos.puntoActivo;

  const apto = AppState.aptoNumero || "0301";

  const coef = AppState.coeficiente || 2.588;



  if (punto.votosEmitidos[apto]) {

    mostrarToast(`La unidad (Apto ${apto}) ya emitió su voto oficial en este punto.`, true);

    return;

  }



  const opc = punto.opciones.find(o => o.id === opcId);

  if (!opc) return;



  punto.votosEmitidos[apto] = {

    opcionId: opcId,

    textoOpcion: opc.texto,

    coef: coef,

    hora: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })

  };



  opc.aptos += 1;

  opc.coeficiente = parseFloat((opc.coeficiente + coef).toFixed(3));

  punto.aptosVotantes += 1;

  punto.aptosFaltantes = Math.max(0, punto.totalCopropietarios - punto.aptosVotantes);

  punto.quorumVotadoAcumulado = parseFloat((punto.quorumVotadoAcumulado + coef).toFixed(3));



  // Recalcular porcentajes sobre emitidos

  const totalEmitido = punto.opciones.reduce((acc, o) => acc + o.coeficiente, 0);

  if (totalEmitido > 0) {

    punto.opciones.forEach(o => {

      o.pctEmitidos = parseFloat(((o.coeficiente / totalEmitido) * 100).toFixed(1));

    });

  }



  renderizarModuloAsambleaVotaciones();

  mostrarToast(`Voto registrado para Apto ${apto}: "${opc.texto}". Coeficiente ponderado: ${coef}% (Ley 675).`);

}



function inicializarModuloAsamblea() {

  renderizarPreguntasAsamblea();

  renderizarModuloAsambleaVotaciones();

}



function crearPreguntaAsamblea() {

  const pregInput = document.getElementById("asamblea-nueva-pregunta");

  const sustentoInput = document.getElementById("asamblea-nuevo-sustento");

  const quorumSel = document.getElementById("asamblea-tipo-quorum");



  if (!pregInput) return;



  const titulo = pregInput.value.trim();

  const sustento = sustentoInput ? (sustentoInput.value.trim() || "Formulado por el Administrador conforme a la Ley 675 de 2001.") : "Pregunta de asamblea";

  const quorum = quorumSel ? (parseFloat(quorumSel.value) || 51.0) : 51.0;



  if (!titulo) {

    mostrarToast("Debe escribir la pregunta que se someterá a votación en la asamblea.", true);

    return;

  }



  const nuevaPregunta = {

    id: `vot_${Date.now().toString().slice(-4)}`,

    titulo: titulo,

    descripcion: sustento,

    quorumMinimo: quorum,

    estado: "ABIERTA",

    opciones: ["Sí", "No", "Voto en Blanco"],

    votos: []

  };



  preguntasAsamblea.unshift(nuevaPregunta);

  pregInput.value = "";

  if (sustentoInput) sustentoInput.value = "";



  renderizarPreguntasAsamblea();

  mostrarToast("Pregunta de asamblea formulada y publicada exitosamente.");

}



function emitirVotoWeb(preguntaId, opcion) {

  const preg = preguntasAsamblea.find(p => p.id === preguntaId);

  if (!preg) return;



  const yaVoto = preg.votos.find(v => v.apto === AppState.aptoNumero);

  if (yaVoto) {

    mostrarToast(`El Apartamento ${AppState.aptoNumero} ya emitió su voto ("${yaVoto.opcion}") en esta pregunta.`, true);

    return;

  }



  preg.votos.push({

    apto: AppState.aptoNumero,

    opcion: opcion,

    coef: AppState.coeficiente

  });



  renderizarPreguntasAsamblea();

  mostrarToast(`Voto "${opcion}" registrado para el Apto ${AppState.aptoNumero}. Coeficiente aplicado: ${AppState.coeficiente}% (Ley 675).`);

}



function renderizarPreguntasAsamblea() {

  const cont = document.getElementById("lista-preguntas-votacion");

  if (!cont) return;



  cont.innerHTML = preguntasAsamblea.map((p, idx) => {

    // Totales de votación

    const totalVotos = p.votos.length;

    const coefTotalEmitido = p.votos.reduce((acc, v) => acc + (v.coef || 0), 0);



    // Conteo por opción

    const votosPorOpcion = {};

    p.opciones.forEach(o => votosPorOpcion[o] = { count: 0, coef: 0 });



    p.votos.forEach(v => {

      if (votosPorOpcion[v.opcion]) {

        votosPorOpcion[v.opcion].count += 1;

        votosPorOpcion[v.opcion].coef += (v.coef || 0);

      }

    });



    const votoUnidadActual = p.votos.find(v => v.apto === AppState.aptoNumero);



    // Estado jurídico según Ley 675

    const coefSi = votosPorOpcion["Sí"] ? votosPorOpcion["Sí"].coef : 0;

    const estaAprobada = coefSi >= p.quorumMinimo;



    return `

      <div class="p-5 rounded-2xl bg-slate-950 border border-slate-800 space-y-4">

        <div class="flex items-center justify-between border-b border-slate-800/80 pb-2.5">

          <div class="flex items-center gap-2">

            <span class="px-2 py-0.5 rounded bg-brand-500/20 text-brand-400 border border-brand-500/40 text-[10px] font-bold uppercase">Pregunta Oficial No. ${preguntasAsamblea.length - idx}</span>

            <span class="text-xs text-slate-400 font-mono">Quórum Requerido: ${p.quorumMinimo}%</span>

          </div>

          <span class="px-2 py-0.5 rounded ${estaAprobada ? 'bg-emerald-950 text-emerald-300 border border-emerald-700/50' : 'bg-slate-800 text-slate-300'} text-[10px] font-black uppercase">

            ${estaAprobada ? 'APROBADA LEY 675' : p.estado}

          </span>

        </div>



        <div>

          <h4 class="text-base font-black text-white">${p.titulo}</h4>

          <p class="text-xs text-slate-400 mt-1">${p.descripcion}</p>

        </div>



        <!-- TOTALES EN TIEMPO REAL -->

        <div class="grid grid-cols-2 sm:grid-cols-3 gap-2.5 p-3 rounded-xl bg-slate-900 border border-slate-800 text-xs">

          <div>

            <span class="text-[10px] text-slate-400 uppercase block font-bold">Unidades Participantes</span>

            <span class="text-base font-black text-white mt-0.5 block">${totalVotos} <span class="text-xs font-normal text-slate-400">/ 44 aptos</span></span>

          </div>

          <div>

            <span class="text-[10px] text-slate-400 uppercase block font-bold">Quórum Coeficiente Acumulado</span>

            <span class="text-base font-black text-brand-400 mt-0.5 block font-mono">${coefTotalEmitido.toFixed(3)}%</span>

          </div>

          <div class="col-span-2 sm:col-span-1">

            <span class="text-[10px] text-slate-400 uppercase block font-bold">Mayoría Exigida</span>

            <span class="text-xs font-bold ${estaAprobada ? 'text-emerald-400' : 'text-amber-400'} mt-1 block">

              ${estaAprobada ? '✅ Superó el 50%+1' : '⏳ En deliberación'}

            </span>

          </div>

        </div>



        <!-- BARRAS DE PROGRESO POR OPCIÓN -->

        <div class="space-y-2">

          ${p.opciones.map(opc => {

            const inf = votosPorOpcion[opc] || { count: 0, coef: 0 };

            const pct = coefTotalEmitido > 0 ? (inf.coef / coefTotalEmitido) * 100 : 0;

            const barColor = opc === 'Sí' ? 'bg-emerald-500' : (opc === 'No' ? 'bg-rose-500' : 'bg-slate-500');



            return `

              <div class="space-y-1">

                <div class="flex items-center justify-between text-xs">

                  <span class="font-bold text-slate-200">${opc}: <strong class="text-white">${inf.count} votos</strong></span>

                  <span class="font-mono text-slate-300 font-bold">${inf.coef.toFixed(3)}% coef. (${pct.toFixed(1)}%)</span>

                </div>

                <div class="w-full bg-slate-800 rounded-full h-2 overflow-hidden">

                  <div class="${barColor} h-2 rounded-full transition-all duration-500" style="width: ${pct}%"></div>

                </div>

              </div>

            `;

          }).join("")}

        </div>



        <!-- ACCIONES DE VOTO PARA EL INMUEBLE -->

        <div class="pt-2 border-t border-slate-800/80">

          ${votoUnidadActual ? `

            <div class="p-2.5 rounded-xl bg-emerald-950/60 border border-emerald-800/60 text-xs flex items-center justify-between">

              <span class="text-slate-300">Tu unidad (Apto ${AppState.aptoNumero}) votó: <strong class="text-white font-bold">${votoUnidadActual.opcion}</strong></span>

              <span class="font-mono text-emerald-400 font-bold">Ponderación: ${votoUnidadActual.coef}%</span>

            </div>

          ` : `

            <div class="space-y-2">

              <span class="text-[11px] text-slate-400 font-medium block">Emite tu voto oficial con el coeficiente de tu unidad (${AppState.coeficiente}%):</span>

              <div class="grid grid-cols-3 gap-2">

                <button onclick="emitirVotoWeb('${p.id}', 'Sí')" class="py-2.5 rounded-xl bg-emerald-600 hover:bg-emerald-500 font-black text-xs text-white shadow-md transition-all">SÍ</button>

                <button onclick="emitirVotoWeb('${p.id}', 'No')" class="py-2.5 rounded-xl bg-rose-600 hover:bg-rose-500 font-black text-xs text-white shadow-md transition-all">NO</button>

                <button onclick="emitirVotoWeb('${p.id}', 'Voto en Blanco')" class="py-2.5 rounded-xl bg-slate-800 hover:bg-slate-700 font-bold text-xs text-slate-300 transition-all">VOTO EN BLANCO</button>

              </div>

            </div>

          `}

        </div>

      </div>

    `;

  }).join("");





  safeCreateIcons();

}



function generarInformeAsamblea() {

  const hoyStr = new Date().toISOString().split("T")[0];

  const cAct = (typeof obtenerDatosCopropiedad === "function") ? obtenerDatosCopropiedad(AppState.codigoEdificio) : listaCopropiedadesSuperadmin.find(c => c.codigo === AppState.codigoEdificio);

  const conjuntoNombre = cAct ? `${cAct.nombre} (CÓDIGO: ${cAct.codigo})` : "EDIFICIO ROBLE ALTO P.H. (CÓDIGO: 4901)";

  const nit = cAct ? cAct.nit : "901690778-9";



  let totalVotantesGeneral = 0;

  let sumaQuorumGeneral = 0;



  const detallePreguntasTexto = preguntasAsamblea.map((p, idx) => {

    const totalVotos = p.votos.length;

    const coefEmitido = p.votos.reduce((acc, v) => acc + (v.coef || 0), 0);

    if (totalVotos > totalVotantesGeneral) totalVotantesGeneral = totalVotos;

    if (coefEmitido > sumaQuorumGeneral) sumaQuorumGeneral = coefEmitido;



    const conteo = {};

    p.opciones.forEach(o => conteo[o] = { count: 0, coef: 0 });

    p.votos.forEach(v => {

      if (conteo[v.opcion]) {

        conteo[v.opcion].count += 1;

        conteo[v.opcion].coef += (v.coef || 0);

      }

    });



    const coefSi = conteo["Sí"] ? conteo["Sí"].coef : 0;

    const coefNo = conteo["No"] ? conteo["No"].coef : 0;

    const coefAbs = (conteo["Voto en Blanco"] ? conteo["Voto en Blanco"].coef : 0) + (conteo["Abstención"] ? conteo["Abstención"].coef : 0);

    const dictamen = coefSi >= p.quorumMinimo ? "APROBADO POR MAYORÍA REGLAMENTARIA (LEY 675)" : "NO APROBADO / EN TRÁMITE";



    return `

PREGUNTA NO. ${idx + 1}:

  "${p.titulo}"

  Sustentación: ${p.descripcion}

  Quórum Reglamentario Exigido: ${p.quorumMinimo}%

  Unidades Participantes: ${totalVotos} de 44 apartamentos

  Quórum Ponderado Total: ${coefEmitido.toFixed(3)}% de coeficientes



  DESGLOSE DETALLADO DE SUFRAGIOS:

    - VOTOS A FAVOR (SÍ):     ${conteo["Sí"] ? conteo["Sí"].count : 0} unidades | Coeficiente: ${coefSi.toFixed(3)}%

    - VOTOS EN CONTRA (NO):    ${conteo["No"] ? conteo["No"].count : 0} unidades | Coeficiente: ${coefNo.toFixed(3)}%

    - VOTOS EN BLANCO:         ${(conteo["Voto en Blanco"] ? conteo["Voto en Blanco"].count : 0) + (conteo["Abstención"] ? conteo["Abstención"].count : 0)} unidades | Coeficiente: ${coefAbs.toFixed(3)}%



  DECISIÓN FINAL CONFORME A LA LEY 675 DE 2001:

  >>> ${dictamen} <<<

--------------------------------------------------------------------------------`;

  }).join("\n");



  const actaTexto = `================================================================================

LEFACTURAMOS - PLATAFORMA DE ADMINISTRACIÓN DE PROPIEDAD HORIZONTAL

INFORME OFICIAL Y ACTA CONSOLIDADA DE ASAMBLEA GENERAL DE COPROPIETARIOS

RÉGIMEN DE PROPIEDAD HORIZONTAL - LEY 675 DE 2001

================================================================================



COPROPIEDAD:       ${conjuntoNombre}

NIT:               ${nit}

FECHA:             ${hoyStr}

TIPO DE REUNIÓN:   Asamblea General Ordinaria de Copropietarios (Art. 39 Ley 675)

CIUDAD:            Bello / Medellín, Antioquia

QUÓRUM INICIAL:    ${sumaQuorumGeneral.toFixed(3)}% de coeficientes de copropiedad registrados

TOTAL INMUEBLES:   44 Unidades Privadas (Apartamentos y Locales)

ADMINISTRADOR:     ADMINISTRACIÓN GENERAL PH (LefacturamosPH@lefacturamos.com)



================================================================================

ORDEN DEL DÍA Y RELACIÓN COMPLETA DE PREGUNTAS Y VOTACIONES SOMETIDAS A SUFRAGIO:

================================================================================

${detallePreguntasTexto}



================================================================================

CONSTANCIA DE VALIDEZ JURÍDICA Y REGISTRO EN GOOGLE DRIVE:

================================================================================

1. Se deja constancia de que los sufragios fueron emitidos de manera personal y/o mediante

   poder legal debidamente verificado, computando la ponderación matemática exacta por el

   coeficiente de copropiedad de cada unidad según el Reglamento de Propiedad Horizontal.

2. Los resultados aquí consignados son vinculantes para todos los copropietarios conforme al

   Artículo 37 y 45 de la Ley 675 de 2001.

3. Este documento queda archivado y respaldado en el Google Drive Oficial de la Copropiedad:

   https://drive.google.com/drive/folders/1u1remh8F3vwpk108ZhibqfDhHErBtYBv?usp=drive_link



FIRMAS REGLAMENTARIAS:





_____________________________                  _____________________________

PRESIDENTE DE LA ASAMBLEA                      SECRETARIO DE LA ASAMBLEA

C.C. Copropietario Designado                   C.C. Copropietario Designado





_____________________________                  _____________________________

ADMINISTRADOR DEL CONJUNTO                     COMISIÓN VERIFICADORA DE ACTA

LEFACTURAMOS PH                                Copropietario Designado

================================================================================`;



  const contenedorActa = document.getElementById("contenido-acta-generada");

  if (contenedorActa) {

    contenedorActa.innerText = actaTexto;

  }



  informesAsambleaPersistidos.unshift({

    fecha: hoyStr,

    titulo: `Acta Oficial de Asamblea - ${hoyStr}`,

    quorum: sumaQuorumGeneral,

    texto: actaTexto

  });



  mostrarToast("Informe Oficial de la Asamblea generado y consolidado con éxito.");

}



function descargarInformeAsambleaTexto() {

  const contenedorActa = document.getElementById("contenido-acta-generada");

  const texto = contenedorActa ? contenedorActa.innerText : "";

  if (!texto || texto.includes("Presione el botón")) {

    generarInformeAsamblea();

  }



  const textoFinal = document.getElementById("contenido-acta-generada").innerText;

  const blob = new Blob([textoFinal], { type: "text/plain;charset=utf-8" });

  const url = URL.createObjectURL(blob);

  const a = document.createElement("a");

  a.href = url;

  a.download = `Acta_Oficial_Asamblea_Ley675_${AppState.codigoEdificio}.txt`;

  document.body.appendChild(a);

  a.click();

  document.body.removeChild(a);

  URL.revokeObjectURL(url);

  mostrarToast("Descargando Acta e Informe de Asamblea en texto...");

}



