// ==============================================================================
// FUNCIÓN INTELIGENTE DE BÚSQUEDA Y CONSULTA JURÍDICA LEY 675
// CON SOPORTE EXACTO PARA: RUIDO, PARQUEADERO, MOVER COSAS A DESHORAS / DESOHORAS
// ==============================================================================
function cargarLey675(filtro = "", sub = "Todos", perfil = "Todos") {
  const cont = document.getElementById("lista-articulos-ley");
  if (!cont) return;

  // Normalización exhaustiva: minúsculas, sin acentos y corrección de variaciones ortográficas
  let qNorm = (filtro || "").toLowerCase().trim();
  qNorm = qNorm.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  qNorm = qNorm.replace(/desohoras/g, "deshoras").replace(/des\s+horas/g, "deshoras");

  const numOnly = qNorm.replace(/[^0-9]/g, "");
  const stopWords = new Set(["a", "de", "la", "el", "en", "que", "y", "los", "las", "por", "un", "una", "con", "se", "o", "del", "al"]);
  const tokens = qNorm.split(/\s+/).filter(t => t.length > 2 && !stopWords.has(t));

  // Filtrado y Ponderación de Relevancia
  let resultados = articulosLey675.map(a => {
    // Filtro por subíndice y perfil
    const coincideSub = sub === "Todos" || a.subindice === sub;
    const coincidePerfil = perfil === "Todos" || a.aplicable === perfil || a.aplicable === "Ambos";

    if (!coincideSub || !coincidePerfil) {
      return { articulo: a, match: false, score: 0 };
    }

    if (!qNorm) {
      return { articulo: a, match: true, score: 1 };
    }

    const textoCompleto = (a.titulo + " " + a.pregunta + " " + a.resolucion + " " + (a.quePuedeHacer || "") + " " + a.contenido + " " + a.palabras + " art " + a.articulo + " articulo " + a.articulo + " " + (a.paragrafo || ""))
      .toLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/desohoras/g, "deshoras");

    let score = 0;

    // Coincidencia exacta de número de artículo
    if (numOnly && String(a.articulo) === numOnly) {
      score += 50;
    }

    // Coincidencia de frase completa
    if (textoCompleto.includes(qNorm)) {
      score += 40;
    }

    // Coincidencia en título
    const titNorm = a.titulo.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    if (titNorm.includes(qNorm)) {
      score += 30;
    }

    // Coincidencia por tokens individuales
    tokens.forEach(tok => {
      if (textoCompleto.includes(tok)) score += 10;
      if (titNorm.includes(tok)) score += 15;
    });

    // Casos especiales frecuentes requeridos:
    if (qNorm.includes("deshoras") && (textoCompleto.includes("mover cosas") || textoCompleto.includes("trasteo") || textoCompleto.includes("mudanza"))) {
      score += 80;
    }
    if (qNorm.includes("ruido") && textoCompleto.includes("ruido")) {
      score += 70;
    }
    if (qNorm.includes("parqueadero") && textoCompleto.includes("parqueadero")) {
      score += 70;
    }

    return {
      articulo: a,
      match: score > 0,
      score: score
    };
  });

  const filtrados = resultados
    .filter(r => r.match)
    .sort((a, b) => b.score - a.score)
    .map(r => r.articulo);

  if (filtrados.length === 0) {
    cont.innerHTML = `
      <div class="p-6 rounded-2xl bg-slate-800/60 border border-slate-700/60 text-center space-y-3">
        <i data-lucide="help-circle" class="w-9 h-9 text-amber-400 mx-auto"></i>
        <h4 class="font-bold text-white text-sm sm:text-base">No se encontraron artículos con el criterio ingresado</h4>
        <p class="text-xs text-slate-400 max-w-md mx-auto">
          Intente con temas frecuentes como: <strong>ruido</strong>, <strong>parqueadero</strong>, <strong>mover cosas a deshoras</strong>, <strong>obras</strong>, <strong>mascotas</strong>, <strong>multas</strong> o <strong>quórum</strong>.
        </p>
        <div class="pt-2">
          <button type="button" onclick="buscarLey675Rapido('')" class="px-4 py-2 rounded-xl bg-slate-700 hover:bg-slate-600 text-white font-bold text-xs">
            Ver Todo el Catálogo Legal
          </button>
        </div>
      </div>
    `;
    safeCreateIcons();
    return;
  }

  cont.innerHTML = filtrados.map(a => {
    const colorBadge = a.aplicable === "Copropietarios" 
      ? "bg-emerald-950/80 text-emerald-300 border-emerald-600/40" 
      : (a.aplicable === "Administradores" ? "bg-sky-950/80 text-sky-300 border-sky-600/40" : "bg-amber-950/80 text-amber-300 border-amber-600/40");

    const guiaPasoPaso = (a.quePuedeHacer || "1. Informar a la portería o administración.\n2. Radicar PQR formal con pruebas.\n3. Acudir al Comité de Convivencia.\n4. Solicitar aplicación de sanciones legales.")
      .split('\n')
      .map(line => {
        const clean = line.replace(/^[0-9]+\.\s*/, '').trim();
        return `<div class="flex items-start gap-2 text-xs text-slate-200"><span class="text-emerald-400 font-bold shrink-0 mt-0.5">•</span><span>${clean}</span></div>`;
      })
      .join('');

    return `
      <div class="p-4 sm:p-5 rounded-2xl bg-slate-800/80 border border-slate-700/60 space-y-3.5 text-xs shadow-lg transition-all hover:border-slate-600">
        <!-- Encabezado con Badges y Artículo/Parágrafo -->
        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-700/60 pb-2.5">
          <div class="flex items-center gap-2 flex-wrap">
            <span class="px-2.5 py-0.5 rounded-lg bg-brand-900/60 text-brand-300 border border-brand-700/50 font-bold text-[10px] uppercase">
              📁 ${a.subindice}
            </span>
            <span class="px-2.5 py-0.5 rounded-lg ${colorBadge} border font-bold text-[10px]">
              Para: ${a.aplicable}
            </span>
            <span class="px-2.5 py-0.5 rounded-lg bg-amber-500/20 text-amber-300 border border-amber-500/40 font-mono font-bold text-[10px]">
              ⚖️ Art. ${a.articulo} · ${a.paragrafo || 'Ley 675 de 2001'}
            </span>
          </div>
          <span class="text-[11px] text-slate-400 font-medium">${a.capitulo}</span>
        </div>

        <!-- Pregunta Concreta del Usuario -->
        <div class="flex items-start gap-2.5 pt-0.5">
          <div class="w-7 h-7 rounded-lg bg-amber-500/20 text-amber-400 flex items-center justify-center shrink-0 mt-0.5 border border-amber-500/30">
            <i data-lucide="help-circle" class="w-4 h-4"></i>
          </div>
          <h4 class="font-bold text-sm sm:text-base text-white leading-snug">${a.pregunta}</h4>
        </div>

        <!-- Dictamen y Qué Dice la Ley -->
        <div class="p-3.5 rounded-xl bg-slate-900/90 border border-slate-700/80 space-y-1.5">
          <div class="flex items-center gap-1.5 font-bold text-brand-400 text-xs uppercase tracking-wide">
            <i data-lucide="scale" class="w-4 h-4 text-emerald-400"></i>
            <span>Fundamento Legal & Dictamen Oficial:</span>
          </div>
          <p class="text-slate-200 text-xs leading-relaxed">${a.resolucion}</p>
          ${a.contenido ? `<p class="text-[11px] text-slate-400 italic pt-1 border-t border-slate-800">"${a.contenido}"</p>` : ''}
        </div>

        <!-- GUÍA DE ACCIÓN: ¿QUÉ PUEDE HACER USTED CON RELACIÓN A ESTO? -->
        <div class="p-3.5 rounded-2xl bg-gradient-to-r from-emerald-950/40 via-slate-900 to-slate-900 border border-emerald-500/40 space-y-2">
          <div class="flex items-center gap-1.5 font-bold text-emerald-300 text-xs uppercase tracking-wide">
            <i data-lucide="check-circle-2" class="w-4 h-4 text-emerald-400"></i>
            <span>¿Qué Puede Hacer Usted con Relación a Esto? (Guía de Acción Paso a Paso):</span>
          </div>
          <div class="space-y-1.5 pl-1">
            ${guiaPasoPaso}
          </div>
        </div>

        <!-- Botones de Acción Inmediata -->
        <div class="flex flex-wrap items-center justify-between gap-2 pt-2 border-t border-slate-700/60">
          <div class="flex items-center gap-2">
            <button type="button" onclick="radicarPQRDesdeLey('${a.articulo}', '${encodeURIComponent(a.titulo)}', '${encodeURIComponent(a.pregunta)}')" class="px-3.5 py-1.5 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-bold text-xs flex items-center gap-1.5 transition-all shadow-md shadow-emerald-950/40 cursor-pointer" title="Radicar una PQR formal basada en este artículo">
              <i data-lucide="send" class="w-3.5 h-3.5"></i>
              <span>Radicar PQR con este Caso</span>
            </button>
          </div>
          <div class="flex items-center gap-2">
            <button type="button" onclick="copiarResolucionWeb('${a.articulo}')" class="px-3 py-1.5 rounded-xl bg-slate-700/60 hover:bg-slate-700 text-slate-300 hover:text-white font-bold text-xs flex items-center gap-1.5 transition-all">
              <i data-lucide="copy" class="w-3.5 h-3.5"></i>
              <span>Copiar</span>
            </button>
          </div>
        </div>
      </div>
    `;
  }).join("");

  safeCreateIcons();
}

function buscarLey675() {

  const q = document.getElementById("ley-search-input")?.value || "";

  const sub = document.getElementById("ley-subindice-sel")?.value || "Todos";

  const perf = document.getElementById("ley-perfil-sel")?.value || "Todos";

  cargarLey675(q, sub, perf);

}



function buscarLey675Rapido(termino) {

  const input = document.getElementById("ley-search-input");

  const subSel = document.getElementById("ley-subindice-sel");

  const perfSel = document.getElementById("ley-perfil-sel");

  if (input) input.value = termino;

  if (subSel) subSel.value = "Todos";

  if (perfSel) perfSel.value = "Todos";

  cargarLey675(termino, "Todos", "Todos");

}



function copiarResolucionWeb(articuloNum) {

  const art = articulosLey675.find(a => a.articulo == articuloNum);

  if (art) {

    const texto = `LEFACTURAMOS - LEY 675 DE 2001 (Art. ${art.articulo})\nPregunta: ${art.pregunta}\nDictamen: ${art.resolucion}\nFundamento: ${art.titulo}`;

    navigator.clipboard.writeText(texto);

    mostrarToast(`Resolución del Art. ${art.articulo} copiada al portapapeles.`);

  }

}



function compartirWhatsAppWeb(articuloNum) {

  const art = articulosLey675.find(a => a.articulo == articuloNum);

  if (art) {

    const msg = encodeURIComponent(`*CONSULTA JURÍDICA LEY 675 DE 2001 (LEFACTURAMOS PH)*\n\n*Pregunta:* ${art.pregunta}\n\n*Resolución Práctica:* ${art.resolucion}\n\n*Fundamento Legal:* Art. ${art.articulo} (${art.titulo})\n_Plataforma LEFACTURAMOS PH_`);

    window.open(`https://api.whatsapp.com/send?text=${msg}`, "_blank");

    mostrarToast("Abriendo WhatsApp con la resolución jurídica.");

  }

}



const LEY_675_PDF_URL = "https://www.personeriabogota.gov.co/archivos/Ley%20675%20de%202001.pdf";

const LEY_675_LOCAL_URL = "assets/Ley_675_de_2001.pdf";



function descargarLey675PDF() {

  mostrarToast("Descargando PDF Oficial Ley 675 de 2001...");

  try {

    const a = document.createElement("a");

    a.href = LEY_675_LOCAL_URL;

    a.download = "Ley_675_de_2001_Oficial.pdf";

    document.body.appendChild(a);

    a.click();

    document.body.removeChild(a);

  } catch (err) {

    console.warn("Descarga local falló, abriendo enlace oficial:", err);

  }

  // Abrir enlace oficial en nueva pestaña

  window.open(LEY_675_PDF_URL, "_blank");

}



