function cargarGastosAdmin() {

  const cont = document.getElementById("lista-gastos-admin");

  if (!cont) return;

  cont.innerHTML = PAGOS_ADMINISTRACION_DATA.map(g => `

    <div class="p-3.5 rounded-xl bg-slate-800/80 border border-slate-700/60 flex flex-col sm:flex-row sm:items-center justify-between gap-2">

      <div>

        <span class="font-bold text-white text-xs block">${g.empresa}</span>

        <span class="text-[11px] text-slate-300">${g.categoria} • ${g.detalle}</span>

        <span class="text-[10px] text-amber-400 font-semibold block mt-0.5">Garantía: ${g.tieneGarantia ? 'Sí' : 'No'} • Fecha: ${g.fecha}</span>

      </div>

      <div class="text-left sm:text-right font-mono font-bold text-sm text-emerald-400 shrink-0">

        $${g.monto.toLocaleString("es-CO")} COP

      </div>

    </div>

  `).join("");

}



function renderizarModuloPagosAdmin(datos = null) {

  const lista = datos || PAGOS_ADMINISTRACION_DATA;

  const tbody = document.getElementById("tbody-pagos-admin");



  // 1. Calcular KPIs

  let totalPagos = 0;

  let trabajosConGarantia = 0;

  const empresasSet = new Set();



  lista.forEach(p => {

    totalPagos += (p.monto || 0);

    if (p.tieneGarantia) trabajosConGarantia++;

    if (p.empresa) empresasSet.add(p.empresa.trim().toLowerCase());

  });



  const kpiTotal = document.getElementById("kpi-pagos-total");

  const kpiTrans = document.getElementById("kpi-pagos-transacciones");

  const kpiGarantia = document.getElementById("kpi-pagos-garantia");

  const kpiEmpresas = document.getElementById("kpi-pagos-empresas");



  if (kpiTotal) kpiTotal.innerText = `$${totalPagos.toLocaleString("es-CO")}`;

  if (kpiTrans) kpiTrans.innerText = `${lista.length} transacciones registradas`;

  if (kpiGarantia) kpiGarantia.innerText = `${trabajosConGarantia} trabajos`;

  if (kpiEmpresas) kpiEmpresas.innerText = `${empresasSet.size} empresas`;



  // 2. Renderizar Filas de la Tabla

  if (tbody) {

    if (lista.length === 0) {

      tbody.innerHTML = `

        <tr>

          <td colspan="6" class="p-8 text-center text-slate-500 font-medium">

            No se encontraron pagos a proveedores con los filtros seleccionados.

          </td>

        </tr>

      `;

    } else {

      tbody.innerHTML = lista.map(p => {

        const garantiaBadge = p.tieneGarantia ? `

          <div class="p-2.5 rounded-xl bg-emerald-950/40 border border-emerald-800/50 space-y-1">

            <span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-emerald-950 text-emerald-400 border border-emerald-800 font-bold text-[10px]">

              <i data-lucide="check" class="w-3 h-3 text-emerald-400"></i>

              <span>Con Garantía</span>

            </span>

            <p class="text-[11px] text-slate-300 leading-snug">${p.garantiaTexto}</p>

          </div>

        ` : `

          <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-800 space-y-1">

            <span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-slate-800 text-slate-400 border border-slate-700 font-bold text-[10px]">

              <span>Sin Garantía</span>

            </span>

            <p class="text-[11px] text-slate-400 leading-snug">${p.garantiaTexto}</p>

          </div>

        `;



        return `

          <tr class="hover:bg-slate-800/40 transition-colors border-b border-slate-800/60">

            <!-- FECHA -->

            <td class="p-3.5 align-top whitespace-nowrap">

              <div class="flex items-center gap-1.5 font-bold text-white text-xs">

                <i data-lucide="calendar" class="w-3.5 h-3.5 text-slate-400"></i>

                <span>${p.fecha}</span>

              </div>

              <p class="text-[10px] text-slate-400 font-mono mt-1">${p.comprobante} / ${p.factura}</p>

            </td>



            <!-- EMPRESA / PROVEEDOR -->

            <td class="p-3.5 align-top min-w-[200px]">

              <p class="font-bold text-white text-xs leading-snug">${p.empresa}</p>

              <p class="text-[10px] text-slate-400 font-mono mt-0.5">NIT: ${p.nit}</p>

              <span class="inline-block mt-1 px-2 py-0.5 rounded-md bg-slate-800 text-slate-300 text-[10px] font-semibold border border-slate-700">

                ${p.categoria}

              </span>

            </td>



            <!-- DETALLE DEL TRABAJO REALIZADO -->

            <td class="p-3.5 align-top max-w-md">

              <p class="text-xs text-slate-300 leading-relaxed">${p.detalle}</p>

              <div class="flex items-center gap-2 mt-1.5 text-[10px] text-slate-400 font-medium">

                <span>Pago: ${p.metodoPago}</span>

                <span>•</span>

                <span class="flex items-center gap-1 text-emerald-400 font-bold">

                  <span class="w-1.5 h-1.5 rounded-full bg-emerald-400"></span>

                  ${p.estadoPago}

                </span>

              </div>

            </td>



            <!-- GARANTÍA -->

            <td class="p-3.5 align-top max-w-xs">

              ${garantiaBadge}

            </td>



            <!-- MONTO PAGADO -->

            <td class="p-3.5 align-top text-right whitespace-nowrap">

              <span class="text-sm font-black text-white font-mono block">$${p.monto.toLocaleString("es-CO")}</span>

              <span class="text-[10px] text-slate-500 uppercase tracking-wider font-bold">COP</span>

            </td>



            <!-- ACCIONES -->

            <td class="p-3.5 align-top text-center whitespace-nowrap">

              <div class="flex items-center justify-center gap-1.5">

                <button type="button" onclick="verDetallePagoAdmin('${p.id}')" title="Ver Comprobante Digital" class="p-1.5 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-400 hover:text-white transition-colors">

                  <i data-lucide="link-2" class="w-3.5 h-3.5 text-slate-400"></i>

                </button>

                <button type="button" onclick="editarPagoAdmin('${p.id}')" title="Editar Pago" class="p-1.5 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-400 hover:text-white transition-colors">

                  <i data-lucide="edit-3" class="w-3.5 h-3.5 text-amber-400"></i>

                </button>

                <button type="button" onclick="eliminarPagoAdmin('${p.id}')" title="Eliminar Registro" class="p-1.5 rounded-lg bg-slate-800 hover:bg-rose-900/60 text-slate-400 hover:text-rose-300 transition-colors">

                  <i data-lucide="trash-2" class="w-3.5 h-3.5 text-rose-400"></i>

                </button>

              </div>

            </td>

          </tr>

        `;

      }).join("");

    }

  }



  cargarGastosAdmin();

  safeCreateIcons();

}



function filtrarPagosAdmin(query) {

  aplicarFiltrosPagosAdmin();

}



function aplicarFiltrosPagosAdmin() {

  const q = (document.getElementById("pagos-search-input")?.value || "").trim().toLowerCase();

  const cat = document.getElementById("pagos-flt-categoria")?.value || "todas";

  const gar = document.getElementById("pagos-flt-garantia")?.value || "todas";



  let filtrados = PAGOS_ADMINISTRACION_DATA.filter(p => {

    // Filtro de texto

    const matchText = !q || (

      (p.empresa && p.empresa.toLowerCase().includes(q)) ||

      (p.detalle && p.detalle.toLowerCase().includes(q)) ||

      (p.garantiaTexto && p.garantiaTexto.toLowerCase().includes(q)) ||

      (p.comprobante && p.comprobante.toLowerCase().includes(q)) ||

      (p.factura && p.factura.toLowerCase().includes(q)) ||

      (p.nit && p.nit.toLowerCase().includes(q))

    );



    // Filtro de categoría

    const matchCat = (cat === "todas") || (p.categoria === cat);



    // Filtro de garantía

    const matchGar = (gar === "todas") ||

      (gar === "con_garantia" && p.tieneGarantia) ||

      (gar === "sin_garantia" && !p.tieneGarantia);



    return matchText && matchCat && matchGar;

  });



  renderizarModuloPagosAdmin(filtrados);

}



