function toggleGarantiaPago(checked) {

  const container = document.getElementById("contenedor-garantia-input");

  const input = document.getElementById("nuevo-pago-garantia-texto");

  if (container) {

    if (checked) {

      container.classList.remove("opacity-40", "pointer-events-none");

      if (input && !input.value.trim()) {

        input.value = "Garantía técnica de 12 meses sobre mano de obra y repuestos hasta Octubre 2027";

      }

    } else {

      container.classList.add("opacity-40", "pointer-events-none");

    }

  }

}



function seleccionarMetodoRapidoPago(metodo) {

  const select = document.getElementById("nuevo-pago-forma");

  if (select) {

    let found = false;

    for (let i = 0; i < select.options.length; i++) {

      if (select.options[i].value.includes(metodo) || metodo.includes(select.options[i].value.split(" ")[0])) {

        select.selectedIndex = i;

        found = true;

        break;

      }

    }

    if (!found) {

      const opt = document.createElement("option");

      opt.value = metodo;

      opt.text = metodo;

      opt.selected = true;

      select.appendChild(opt);

    }

    mostrarToast(`✓ Medio de pago seleccionado: ${select.value.split(" ")[0]}`);

  }

}



function guardarNuevoPagoAdmin(e) {

  e.preventDefault();

  const empresa = document.getElementById("nuevo-pago-empresa")?.value.trim();

  const nit = document.getElementById("nuevo-pago-nit")?.value.trim() || "NIT Proveedor";

  const categoria = document.getElementById("nuevo-pago-categoria")?.value || "Mantenimiento";

  const fecha = document.getElementById("nuevo-pago-fecha")?.value || new Date().toISOString().split("T")[0];

  const monto = parseInt(document.getElementById("nuevo-pago-monto")?.value) || 0;

  const comprobante = document.getElementById("nuevo-pago-comprobante")?.value.trim() || `CE-2026-000${PAGOS_ADMINISTRACION_DATA.length + 1}`;

  const factura = document.getElementById("nuevo-pago-factura")?.value.trim() || "Factura Oficial";

  const formaPago = document.getElementById("nuevo-pago-forma")?.value || "Transferencia Bancaria";

  const detalle = document.getElementById("nuevo-pago-detalle")?.value.trim();

  const tieneGarantia = document.getElementById("nuevo-pago-tiene-garantia")?.checked ?? true;

  const garantiaTexto = document.getElementById("nuevo-pago-garantia-texto")?.value.trim() || (tieneGarantia ? "Garantía técnica vigente de 12 meses." : "Sin garantía técnica aplicable.");



  if (!empresa || !detalle) {

    mostrarToast("Por favor complete el nombre de la empresa y el detalle del trabajo.", true);

    return;

  }



  const nuevoPago = {

    id: `pago_${Date.now()}`,

    fecha,

    comprobante,

    factura,

    empresa,

    nit,

    categoria,

    detalle,

    metodoPago: formaPago,

    estadoPago: "Pagado",

    tieneGarantia,

    garantiaTexto,

    monto,

    moneda: "COP",

    soporteUrl: "https://drive.google.com/drive/folders/1u1remh8F3vwpk108ZhibqfDhHErBtYBv"

  };



  PAGOS_ADMINISTRACION_DATA.unshift(nuevoPago);

  cerrarModalMontarPagoAdmin();

  renderizarModuloPagosAdmin();

  mostrarToast(`✓ Pago a ${empresa} por $${monto.toLocaleString("es-CO")} registrado y conciliado.`);

}



