// Toast flotante (Modo Oscuro)

function mostrarToast(mensaje, esError = false) {

  const existing = document.getElementById("app-toast");

  if (existing) existing.remove();



  const toast = document.createElement("div");

  toast.id = "app-toast";

  toast.className = `fixed top-20 right-4 z-50 px-4 py-3 rounded-xl shadow-2xl text-xs font-bold text-white transition-all transform duration-300 border ${esError ? "bg-rose-950/95 border-rose-500/50 text-rose-200" : "bg-slate-900/95 border-brand-500/50 text-brand-300"}`;

  toast.innerText = mensaje;

  document.body.appendChild(toast);



  setTimeout(() => {

    toast.style.opacity = "0";

    setTimeout(() => toast.remove(), 300);

  }, 3500);

}



