function obtenerDocumentoManualActivo() {

  return documentoManualActivo === "manual" ? MANUAL_CONVIVENCIA_DATA : REGLAMENTO_PH_DATA;

}



function obtenerMetadataActiva() {

  return documentoManualActivo === "manual" ? legalMetadataManual : legalMetadataReglamento;

}



function cambiarDocumentoManual(tipo) {

  documentoManualActivo = tipo;

  filtroTextoManual = "";

  const inputSearch = document.getElementById("manual-search-input");

  if (inputSearch) inputSearch.value = "";

  renderizarModuloManualReglamento();

  mostrarToast(`Cambiado a: ${tipo === "manual" ? "Manual de Convivencia" : "Reglamento de Propiedad Horizontal"}`);

}



function renderizarModuloManualReglamento() {

  const esManual = (documentoManualActivo === "manual");

  const listaData = obtenerDocumentoManualActivo();

  const meta = obtenerMetadataActiva();



  // 1. Conteo total de artículos

  const totalArtsManual = MANUAL_CONVIVENCIA_DATA.reduce((acc, c) => acc + c.articulos.length, 0);

  const totalArtsReglamento = REGLAMENTO_PH_DATA.reduce((acc, c) => acc + c.articulos.length, 0);

  const totalArtsActivo = listaData.reduce((acc, c) => acc + c.articulos.length, 0);



  // 2. Badges en la barra de pestañas

  const badgeManual = document.getElementById("badge-arts-manual");

  if (badgeManual) badgeManual.innerText = `${totalArtsManual} arts.`;

  const badgeReglamento = document.getElementById("badge-arts-reglamento");

  if (badgeReglamento) badgeReglamento.innerText = `${totalArtsReglamento} arts.`;



  const btnTabManual = document.getElementById("tab-doc-manual");

  const btnTabReglamento = document.getElementById("tab-doc-reglamento");



  if (esManual) {

    if (btnTabManual) {

      btnTabManual.className = "px-4 py-2 rounded-xl bg-emerald-600 text-white font-bold text-xs flex items-center gap-2 shadow-sm transition-all";

    }

    if (btnTabReglamento) {

      btnTabReglamento.className = "px-4 py-2 rounded-xl bg-slate-950 text-slate-400 hover:text-white font-semibold text-xs flex items-center gap-2 border border-slate-800 transition-all";

    }

  } else {

    if (btnTabManual) {

      btnTabManual.className = "px-4 py-2 rounded-xl bg-slate-950 text-slate-400 hover:text-white font-semibold text-xs flex items-center gap-2 border border-slate-800 transition-all";

    }

    if (btnTabReglamento) {

      btnTabReglamento.className = "px-4 py-2 rounded-xl bg-emerald-600 text-white font-bold text-xs flex items-center gap-2 shadow-sm transition-all";

    }

  }



  // 3. Tarjeta resumen del documento activo

  const badgeDoc = document.getElementById("manual-doc-badge");

  if (badgeDoc) {

    badgeDoc.innerText = esManual ? "MANUAL DE CONVIVENCIA" : "REGLAMENTO DE PROPIEDAD HORIZONTAL";

  }

  const tituloDoc = document.getElementById("manual-doc-titulo");

  if (tituloDoc) tituloDoc.innerText = meta.titulo;

  const descDoc = document.getElementById("manual-doc-desc");

  if (descDoc) descDoc.innerText = meta.descripcion;

  const soporteDoc = document.getElementById("manual-doc-soporte");

  if (soporteDoc) {

    soporteDoc.innerText = `Soporte: ${meta.soporte} • Fecha: ${meta.fecha} • Ciudad/Notaría: ${meta.ciudad}`;

  }



  const countCaps = document.getElementById("manual-count-caps");

  if (countCaps) countCaps.innerText = `${listaData.length} Capítulos`;

  const countArts = document.getElementById("manual-count-arts");

  if (countArts) countArts.innerText = `${totalArtsActivo} Artículos redactados`;



  // 4. Poblar selector de capítulos para el modal de nuevo artículo

  const selCap = document.getElementById("nuevo-art-capitulo");

  if (selCap) {

    selCap.innerHTML = listaData.map(c => `<option value="${c.id}">${c.titulo}</option>`).join("");

  }



  // 5. Renderizar Capítulos y Artículos filtrados

  const cont = document.getElementById("contenedor-capitulos-manual");

  if (!cont) return;



  const q = (filtroTextoManual || "").trim().toLowerCase();

  const cat = filtroCategoriaManual || "todas";



  let htmlCaps = "";



  listaData.forEach(cap => {

    // Filtrar artículos dentro del capítulo

    const artsFiltrados = cap.articulos.filter(art => {

      const matchCat = (cat === "todas" || art.categoria === cat);

      if (!matchCat) return false;

      if (!q) return true;

      const haystack = `${art.numero} ${art.titulo} ${art.ley} ${art.texto} ${cap.titulo}`.toLowerCase();

      return haystack.includes(q);

    });



    // Si hay búsqueda y no hay artículos que coincidan, ocultar capítulo

    if (q && artsFiltrados.length === 0) return;



    const estaAbierto = (cap.abierto !== false);



    htmlCaps += `

      <div class="bg-slate-900 border border-slate-800 rounded-2xl overflow-hidden shadow-lg transition-all">

        <!-- Encabezado del Capítulo Clickable -->

        <div onclick="toggleCapituloManual('${cap.id}')" class="p-4 sm:p-5 flex items-center justify-between gap-3 cursor-pointer select-none hover:bg-slate-800/40 transition-colors">

          <div class="flex items-center gap-3.5">

            <div class="w-8 h-8 rounded-full bg-emerald-950 border border-emerald-500/40 text-emerald-400 font-black text-xs flex items-center justify-center shrink-0 shadow-sm">

              ${cap.num}

            </div>

            <div>

              <h4 class="text-sm sm:text-base font-extrabold text-white tracking-tight">${cap.titulo}</h4>

              <p class="text-xs text-slate-400">${cap.descripcion}</p>

            </div>

          </div>

          <div class="flex items-center gap-3 shrink-0">

            <span class="text-xs font-semibold text-slate-400 hidden sm:inline">${artsFiltrados.length} artículos</span>

            <button type="button" onclick="event.stopPropagation(); abrirModalNuevoArticulo('${cap.id}')" class="px-2.5 py-1 rounded-lg bg-emerald-950/60 hover:bg-emerald-900/80 text-emerald-300 border border-emerald-800/80 text-xs font-bold flex items-center gap-1 transition-all">

              <i data-lucide="plus" class="w-3.5 h-3.5"></i>

              <span>+ Artículo</span>

            </button>

            <div class="w-6 h-6 rounded-lg bg-slate-800 flex items-center justify-center text-slate-400">

              <i data-lucide="${estaAbierto ? 'chevron-up' : 'chevron-down'}" class="w-4 h-4"></i>

            </div>

          </div>

        </div>



        <!-- Artículos del Capítulo -->

        ${estaAbierto ? `

          <div class="border-t border-slate-800 divide-y divide-slate-800/60 bg-slate-950/40">

            ${artsFiltrados.length === 0 ? `

              <div class="p-4 text-center text-xs text-slate-500">No hay artículos que coincidan con el filtro en este capítulo.</div>

            ` : artsFiltrados.map(art => `

              <div class="p-4 sm:p-5 hover:bg-slate-800/20 transition-colors space-y-2">

                <div class="flex items-center justify-between gap-2 flex-wrap">

                  <div class="flex items-center gap-2 flex-wrap">

                    <span class="text-xs sm:text-sm font-extrabold text-white tracking-tight">${art.numero}. ${art.titulo}</span>

                    ${art.ley ? `<span class="px-2.5 py-0.5 rounded-full bg-emerald-950 text-emerald-400 border border-emerald-800 text-[10px] font-bold">${art.ley}</span>` : ''}

                    ${art.categoria ? `<span class="px-2.5 py-0.5 rounded-full bg-slate-800 text-slate-400 border border-slate-700 text-[10px] font-medium">${art.categoria}</span>` : ''}

                  </div>

                  <div class="flex items-center gap-1 text-slate-400">

                    <button type="button" onclick="editarArticuloManual('${cap.id}', ${art.id})" class="p-1 hover:text-amber-400 rounded-lg hover:bg-slate-800 transition-colors" title="Editar artículo">

                      <i data-lucide="edit-2" class="w-3.5 h-3.5"></i>

                    </button>

                    <button type="button" onclick="eliminarArticuloManual('${cap.id}', ${art.id})" class="p-1 hover:text-rose-400 rounded-lg hover:bg-slate-800 transition-colors" title="Eliminar artículo">

                      <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>

                    </button>

                  </div>

                </div>

                <p class="text-xs text-slate-300 leading-relaxed font-normal">${art.texto}</p>

              </div>

            `).join('')}

          </div>

        ` : ''}

      </div>

    `;

  });



  if (!htmlCaps) {

    htmlCaps = `

      <div class="p-8 text-center bg-slate-900 border border-slate-800 rounded-2xl space-y-2">

        <i data-lucide="search-x" class="w-8 h-8 text-slate-500 mx-auto"></i>

        <p class="text-sm font-bold text-white">No se encontraron artículos</p>

        <p class="text-xs text-slate-400">Intenta con otros términos como 'ruido', 'mascotas', 'trasteo' o restablece los filtros.</p>

      </div>

    `;

  }



  cont.innerHTML = htmlCaps;

  safeCreateIcons();

}



