function abrirModalNuevoArticulo(capId = null) {

  const listaData = obtenerDocumentoManualActivo();

  const selCap = document.getElementById("nuevo-art-capitulo");

  if (selCap) {

    selCap.innerHTML = listaData.map(c => `<option value="${c.id}">${c.titulo}</option>`).join("");

    if (capId) selCap.value = capId;

  }

  const modal = document.getElementById("modal-nuevo-articulo");

  if (modal) {

    modal.classList.remove("hidden");

    safeCreateIcons();

  }

}



function cerrarModalNuevoArticulo() {

  document.getElementById("modal-nuevo-articulo")?.classList.add("hidden");

}



function guardarNuevoArticulo(e) {

  e.preventDefault();

  const listaData = obtenerDocumentoManualActivo();

  const capId = document.getElementById("nuevo-art-capitulo")?.value;

  const tituloCompleto = document.getElementById("nuevo-art-titulo")?.value || "";

  const ley = document.getElementById("nuevo-art-ley")?.value || "Ley 675 de 2001";

  const categoria = document.getElementById("nuevo-art-categoria")?.value || "General";

  const texto = document.getElementById("nuevo-art-texto")?.value || "";



  const cap = listaData.find(c => c.id === capId) || listaData[0];

  if (!cap) return;



  const totalArticulosActual = listaData.reduce((acc, c) => acc + c.articulos.length, 0);

  const nuevoNum = `Artículo ${totalArticulosActual + 1}º`;



  let numStr = nuevoNum;

  let titStr = tituloCompleto;

  if (tituloCompleto.includes(".")) {

    const parts = tituloCompleto.split(".");

    numStr = parts[0].trim();

    titStr = parts.slice(1).join(".").trim();

  }



  cap.articulos.push({

    id: Date.now(),

    numero: numStr,

    titulo: titStr,

    ley: ley,

    categoria: categoria,

    texto: texto

  });

  cap.abierto = true;



  cerrarModalNuevoArticulo();

  renderizarModuloManualReglamento();

  mostrarToast("✅ Artículo normativo añadido y guardado con éxito.");

}



