function guardarTextoPegadoManual(e) {

  e.preventDefault();

  const tipoDoc = document.getElementById("pegar-texto-tipo-doc")?.value || "manual";

  const texto = document.getElementById("pegar-texto-contenido")?.value || "";



  if (!texto.trim()) {

    mostrarToast("⚠️ Ingrese texto para procesar.");

    return;

  }



  const listaData = tipoDoc === "manual" ? MANUAL_CONVIVENCIA_DATA : REGLAMENTO_PH_DATA;

  const ultimoCap = listaData[listaData.length - 1];



  if (ultimoCap) {

    ultimoCap.articulos.push({

      id: Date.now(),

      numero: `Artículo ${listaData.reduce((acc, c) => acc + c.articulos.length, 0) + 1}º`,

      titulo: "Disposición Anexa",

      ley: "Ley 675 de 2001",

      categoria: "General",

      texto: texto.slice(0, 300) + (texto.length > 300 ? "..." : "")

    });

  }



  cerrarModalPegarTextoManual();

  cambiarDocumentoManual(tipoDoc);

  mostrarToast("✅ Texto oficial procesado e incorporado correctamente.");

}



