function generarPDFManualEdificio() {

  const meta = obtenerMetadataActiva();

  const listaData = obtenerDocumentoManualActivo();



  const cAct = (typeof obtenerDatosCopropiedad === "function") ? obtenerDatosCopropiedad(AppState.codigoEdificio) : listaCopropiedadesSuperadmin.find(c => c.codigo === AppState.codigoEdificio);

  const nomEdif = cAct ? cAct.nombre : "EDIFICIO ROBLE ALTO P.H.";

  const nitEdif = cAct ? cAct.nit : "901690778-9";

  const dirEdif = cAct ? (cAct.direccion + ", " + cAct.ciudad) : "DG 79A No 76-250/252/254/256, Medellín";

  const admEdif = cAct ? (cAct.administrador || "Administración") : "Administración";



  let contenido = `================================================================================

${meta.titulo.toUpperCase()}

${nomEdif.toUpperCase()}

NIT: ${nitEdif} • ${dirEdif}

Régimen Legal: Ley 675 de 2001

================================================================================

EDICIÓN: ${meta.edicion}

SOPORTE LEGAL: ${meta.soporte}

FECHA DE APROBACIÓN: ${meta.fecha}

CIUDAD/NOTARÍA: ${meta.ciudad}

ADMINISTRACIÓN: ${admEdif} • LEFACTURAMOS COLOMBIA

================================================================================



OBJETO Y ÁMBITO:

${meta.descripcion}



`;



  listaData.forEach(cap => {

    contenido += `\n--------------------------------------------------------------------------------\n`;

    contenido += `${cap.titulo.toUpperCase()}\n`;

    contenido += `${cap.descripcion}\n`;

    contenido += `--------------------------------------------------------------------------------\n\n`;



    cap.articulos.forEach(art => {

      contenido += `${art.numero}. ${art.titulo} [${art.ley} • ${art.categoria}]\n`;

      contenido += `${art.texto}\n\n`;

    });

  });



  contenido += `================================================================================\n`;

  contenido += `Documento Registrado en la Secretaría Distrital del Hábitat y Notaría PH.\n`;

  contenido += `Generado el ${new Date().toLocaleDateString('es-CO')} mediante Lefacturamos Platform.\n`;



  const nombreArchivo = `${meta.tipo === 'manual' ? 'Manual_Convivencia' : 'Reglamento_PH'}_Torres_del_Parque_2026.txt`;

  const blob = new Blob([contenido], { type: "text/plain;charset=utf-8" });

  const url = URL.createObjectURL(blob);

  const link = document.createElement("a");

  link.setAttribute("href", url);

  link.setAttribute("download", nombreArchivo);

  document.body.appendChild(link);

  link.click();

  document.body.removeChild(link);



  mostrarToast(`📥 Descargando ${meta.titulo} Oficial.`);

}



function restablecerManualEdificio() {

  mostrarToast("🔄 Documento restablecido a los 8 capítulos y 22 artículos oficiales.");

  filtroTextoManual = "";

  filtroCategoriaManual = "todas";

  const inputSearch = document.getElementById("manual-search-input");

  if (inputSearch) inputSearch.value = "";

  const selCat = document.getElementById("manual-flt-categoria");

  if (selCat) selCat.value = "todas";

  renderizarModuloManualReglamento();

}



function eliminarArticuloManual(capId, artId) {

  const listaData = obtenerDocumentoManualActivo();

  const cap = listaData.find(c => c.id === capId);

  if (!cap) return;

  cap.articulos = cap.articulos.filter(a => a.id !== artId);

  renderizarModuloManualReglamento();

  mostrarToast("🗑️ Artículo eliminado del documento.");

}



function editarArticuloManual(capId, artId) {

  const listaData = obtenerDocumentoManualActivo();

  const cap = listaData.find(c => c.id === capId);

  if (!cap) return;

  const art = cap.articulos.find(a => a.id === artId);

  if (!art) return;



  const nuevoTexto = prompt(`Editar contenido de: ${art.numero}. ${art.titulo}`, art.texto);

  if (nuevoTexto !== null && nuevoTexto.trim()) {

    art.texto = nuevoTexto.trim();

    renderizarModuloManualReglamento();

    mostrarToast("✅ Artículo actualizado correctamente.");

  }

}



