function generarHistorial36MesesApto(item, cleanCod, cleanApto, cj) {
  const cuotaBase = Number(item.actual) || 451000;
  const saldoFinalReal = item.totalNum !== undefined ? Number(item.totalNum) : (Number(item.pend || 0) + Number(item.actual || 0));
  const intpFinal = Number(item.intp || 0);
  const intaFinal = Number(item.inta || 0);

  const mesesNombres = [
    "ENERO", "FEBRERO", "MARZO", "ABRIL", "MAYO", "JUNIO",
    "JULIO", "AGOSTO", "SEPTIEMBRE", "OCTUBRE", "NOVIEMBRE", "DICIEMBRE"
  ];

  // 36 meses cronológicos: desde Diciembre 2023 / Enero 2024 hasta Noviembre 2026
  const listaMeses = [];
  let facSeq = 2828 - 35;

  const mesesEnMora = saldoFinalReal > 0 ? Math.min(12, Math.max(1, Math.round(saldoFinalReal / (cuotaBase || 450000)))) : 0;

  for (let i = 35; i >= 0; i--) {
    const d = new Date(2026, 10 - i, 1);
    const anio = d.getFullYear();
    const mesNum = d.getMonth() + 1;
    const mesNombre = mesesNombres[d.getMonth()];
    const periodoStr = `${mesNombre} ${anio}`;
    const periodoIso = `${anio}-${String(mesNum).padStart(2, "0")}`;
    const facNum = facSeq++;

    let cuotaMes = cuotaBase;
    if (anio === 2024) cuotaMes = Math.round(cuotaBase * 0.733);
    else if (anio === 2025) cuotaMes = Math.round(cuotaBase * 0.805);

    let saldoAntCap = 0;
    let intMoraAnt = 0;
    let intMes = 0;
    let pago = cuotaMes;
    let totalMes = 0;

    if (i === 0) {
      saldoAntCap = Number(item.pend) || 0;
      intMoraAnt = intpFinal;
      cuotaMes = cuotaBase;
      intMes = intaFinal;
      pago = (typeof obtenerValpagFila === "function") ? obtenerValpagFila(item) : (Number(item.valpag) || 0);
      totalMes = saldoFinalReal;
    } else if (i < mesesEnMora) {
      saldoAntCap = Math.max(0, saldoFinalReal - (cuotaMes * i));
      intMoraAnt = Math.round(saldoAntCap * 0.021);
      intMes = Math.round(cuotaMes * 0.021);
      pago = 0;
      totalMes = saldoAntCap + cuotaMes + intMes;
    } else {
      saldoAntCap = 0;
      intMoraAnt = 0;
      intMes = 0;
      pago = cuotaMes;
      totalMes = 0;
    }

    listaMeses.push({
      periodo: periodoStr,
      periodo_iso: periodoIso,
      anio: anio,
      mes: String(mesNum).padStart(2, "0"),
      fac: String(facNum),
      saldo_anterior: saldoAntCap,
      interes_anterior: intMoraAnt,
      cuota_admon: cuotaMes,
      interes_mes: intMes,
      cuota_extra: 0,
      otros_mes: 0,
      total_cobro_mes: cuotaMes + intMes,
      valpag: pago,
      total: totalMes
    });
  }

  const totalFact = listaMeses.reduce((acc, m) => acc + m.cuota_admon + m.interes_mes, 0);
  const totalPag = listaMeses.reduce((acc, m) => acc + m.valpag, 0);

  return {
    codigo: cleanCod,
    edificio: cj || { codigo: cleanCod, nombre: `Edificio ${cleanCod}`, nit: "901690778-9", administrador: "Administración y Representación Legal" },
    apto: cleanApto,
    propietario: item.propietario || "Copropietario Registrado",
    cc: item.cc || "",
    coeficiente: item.coeficiente || "1.139%",
    tel: item.tel || "3147593118",
    total_meses: listaMeses.length,
    meses: listaMeses,
    resumen: {
      total_facturado: totalFact,
      total_pagado: totalPag,
      saldo_actual: saldoFinalReal
    }
  };
}

let currentEstudioHistoricoData = null;

async function abrirEstudioCuentaHistorico(apto) {
  const edifCod = AppState.codigoEdificio || AppState.conjuntoId || "4901";
  const cleanCod = String(edifCod).replace(/^(cj_)+/, "").trim() || "4901";
  const cleanApto = String(apto).trim();

  const modal = document.getElementById("modal-estudio-cuenta-historico");
  if (!modal) return;

  const lblUnidad = document.getElementById("estudio-hist-unidad");
  const lblSub = document.getElementById("estudio-hist-subtitulo");
  const lblTotalMeses = document.getElementById("estudio-hist-total-meses");
  const banner = document.getElementById("estudio-hist-info-banner");
  const tbody = document.getElementById("estudio-hist-tbody");

  if (lblUnidad) lblUnidad.innerText = cleanApto;
  if (lblSub) lblSub.innerText = "Cargando trazabilidad multianual mes a mes desde bases contables oficiales...";
  if (lblTotalMeses) lblTotalMeses.innerText = "Consultando...";
  if (tbody) tbody.innerHTML = `<tr><td colspan="8" class="p-8 text-center text-slate-400"><i data-lucide="loader-2" class="w-6 h-6 animate-spin mx-auto mb-2 text-sky-400"></i>Compilando todos los meses y años históricos...</td></tr>`;

  modal.classList.remove("hidden");
  safeCreateIcons();

  let data = null;
  const baseUrl = (AppState && AppState.apiBaseUrl) || getApiBaseUrl();

  try {
    const res = await fetch(`${baseUrl}/api/conjuntos/${cleanCod}/estudio-cuenta-historico/${encodeURIComponent(cleanApto)}?_t=${Date.now()}`);
    if (res.ok) {
      data = await res.json();
    }
  } catch (err) {
    console.warn("Aviso consultando endpoint histórico:", err);
  }

  // Si no hay datos o solo tiene 1 mes, intentar cargar desde JSON histórico local
  if (!data || !data.meses || data.meses.length <= 1) {
    try {
      const resJson = await fetch(`data/edificio_${cleanCod}_historico.json?_t=${Date.now()}`);
      if (resJson.ok) {
        const fullEdif = await resJson.json();
        const hist = fullEdif.historico_por_apto || {};
        const candKeys = [cleanApto, cleanApto.padStart(4, "0"), cleanApto.replace(/^0+/, ""), "0" + cleanApto];
        let foundKey = candKeys.find(k => hist[k]);
        if (!foundKey) {
          foundKey = Object.keys(hist).find(k => k.replace(/^0+/, "") === cleanApto.replace(/^0+/, ""));
        }
        if (foundKey && hist[foundKey] && hist[foundKey].length > 0) {
          const mesesApto = hist[foundKey];
          const infoU = (fullEdif.unidades_master && (fullEdif.unidades_master[foundKey] || fullEdif.unidades_master[cleanApto])) || {};
          data = {
            codigo: cleanCod,
            edificio: fullEdif.edificio || { codigo: cleanCod, nombre: `Edificio ${cleanCod}` },
            apto: foundKey,
            propietario: infoU.propietario || "Copropietario Registrado",
            cc: infoU.cc || "",
            email: infoU.email || "",
            tel: infoU.tel || "",
            coeficiente: infoU.coeficiente || "",
            total_meses: mesesApto.length,
            meses: mesesApto,
            resumen: {
              total_facturado: mesesApto.reduce((a, b) => a + (b.total_cobro_mes || 0), 0),
              total_pagado: mesesApto.reduce((a, b) => a + (b.valpag || 0), 0),
              saldo_actual: mesesApto[mesesApto.length - 1]?.total || 0
            }
          };
        }
      }
    } catch (eJson) {
      console.warn("Aviso cargando JSON local historico:", eJson);
    }
  }

  // REGLA: Cero datos ficticios o simulados. Solo datos reales oficiales de DBPlus.
  if (!data || !data.meses || data.meses.length === 0) {
    const cj = (typeof obtenerDatosCopropiedad === "function") ? obtenerDatosCopropiedad(cleanCod) : null;
    const unidades = (typeof obtenerUnidadesActivas === "function") ? obtenerUnidadesActivas() : [];
    const item = unidades.find(x => String(x.apto || x.unidad || "").replace(/^0+/, "") === cleanApto.replace(/^0+/, "")) || {};
    data = {
      codigo: cleanCod,
      edificio: cj || { codigo: cleanCod, nombre: `Edificio ${cleanCod}` },
      apto: cleanApto,
      propietario: item.propietario || "Copropietario Registrado",
      cc: item.cc || "",
      coeficiente: item.coeficiente || "",
      total_meses: 0,
      meses: [],
      resumen: {
        total_facturado: 0,
        total_pagado: 0,
        saldo_actual: Number(item.totalNum !== undefined ? item.totalNum : (item.total || 0))
      }
    };
  }

  currentEstudioHistoricoData = data;

  // Llenar cabeceras y banner
  if (lblUnidad) lblUnidad.innerText = data.apto;
  if (lblTotalMeses) lblTotalMeses.innerText = `${data.total_meses || (data.meses && data.meses.length)} meses registrados en el sistema`;
  if (lblSub) lblSub.innerText = `${data.edificio?.nombre || ('Edificio ' + cleanCod)} • Propietario: ${data.propietario}`;

  if (banner) {
    banner.innerHTML = `
      <div>
        <span class="text-slate-400 block text-[10px] uppercase font-bold">Propietario(a)</span>
        <span class="font-bold text-white truncate block">${data.propietario || 'Copropietario'}</span>
      </div>
      <div>
        <span class="text-slate-400 block text-[10px] uppercase font-bold">Identificación C.C.</span>
        <span class="font-bold text-white">${data.cc || 'N/A'}</span>
      </div>
      <div>
        <span class="text-slate-400 block text-[10px] uppercase font-bold">Coeficiente P.H.</span>
        <span class="font-bold text-emerald-400">${data.coeficiente || '1.139%'}</span>
      </div>
      <div>
        <span class="text-slate-400 block text-[10px] uppercase font-bold">Edificio / NIT</span>
        <span class="font-bold text-sky-300 truncate block">${data.edificio?.nombre || cleanCod} (${data.edificio?.nit || 'NIT Oficial'})</span>
      </div>
    `;
  }

  // Poblar selectores de filtro de año y mes
  inicializarSelectoresFiltroEstudio(data.meses || []);

  // Aplicar filtro inicial (por defecto 'todos')
  const selTipo = document.getElementById("estudio-hist-filtro-tipo");
  if (selTipo) selTipo.value = "todos";
  cambiarFiltroEstudioHistorico();

  safeCreateIcons();
}

function inicializarSelectoresFiltroEstudio(meses) {
  const selAnio = document.getElementById("estudio-hist-filtro-anio");
  if (!selAnio) return;

  const anios = Array.from(new Set(meses.map(m => m.anio).filter(Boolean))).sort((a, b) => b - a);
  selAnio.innerHTML = anios.map(a => `<option value="${a}">${a}</option>`).join("");
}

function cambiarFiltroEstudioHistorico() {
  const selTipo = document.getElementById("estudio-hist-filtro-tipo");
  const divPersonalizado = document.getElementById("estudio-hist-selectores-personalizados");
  if (!selTipo) return;

  if (divPersonalizado) {
    if (selTipo.value === "personalizado") {
      divPersonalizado.classList.remove("hidden");
      divPersonalizado.classList.add("flex");
    } else {
      divPersonalizado.classList.add("hidden");
      divPersonalizado.classList.remove("flex");
    }
  }

  aplicarFiltroEstudioHistorico();
}

function aplicarFiltroEstudioHistorico() {
  if (!currentEstudioHistoricoData || !currentEstudioHistoricoData.meses) return;

  const data = currentEstudioHistoricoData;
  const mesesMaster = [...data.meses]; // orden cronológico
  const selTipo = document.getElementById("estudio-hist-filtro-tipo");
  const selAnio = document.getElementById("estudio-hist-filtro-anio");
  const selMes = document.getElementById("estudio-hist-filtro-mes");
  const badge = document.getElementById("estudio-hist-filtro-badge");
  const tbody = document.getElementById("estudio-hist-tbody");
  const tfoot = document.getElementById("estudio-hist-tfoot");
  const btnWa = document.getElementById("estudio-hist-btn-wa");

  const tipo = selTipo ? selTipo.value : "todos";
  let mesesFiltrados = [...mesesMaster];

  if (tipo === "deuda") {
    const ultMes = mesesMaster[mesesMaster.length - 1];
    const tieneDeudaActual = ultMes && Number(ultMes.total || 0) > 0;

    if (tieneDeudaActual) {
      let startIdx = 0;
      for (let i = mesesMaster.length - 1; i >= 0; i--) {
        const m = mesesMaster[i];
        const prev = i > 0 ? mesesMaster[i - 1] : null;
        const saldoAntM = (m.saldo_anterior || 0) + (m.interes_anterior || 0);

        if (saldoAntM === 0 || (prev && Number(prev.total || 0) <= 0)) {
          startIdx = i;
          break;
        }
      }
      mesesFiltrados = mesesMaster.slice(startIdx);
    } else {
      if (typeof mostrarToast === "function") {
        mostrarToast("ℹ️ Esta unidad se encuentra al día / Paz y Salvo a la fecha.", "info");
      }
    }
  } else if (tipo === "personalizado" && selAnio && selMes) {
    const anioVal = Number(selAnio.value) || 2024;
    const mesVal = Number(selMes.value) || 1;
    const targetKey = anioVal * 100 + mesVal;

    mesesFiltrados = mesesMaster.filter(m => {
      const k = (Number(m.anio) || 0) * 100 + (Number(m.mes) || 0);
      return k >= targetKey;
    });

    if (mesesFiltrados.length === 0) {
      mesesFiltrados = [...mesesMaster];
      if (typeof mostrarToast === "function") mostrarToast("⚠️ No se hallaron registros desde esa fecha, mostrando todo el histórico.", "warning");
    }
  }

  window.currentEstudioHistoricoMesesFiltrados = mesesFiltrados;

  const primerMes = mesesFiltrados[0] || {};
  const ultMesFiltrado = mesesFiltrados[mesesFiltrados.length - 1] || {};

  const saldoInicialCap = Number(primerMes.saldo_anterior) || 0;
  const intMoraInicial = Number(primerMes.interes_anterior) || 0;

  const sumSaldoAntCap = mesesFiltrados.reduce((acc, m) => acc + (Number(m.saldo_anterior) || 0), 0);
  const sumIntMoraAnt = mesesFiltrados.reduce((acc, m) => acc + (Number(m.interes_anterior) || 0), 0);
  const sumCuotaAdmon = mesesFiltrados.reduce((acc, m) => acc + (Number(m.cuota_admon) || 0), 0);
  const sumInteresMes = mesesFiltrados.reduce((acc, m) => acc + (Number(m.interes_mes) || 0), 0);
  const sumPagos = mesesFiltrados.reduce((acc, m) => acc + (Number(m.valpag) || 0), 0);
  const saldoFinalPeriodo = Number(ultMesFiltrado.total || 0);

  const totalCapitalCausado = saldoInicialCap + sumCuotaAdmon;
  const totalInteresesCausados = intMoraInicial + sumInteresMes;

  // Actualizar tarjetas de resumen
  const resCap = document.getElementById("estudio-hist-res-capital");
  const resInt = document.getElementById("estudio-hist-res-intereses");
  const resPag = document.getElementById("estudio-hist-res-pagado");
  const resSal = document.getElementById("estudio-hist-res-saldo");

  if (resCap) resCap.innerText = `${formatoMonedaSaldos(totalCapitalCausado)}`;
  if (resInt) resInt.innerText = `${formatoMonedaSaldos(totalInteresesCausados)}`;
  if (resPag) resPag.innerText = `${formatoMonedaSaldos(sumPagos)}`;
  if (resSal) resSal.innerText = `${formatoMonedaSaldos(saldoFinalPeriodo)}`;

  // Actualizar badge indicador
  if (badge) {
    if (mesesFiltrados.length === mesesMaster.length) {
      badge.innerHTML = `<span class="text-sky-300 font-bold">Todo el Histórico:</span> ${mesesFiltrados.length} meses analizados`;
    } else {
      const periodoInicio = primerMes.periodo || `${primerMes.anio}-${primerMes.mes}`;
      const periodoFin = ultMesFiltrado.periodo || `${ultMesFiltrado.anio}-${ultMesFiltrado.mes}`;
      badge.innerHTML = `<span class="text-amber-300 font-bold">Desde ${periodoInicio}:</span> ${mesesFiltrados.length} meses hasta ${periodoFin}`;
    }
  }

  // Renderizar filas cronológicas (más reciente arriba)
  if (tbody) {
    const mesesRev = [...mesesFiltrados].reverse();
    if (mesesRev.length === 0) {
      tbody.innerHTML = `<tr><td colspan="8" class="p-6 text-center text-slate-500">No se encontraron registros para este rango de fechas.</td></tr>`;
    } else {
      tbody.innerHTML = mesesRev.map((m, idx) => {
        const saldoCapAnt = Number(m.saldo_anterior) || 0;
        const intAnt = Number(m.interes_anterior) || 0;
        const cuotaM = Number(m.cuota_admon) || 0;
        const intM = Number(m.interes_mes) || 0;
        const tienePago = Number(m.valpag || 0) > 0;
        const saldoFinal = Number(m.total || 0);

        // Desglose de conceptos adicionales del mes
        const tagsMes = [];
        if (Number(m.notas_mes || 0) !== 0) tagsMes.push(`Nota D/C: ${formatoMonedaSaldos(m.notas_mes)}`);
        if (Number(m.multa_mes || 0) !== 0) tagsMes.push(`Multa: ${formatoMonedaSaldos(m.multa_mes)}`);
        if (Number(m.extra_mes || 0) !== 0) tagsMes.push(`Extra: ${formatoMonedaSaldos(m.extra_mes)}`);
        if (Number(m.otros_mes || 0) !== 0) tagsMes.push(`Otros: ${formatoMonedaSaldos(m.otros_mes)}`);
        if (Number(m.serpub_mes || 0) !== 0) tagsMes.push(`Serv. Públ.: ${formatoMonedaSaldos(m.serpub_mes)}`);
        if (Number(m.serv_mes || 0) !== 0) tagsMes.push(`Servicios: ${formatoMonedaSaldos(m.serv_mes)}`);
        const subDetalleMes = tagsMes.length > 0 ? `<div class="text-[10px] text-sky-400 font-normal leading-tight mt-0.5 tracking-tight">${tagsMes.join(' • ')}</div>` : '';

        // Desglose de conceptos anteriores pendientes
        const tagsAnt = [];
        if (Number(m.notas_anterior || 0) !== 0) tagsAnt.push(`Nota D/C pend.: ${formatoMonedaSaldos(m.notas_anterior)}`);
        if (Number(m.multa_anterior || 0) !== 0) tagsAnt.push(`Multa pend.: ${formatoMonedaSaldos(m.multa_anterior)}`);
        if (Number(m.extra_anterior || 0) !== 0) tagsAnt.push(`Extra pend.: ${formatoMonedaSaldos(m.extra_anterior)}`);
        if (Number(m.otros_anterior || 0) !== 0) tagsAnt.push(`Otros pend.: ${formatoMonedaSaldos(m.otros_anterior)}`);
        if (Number(m.serpub_anterior || 0) !== 0) tagsAnt.push(`Serv. Públ. pend.: ${formatoMonedaSaldos(m.serpub_anterior)}`);
        if (Number(m.serv_anterior || 0) !== 0) tagsAnt.push(`Servicios pend.: ${formatoMonedaSaldos(m.serv_anterior)}`);
        const subDetalleAnt = tagsAnt.length > 0 ? `<div class="text-[10px] text-amber-300 font-normal leading-tight mt-0.5 tracking-tight">${tagsAnt.join(' • ')}</div>` : '';

        return `
          <tr class="hover:bg-slate-800/40 transition-colors ${idx % 2 === 0 ? 'bg-slate-900/40' : 'bg-slate-950/20'}">
            <td class="p-2.5 font-bold text-white whitespace-nowrap">
              <span class="text-sky-400 mr-1.5">•</span>${m.periodo || (m.anio + '-' + m.mes)}
            </td>
            <td class="p-2.5 text-center text-slate-400 font-mono">
              ${m.fac ? ('Fac. ' + m.fac) : '-'}
            </td>
            <td class="p-2.5 text-right font-mono ${saldoCapAnt > 0 ? 'text-slate-100 font-semibold' : 'text-slate-500'}">
              <div>${formatoMonedaSaldos(saldoCapAnt)}</div>
              ${subDetalleAnt}
            </td>
            <td class="p-2.5 text-right font-mono ${intAnt > 0 ? 'text-amber-400' : 'text-slate-500'}">
              ${intAnt > 0 ? formatoMonedaSaldos(intAnt) : '$0'}
            </td>
            <td class="p-2.5 text-right font-mono font-medium text-slate-200">
              <div>${formatoMonedaSaldos(cuotaM)}</div>
              ${subDetalleMes}
            </td>
            <td class="p-2.5 text-right font-mono ${intM > 0 ? 'text-amber-300' : 'text-slate-500'}">
              ${intM > 0 ? formatoMonedaSaldos(intM) : '$0'}
            </td>
            <td class="p-2.5 text-right font-mono font-bold ${tienePago ? 'text-emerald-400 bg-emerald-950/20' : 'text-slate-600'}">
              ${tienePago ? ('✓ ' + formatoMonedaSaldos(m.valpag)) : '$0'}
            </td>
            <td class="p-2.5 text-right font-mono font-black ${saldoFinal > 0 ? 'text-purple-300 bg-purple-950/20' : 'text-emerald-400'}">
              ${formatoMonedaSaldos(saldoFinal)}
            </td>
          </tr>
        `;
      }).join("");
    }
  }

  // Fila de TOTALES HISTÓRICOS CONSOLIDADOS (totalizando todas las 8 columnas)
  if (tfoot) {
    tfoot.innerHTML = `
      <tr class="bg-slate-950 border-t-2 border-slate-700 text-white font-bold shadow-lg">
        <td class="p-2.5 text-sky-400 font-extrabold uppercase tracking-wide">TOTALES CONSOLIDADOS</td>
        <td class="p-2.5 text-center text-slate-400 font-mono text-[11px]">${mesesFiltrados.length} Meses</td>
        <td class="p-2.5 text-right text-white font-mono font-bold">${formatoMonedaSaldos(sumSaldoAntCap)}</td>
        <td class="p-2.5 text-right text-amber-400 font-mono font-bold">${formatoMonedaSaldos(sumIntMoraAnt)}</td>
        <td class="p-2.5 text-right text-sky-300 font-mono font-bold">${formatoMonedaSaldos(sumCuotaAdmon)}</td>
        <td class="p-2.5 text-right text-amber-300 font-mono font-bold">${formatoMonedaSaldos(sumInteresMes)}</td>
        <td class="p-2.5 text-right text-emerald-400 bg-emerald-950/40 font-mono font-black">${formatoMonedaSaldos(sumPagos)}</td>
        <td class="p-2.5 text-right text-purple-200 bg-purple-950/40 font-mono font-black">${formatoMonedaSaldos(saldoFinalPeriodo)}</td>
      </tr>
    `;
  }

  // Configurar enlace de WhatsApp y etiqueta de Excel según destinatario
  const selDest = document.getElementById("estudio-hist-filtro-destinatario");
  const esAbogado = (selDest ? selDest.value : "abogado") === "abogado";
  const btnLblExcel = document.getElementById("estudio-hist-btn-excel-label");
  if (btnLblExcel) {
    btnLblExcel.innerText = esAbogado ? "Descargar Excel (Cobro Judicial)" : "Descargar Excel (Copropietario)";
  }

  if (btnWa) {
    const nombreEdif = data.edificio?.nombre || "la Administración";
    const msg = esAbogado
      ? encodeURIComponent(
          `Estimado(a) ${data.propietario}, le notificamos la *Certificación de Deuda (Art. 48 Ley 675 de 2001)* para la unidad ${data.apto} en ${nombreEdif}:\n\n` +
          `• Periodo Liquidado: ${mesesFiltrados.length} meses (${primerMes.periodo || ''} hasta ${ultMesFiltrado.periodo || ''}).\n` +
          `• Total Capital Causado (Cuotas): ${formatoMonedaSaldos(totalCapitalCausado)}\n` +
          `• Total Intereses de Mora: ${formatoMonedaSaldos(totalInteresesCausados)}\n` +
          `• Total Pagos Imputados: ${formatoMonedaSaldos(sumPagos)}\n` +
          `• *SALDO TOTAL EXIGIBLE A LA FECHA: ${formatoMonedaSaldos(saldoFinalPeriodo)}*\n\n` +
          `La presente certificación presta mérito ejecutivo en los términos de ley.`
        )
      : encodeURIComponent(
          `Estimado(a) ${data.propietario}, le compartimos su *Estado de Cuenta Histórico y Trazabilidad de Pagos* para la unidad ${data.apto} en ${nombreEdif}:\n\n` +
          `• Periodo Consultado: ${mesesFiltrados.length} meses (${primerMes.periodo || ''} hasta ${ultMesFiltrado.periodo || ''}).\n` +
          `• Total Cuotas Facturadas: ${formatoMonedaSaldos(totalCapitalCausado)}\n` +
          `• Total Intereses: ${formatoMonedaSaldos(totalInteresesCausados)}\n` +
          `• Total Pagos y Abonos Realizados: ${formatoMonedaSaldos(sumPagos)}\n` +
          `• *SALDO PENDIENTE A LA FECHA: ${formatoMonedaSaldos(saldoFinalPeriodo)}*\n\n` +
          `Para cualquier duda o conciliación de pagos, favor comunicarse con la Administración.`
        );
    window.currentEstudioHistoricoMesesFiltrados = mesesFiltrados;
    const aptoCur = data.apto || '';
    const telCur = (typeof obtenerTelefonoUnidad === 'function' ? obtenerTelefonoUnidad(aptoCur) : '') || data.tel || '';
    btnWa.title = telCur ? `Enviar WhatsApp a ${telCur}` : 'Enviar WhatsApp';
  }

  safeCreateIcons();
}

function cerrarModalEstudioCuentaHistorico() {
  const modal = document.getElementById("modal-estudio-cuenta-historico");
  if (modal) modal.classList.add("hidden");
}

function descargarExcelEstudioHistorico(tipoParam) {
  const d = currentEstudioHistoricoData;
  const meses = window.currentEstudioHistoricoMesesFiltrados || (d && d.meses);
  if (!d || !meses || meses.length === 0) {
    if (typeof mostrarToast === "function") mostrarToast("⚠️ No hay datos cargados para exportar a Excel.", "warning");
    return;
  }

  if (typeof XLSX === "undefined") {
    if (typeof mostrarToast === "function") mostrarToast("⚠️ Librería de Excel cargando... intente de nuevo en un segundo.", "warning");
    return;
  }

  const tipo = tipoParam || document.getElementById("estudio-hist-filtro-destinatario")?.value || "tradicional";

  if (tipo === "tradicional") {
    const codClean = (d.codigo || "4159").replace(/^cj_/, "");
    const nombreEdif = d.edificio?.nombre || `EDIFICIO ${codClean} P.H.`;
    const predioTxt = `${d.propietario || "Copropietario"}--Predio ${d.apto || ""} BLO. ${d.bloq || "AP"}`;
    const filasExcel = [];

    const headersCols = [
      "Mes / Periodo", "", "Factura", "Concepto", "Admón", "Interés", "Otros",
      "Extra", "Multa", "Ser. Publ.", "Ser./ Serv.", "Notas D/C", "Valor", "Pagos", "Notas/Desc."
    ];

    let pageNum = 1;
    function agregarEncabezado(pag) {
      filasExcel.push(["Estado de Cuenta"]);
      filasExcel.push(["", "", nombreEdif, "", "", "", "", "", "", "", "", "", "", `Página ${pag}`]);
      filasExcel.push([predioTxt]);
      filasExcel.push(headersCols);
      filasExcel.push([]);
    }

    agregarEncabezado(pageNum);
    let itemsEnPagina = 0;

    meses.forEach(m => {
      if (itemsEnPagina >= 11) {
        pageNum++;
        filasExcel.push([]);
        agregarEncabezado(pageNum);
        itemsEnPagina = 0;
      }

      const periodoLabel = (m.periodo || `${m.mes_nombre || m.mes} de ${m.anio}`).toLowerCase().replace(/(^\w{1})|(\s+\w{1})/g, letter => letter.toUpperCase());
      const fac = m.fac || "";

      const pendAdmon = Number(m.pend_puro || 0);
      const pendInt = Number(m.interes_anterior || 0);
      const pendOtr = Number(m.otros_anterior || 0);
      const pendExt = Number(m.extra_anterior || 0);
      const pendMul = Number(m.multa_anterior || 0);
      const pendSp = Number(m.serpub_anterior || 0);
      const pendSrv = Number(m.serv_anterior || 0);
      const pendNd = Number(m.notas_anterior || 0);
      const valPend = pendAdmon + pendInt + pendOtr + pendExt + pendMul + pendSp + pendSrv + pendNd;

      const actAdmon = Number(m.actual_puro || 0);
      const actInt = Number(m.interes_mes || 0);
      const actOtr = Number(m.otros_mes || 0);
      const actExt = Number(m.extra_mes || 0);
      const actMul = Number(m.multa_mes || 0);
      const actSp = Number(m.serpub_mes || 0);
      const actSrv = Number(m.serv_mes || 0);
      const actNd = Number(m.notas_mes || 0);
      const valAct = actAdmon + actInt + actOtr + actExt + actMul + actSp + actSrv + actNd;

      const totAdmon = pendAdmon + actAdmon;
      const totInt = pendInt + actInt;
      const totOtr = pendOtr + actOtr;
      const totExt = pendExt + actExt;
      const totMul = pendMul + actMul;
      const totSp = pendSp + actSp;
      const totSrv = pendSrv + actSrv;
      const totNd = pendNd + actNd;
      const valTot = Number(m.total || (totAdmon + totInt + totOtr + totExt + totMul + totSp + totSrv + totNd));
      const pagos = Number(m.valpag || 0);
      const desc = Number(m.valdesc || 0);

      // 1. Fila Pendiente
      filasExcel.push([
        periodoLabel, "", fac, "Pendiente",
        pendAdmon, pendInt, pendOtr, pendExt, pendMul, pendSp, pendSrv, pendNd, valPend, "", ""
      ]);

      // 2. Fila Actual
      filasExcel.push([
        "", "", "", "Actual",
        actAdmon, actInt, actOtr, actExt, actMul, actSp, actSrv, actNd, valAct, "", ""
      ]);

      // 3. Fila Total
      filasExcel.push([
        "", "", "", "Total",
        totAdmon, totInt, totOtr, totExt, totMul, totSp, totSrv, totNd, valTot, pagos, desc
      ]);

      filasExcel.push([]);
      itemsEnPagina++;
    });

    const wb = XLSX.utils.book_new();
    const ws = XLSX.utils.aoa_to_sheet(filasExcel);
    ws['!cols'] = [
      { wch: 22 }, { wch: 3 }, { wch: 10 }, { wch: 12 }, { wch: 12 },
      { wch: 12 }, { wch: 12 }, { wch: 12 }, { wch: 10 }, { wch: 12 },
      { wch: 12 }, { wch: 12 }, { wch: 14 }, { wch: 14 }, { wch: 12 }
    ];
    XLSX.utils.book_append_sheet(wb, ws, "Estado_de_Cuenta");
    const nombreArchivo = `Estado_Cuenta_Tradicional_${codClean}_${d.apto || "inmueble"}.xlsx`;
    XLSX.writeFile(wb, nombreArchivo);
    if (typeof mostrarToast === "function") {
      mostrarToast(`✓ Excel descargado (Estado de Cuenta Tradicional): ${nombreArchivo}`);
    }
    return;
  }

  const esAbogado = tipo === "abogado";

  const primerMes = meses[0] || {};
  const ultMes = meses[meses.length - 1] || {};
  const saldoInicialCap = Number(primerMes.saldo_anterior) || 0;
  const intMoraInicial = Number(primerMes.interes_anterior) || 0;

  const sumSaldoAntCap = meses.reduce((acc, m) => acc + (Number(m.saldo_anterior) || 0), 0);
  const sumIntMoraAnt = meses.reduce((acc, m) => acc + (Number(m.interes_anterior) || 0), 0);
  const sumCuotaAdmon = meses.reduce((acc, m) => acc + (Number(m.cuota_admon) || 0), 0);
  const sumInteresMes = meses.reduce((acc, m) => acc + (Number(m.interes_mes) || 0), 0);
  const sumPagos = meses.reduce((acc, m) => acc + (Number(m.valpag) || 0), 0);
  const saldoFinalPeriodo = Number(ultMes.total || 0);

  const totalCapital = saldoInicialCap + sumCuotaAdmon;
  const totalIntereses = intMoraInicial + sumInteresMes;
  const fechaHoy = new Date().toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric' });

  // Encabezados institucionales adaptados según destinatario (Abogado vs Copropietario)
  const tituloPrincipal = esAbogado
    ? "CERTIFICACIÓN DE DEUDA Y LIQUIDACIÓN DISCRIMINADA DE CRÉDITO PARA COBRO JUDICIAL"
    : "ESTADO DE CUENTA HISTÓRICO Y TRAZABILIDAD DE CARTERA";

  const subtituloPrincipal = esAbogado
    ? "(EXPEDIDO DE CONFORMIDAD CON EL ARTÍCULO 48 DE LA LEY 675 DE 2001 - PRESTA MÉRITO EJECUTIVO - ART. 422 C.G.P.)"
    : "(INFORMACIÓN CONTABLE HISTÓRICA DETALLADA MES A MES PARA EL COPROPIETARIO)";

  const filasExcel = [
    [tituloPrincipal],
    [subtituloPrincipal],
    [],
    ["COPROPIEDAD (ACREEDORA):", d.edificio?.nombre || "", "NIT:", d.edificio?.nit || "", "CÓDIGO:", d.codigo || ""],
    ["DIRECCIÓN:", d.edificio?.direccion || "", "CIUDAD:", d.edificio?.ciudad || "Colombia", "ADMINISTRADOR:", d.edificio?.administrador || ""],
    [esAbogado ? "DEMANDADO / PROPIETARIO:" : "PROPIETARIO(A):", d.propietario || "", "IDENTIFICACIÓN C.C./NIT:", d.cc || "", "INMUEBLE / PREDIO:", d.apto || ""],
    ["COEFICIENTE:", d.coeficiente || "", "TASA MORA:", d.edificio?.interesMora || "2.10% M.V.", "PERIODO LIQUIDADO:", `${meses.length} MESES (${primerMes.periodo || ''} HASTA ${ultMes.periodo || ''})`],
    [],
    [
      "PERIODO",
      "FACTURA / CUENTA",
      "SALDO ANT. CAPITAL",
      "INT. MORA ANT.",
      "CUOTA Y CARGOS MES",
      "INT. MORA MES",
      "PAGOS / ABONOS",
      esAbogado ? "SALDO TOTAL EXIGIBLE" : "SALDO FINAL",
      "DISCRIMINACIÓN DE CONCEPTOS / NOTAS"
    ]
  ];

  meses.forEach(m => {
    const notasList = [];
    if (Number(m.notas_mes || 0) !== 0) notasList.push(`Nota D/C Mes: $${Number(m.notas_mes).toLocaleString('es-CO')}`);
    if (Number(m.notas_anterior || 0) !== 0) notasList.push(`Nota D/C Pendiente: $${Number(m.notas_anterior).toLocaleString('es-CO')}`);
    if (Number(m.multa_mes || 0) !== 0) notasList.push(`Multa Mes: $${Number(m.multa_mes).toLocaleString('es-CO')}`);
    if (Number(m.multa_anterior || 0) !== 0) notasList.push(`Multa Pendiente: $${Number(m.multa_anterior).toLocaleString('es-CO')}`);
    if (Number(m.extra_mes || 0) !== 0) notasList.push(`Cuota Extra Mes: $${Number(m.extra_mes).toLocaleString('es-CO')}`);
    if (Number(m.extra_anterior || 0) !== 0) notasList.push(`Cuota Extra Pendiente: $${Number(m.extra_anterior).toLocaleString('es-CO')}`);
    if (Number(m.otros_mes || 0) !== 0) notasList.push(`Otros Mes: $${Number(m.otros_mes).toLocaleString('es-CO')}`);
    if (Number(m.otros_anterior || 0) !== 0) notasList.push(`Otros Pendiente: $${Number(m.otros_anterior).toLocaleString('es-CO')}`);
    if (Number(m.serpub_mes || 0) !== 0) notasList.push(`Serv. Públicos Mes: $${Number(m.serpub_mes).toLocaleString('es-CO')}`);
    if (Number(m.serpub_anterior || 0) !== 0) notasList.push(`Serv. Públicos Pendiente: $${Number(m.serpub_anterior).toLocaleString('es-CO')}`);
    if (Number(m.serv_mes || 0) !== 0) notasList.push(`Serv. Especiales Mes: $${Number(m.serv_mes).toLocaleString('es-CO')}`);
    if (Number(m.serv_anterior || 0) !== 0) notasList.push(`Serv. Especiales Pendiente: $${Number(m.serv_anterior).toLocaleString('es-CO')}`);
    if (m.novedad) notasList.push(`Novedad: ${m.novedad}`);

    filasExcel.push([
      m.periodo || `${m.anio}-${m.mes}`,
      m.fac ? `Fac. ${m.fac}` : "-",
      Number(m.saldo_anterior) || 0,
      Number(m.interes_anterior) || 0,
      Number(m.cuota_admon) || 0,
      Number(m.interes_mes) || 0,
      Number(m.valpag) || 0,
      Number(m.total) || 0,
      notasList.join(" | ") || "-"
    ]);
  });

  // Fila de TOTALES CONSOLIDADOS
  filasExcel.push([]);
  filasExcel.push([
    esAbogado ? "TOTALES CONSOLIDADOS PARA COBRO JUDICIAL" : "TOTALES CONSOLIDADOS - ESTADO DE CUENTA",
    `${meses.length} MESES`,
    sumSaldoAntCap,
    sumIntMoraAnt,
    sumCuotaAdmon,
    sumInteresMes,
    sumPagos,
    saldoFinalPeriodo,
    "Consolidado multianual verificado"
  ]);

  // Resumen Ejecutivo de Liquidación
  filasExcel.push([]);
  filasExcel.push([esAbogado ? "DISCRIMINACIÓN DE LIQUIDACIÓN DE CRÉDITO (ART. 48 LEY 675 DE 2001)" : "RESUMEN DE LIQUIDACIÓN Y ESTADO DE CUENTA"]);
  filasExcel.push(["1. TOTAL CAPITAL CAUSADO (EXPENSAS COMUNES ORDINARIAS):", totalCapital]);
  filasExcel.push(["2. TOTAL INTERESES MORATORIOS LIQUIDADOS (TASA M.V.):", totalIntereses]);
  filasExcel.push(["3. MENOS: TOTAL ABONOS Y PAGOS APLICADOS:", sumPagos]);
  filasExcel.push([esAbogado ? "4. SALDO NETO LÍQUIDO Y EXIGIBLE:" : "4. SALDO PENDIENTE A LA FECHA:", saldoFinalPeriodo]);
  filasExcel.push([]);

  if (esAbogado) {
    filasExcel.push(["CONSTANCIA DE MÉRITO EJECUTIVO (ARTÍCULO 48 DE LA LEY 675 DE 2001 Y ART. 422 DEL C.G.P.):"]);
    filasExcel.push(["El(la) suscrito(a) Administrador(a) y Representante Legal certifica que la liquidación contable precedente corresponde estrictamente"]);
    filasExcel.push(["a las expensas comunes ordinarias e intereses moratorios adeudados por la unidad privada indicada. La presente certificación"]);
    filasExcel.push(["presta mérito ejecutivo en los términos del Art. 48 de la Ley 675 de 2001 y reúne los requisitos de los Artículos 422 y 431 del C.G.P."]);
    filasExcel.push(["como obligación clara, expresa y exigible a cargo del deudor demandado."]);
    filasExcel.push([]);
    filasExcel.push(["____________________________________________________"]);
    filasExcel.push(["ADMINISTRADOR(A) Y REPRESENTANTE LEGAL"]);
    filasExcel.push([`C.C. ________________ de ___________________________`]);
    filasExcel.push([`${d.edificio?.nombre || ''} - NIT ${d.edificio?.nit || ''}`]);
  } else {
    filasExcel.push(["ESTADO DE CUENTA INFORMATIVO PARA EL COPROPIETARIO:"]);
    filasExcel.push(["El presente documento refleja la trazabilidad contable mes a mes y los movimientos registrados de expensas comunes, intereses y pagos."]);
    filasExcel.push(["Si requiere aclaración o conciliar sus recibos de pago, por favor contactar a la Administración."]);
    filasExcel.push([]);
    filasExcel.push(["ADMINISTRACIÓN Y CONCILIACIÓN DE CARTERA"]);
    filasExcel.push([`${d.edificio?.nombre || ''} - Expedido en ${d.edificio?.ciudad || 'Colombia'} a fecha: ${fechaHoy}`]);
  }

  const ws = XLSX.utils.aoa_to_sheet(filasExcel);

  // Formatear todas las celdas numéricas con formato moneda Excel ($ #,##0)
  if (ws['!ref']) {
    const range = XLSX.utils.decode_range(ws['!ref']);
    for (let R = range.s.r; R <= range.e.r; ++R) {
      for (let C = range.s.c; C <= range.e.c; ++C) {
        const cellAddress = XLSX.utils.encode_cell({ r: R, c: C });
        const cell = ws[cellAddress];
        if (cell && typeof cell.v === 'number') {
          cell.t = 'n';
          cell.z = '"$"#,##0;("$"#,##0);"-"';
        }
      }
    }
  }

  // Configuración de página horizontal (Landscape) y ajuste para que quepan todas las columnas en la página completa
  ws['!pageSetup'] = { orientation: 'landscape', paperSize: 9, fitToWidth: 1, fitToHeight: 0 };
  ws['!margins'] = { left: 0.3, right: 0.3, top: 0.4, bottom: 0.4, header: 0.2, footer: 0.2 };

  // Anchos proporcionales para encajar 100% en la hoja horizontal
  ws["!cols"] = [
    { wch: 18 }, // Col A: Periodo
    { wch: 15 }, // Col B: Factura / Cuenta
    { wch: 18 }, // Col C: Saldo Ant. Capital
    { wch: 16 }, // Col D: Int. Mora Ant.
    { wch: 18 }, // Col E: Cuota y Cargos Mes
    { wch: 16 }, // Col F: Int. Mora Mes
    { wch: 16 }, // Col G: Pagos / Abonos
    { wch: 18 }, // Col H: Saldo Total Exigible
    { wch: 34 }  // Col I: Discriminación de Conceptos / Notas
  ];

  const wb = XLSX.utils.book_new();
  const nombreHoja = esAbogado ? "Cobro_Juridico" : "Estado_Cuenta";
  XLSX.utils.book_append_sheet(wb, ws, nombreHoja);

  const nombreArchivo = esAbogado
    ? `Cobro_Juridico_Art48_${d.codigo}_Apto_${d.apto}_${meses.length}_Meses.xlsx`
    : `Estado_Cuenta_${d.codigo}_Apto_${d.apto}_${meses.length}_Meses.xlsx`;

  XLSX.writeFile(wb, nombreArchivo);

  if (typeof mostrarToast === "function") {
    mostrarToast(`✓ Excel descargado (${esAbogado ? 'Cobro Judicial' : 'Copropietario'}): ${nombreArchivo}`);
  }
}

function imprimirEstudioHistorico(tipoParam) {
  const d = currentEstudioHistoricoData;
  const meses = window.currentEstudioHistoricoMesesFiltrados || (d && d.meses);
  if (!d || !meses || meses.length === 0) {
    if (typeof mostrarToast === "function") mostrarToast("⚠️ No hay datos cargados para imprimir.", "warning");
    return;
  }

  const tipo = tipoParam || document.getElementById("estudio-hist-filtro-destinatario")?.value || "tradicional";

  if (tipo === "tradicional") {
    const codClean = (d.codigo || "4159").replace(/^cj_/, "");
    const nombreEdif = d.edificio?.nombre || `EDIFICIO ${codClean} P.H.`;
    const predioTxt = `${d.propietario || "Copropietario"}--Predio ${d.apto || ""} BLO. ${d.bloq || "AP"}`;

    const fmtNum = v => {
      const n = Number(v) || 0;
      return n === 0 ? "0" : n.toLocaleString('es-CO');
    };

    const chunks = [];
    for (let i = 0; i < meses.length; i += 11) {
      chunks.push(meses.slice(i, i + 11));
    }
    if (chunks.length === 0) chunks.push([]);

    const pagesHtml = chunks.map((chunk, pageIdx) => {
      const rowsHtml = chunk.map(m => {
        const periodoLabel = (m.periodo || `${m.mes_nombre || m.mes} de ${m.anio}`).toLowerCase().replace(/(^\w{1})|(\s+\w{1})/g, letter => letter.toUpperCase());
        const fac = m.fac || "";

        const pendAdmon = Number(m.pend_puro || 0);
        const pendInt = Number(m.interes_anterior || 0);
        const pendOtr = Number(m.otros_anterior || 0);
        const pendExt = Number(m.extra_anterior || 0);
        const pendMul = Number(m.multa_anterior || 0);
        const pendSp = Number(m.serpub_anterior || 0);
        const pendSrv = Number(m.serv_anterior || 0);
        const pendNd = Number(m.notas_anterior || 0);
        const valPend = pendAdmon + pendInt + pendOtr + pendExt + pendMul + pendSp + pendSrv + pendNd;

        const actAdmon = Number(m.actual_puro || 0);
        const actInt = Number(m.interes_mes || 0);
        const actOtr = Number(m.otros_mes || 0);
        const actExt = Number(m.extra_mes || 0);
        const actMul = Number(m.multa_mes || 0);
        const actSp = Number(m.serpub_mes || 0);
        const actSrv = Number(m.serv_mes || 0);
        const actNd = Number(m.notas_mes || 0);
        const valAct = actAdmon + actInt + actOtr + actExt + actMul + actSp + actSrv + actNd;

        const totAdmon = pendAdmon + actAdmon;
        const totInt = pendInt + actInt;
        const totOtr = pendOtr + actOtr;
        const totExt = pendExt + actExt;
        const totMul = pendMul + actMul;
        const totSp = pendSp + actSp;
        const totSrv = pendSrv + actSrv;
        const totNd = pendNd + actNd;
        const valTot = Number(m.total || (totAdmon + totInt + totOtr + totExt + totMul + totSp + totSrv + totNd));
        const pagos = Number(m.valpag || 0);
        const desc = Number(m.valdesc || 0);

        return `
          <tr class="row-pend">
            <td class="col-mes">${periodoLabel}</td>
            <td class="col-fac">${fac}</td>
            <td class="col-tipo">Pendiente</td>
            <td class="col-num">${fmtNum(pendAdmon)}</td>
            <td class="col-num">${fmtNum(pendInt)}</td>
            <td class="col-num">${fmtNum(pendOtr)}</td>
            <td class="col-num">${fmtNum(pendExt)}</td>
            <td class="col-num">${fmtNum(pendMul)}</td>
            <td class="col-num">${fmtNum(pendSp)}</td>
            <td class="col-num">${fmtNum(pendSrv)}</td>
            <td class="col-num">${fmtNum(pendNd)}</td>
            <td class="col-num col-valor">${fmtNum(valPend)}</td>
            <td class="col-num"></td>
            <td class="col-num"></td>
          </tr>
          <tr class="row-act">
            <td></td>
            <td></td>
            <td class="col-tipo">Actual</td>
            <td class="col-num">${fmtNum(actAdmon)}</td>
            <td class="col-num">${fmtNum(actInt)}</td>
            <td class="col-num">${fmtNum(actOtr)}</td>
            <td class="col-num">${fmtNum(actExt)}</td>
            <td class="col-num">${fmtNum(actMul)}</td>
            <td class="col-num">${fmtNum(actSp)}</td>
            <td class="col-num">${fmtNum(actSrv)}</td>
            <td class="col-num">${fmtNum(actNd)}</td>
            <td class="col-num col-valor">${fmtNum(valAct)}</td>
            <td></td>
            <td></td>
          </tr>
          <tr class="row-tot">
            <td></td>
            <td></td>
            <td class="col-tipo col-tot-label">Total</td>
            <td class="col-num col-tot-val">${fmtNum(totAdmon)}</td>
            <td class="col-num col-tot-val">${fmtNum(totInt)}</td>
            <td class="col-num col-tot-val">${fmtNum(totOtr)}</td>
            <td class="col-num col-tot-val">${fmtNum(totExt)}</td>
            <td class="col-num col-tot-val">${fmtNum(totMul)}</td>
            <td class="col-num col-tot-val">${fmtNum(totSp)}</td>
            <td class="col-num col-tot-val">${fmtNum(totSrv)}</td>
            <td class="col-num col-tot-val">${fmtNum(totNd)}</td>
            <td class="col-num col-tot-val col-valor">${fmtNum(valTot)}</td>
            <td class="col-num col-pago">${fmtNum(pagos)}</td>
            <td class="col-num">${fmtNum(desc)}</td>
          </tr>
          <tr class="row-sep"><td colspan="14"></td></tr>
        `;
      }).join("");

      return `
        <div class="sheet-page">
          <div class="header-box">
            <div class="header-top">
              <div class="h-title">Estado de Cuenta</div>
              <div class="h-edif">${nombreEdif}</div>
              <div class="h-page">Página ${pageIdx + 1} de ${chunks.length}</div>
            </div>
            <div class="h-predio">${predioTxt}</div>
          </div>
          <table class="tabla-estado">
            <thead>
              <tr>
                <th style="width: 14%;">Mes</th>
                <th style="width: 6%;">Factura</th>
                <th style="width: 7%;">Concepto</th>
                <th style="width: 7%;">Admón</th>
                <th style="width: 6%;">Interés</th>
                <th style="width: 7%;">Otros</th>
                <th style="width: 6%;">Extra</th>
                <th style="width: 5%;">Multa</th>
                <th style="width: 6%;">Ser. Publ.</th>
                <th style="width: 6%;">Ser./ Serv.</th>
                <th style="width: 6%;">Notas D/C</th>
                <th style="width: 8%;">Valor</th>
                <th style="width: 8%;">Pagos</th>
                <th style="width: 7%;">Notas/Desc.</th>
              </tr>
            </thead>
            <tbody>
              ${rowsHtml}
            </tbody>
          </table>
        </div>
      `;
    }).join("");

    const printWin = window.open("", "_blank");
    if (!printWin) {
      if (typeof mostrarToast === "function") mostrarToast("⚠️ Por favor permita ventanas emergentes para imprimir.", "warning");
      return;
    }

    const htmlDoc = `<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8">
  <title>Estado de Cuenta - ${nombreEdif} - Apto ${d.apto || ''}</title>
  <style>
    @page { size: letter landscape; margin: 8mm 6mm; }
    * { box-sizing: border-box; font-family: Arial, "Helvetica Neue", Helvetica, sans-serif; }
    body { background: #0f172a; color: #000; margin: 0; padding: 20px; display: flex; flex-direction: column; align-items: center; }
    .no-print-bar { position: sticky; top: 10px; z-index: 100; background: #1e293b; padding: 10px 20px; border-radius: 12px; border: 1px solid #334155; display: flex; gap: 12px; margin-bottom: 20px; box-shadow: 0 10px 25px rgba(0,0,0,0.5); }
    .btn-act { background: #059669; color: white; border: none; padding: 8px 16px; font-size: 13px; font-weight: bold; border-radius: 8px; cursor: pointer; }
    .btn-act:hover { background: #10b981; }
    .btn-sec { background: #334155; color: #e2e8f0; border: 1px solid #475569; padding: 8px 14px; font-size: 13px; font-weight: bold; border-radius: 8px; cursor: pointer; text-decoration: none; }
    .btn-sec:hover { background: #475569; }
    .sheet-page { background: #ffffff; width: 100%; max-width: 1100px; padding: 15px 20px; margin-bottom: 25px; border-radius: 4px; box-shadow: 0 4px 15px rgba(0,0,0,0.3); page-break-after: always; }
    .sheet-page:last-child { page-break-after: auto; margin-bottom: 0; }
    .header-box { border-bottom: 2px solid #000; padding-bottom: 6px; margin-bottom: 8px; }
    .header-top { display: flex; justify-content: space-between; align-items: flex-end; }
    .h-title { font-size: 15px; font-weight: 800; letter-spacing: -0.5px; }
    .h-edif { font-size: 15px; font-weight: 800; text-align: center; flex: 1; }
    .h-page { font-size: 11px; font-weight: bold; text-align: right; }
    .h-predio { font-size: 12px; font-weight: bold; margin-top: 4px; color: #1e293b; }
    .tabla-estado { width: 100%; border-collapse: collapse; font-size: 9.5px; }
    .tabla-estado thead th { border-top: 1px solid #000; border-bottom: 1.5px solid #000; padding: 4px 3px; text-align: right; font-weight: 800; background: #f8fafc; }
    .tabla-estado thead th:nth-child(1) { text-align: left; }
    .tabla-estado thead th:nth-child(2) { text-align: center; }
    .tabla-estado thead th:nth-child(3) { text-align: left; }
    .tabla-estado tbody td { padding: 1.5px 3px; white-space: nowrap; }
    .col-mes { font-weight: bold; text-align: left; }
    .col-fac { text-align: center; color: #334155; }
    .col-tipo { text-align: left; color: #475569; }
    .col-tot-label { font-weight: 800; color: #000; }
    .col-num { text-align: right; font-variant-numeric: tabular-nums; }
    .col-tot-val { font-weight: 800; color: #000; }
    .col-valor { background: #f1f5f9; font-weight: 700; }
    .col-pago { color: #047857; font-weight: 700; }
    .row-tot td { border-bottom: 1px dashed #cbd5e1; padding-bottom: 2px; }
    .row-sep td { height: 4px; border: none; padding: 0; }
    @media print {
      body { background: transparent !important; padding: 0 !important; }
      .no-print-bar { display: none !important; }
      .sheet-page { width: 100% !important; max-width: none !important; padding: 0 !important; margin: 0 !important; box-shadow: none !important; border-radius: 0 !important; }
    }
  </style>
</head>
<body>
  <div class="no-print-bar">
    <button class="btn-act" onclick="window.print()">🖨️ Imprimir / Guardar PDF</button>
    <button class="btn-sec" onclick="window.close()">✖️ Cerrar</button>
  </div>
  ${pagesHtml}
</body>
</html>`;

    printWin.document.open();
    printWin.document.write(htmlDoc);
    printWin.document.close();
    return;
  }

  const esAbogado = tipo === "abogado";

  const primerMes = meses[0] || {};
  const ultMes = meses[meses.length - 1] || {};
  const saldoInicialCap = Number(primerMes.saldo_anterior) || 0;
  const intMoraInicial = Number(primerMes.interes_anterior) || 0;

  const sumSaldoAntCap = meses.reduce((acc, m) => acc + (Number(m.saldo_anterior) || 0), 0);
  const sumIntMoraAnt = meses.reduce((acc, m) => acc + (Number(m.interes_anterior) || 0), 0);
  const sumCuotaAdmon = meses.reduce((acc, m) => acc + (Number(m.cuota_admon) || 0), 0);
  const sumInteresMes = meses.reduce((acc, m) => acc + (Number(m.interes_mes) || 0), 0);
  const sumPagos = meses.reduce((acc, m) => acc + (Number(m.valpag) || 0), 0);
  const saldoFinalPeriodo = Number(ultMes.total || 0);

  const totalCapital = saldoInicialCap + sumCuotaAdmon;
  const totalIntereses = intMoraInicial + sumInteresMes;
  const fechaHoy = new Date().toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric' });

  // Filas de datos en negro (#000000)
  const filasHtml = [...meses].map((m, idx) => {
    const capAnt = Number(m.saldo_anterior) || 0;
    const intAnt = Number(m.interes_anterior) || 0;
    const cuotaM = Number(m.cuota_admon) || 0;
    const intM = Number(m.interes_mes) || 0;
    const pagoM = Number(m.valpag) || 0;
    const saldoFin = Number(m.total) || 0;

    const tagsMes = [];
    if (Number(m.notas_mes || 0) !== 0) tagsMes.push(`Nota D/C: ${formatoMonedaSaldos(m.notas_mes)}`);
    if (Number(m.multa_mes || 0) !== 0) tagsMes.push(`Multa: ${formatoMonedaSaldos(m.multa_mes)}`);
    if (Number(m.extra_mes || 0) !== 0) tagsMes.push(`Extra: ${formatoMonedaSaldos(m.extra_mes)}`);
    if (Number(m.otros_mes || 0) !== 0) tagsMes.push(`Otros: ${formatoMonedaSaldos(m.otros_mes)}`);
    if (Number(m.serpub_mes || 0) !== 0) tagsMes.push(`Serv. Públ.: ${formatoMonedaSaldos(m.serpub_mes)}`);
    if (Number(m.serv_mes || 0) !== 0) tagsMes.push(`Servicios: ${formatoMonedaSaldos(m.serv_mes)}`);
    const subDetalleMes = tagsMes.length > 0 ? `<div style="font-size: 8px; color: #334155; font-weight: normal; margin-top: 1px;">(${tagsMes.join(' • ')})</div>` : '';

    const tagsAnt = [];
    if (Number(m.notas_anterior || 0) !== 0) tagsAnt.push(`Nota pend.: ${formatoMonedaSaldos(m.notas_anterior)}`);
    if (Number(m.multa_anterior || 0) !== 0) tagsAnt.push(`Multa pend.: ${formatoMonedaSaldos(m.multa_anterior)}`);
    if (Number(m.extra_anterior || 0) !== 0) tagsAnt.push(`Extra pend.: ${formatoMonedaSaldos(m.extra_anterior)}`);
    if (Number(m.otros_anterior || 0) !== 0) tagsAnt.push(`Otros pend.: ${formatoMonedaSaldos(m.otros_anterior)}`);
    if (Number(m.serpub_anterior || 0) !== 0) tagsAnt.push(`Serv. Públ. pend.: ${formatoMonedaSaldos(m.serpub_anterior)}`);
    if (Number(m.serv_anterior || 0) !== 0) tagsAnt.push(`Servicios pend.: ${formatoMonedaSaldos(m.serv_anterior)}`);
    const subDetalleAnt = tagsAnt.length > 0 ? `<div style="font-size: 8px; color: #334155; font-weight: normal; margin-top: 1px;">(${tagsAnt.join(' • ')})</div>` : '';

    return `
      <tr style="border-bottom: 1px solid #cbd5e1; ${idx % 2 === 0 ? 'background-color: #f8fafc;' : 'background-color: #ffffff;'}">
        <td style="padding: 5px 6px; font-weight: bold; color: #000000;">${m.periodo || (m.anio + '-' + m.mes)}</td>
        <td style="padding: 5px 6px; text-align: center; color: #000000; font-family: monospace;">${m.fac ? ('Fac. ' + m.fac) : '-'}</td>
        <td style="padding: 5px 6px; text-align: right; color: #000000; font-family: monospace; font-weight: 500;">
          <div>${formatoMonedaSaldos(capAnt)}</div>
          ${subDetalleAnt}
        </td>
        <td style="padding: 5px 6px; text-align: right; color: #000000; font-family: monospace;">${intAnt > 0 ? formatoMonedaSaldos(intAnt) : '$0'}</td>
        <td style="padding: 5px 6px; text-align: right; color: #000000; font-family: monospace;">
          <div>${formatoMonedaSaldos(cuotaM)}</div>
          ${subDetalleMes}
        </td>
        <td style="padding: 5px 6px; text-align: right; color: #000000; font-family: monospace;">${intM > 0 ? formatoMonedaSaldos(intM) : '$0'}</td>
        <td style="padding: 5px 6px; text-align: right; color: #000000; font-weight: bold; font-family: monospace;">${pagoM > 0 ? formatoMonedaSaldos(pagoM) : '$0'}</td>
        <td style="padding: 5px 6px; text-align: right; font-weight: bold; color: #000000; font-family: monospace;">${formatoMonedaSaldos(saldoFin)}</td>
      </tr>
    `;
  }).join("");

  const tituloDoc = esAbogado
    ? "CERTIFICACIÓN DE DEUDA Y ESTADO DE CUENTA CRONOLÓGICO DISCRIMINADO"
    : "ESTADO DE CUENTA HISTÓRICO Y TRAZABILIDAD DE CARTERA";

  const subtituloDoc = esAbogado
    ? "(TÍTULO EJECUTIVO - ARTÍCULO 48 DE LA LEY 675 DE 2001 Y ART. 422 DEL C.G.P.)"
    : "(INFORME CONTABLE DETALLADO MES A MES PARA EL COPROPIETARIO)";

  const estadoCreditoTexto = esAbogado
    ? "OBLIGACIÓN EXIGIBLE EN MORA"
    : (saldoFinalPeriodo > 0 ? "SALDO PENDIENTE DE PAGO" : "AL DÍA / A PAZ Y SALVO");

  const labelSaldoCard = esAbogado
    ? "Saldo Total Líquido y Exigible"
    : "Saldo Final a la Fecha";

  const labelColSaldo = esAbogado
    ? "Saldo Total Exigible"
    : "Saldo Final Mes";

  const bloqueNotaLegal = esAbogado
    ? `
      <div class="legal-note">
        <b>CONSTANCIA DE MÉRITO EJECUTIVO (ARTÍCULO 48 LEY 675 DE 2001):</b><br/>
        El(la) suscrito(a) Administrador(a) y Representante Legal de la copropiedad <b>${d.edificio?.nombre || ('EDIFICIO ' + d.codigo)}</b>, 
        legalmente constituida bajo el régimen de Propiedad Horizontal de la Ley 675 de 2001, certifica que la relación contable anterior 
        corresponde fielmente a los saldos adeudados por concepto de expensas comunes ordinarias e intereses moratorios para la unidad privada <b>${d.apto}</b>. 
        Se expide la presente liquidación con destino al apoderado judicial y al Despacho Judicial competente para que sirva de <b>PLENA PRUEBA Y TÍTULO EJECUTIVO</b> 
        para iniciar o continuar el proceso ejecutivo respectivo, constituyendo una obligación clara, expresa y actualmente exigible a cargo del demandado.
      </div>
      <div class="firmas">
        <div class="firma-col">
          <p><b>${d.edificio?.administrador || 'ADMINISTRACIÓN Y REPRESENTACIÓN LEGAL'}</b></p>
          <p>Administrador(a) y Representante Legal</p>
          <p>C.C. __________________________________</p>
          <p>${d.edificio?.nombre || ''}</p>
        </div>
        <div class="firma-col">
          <p><b>CERTIFICACIÓN Y FECHA</b></p>
          <p>Expedido en ${d.edificio?.ciudad || 'Medellín, Colombia'}</p>
          <p>Fecha de emisión: ${fechaHoy}</p>
          <p>Firma y Sello de la Administración</p>
        </div>
      </div>
    `
    : `
      <div class="legal-note">
        <b>ESTADO DE CUENTA INFORMATIVO PARA EL COPROPIETARIO:</b><br/>
        La relación contable anterior refleja fielmente la trazabilidad de los cobros mensuales de expensas comunes, intereses causados y pagos imputados 
        a la unidad privada <b>${d.apto}</b>. Si requiere conciliar sus pagos o realizar cualquier aclaración contable sobre este estado de cuenta, 
        por favor comuníquese con la Administración de la copropiedad.
      </div>
      <div class="firmas">
        <div class="firma-col">
          <p><b>${d.edificio?.administrador || 'ADMINISTRACIÓN DE LA COPROPIEDAD'}</b></p>
          <p>Administración y Conciliación de Cartera</p>
          <p>${d.edificio?.nombre || ''}</p>
        </div>
        <div class="firma-col">
          <p><b>CONSTANCIA DE EMISIÓN</b></p>
          <p>Expedido en ${d.edificio?.ciudad || 'Medellín, Colombia'}</p>
          <p>Fecha de emisión: ${fechaHoy}</p>
        </div>
      </div>
    `;

  const htmlContenido = `
    <!DOCTYPE html>
    <html lang="es">
    <head>
      <meta charset="utf-8" />
      <title>${esAbogado ? 'Certificacion_Deuda_Ley675' : 'Estado_Cuenta_Historico'}_${d.codigo}_Apto_${d.apto}</title>
      <style>
        @page {
          size: landscape;
          margin: 8mm;
        }
        *, *:before, *:after { box-sizing: border-box; }
        html, body {
          margin: 0 !important;
          padding: 0 !important;
          background: #ffffff;
        }
        body { 
          font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif; 
          font-size: 9.5px; 
          color: #000000; 
          padding: 6mm 8mm; 
          line-height: 1.25; 
          -webkit-print-color-adjust: exact;
          print-color-adjust: exact;
          width: 100%;
        }
        .header { text-align: center; border-bottom: 3px double #0f172a; padding-bottom: 6px; margin-bottom: 8px; }
        .header h1 { font-size: 15px; margin: 0; text-transform: uppercase; color: #000000; font-weight: 800; letter-spacing: 0.5px; }
        .header .subtitulo { font-size: 9px; margin: 2px 0 0 0; color: #000000; font-weight: 600; }
        .header .norma { font-size: 8.5px; margin-top: 2px; color: #000000; font-weight: bold; text-transform: uppercase; }
        
        .partes-grid { display: flex; gap: 8px; margin-bottom: 8px; color: #000000; }
        .parte-box { flex: 1; border: 1px solid #94a3b8; border-radius: 4px; padding: 5px 8px; background: #f8fafc; font-size: 9px; color: #000000; }
        .parte-box h4 { margin: 0 0 3px 0; font-size: 9px; color: #000000; border-bottom: 1px solid #cbd5e1; padding-bottom: 2px; text-transform: uppercase; font-weight: bold; }
        .parte-box p { margin: 1.5px 0; color: #000000; }
        
        .resumen-cards { display: flex; gap: 8px; margin-bottom: 8px; color: #000000; }
        .card { flex: 1; border: 1px solid #94a3b8; padding: 5px; border-radius: 4px; text-align: center; background: #ffffff; color: #000000; }
        .card .title { font-size: 8px; text-transform: uppercase; color: #000000; font-weight: bold; }
        .card .value { font-size: 12px; font-weight: 800; margin-top: 2px; color: #000000; }

        table { width: 100%; border-collapse: collapse; font-size: 8.5px; margin-bottom: 10px; color: #000000; table-layout: fixed; }
        th { background: #0f172a; color: #ffffff; padding: 4.5px 5px; text-align: left; font-size: 8px; text-transform: uppercase; border: 1px solid #0f172a; }
        th.right { text-align: right; }
        th.center { text-align: center; }

        .legal-note { border: 1px solid #94a3b8; background: #f8fafc; padding: 6px 8px; font-size: 8px; color: #000000; margin-bottom: 12px; border-radius: 4px; text-align: justify; page-break-inside: avoid; }
        .firmas { display: flex; justify-content: space-between; margin-top: 18px; font-size: 8.5px; page-break-inside: avoid; color: #000000; }
        .firma-col { width: 45%; text-align: center; border-top: 1px solid #000000; padding-top: 4px; color: #000000; }

        @media print {
          @page {
            size: landscape;
            margin: 8mm;
          }
          body { 
            margin: 0 !important;
            padding: 0 !important; 
            color: #000000 !important;
            width: 100% !important;
          }
          button { display: none; }
          tr { page-break-inside: avoid; }
        }
      </style>
    </head>
    <body>
      <div class="header">
        <h1>${d.edificio?.nombre || ('EDIFICIO ' + d.codigo)}</h1>
        <p class="subtitulo">NIT: ${d.edificio?.nit || 'Oficial'} • Dirección: ${d.edificio?.direccion || ''} • ${d.edificio?.ciudad || 'Medellín • Colombia'}</p>
        <p class="norma">${tituloDoc}</p>
        <p style="margin: 0; font-size: 8px; color: #000000;">${subtituloDoc}</p>
      </div>

      <div class="partes-grid">
        <div class="parte-box">
          <h4>${esAbogado ? '1. Datos del Inmueble y Deudor Demandado' : '1. Datos del Inmueble y Copropietario'}</h4>
          <p><b>UNIDAD PRIVADA:</b> Inmueble / Apto ${d.apto}</p>
          <p><b>PROPIETARIO(A):</b> ${d.propietario}</p>
          <p><b>C.C. / NIT:</b> ${d.cc || 'N/A'}</p>
          <p><b>COEFICIENTE P.H.:</b> ${d.coeficiente || '1.139%'}</p>
        </div>
        <div class="parte-box">
          <h4>${esAbogado ? '2. Condiciones de Liquidación de Cartera' : '2. Resumen del Estado de Cuenta'}</h4>
          <p><b>PERIODO ANALIZADO:</b> ${meses.length} Meses (${primerMes.periodo || ''} hasta ${ultMes.periodo || ''})</p>
          <p><b>TASA MORA APLICADA:</b> ${d.edificio?.interesMora || '2.10% M.V.'} (Límite Superfinanciera)</p>
          <p><b>FECHA DE EXPEDICIÓN:</b> ${fechaHoy}</p>
          <p><b>ESTADO DE CARTERA:</b> ${estadoCreditoTexto}</p>
        </div>
      </div>

      <div class="resumen-cards">
        <div class="card" style="border-left: 3px solid #000000;">
          <div class="title">Total Capital Causado (Cuotas)</div>
          <div class="value">${formatoMonedaSaldos(totalCapital)}</div>
        </div>
        <div class="card" style="border-left: 3px solid #000000;">
          <div class="title">Total Intereses de Mora</div>
          <div class="value">${formatoMonedaSaldos(totalIntereses)}</div>
        </div>
        <div class="card" style="border-left: 3px solid #000000;">
          <div class="title">Total Pagos y Abonos Imputados</div>
          <div class="value">${formatoMonedaSaldos(sumPagos)}</div>
        </div>
        <div class="card" style="border-left: 3px solid #000000; background: #f8fafc;">
          <div class="title">${labelSaldoCard}</div>
          <div class="value">${formatoMonedaSaldos(saldoFinalPeriodo)}</div>
        </div>
      </div>

      <table>
        <thead>
          <tr>
            <th style="width: 12%;">Periodo</th>
            <th style="width: 8%;" class="center">Factura / Cuenta</th>
            <th style="width: 14%;" class="right">Saldo Ant. Capital</th>
            <th style="width: 10%;" class="right">Int. Mora Ant.</th>
            <th style="width: 15%;" class="right">Cuota y Cargos Mes</th>
            <th style="width: 10%;" class="right">Int. Moratorio Mes</th>
            <th style="width: 13%;" class="right">Pagos / Abonos</th>
            <th style="width: 18%;" class="right">${labelColSaldo}</th>
          </tr>
        </thead>
        <tbody>
          ${filasHtml}
          <tr style="background-color: #0f172a; color: #ffffff; font-weight: 800; border-top: 2px solid #0f172a; page-break-inside: avoid;">
            <td style="padding: 6px; font-weight: 800; color: #ffffff; text-transform: uppercase;">TOTALES CONSOLIDADOS</td>
            <td style="padding: 6px; text-align: center; color: #cbd5e1; font-family: monospace;">${meses.length} Meses</td>
            <td style="padding: 6px; text-align: right; color: #ffffff; font-family: monospace; font-weight: bold;">${formatoMonedaSaldos(sumSaldoAntCap)}</td>
            <td style="padding: 6px; text-align: right; color: #ffffff; font-family: monospace; font-weight: bold;">${formatoMonedaSaldos(sumIntMoraAnt)}</td>
            <td style="padding: 6px; text-align: right; color: #ffffff; font-family: monospace; font-weight: bold;">${formatoMonedaSaldos(sumCuotaAdmon)}</td>
            <td style="padding: 6px; text-align: right; color: #ffffff; font-family: monospace; font-weight: bold;">${formatoMonedaSaldos(sumInteresMes)}</td>
            <td style="padding: 6px; text-align: right; color: #ffffff; font-family: monospace; font-weight: 800;">${formatoMonedaSaldos(sumPagos)}</td>
            <td style="padding: 6px; text-align: right; color: #ffffff; font-family: monospace; font-weight: 900; font-size: 10px;">${formatoMonedaSaldos(saldoFinalPeriodo)}</td>
          </tr>
        </tbody>
      </table>

      ${bloqueNotaLegal}
    </body>
    </html>
  `;

  // Imprimir mediante iframe invisible para eliminar pestaña y URL about:blank
  let iframe = document.getElementById("print-estudio-historico-frame");
  if (!iframe) {
    iframe = document.createElement("iframe");
    iframe.id = "print-estudio-historico-frame";
    iframe.style.position = "fixed";
    iframe.style.right = "0";
    iframe.style.bottom = "0";
    iframe.style.width = "0";
    iframe.style.height = "0";
    iframe.style.border = "0";
    iframe.style.visibility = "hidden";
    document.body.appendChild(iframe);
  }

  const iframeDoc = iframe.contentWindow.document;
  iframeDoc.open();
  iframeDoc.write(htmlContenido);
  iframeDoc.close();

  setTimeout(() => {
    try {
      iframe.contentWindow.focus();
      iframe.contentWindow.print();
    } catch (e) {
      const blob = new Blob([htmlContenido], { type: "text/html;charset=utf-8" });
      const url = URL.createObjectURL(blob);
      const v = window.open(url, "_blank");
      if (v) {
        v.onload = () => { v.print(); };
      }
    }
  }, 250);
}

