function abrirGmailCopropiedad() {

  const cAct = (typeof obtenerDatosCopropiedad === "function") ? obtenerDatosCopropiedad(AppState.codigoEdificio) : listaCopropiedadesSuperadmin.find(c => c.codigo === AppState.codigoEdificio);

  const email = (cAct && cAct.email) ? cAct.email.split(";")[0].trim() : "LefacturamosPH@lefacturamos.com";

  const nombre = cAct ? cAct.nombre : "EDIFICIO ROBLE ALTO P.H.";

  const subject = encodeURIComponent(`Gestión Administrativa - ${nombre}`);

  window.open(`https://mail.google.com/mail/?view=cm&fs=1&to=${email}&su=${subject}`, "_blank");

  mostrarToast(`📧 Abriendo Gmail para ${nombre}`);

}



