function cambiarVistaResidentes(vista) {

  estadoDirectorioResidentes.vista = vista;

  const cards = document.getElementById("residentes-cards-view");

  const table = document.getElementById("residentes-table-view");

  const btnTarjetas = document.getElementById("btn-vista-res-tarjetas");

  const btnTabla = document.getElementById("btn-vista-res-tabla");



  if (vista === "tarjetas") {

    cards?.classList.remove("hidden");

    table?.classList.add("hidden");

    if (btnTarjetas) btnTarjetas.className = "px-3 py-1.5 rounded-lg text-xs font-bold transition-all flex items-center gap-1.5 bg-slate-800 text-white shadow-sm";

    if (btnTabla) btnTabla.className = "px-3 py-1.5 rounded-lg text-xs font-bold transition-all flex items-center gap-1.5 text-slate-400 hover:text-white";

  } else {

    cards?.classList.add("hidden");

    table?.classList.remove("hidden");

    if (btnTarjetas) btnTarjetas.className = "px-3 py-1.5 rounded-lg text-xs font-bold transition-all flex items-center gap-1.5 text-slate-400 hover:text-white";

    if (btnTabla) btnTabla.className = "px-3 py-1.5 rounded-lg text-xs font-bold transition-all flex items-center gap-1.5 bg-slate-800 text-white shadow-sm";

  }

  safeCreateIcons();

}



function filtrarDirectorioResidentes(val) {

  estadoDirectorioResidentes.query = val;

  renderizarDirectorioResidentes();

}



function filtrarTipoResidentes(tipo) {

  estadoDirectorioResidentes.filtroTipo = tipo;

  ['todos', 'propietarios', 'inquilinos'].forEach(t => {

    const btn = document.getElementById(`filtro-res-${t}`);

    if (btn) {

      if (t === tipo) {

        btn.className = "btn-filtro-res active px-3.5 py-1.5 rounded-xl bg-slate-800 text-white border border-slate-700 text-xs font-bold transition-all shadow-sm";

      } else {

        btn.className = "btn-filtro-res px-3.5 py-1.5 rounded-xl bg-slate-950 hover:bg-slate-800 text-slate-400 hover:text-white border border-slate-800 text-xs font-bold transition-all";

      }

    }

  });

  renderizarDirectorioResidentes();

}



function copiarFichaResidente(id) {

  const r = DIRECTORIO_RESIDENTES_DATA.find(item => item.id === id);

  if (!r) return;



  const textoFicha = `================================================

FICHA TÉCNICA RESIDENTE - COPROPIEDAD OFICIAL

================================================

Inmueble: ${r.inmueble}

Condición: ${r.tipo === 'propietario' ? 'Propietario Titular' : 'Inquilino / Arrendatario'}

Nombre: ${r.nombre}

Documento: ${r.documento}

Teléfono: ${r.tel}

Email: ${r.email}

Parqueadero: ${r.parqueadero || "No tiene"}

Cuarto Útil: ${r.cuartoUtil || "No tiene"}

Coeficiente: ${r.coeficiente} | Área: ${r.area}

Estado Cartera: ${r.cartera}

Clave Digital de Acceso: ${r.clave}

================================================`;



  if (navigator.clipboard && navigator.clipboard.writeText) {

    navigator.clipboard.writeText(textoFicha).then(() => {

      mostrarToast(`📋 Ficha de ${r.inmueble} copiada al portapapeles`);

    }).catch(() => {

      mostrarToast(`📋 Ficha de ${r.inmueble} generada`);

    });

  } else {

    mostrarToast(`📋 Ficha de ${r.inmueble} copiada`);

  }

}



function editarResidente(id) {

  const r = DIRECTORIO_RESIDENTES_DATA.find(item => item.id === id);

  if (!r) return;

  editarInmuebleInventario(r.apto);

}



function abrirModalNuevoResidente() {

  document.getElementById("modal-nuevo-residente")?.classList.remove("hidden");

  safeCreateIcons();

}



function cerrarModalNuevoResidente() {

  document.getElementById("modal-nuevo-residente")?.classList.add("hidden");

}



function guardarNuevoResidente(e) {

  if (e) e.preventDefault();

  const torre = document.getElementById("nuevo-res-torre").value.trim();

  const apto = document.getElementById("nuevo-res-apto").value.trim();

  const tipo = document.getElementById("nuevo-res-tipo").value;

  const nombre = document.getElementById("nuevo-res-nombre").value.trim();

  const doc = document.getElementById("nuevo-res-doc").value.trim();

  const tel = document.getElementById("nuevo-res-tel").value.trim();

  const email = document.getElementById("nuevo-res-email").value.trim();

  const pk = document.getElementById("nuevo-res-pk").value.trim() || "";

  const cu = document.getElementById("nuevo-res-cu").value.trim() || "";

  const area = document.getElementById("nuevo-res-area").value.trim() || "80 m²";

  const coef = document.getElementById("nuevo-res-coef").value.trim() || "1.000%";

  const cartera = document.getElementById("nuevo-res-cartera").value;

  const clave = document.getElementById("nuevo-res-clave").value.trim() || "1234";



  const nuevo = {

    id: `res_user_${Date.now()}`,

    torre: torre,

    apto: apto,

    inmueble: `${torre} • Apto ${apto}`,

    tipo: tipo,

    titularBadge: tipo === "propietario" ? "Propietario Titular" : "Inquilino / Ocupante",

    nombre: nombre,

    documento: doc,

    tel: tel,

    email: email,

    parqueadero: pk,

    cuartoUtil: cu,

    coeficiente: coef,

    area: area,

    cartera: cartera,

    alDia: cartera.includes("Al día"),

    clave: clave,

    inquilino: null

  };



  DIRECTORIO_RESIDENTES_DATA.unshift(nuevo);

  cerrarModalNuevoResidente();

  renderizarDirectorioResidentes();

  mostrarToast(`✓ Residente ${nombre} registrado en censo exitosamente`);

}



