function renderizarInformesGeneralesDrive() {

  const cont = document.getElementById("drive-grid-informes-generales");

  if (!cont) return;



  const badgeInformes = document.getElementById("drive-badge-conteo-informes");

  if (badgeInformes) {

    badgeInformes.innerText = driveInformesGeneralesData ? driveInformesGeneralesData.length : 6;

  }



  if (!driveInformesGeneralesData || driveInformesGeneralesData.length === 0) {

    generarDocumentosDriveLocal();

  }



  cont.innerHTML = driveInformesGeneralesData.map(inf => {

    const tienePDF = inf.formatos && inf.formatos.includes("PDF");

    const tieneXLSX = inf.formatos && inf.formatos.includes("XLSX");

    const descripcion = inf.subtitulo || inf.descripcion || "Listado oficial consolidado para la copropiedad.";



    return `

      <div class="p-4 rounded-2xl bg-slate-900/90 border border-slate-800 hover:border-amber-500/40 transition-all flex flex-col justify-between space-y-3 group shadow-lg">

        <div>

          <!-- Header de Tarjeta: Ícono + Badges Formato -->

          <div class="flex items-start justify-between gap-2">

            <div class="w-9 h-9 rounded-xl ${inf.tipo === 'FACTURACION' ? 'bg-amber-500/20 text-amber-400' : (inf.tipo === 'PLANILLA' ? 'bg-emerald-500/20 text-emerald-400' : 'bg-sky-500/20 text-sky-400')} flex items-center justify-center shrink-0">

              <i data-lucide="${inf.tipo === 'PLANILLA' ? 'file-spreadsheet' : 'file-text'}" class="w-5 h-5"></i>

            </div>

            <div class="flex items-center gap-1.5 shrink-0">

              ${tienePDF ? '<span class="px-2 py-0.5 rounded text-[10px] font-black bg-rose-500/20 text-rose-400 border border-rose-500/30">PDF</span>' : ''}

              ${tieneXLSX ? '<span class="px-2 py-0.5 rounded text-[10px] font-black bg-emerald-500/20 text-emerald-400 border border-emerald-500/30">EXCEL</span>' : ''}

            </div>

          </div>



          <!-- Título Oficial del Informe -->

          <h5 class="text-xs font-black text-white mt-2.5 leading-snug tracking-tight font-mono">

            ${inf.titulo}

          </h5>

          <p class="text-[11px] text-slate-400 mt-1 line-clamp-2">

            ${descripcion}

          </p>

        </div>



        <!-- Botones de Acción Oficiales -->

        <div class="pt-2 border-t border-slate-800/80 space-y-2">

          <div class="grid grid-cols-2 gap-1.5">

            ${tienePDF ? `

              <button type="button" onclick="descargarDocumentoDriveDirecto('${inf.id}', 'PDF')" class="px-2 py-1.5 rounded-lg bg-rose-600/20 hover:bg-rose-600/30 text-rose-300 font-bold text-[11px] flex items-center justify-center gap-1 transition-all cursor-pointer">

                <i data-lucide="download" class="w-3 h-3"></i>

                <span>Descargar PDF</span>

              </button>

            ` : ''}

            ${tieneXLSX ? `

              <button type="button" onclick="descargarDocumentoDriveDirecto('${inf.id}', 'XLSX')" class="px-2 py-1.5 rounded-lg bg-emerald-600/20 hover:bg-emerald-600/30 text-emerald-300 font-bold text-[11px] flex items-center justify-center gap-1 transition-all cursor-pointer ${!tienePDF ? 'col-span-2' : ''}">

                <i data-lucide="file-spreadsheet" class="w-3 h-3"></i>

                <span>Descargar Excel</span>

              </button>

            ` : ''}

          </div>



          <div class="flex items-center justify-between pt-1 text-[11px] text-slate-400">

            <button type="button" onclick="verDocumentoDriveEnModal('${inf.id}')" title="${tienePDF ? 'Ver PDF Oficial' : 'Ver Detalle Excel'}" class="px-2.5 py-1.5 rounded-lg ${tienePDF ? 'bg-amber-500/15 hover:bg-amber-500/25 text-amber-300 border border-amber-500/30' : 'bg-emerald-500/15 hover:bg-emerald-500/25 text-emerald-300 border border-emerald-500/30'} font-bold flex items-center gap-1.5 transition-all cursor-pointer">

              <i data-lucide="eye" class="w-3.5 h-3.5"></i>

              <span>${tienePDF ? 'Ver PDF' : 'Ver Detalle'}</span>

            </button>

            <span class="text-[10px] text-slate-400 font-mono">${inf.tam_pdf || inf.tam_xlsx || 'Oficial'}</span>

          </div>

        </div>

      </div>

    `;

  }).join("");





  safeCreateIcons();

}



function renderizarDocumentosInmueblesDrive(docs) {

  const cont = document.getElementById("drive-lista-documentos-inmuebles");

  if (!cont) return;



  const lista = docs || driveDocumentosFiltrados;

  const esResidente = (typeof AppState !== "undefined" && AppState.rol === "residente");

  const badgeConteo = document.getElementById("drive-badge-conteo-inmuebles");

  if (badgeConteo) badgeConteo.innerText = esResidente ? lista.length : driveDocumentosInmueblesData.length;



  const lblFiltrados = document.getElementById("drive-contador-inmuebles-filtrados");

  if (lblFiltrados) lblFiltrados.innerText = `${lista.length} documentos`;



  if (lista.length === 0) {

    cont.innerHTML = `

      <div class="col-span-full py-8 text-center text-slate-500">

        <i data-lucide="search-x" class="w-8 h-8 mx-auto mb-2 opacity-40"></i>

        <p class="text-xs">No se encontraron facturas o recibos para tu inmueble en este periodo.</p>

      </div>

    `;

    safeCreateIcons();

    return;

  }



  cont.innerHTML = lista.map(doc => {

    const esFac = doc.tipo === "FACTURA";



    return `

      <div class="p-3.5 rounded-xl bg-slate-900 border border-slate-800 hover:border-slate-700 transition-all flex flex-col justify-between space-y-2.5 shadow-sm">

        <div class="flex items-start justify-between gap-2">

          <div class="flex items-center gap-2.5 min-w-0">

            <div class="w-8 h-8 rounded-lg ${esFac ? 'bg-amber-500/10 text-amber-400' : 'bg-emerald-500/10 text-emerald-400'} flex items-center justify-center shrink-0">

              <i data-lucide="${esFac ? 'receipt' : 'check-circle-2'}" class="w-4 h-4"></i>

            </div>

            <div class="min-w-0">

              <div class="flex items-center gap-1.5">

                <span class="px-1.5 py-0.2 rounded text-[9px] font-black uppercase ${esFac ? 'bg-amber-500/20 text-amber-400' : 'bg-emerald-500/20 text-emerald-400'}">

                  ${esFac ? 'Factura' : 'Recibo Caja'}

                </span>

                <span class="text-xs font-mono font-bold text-white">${doc.apto}</span>

              </div>

              <p class="text-xs font-semibold text-slate-200 truncate mt-0.5">${doc.propietario}</p>

            </div>

          </div>

          <div class="text-right shrink-0">

            <span class="text-xs font-black text-white font-mono">${doc.valor}</span>

            <p class="text-[10px] text-slate-400 font-mono">${doc.periodo}</p>

          </div>

        </div>



        <!-- Nombre oficial del documento en la nube de Lefacturamos -->

        <div class="p-2 rounded-lg bg-slate-950 text-[10px] font-mono text-slate-300 truncate" title="${doc.nombre_archivo}">

          ${doc.nombre_archivo}

        </div>



        <!-- Botones de Acción (Aislamiento Total: El residente NO ve enlaces a Google Drive) -->

        <div class="flex items-center justify-between pt-1 border-t border-slate-800 text-xs">

          <div class="flex items-center gap-1.5 flex-wrap">

            <button type="button" onclick="descargarDocumentoDriveDirecto('${doc.id}', 'PDF')" class="px-2.5 py-1.5 rounded-lg bg-slate-800 hover:bg-slate-700 text-amber-400 font-bold text-[11px] flex items-center gap-1 transition-all cursor-pointer">

              <i data-lucide="download" class="w-3.5 h-3.5"></i>

              <span>Descargar PDF</span>

            </button>

            <button type="button" onclick="verDocumentoDriveEnModal('${doc.id}')" title="Ver PDF" class="px-2.5 py-1.5 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-bold text-[11px] flex items-center gap-1 transition-colors cursor-pointer">

              <i data-lucide="eye" class="w-3.5 h-3.5"></i>

              <span>Ver PDF</span>

            </button>

          </div>



          <div class="flex items-center gap-1.5">

            ${(esResidente && esFac) ? `

              <button type="button" onclick="cambiarPestana('pagos')" class="px-3 py-1.5 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-white font-black text-[11px] flex items-center gap-1 shadow-md shadow-emerald-950/40 transition-all active:scale-95 cursor-pointer">

                <i data-lucide="credit-card" class="w-3.5 h-3.5"></i>

                <span>Pagar Cuota</span>

              </button>

            ` : (esResidente ? '' : `

              <button type="button" onclick="compartirDocumentoWhatsApp('${doc.id}')" title="Enviar enlace por WhatsApp" class="p-1.5 rounded-lg bg-emerald-600/20 hover:bg-emerald-600/30 text-emerald-400 transition-colors cursor-pointer">

                <i data-lucide="message-circle" class="w-3.5 h-3.5"></i>

              </button>

              <a href="${doc.drive_url}" target="_blank" rel="noopener noreferrer" title="Abrir en Google Drive" class="p-1.5 rounded-lg bg-slate-800 hover:bg-slate-700 text-sky-400 transition-colors">

                <i data-lucide="external-link" class="w-3.5 h-3.5"></i>

              </a>

            `)}

          </div>

        </div>

      </div>

    `;

  }).join("");





  safeCreateIcons();

}



function filtrarDocumentosInmueblesDrive() {

  const esResidente = (typeof AppState !== "undefined" && AppState.rol === "residente");

  const aptoActual = (typeof AppState !== "undefined" && AppState.aptoNumero) ? String(AppState.aptoNumero).trim() : "0107";

  const numActual = parseInt(aptoActual.replace(/\D/g, ""), 10);



  // 1. Gestionar visibilidad del banner del residente y barra de busqueda

  const bannerResidente = document.getElementById("drive-banner-residente-inmueble");

  const barraFiltros = document.getElementById("drive-barra-filtros-inmuebles");

  if (bannerResidente) {

    if (esResidente) {

      bannerResidente.classList.remove("hidden");

      bannerResidente.classList.add("flex");

      const bApto = document.getElementById("drive-banner-residente-apto");

      const bProp = document.getElementById("drive-banner-residente-prop");

      const bTot = document.getElementById("drive-banner-residente-total");

      const bEstBox = document.getElementById("drive-banner-residente-estado-box");

      if (bApto) bApto.innerText = `Apartamento ${AppState.aptoNumero}`;

      if (bProp) bProp.innerText = AppState.propietario || "Propietario";

      if (bTot) bTot.innerText = `$${Number(AppState.saldoTotal).toLocaleString('es-CO')} COP`;

      if (bEstBox) {

        // Calcular saldo pendiente total considerando todos los conceptos pendientes (mora ant., notas, extras, multas, etc.)
        let pendTotal = 0;
        try {
          const edifCod = AppState.codigoEdificio || AppState.conjuntoId || "4901";
          const cleanCod = String(edifCod).replace(/^(cj_)+/, "").trim() || "4901";
          const cj = (typeof obtenerDatosCopropiedad === "function") ? obtenerDatosCopropiedad(cleanCod) : null;
          const unidades = (cj && cj.unidades) || ((typeof obtenerUnidadesActivas === "function") ? obtenerUnidadesActivas() : []);
          const aptoBuscado = String(AppState.aptoNumero || "").trim();
          const uEncontrada = unidades.find(u => {
            const uCod = String(u.unidad || u.apto || "").trim();
            return uCod.toLowerCase() === aptoBuscado.toLowerCase() || parseInt(uCod.replace(/\D/g, ""), 10) === parseInt(aptoBuscado.replace(/\D/g, ""), 10);
          });
          if (uEncontrada) {
            const p_pend = parseFloat(uEncontrada.pend) || 0;
            const p_intp = parseFloat(uEncontrada.intp) || 0;
            const p_ndncp = parseFloat(uEncontrada.ndncp) || 0;
            const p_extrap = parseFloat(uEncontrada.extrap) || 0;
            const p_otrosp = parseFloat(uEncontrada.otrosp) || 0;
            const p_multap = parseFloat(uEncontrada.multap) || 0;
            const p_serpup = parseFloat(uEncontrada.serpup) || 0;
            const p_servip = parseFloat(uEncontrada.servip) || 0;
            pendTotal = (uEncontrada.saldoPendienteNum !== undefined && !isNaN(uEncontrada.saldoPendienteNum))
              ? parseFloat(uEncontrada.saldoPendienteNum)
              : (p_pend + p_intp + p_ndncp + p_extrap + p_otrosp + p_multap + p_serpup + p_servip);
          }
        } catch (eCalc) {
          console.warn("Aviso calculando saldo pendiente total:", eCalc);
        }

        if (!pendTotal) {
          pendTotal = Number(AppState.saldoPendienteTotal !== undefined ? AppState.saldoPendienteTotal : AppState.pend) || 0;
        }

        const esMora = (AppState.estado === "En Mora" || pendTotal > 0);

        bEstBox.innerHTML = esMora

          ? `<span class="px-2.5 py-1 rounded-lg text-xs font-bold bg-rose-950 text-rose-400 border border-rose-800">En Mora (Pend: $${Number(pendTotal).toLocaleString('es-CO')})</span>`

          : `<span class="px-2.5 py-1 rounded-lg text-xs font-bold bg-emerald-950 text-emerald-400 border border-emerald-800">Al Dia (Paz y Salvo)</span>`;

      }

    } else {

      bannerResidente.classList.add("hidden");

      bannerResidente.classList.remove("flex");

    }

  }



  // Ocultar barra de busqueda y filtros para copropietarios (solo ven sus propios cuadros)

  if (barraFiltros) {

    if (esResidente) {

      barraFiltros.classList.add("hidden");

    } else {

      barraFiltros.classList.remove("hidden");

    }

  }



  const q = (document.getElementById("drive-filtro-inmueble-busqueda")?.value || "").toLowerCase().trim();

  const tipo = document.getElementById("drive-filtro-tipo-doc")?.value || "TODOS";



  driveDocumentosFiltrados = driveDocumentosInmueblesData.filter(d => {

    // Si es residente, AISLAMIENTO 100% ESTRICTO: EXCLUSIVAMENTE los cuadros de su apartamento

    if (esResidente && aptoActual) {

      const aptoDoc = String(d.apto || "").trim();

      const numDoc = parseInt(aptoDoc.replace(/\D/g, ""), 10);

      const coincide = (aptoDoc.toLowerCase() === aptoActual.toLowerCase()) ||

                       (!isNaN(numActual) && !isNaN(numDoc) && numActual === numDoc);

      if (!coincide) return false;

    }



    const matchTipo = (tipo === "TODOS") || (d.tipo === tipo);

    const matchQ = !q || 

      d.apto.toLowerCase().includes(q) ||

      d.propietario.toLowerCase().includes(q) ||

      d.nombre_archivo.toLowerCase().includes(q);

    return matchTipo && matchQ;

  });



  renderizarDocumentosInmueblesDrive(driveDocumentosFiltrados);

}



function cambiarSubtabDrive(subtab) {

  const esResidente = (typeof AppState !== "undefined" && AppState.rol === "residente");
  if (esResidente && subtab === "informes") {
    subtab = "inmuebles";
  }

  driveSubtabActual = subtab;



  const tabInformes = document.getElementById("subtab-drive-informes");

  const tabInmuebles = document.getElementById("subtab-drive-inmuebles");



  const btnInformes = document.getElementById("btn-subtab-drive-informes");

  const btnInmuebles = document.getElementById("btn-subtab-drive-inmuebles");



  if (tabInformes) tabInformes.classList.toggle("hidden", subtab !== "informes" || esResidente);

  if (tabInmuebles) tabInmuebles.classList.toggle("hidden", subtab !== "inmuebles" && !esResidente);



  if (btnInformes) {

    if (esResidente) {
      btnInformes.classList.add("hidden");
      btnInformes.style.display = "none";
    } else {
      btnInformes.style.display = "flex";
      btnInformes.className = subtab === "informes"

        ? "px-3.5 py-1.5 rounded-xl bg-amber-500 text-slate-950 font-black text-xs flex items-center gap-1.5 transition-all shadow-sm cursor-pointer"

        : "px-3.5 py-1.5 rounded-xl bg-slate-900 hover:bg-slate-800 text-slate-300 border border-slate-700 font-bold text-xs flex items-center gap-1.5 transition-all cursor-pointer";
    }

  }



  if (btnInmuebles) {

    btnInmuebles.className = (subtab === "inmuebles" || esResidente)

      ? "px-3.5 py-1.5 rounded-xl bg-amber-500 text-slate-950 font-black text-xs flex items-center gap-1.5 transition-all shadow-sm cursor-pointer"

      : "px-3.5 py-1.5 rounded-xl bg-slate-900 hover:bg-slate-800 text-slate-300 border border-slate-700 font-bold text-xs flex items-center gap-1.5 transition-all cursor-pointer";

  }



  // Asegurar que los datos locales existan antes de renderizar
  if (!driveInformesGeneralesData || driveInformesGeneralesData.length === 0 ||
      !driveDocumentosInmueblesData || driveDocumentosInmueblesData.length === 0) {
    if (typeof generarDocumentosDriveLocal === "function") {
      generarDocumentosDriveLocal();
    }
  }

  // Renderizar la vista de la subpestaña seleccionada (SIN llamar actualizarDocumentosDrive para evitar ciclos)
  if (subtab === "informes" && !esResidente) {
    renderizarInformesGeneralesDrive();
  } else {
    filtrarDocumentosInmueblesDrive();
  }

  safeCreateIcons();

}



function cargarDatosDriveExplorador(forzar = false) {

  mostrarToast("Sincronizando documentos...");

  inicializarModuloDriveInformes(true);

  setTimeout(() => {

    mostrarToast("✓ Documentos sincronizados con éxito");

  }, 700);

}



function descargarDocumentoDriveDirecto(docId, formato) {

  let doc = null;

  if (Array.isArray(driveInformesGeneralesData)) {

    doc = driveInformesGeneralesData.find(d => d.id === docId);

    if (!doc) {

      doc = driveInformesGeneralesData.find(d => d.titulo === docId || (d.id && docId && (d.id.includes(docId) || docId.includes(d.id))));

    }

  }

  if (!doc && Array.isArray(driveDocumentosInmueblesData)) {

    doc = driveDocumentosInmueblesData.find(d => d.id === docId);

    if (!doc) {

      doc = driveDocumentosInmueblesData.find(d => d.nombre_archivo === docId || (d.id && docId && (d.id.includes(docId) || docId.includes(d.id))));

    }

  }

  const esResidente = (typeof AppState !== "undefined" && AppState.rol === "residente");

  if (!doc && esResidente && Array.isArray(driveDocumentosInmueblesData)) {

    if (docId && (docId.includes("fac_") || docId.includes("fac"))) {

      doc = driveDocumentosInmueblesData.find(d => d.tipo === "FACTURA");

    } else {

      doc = driveDocumentosInmueblesData.find(d => d.tipo === "RECIBO_CAJA");

    }

  }

  if (!doc) {

    mostrarToast("Documento no encontrado");

    return;

  }



  const cod = driveEdificioSeleccionado || (typeof AppState !== "undefined" ? AppState.codigoEdificio : "4901");

  const anio = (typeof driveAnioSeleccionado !== "undefined") ? driveAnioSeleccionado : 2026;

  const mes = (typeof driveMesSeleccionado !== "undefined") ? driveMesSeleccionado : "OCTUBRE";

  

  let nombreArchivo = "";

  let urlDescarga = "";



  if (formato === "XLSX") {

    if (!doc.archivo_xlsx) {

      const nomEdif = (cod === "4901") ? "EDIFICIO ROBLE ALTO P.H." : "COPROPIEDAD";

      if (doc.tipo === "RECIBO_CAJA") {

        doc.archivo_xlsx = `${nomEdif}.-- LISTADO DE RECIBOS DE CAJA  -- ${mes} DE ${anio}.XLSX`;

      } else {

        doc.archivo_xlsx = `${nomEdif}.-- LISTADO DE FACTURACION  -- ${mes} DE ${anio}.XLSX`;

      }

    }

    nombreArchivo = doc.archivo_xlsx || `${doc.titulo || doc.nombre_archivo}.xlsx`;

    urlDescarga = doc.url_xlsx || `/api/drive/archivo?edificio=${encodeURIComponent(cod)}&anio=${encodeURIComponent(anio)}&mes=${encodeURIComponent(mes)}&archivo=${encodeURIComponent(nombreArchivo)}&descargar=true`;

  } else {

    nombreArchivo = doc.archivo_pdf || doc.nombre_archivo || `${doc.titulo}.pdf`;

    urlDescarga = doc.url_descarga || (doc.url_pdf ? `${doc.url_pdf}&descargar=true` : `/api/drive/archivo?edificio=${encodeURIComponent(cod)}&anio=${encodeURIComponent(anio)}&mes=${encodeURIComponent(mes)}&archivo=${encodeURIComponent(nombreArchivo)}&descargar=true`);

  }



  const link = document.createElement("a");

  link.href = urlDescarga;

  link.download = nombreArchivo;

  link.target = "_blank";

  document.body.appendChild(link);

  link.click();

  document.body.removeChild(link);

  mostrarToast(`✓ Descargando archivo oficial de Google Drive: ${nombreArchivo}`);

}



function verDocumentoDriveEnModal(docId) {

  let doc = null;

  let esGeneral = false;

  if (Array.isArray(driveInformesGeneralesData)) {

    doc = driveInformesGeneralesData.find(d => d.id === docId);

    if (!doc) {

      doc = driveInformesGeneralesData.find(d => d.titulo === docId || (d.id && docId && (d.id.includes(docId) || docId.includes(d.id))));

    }

    if (doc) esGeneral = true;

  }

  if (!doc && Array.isArray(driveDocumentosInmueblesData)) {

    doc = driveDocumentosInmueblesData.find(d => d.id === docId);

    if (!doc) {

      doc = driveDocumentosInmueblesData.find(d => d.nombre_archivo === docId || (d.id && docId && (d.id.includes(docId) || docId.includes(d.id))));

    }

  }

  const esResidente = (typeof AppState !== "undefined" && AppState.rol === "residente");

  if (!doc && esResidente && Array.isArray(driveDocumentosInmueblesData)) {

    if (docId && (docId.includes("fac_") || docId.includes("fac"))) {

      doc = driveDocumentosInmueblesData.find(d => d.tipo === "FACTURA");

    } else {

      doc = driveDocumentosInmueblesData.find(d => d.tipo === "RECIBO_CAJA");

    }

  }

  if (!doc) {

    mostrarToast("Documento no disponible");

    return;

  }

  const codEdif = driveEdificioSeleccionado || (typeof AppState !== "undefined" ? AppState.codigoEdificio : "4901");

  const anio = (typeof driveAnioSeleccionado !== "undefined") ? driveAnioSeleccionado : 2026;

  const mes = (typeof driveMesSeleccionado !== "undefined") ? driveMesSeleccionado : "OCTUBRE";

  const nombreArchivo = doc.archivo_pdf || doc.nombre_archivo || doc.archivo_xlsx || `${doc.titulo || 'documento'}.pdf`;

  const urlPdfReal = doc.url_ver || `/api/drive/archivo?edificio=${encodeURIComponent(codEdif)}&anio=${encodeURIComponent(anio)}&mes=${encodeURIComponent(mes)}&archivo=${encodeURIComponent(nombreArchivo)}`;

  const esPdf = !!(doc.archivo_pdf || (doc.nombre_archivo && doc.nombre_archivo.toUpperCase().endsWith(".PDF")) || doc.tipo === "FACTURA" || doc.tipo === "RECIBO_CAJA" || (doc.formatos && doc.formatos.includes("PDF")));

  const esSoloExcel = !esPdf && !!(doc.archivo_xlsx || (doc.formatos && doc.formatos.includes("XLSX")));

  docDriveActualSeleccionado = {

    id: doc.id,

    tipo: doc.tipo || (esGeneral ? "INFORME" : "FACTURA"),

    nombre: nombreArchivo,

    url: urlPdfReal,

    url_descarga: doc.url_descarga || `/api/drive/archivo?edificio=${encodeURIComponent(codEdif)}&anio=${encodeURIComponent(anio)}&mes=${encodeURIComponent(mes)}&archivo=${encodeURIComponent(nombreArchivo)}&descargar=true`,

    archivo_xlsx: doc.archivo_xlsx,

    url_xlsx: doc.url_xlsx,

    tiene_xlsx: !!(doc.archivo_xlsx || (doc.formatos && doc.formatos.includes("XLSX"))),

    esSoloExcel: esSoloExcel

  };

  // 1. Poblar Encabezado del Visor

  const elTitulo = document.getElementById("modal-ver-doc-titulo");

  const elSubtitulo = document.getElementById("modal-ver-doc-subtitulo");

  const elBadgeTipo = document.getElementById("modal-ver-doc-badge-tipo");

  if (elTitulo) elTitulo.innerText = doc.tipo === "FACTURA" ? "Factura Oficial de Administración" : (doc.tipo === "RECIBO_CAJA" ? "Recibo Oficial de Caja" : (doc.titulo || "Informe Oficial"));

  if (elSubtitulo) elSubtitulo.innerText = nombreArchivo;

  if (elBadgeTipo) elBadgeTipo.innerText = esSoloExcel ? "EXCEL OFICIAL" : "GOOGLE DRIVE OFICIAL";

  // 2. Alternar entre visor PDF (iframe nativo) y visor Excel (tarjeta de detalle oficial)

  const iframe = document.getElementById("visor-pdf-iframe");

  const fallbackExcel = document.getElementById("visor-excel-fallback");

  const btnAbrirPestana = document.getElementById("modal-ver-doc-btn-abrir-pestana");

  const btnImprimir = document.getElementById("modal-ver-doc-btn-imprimir");

  if (esSoloExcel) {

    if (iframe) {

      iframe.classList.add("hidden");

      iframe.style.display = "none";

      iframe.src = "";

    }

    if (fallbackExcel) {

      fallbackExcel.classList.remove("hidden");

      fallbackExcel.style.display = "flex";

      const elExcelNombre = document.getElementById("visor-excel-nombre");

      const elExcelDesc = document.getElementById("visor-excel-desc");

      if (elExcelNombre) elExcelNombre.innerText = doc.archivo_xlsx || nombreArchivo;

      if (elExcelDesc) elExcelDesc.innerText = doc.subtitulo || doc.descripcion || "Documento contable oficial en formato Excel para conciliacion, registro y auditoria del edificio.";

    }

    if (btnAbrirPestana) btnAbrirPestana.classList.add("hidden");

    if (btnImprimir) btnImprimir.classList.add("hidden");

  } else {

    if (fallbackExcel) {

      fallbackExcel.classList.add("hidden");

      fallbackExcel.style.display = "none";

    }

    if (iframe) {

      iframe.classList.remove("hidden");

      iframe.style.display = "block";

      iframe.src = urlPdfReal;

    }

    if (btnAbrirPestana) btnAbrirPestana.classList.remove("hidden");

    if (btnImprimir) btnImprimir.classList.remove("hidden");

  }

  // 3. Botones de Acción

  const btnPagar = document.getElementById("modal-ver-doc-btn-pagar");

  const btnDescargar = document.getElementById("modal-ver-doc-btn-descargar");

  const btnWa = document.getElementById("modal-ver-doc-btn-whatsapp");

  const linkDrive = document.getElementById("modal-ver-doc-link-externo");

  if (btnPagar) btnPagar.classList.toggle("hidden", !esResidente || doc.tipo !== "FACTURA");

  if (btnDescargar) btnDescargar.classList.toggle("hidden", !!esSoloExcel);

  if (btnWa) btnWa.classList.toggle("hidden", esResidente);

  if (linkDrive) linkDrive.classList.add("hidden"); // Proteger enlace raíz al residente

  const modal = document.getElementById("modal-ver-documento-drive");

  if (modal) {

    modal.classList.remove("hidden");

    modal.style.display = "flex";

    safeCreateIcons();

  }

}



