function descargarExcelConsolidadoDocumentos() {

  let csv = "\uFEFF"; // UTF-8 BOM para Excel

  csv += "ID;CARPETA;NOMBRE_DOCUMENTO;FORMATO;TAMANIO;FECHA;APTO_DESTINO;URL_DRIVE\r\n";

  DOCUMENTOS_DRIVE_DATA.forEach(d => {

    csv += `"${d.id}";"${d.carpetaNombre}";"${d.nombre}";"${d.formato}";"${d.tamanio}";"${d.fecha}";"${d.apto}";"${d.url}"\r\n`;

  });



  const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });

  const link = document.createElement("a");

  const url = URL.createObjectURL(blob);

  link.setAttribute("href", url);

  link.setAttribute("download", `CONSOLIDADO_DOCUMENTOS_GOOGLE_DRIVE_${driveAnioSeleccionado}.csv`);

  document.body.appendChild(link);

  link.click();

  document.body.removeChild(link);

  mostrarToast("✓ Consolidado Excel generado y descargado exitosamente");

}









// Manejador del Selector en Menú Vertical: ¿A qué edificio vas a hacerle cambio?

function onCambioEdificioSidebar(valor) {

  if (!valor) return;

  ejecutarCambioEdificioPorCodigo(valor);

}



function onInputCodigoEdificioSidebar(valor) {

  const limpio = String(valor || "").trim().toLowerCase();

  const sel = document.getElementById("sidebar-sel-cambio-edificio");

  if (!sel || !limpio) return;

  const opt = Array.from(sel.options).find(o => 

    o.value.toLowerCase() === limpio || 

    o.value.toLowerCase() === ("cj_" + limpio) ||

    o.text.toLowerCase().includes(limpio)

  );

  if (opt) {

    sel.value = opt.value;

  }

}



async function ejecutarCambioEdificioPorCodigo(codigoInput) {
  const limpio = String(codigoInput || "").trim().replace(/^cj_/, "");
  if (!limpio) {
    if (typeof mostrarToast === "function") {
      mostrarToast("⚠️ Por favor escribe el código del edificio (ej: 4901 o 7480)", "warning");
    }
    const inp = document.getElementById("sidebar-input-codigo-edificio") || document.getElementById("main-input-buscar-edificio");
    if (inp) inp.focus();
    return;
  }

  // 1. Buscar si la copropiedad existe REALMENTE en la plataforma
  let copropiedadEncontrada = (typeof obtenerDatosCopropiedad === "function") ? obtenerDatosCopropiedad(limpio) : null;
  if (!copropiedadEncontrada && typeof listaCopropiedadesSuperadmin !== "undefined") {
    copropiedadEncontrada = listaCopropiedadesSuperadmin.find(c => 
      c && (String(c.codigo).trim().toLowerCase() === limpio.toLowerCase() || String(c.id).toLowerCase() === `cj_${limpio.toLowerCase()}`)
    );
  }

  // SI NO EXISTE: CÓDIGO INCORRECTO. NUNCA CREAR UN EDIFICIO FICTICIO.
  if (!copropiedadEncontrada) {
    if (typeof mostrarToast === "function") {
      mostrarToast(`⚠️ Código incorrecto (#${limpio}). El edificio no existe en la plataforma.`, "error");
    }
    const inp = document.getElementById("sidebar-input-codigo-edificio") || document.getElementById("main-input-buscar-edificio");
    if (inp) {
      inp.focus();
      inp.classList.add("border-rose-500", "text-rose-400");
      setTimeout(() => {
        inp.classList.remove("border-rose-500", "text-rose-400");
      }, 3000);
    }
    return;
  }

  // 2. Si existe: Activar filtro exclusivo para mostrar SOLO el cuadro de este edificio real
  edificioFiltroCodigoSuperadmin = copropiedadEncontrada.codigo;

  // 3. Si la app principal está oculta, abrirla
  try {
    const pantallaEntrada = document.getElementById("pantalla-entrada");
    const appPrincipal = document.getElementById("app-principal");
    if (pantallaEntrada && !pantallaEntrada.classList.contains("hidden")) {
      pantallaEntrada.classList.add("hidden");
      pantallaEntrada.style.display = "none";
    }
    if (appPrincipal) {
      appPrincipal.classList.remove("hidden");
      appPrincipal.style.display = "flex";
    }
  } catch (e) {}

  // 4. Cambiar a rol Superadministrador y sub-pestaña de Conjuntos
  try {
    if (typeof cambiarRolActivo === "function") cambiarRolActivo("superadmin");
    if (typeof cambiarPestana === "function") cambiarPestana("superadmin");
    if (typeof cambiarSubtabSuperadmin === "function") cambiarSubtabSuperadmin("conjuntos");
  } catch (e) {}

  // 5. Renderizar el cuadro del edificio real
  if (typeof renderizarCopropiedadesSuperadmin === "function") {
    renderizarCopropiedadesSuperadmin();
  }



  // 6. Sincronizar inputs del sidebar y principal

  const sideInp = document.getElementById("sidebar-input-codigo-edificio");

  if (sideInp) sideInp.value = copropiedadEncontrada.codigo;

  const mainInp = document.getElementById("main-input-buscar-edificio");

  if (mainInp) mainInp.value = copropiedadEncontrada.codigo;



  // 7. Scroll suave hacia el cuadro del edificio para que quede enfocado en pantalla

  setTimeout(() => {

    try {

      const gridEl = document.getElementById("grid-copropiedades-superadmin");

      if (gridEl) {

        gridEl.scrollIntoView({ behavior: "smooth", block: "start" });

      }

    } catch (e) {}

  }, 90);



  // 8. Sincronizar Fusión 3-en-1 y Carga Masiva

  if (typeof codigoEdificioActivoFusion !== "undefined") {

    codigoEdificioActivoFusion = copropiedadEncontrada.codigo;

  }

  if (typeof codigoNuevoEdificioEnCreacion !== "undefined") {

    codigoNuevoEdificioEnCreacion = copropiedadEncontrada.codigo;

  }

  if (typeof nombreNuevoEdificioEnCreacion !== "undefined") {

    nombreNuevoEdificioEnCreacion = copropiedadEncontrada.nombre;

  }

  if (typeof copropiedadCargaMasivaActiva !== "undefined") {

    copropiedadCargaMasivaActiva = copropiedadEncontrada.codigo;

  }

  const f3Inp = document.getElementById("f3-input-codigo-dbplus");

  if (f3Inp) f3Inp.value = copropiedadEncontrada.codigo;

  if (typeof actualizarBotonCargarDatosRealesFusion === "function") {

    actualizarBotonCargarDatosRealesFusion(copropiedadEncontrada.nombre, copropiedadEncontrada.codigo);

  }



  // 9. Sincronizar en segundo plano con la base de datos real (C:\dbplus\{limpio} y SQLite)

  const urlApi = (typeof getApiBaseUrl === "function") ? getApiBaseUrl() : "http://127.0.0.1:8000";

  try {

    const res = await fetch(`${urlApi}/api/dbplus/cargar/${encodeURIComponent(limpio)}`);

    if (res.ok) {

      const dataBackend = await res.json();

      if (dataBackend && dataBackend.edificio) {

        const u = Array.isArray(dataBackend.unidades) ? dataBackend.unidades : [];

        copropiedadEncontrada.nombre = dataBackend.edificio.nombre || copropiedadEncontrada.nombre;

        copropiedadEncontrada.nit = dataBackend.edificio.nit || copropiedadEncontrada.nit;

        copropiedadEncontrada.direccion = dataBackend.edificio.direccion || copropiedadEncontrada.direccion;

        copropiedadEncontrada.ciudad = dataBackend.edificio.ciudad || copropiedadEncontrada.ciudad;

        copropiedadEncontrada.banco = dataBackend.edificio.banco || copropiedadEncontrada.banco;

        copropiedadEncontrada.tipoCuenta = dataBackend.edificio.tipoCuenta || copropiedadEncontrada.tipoCuenta;

        copropiedadEncontrada.cuenta = dataBackend.edificio.cuenta || copropiedadEncontrada.cuenta;

        copropiedadEncontrada.administrador = dataBackend.edificio.administrador || copropiedadEncontrada.administrador;

        copropiedadEncontrada.telefono = dataBackend.edificio.telefono || copropiedadEncontrada.telefono;

        copropiedadEncontrada.email = dataBackend.edificio.email || copropiedadEncontrada.email;

        if (u.length > 0) {

          copropiedadEncontrada.unidades = u;

          copropiedadEncontrada.inmueblesCount = u.length;

          copropiedadEncontrada.inmueblesOcupados = u.length;

          copropiedadEncontrada.censoCount = u.length;

        }



        const idx = listaCopropiedadesSuperadmin.findIndex(c => String(c.codigo).trim() === limpio || c.id === copropiedadEncontrada.id);

        if (idx >= 0) {

          listaCopropiedadesSuperadmin[idx] = copropiedadEncontrada;

        }



        try {
          localStorage.setItem("lefacturamos_copropiedades_custom", JSON.stringify(listaCopropiedadesSuperadmin));
          if (typeof DIRECTORIO_ADMINISTRADORES !== "undefined") {
            localStorage.setItem("lefacturamos_directorio_admins", JSON.stringify(DIRECTORIO_ADMINISTRADORES));
          }
        } catch (e) {}



        renderizarCopropiedadesSuperadmin();

        if (typeof actualizarTodosLosSelectsDeCopropiedad === "function") {

          actualizarTodosLosSelectsDeCopropiedad(copropiedadEncontrada.codigo);

        }

        if (typeof mostrarToast === "function") {

          mostrarToast(`✅ [${copropiedadEncontrada.codigo}] ${copropiedadEncontrada.nombre} sincronizado (${copropiedadEncontrada.inmueblesCount} unidades reales cargadas)`, "success");

        }

        return;

      }

    }

  } catch (errDbp) {

    console.warn("Sync DBPLUS background:", errDbp);

  }



  // Notificar carga local completada si backend DBPLUS no estaba presente

  if (typeof mostrarToast === "function") {

    mostrarToast(`🏢 [${copropiedadEncontrada.codigo}] ${copropiedadEncontrada.nombre} listo para editar y arreglar.`, "success");

  }

}



function mostrarTodosLosEdificiosSuperadmin() {

  edificioFiltroCodigoSuperadmin = null;

  renderizarCopropiedadesSuperadmin();

  if (typeof mostrarToast === "function") {

    mostrarToast("Mostrando todos los edificios registrados");

  }

}


