window.renderizarTabFacturacion = function() {
  const cod = AppState.codigoEdificio || "4901";
  const cop = (typeof obtenerDatosCopropiedad === "function") ? obtenerDatosCopropiedad(cod) : null;
  const nombre = cop ? cop.nombre : `Copropiedad #${cod}`;
  const nit = cop ? cop.nit : "";
  const admin = cop ? cop.administrador : "";
  const tasa = cop ? (cop.interesMora || "2.16%") : "2.16%";
  const unidades = (cop && cop.unidades && cop.unidades.length > 0) ? cop.unidades : [];

  const badgeCod = document.getElementById("facturacion-badge-cod");
  if (badgeCod) badgeCod.innerText = cod;

  const headerNom = document.getElementById("facturacion-header-nombre");
  if (headerNom) headerNom.innerText = `${nombre} • NIT: ${nit} • Admin: ${admin || 'Administración PH'}`;

  // Calcular métricas
  let totalFact = 0;
  let totalCartera = 0;
  unidades.forEach(u => {
    totalFact += Number(u.admon || u.val || 0);
    totalCartera += Number(u.pend || u.saldo || 0);
  });

  const metricaTotal = document.getElementById("facturacion-metrica-total");
  if (metricaTotal) {
    metricaTotal.innerText = totalFact > 0 ? ("$" + Math.round(totalFact).toLocaleString("es-CO")) : (cop?.recaudoTotal || "$38.911.000");
  }

  const metricaCartera = document.getElementById("facturacion-metrica-cartera");
  if (metricaCartera) {
    metricaCartera.innerText = totalCartera > 0 ? ("$" + Math.round(totalCartera).toLocaleString("es-CO")) : (cop?.carteraPendiente || "$11.498.390");
  }

  const metricaTasa = document.getElementById("facturacion-metrica-tasa");
  if (metricaTasa) metricaTasa.innerText = tasa;

  const metricaInm = document.getElementById("facturacion-metrica-inmuebles");
  if (metricaInm) metricaInm.innerText = unidades.length > 0 ? unidades.length : (cop?.inmueblesCount || 83);

  // Renderizar tabla
  const tbody = document.getElementById("facturacion-tbody-unidades");
  if (tbody) {
    if (unidades.length === 0) {
      tbody.innerHTML = `<tr><td colspan="9" class="text-center py-6 text-slate-500">No hay unidades cargadas para este edificio. Utilice Carga Masiva para sincronizar.</td></tr>`;
      return;
    }

    tbody.innerHTML = unidades.map(u => {
      const cuota = Number(u.admon || u.val || 0);
      const saldoPrev = Number(u.pend || u.saldo || 0);
      const moraCalc = saldoPrev > 0 ? Math.round(saldoPrev * 0.0216) : 0;
      const descPronto = Math.round(cuota * 0.05);
      const totalPagar = cuota + saldoPrev + moraCalc;
      const estadoAlDia = saldoPrev <= 0;
      const tel = u.celular || u.tel || "3001234567";
      const textoWA = encodeURIComponent(`Hola ${u.propietario || 'Estimado Propietario'}, le informamos que su estado de cuenta para la unidad ${u.unidad || u.apto} de ${nombre} es de $${totalPagar.toLocaleString('es-CO')}. Cuota Admon: $${cuota.toLocaleString('es-CO')}.`);

      return `
        <tr class="hover:bg-slate-800/40 transition-colors">
          <td class="py-2.5 px-3 font-mono font-bold text-emerald-400">${u.unidad || u.apto}</td>
          <td class="py-2.5 px-3 font-semibold text-white truncate max-w-[180px]">${u.propietario || 'Copropietario'}</td>
          <td class="py-2.5 px-3 font-mono text-slate-400">${u.coeficiente ? (u.coeficiente + (String(u.coeficiente).includes('%') ? '' : '%')) : '1.20%'}</td>
          <td class="py-2.5 px-3 font-mono text-slate-200">$${cuota.toLocaleString('es-CO')}</td>
          <td class="py-2.5 px-3 font-mono ${moraCalc > 0 ? 'text-rose-400 font-bold' : 'text-slate-500'}">$${moraCalc.toLocaleString('es-CO')}</td>
          <td class="py-2.5 px-3 font-mono text-emerald-400">-$${descPronto.toLocaleString('es-CO')}</td>
          <td class="py-2.5 px-3 font-mono font-black text-amber-400 text-right">$${totalPagar.toLocaleString('es-CO')}</td>
          <td class="py-2.5 px-3 text-center">
            <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${estadoAlDia ? 'bg-emerald-950 text-emerald-400 border border-emerald-800' : 'bg-rose-950 text-rose-400 border border-rose-800'}">
              ${estadoAlDia ? 'Al Día' : 'En Mora'}
            </span>
          </td>
          <td class="py-2.5 px-3 text-center">
            <a href="https://wa.me/57${tel}?text=${textoWA}" target="_blank" class="p-1.5 rounded-lg bg-emerald-600/20 hover:bg-emerald-600/40 text-emerald-400 inline-flex items-center justify-center transition-all" title="Enviar cobro por WhatsApp">
              <i data-lucide="message-circle" class="w-3.5 h-3.5"></i>
            </a>
          </td>
        </tr>
      `;
    }).join("");
  }
  safeCreateIcons();
};

